INSERT INTO public.thu_tuc_thue (ma, ten, cap_thuc_hien, doi_tuong, co_quan, trinh_tu, cach_thuc, thanh_phan_ho_so, ket_qua, dieu_kien, can_cu_phap_ly, mau_to_khai, nguon, lay_luc, tim)
SELECT x.ma, x.ten, x.cap_thuc_hien, x.doi_tuong, x.co_quan, x.trinh_tu, x.cach_thuc, x.thanh_phan_ho_so, x.ket_qua, x.dieu_kien, x.can_cu_phap_ly,
       coalesce(ARRAY(SELECT jsonb_array_elements_text(x.mau_to_khai)), '{}'), x.nguon, '2026-09-25T10:50:59+0700'::timestamptz,
       to_tsvector('simple', coalesce(x.ten, '') || ' ' || coalesce((SELECT string_agg(v, ' ') FROM jsonb_array_elements_text(x.mau_to_khai) v), '') || ' ' || coalesce(x.doi_tuong, ''))
FROM jsonb_to_recordset($du_lieu$[{"ma": "1.007674", "ten": "Khai thuế TNCN đối với cá nhân có thu nhập từ chuyển nhượng bất động sản; thu nhập từ nhận thừa kế và nhận quà tặng là bất động sản", "cap_thuc_hien": "Cấp xã", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Thuế cơ sở", "trinh_tu": "'+ Bước 1. Tổ chức, cá nhân khai (khai thay) thuế thu nhập cá nhân cho cá nhân chuyển nhượng bất động động sản chuẩn bị hồ sơ khai thuế và nộp hồ sơ khai thuế tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã.\n Thời hạn nộp hồ sơ khai thuế:\n ++ Trường hợp hợp đồng chuyển nhượng không có thỏa thuận bên mua là người nộp thuế thay cho bên bán thì nộp hồ sơ khai thuế chậm nhất là 10 (mười) ngày kể từ thời điểm hợp đồng chuyển nhượng có hiệu lực theo quy định của pháp luật.\n ++ Trường hợp hợp đồng chuyển nhượng có thỏa thuận bên mua là người nộp thuế thay cho bên bán thì nộp hồ sơ khai thuế chậm nhất là thời điểm làm thủ tục đăng ký quyền sở hữu, quyền sử dụng bất động sản. Trường hợp cá nhân nhận chuyển nhượng nhà, công trình xây dựng tương lai là thời điểm cá nhân nộp hồ sơ khai thuế với cơ quan thuế.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ và trả kết quả thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n ++ Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân có thu nhập từ chuyển nhượng bất động sản; thu nhập từ nhận thừa kế, quà tặng là bất động sản) mẫu số 03/BĐS-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính;\n ++ Bản sao hộ chiếu đối với trường hợp cá nhân không có quốc tịch Việt Nam;\n ++ Bản sao giấy chứng nhận quyền sử dụng đất, giấy tờ chứng minh quyền sở hữu nhà hoặc quyền sở hữu các công trình trên đất và cá nhân ký cam kết chịu trách nhiệm vào Bản sao đó. Trường hợp chuyển nhượng hợp đồng mua bán nhà ở, nhà ở thương mại, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở thì nộp bản sao hợp đồng mua bán nhà ở, nhà ở thương mại, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở ký với chủ dự án cấp I, cấp II hoặc sàn giao dịch của chủ dự án.\n ++ Bản sao Hợp đồng chuyển nhượng bất động sản. Trường hợp chuyển nhượng hợp đồng mua bán nhà, công trình xây dựng hình thành trong tương lai thì nộp Bản sao Hợp đồng chuyển nhượng Hợp đồng mua bán nhà ở, nhà ở thương mại, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở. Nếu chuyển nhượng hợp đồng mua bán nhà ở, nhà ở thương mại, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở từ lần thứ hai trở đi thì các bên phải xuất trình thêm Bản sao hợp đồng chuyển nhượng lần trước liền kề. Trường hợp ủy quyền bất động sản thì nộp Bản sao Hợp đồng ủy quyền bất động sản.\n ++ Đối với thu nhập từ nhận thừa kế, quà tặng là bất động sản, Bản sao Hợp đồng chuyển nhượng bất động sản thay thế bằng bản sao giấy tờ pháp lý chứng minh quyền được nhận thừa kế, quà tặng. Đối với nhận thừa kế, quà tặng là nhà ở, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở thì Bản sao Hợp đồng chuyển nhượng, Hợp đồng mua bán nhà ở, công trình xây dựng hình thành trong tương lai, công trình xây dựng, nhà ở đã được dự án bàn giao đưa vào sử dụng nhưng chưa cấp Giấy chứng nhận quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về nhà ở được thay bằng bản sao giấy tờ pháp lý chứng minh quyền được nhận thừa kế, quà tặng.\n ++ Đối với thu nhập từ chuyển nhượng bất động sản trong trường hợp góp vốn bằng bất động sản thì Bản sao Hợp đồng chuyển nhượng bất động sản được thay bằng bản sao Hợp đồng góp vốn.\n ++ Bản sao tài liệu xác định đối tượng được miễn thuế thu nhập cá nhân, đối tượng không phải nộp thuế thu nhập cá nhân, đối tượng tạm thời chưa phải nộp thuế thu nhập cá nhân theo quy định của Bộ Tài chính.\n Bản sao các giấy tờ trong hồ sơ khai thuế theo từng lần phát sinh đối với thuế thu nhập cá nhân của cá nhân có thu nhập từ chuyển nhượng bất động sản, thu nhập từ nhận thừa kế, quà tặng là bất động sản là bản chụp từ bản chính. Trường hợp tổ chức, cá nhân nộp bản sao bằng hình thức trực tiếp thì phải xuất trình bản chính để đối chiếu. Trường hợp tổ chức, cá nhân nộp bản sao bằng hình thức điện tử thì phải ký số cam kết chịu trách nhiệm trên hồ sơ. Trường hợp cơ quan thuế đã kết nối liên thông điện tử với cơ quan có liên quan thì hồ sơ khai là Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân có thu nhập từ chuyển nhượng bất động sản; thu nhập từ nhận thừa kế, quà tặng là bất động sản).\n ++ Văn bản ủy quyền khai thuế thay (nếu có).\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Thông báo nộp tiền về thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng bất động sản mẫu số 03/TB-BĐS-TNCN tại Phụ lục II - Danh mục thông báo của cơ quan quản lý thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03/BĐS-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007674"}, {"ma": "1.007607", "ten": "Chấm dứt hiệu lực mã số thuế", "cap_thuc_hien": "Cấp Thuế cơ sở", "doi_tuong": "(i) Chấm dứt hiệu lực mã số thuế đối với tổ chức kinh tế, tổ chức khác và đơn vị phụ thuộc (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh): \n Đối tượng thực hiện thủ tục hành chính: Tổ chức kinh tế, tổ chức khác.\n (ii) Chấm dứt hiệu lực mã số thuế của doanh nghiệp, hợp tác xã bị chia, bị sáp nhập, bị hợp nhất; Chấm dứt hoạt động đơn vị phụ thuộc của doanh nghiệp và hợp tác xã.\n Đối tượng thực hiện thủ tục hành chính: Doanh nghiệp, hợp tác xã\n (iii) Chấm dứt hiệu lực mã số thuế đối với nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, nhà thầu nước ngoài.\n Đối tượng thực hiện thủ tục hành chính: Nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, nhà thầu nước ngoài.\n (iv) Chấm dứt hiệu lực mã số thuế đối với hộ gia đình, cá nhân có hoạt động sản xuất kinh doanh do chấm dứt hoạt động kinh doanh; chấm dứt hoạt động của địa điểm kinh doanh.\n Đối tượng thực hiện thủ tục hành chính: Hộ gia đình, cá nhân có hoạt động sản xuất kinh doanh.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "- Trình tự thực hiện: \n (i) Chấm dứt hiệu lực mã số thuế đối với tổ chức kinh tế, tổ chức khác và đơn vị phụ thuộc (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh): \n + Bước 1: Tổ chức kinh tế, tổ chức khác nộp hồ sơ chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 ngày làm việc kể từ ngày có văn bản chấm dứt hoạt động hoặc chấm dứt hoạt động kinh doanh hoặc ngày kết thúc hợp đồng. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn. \n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (ii) Chấm dứt hiệu lực mã số thuế của doanh nghiệp, hợp tác xã bị chia, bị sáp nhập, bị hợp nhất; Chấm dứt hoạt động đơn vị phụ thuộc của doanh nghiệp và hợp tác xã.\n - Trình tự thực hiện: \n + Bước 1: Doanh nghiệp, hợp tác xã, đơn vị phụ thuộc của doanh nghiệp và hợp tác xã trước khi nộp hồ sơ để chấm dứt hoạt động doanh nghiệp, hợp tác xã do bị chia, bị sáp nhập, bị hợp nhất hoặc chấm dứt hoạt động đơn vị phụ thuộc của doanh nghiệp tại cơ quan đăng ký kinh doanh, cơ quan đăng ký hợp tác xã phải nộp hồ sơ đến cơ quan thuế quản lý trực tiếp để thực hiện các thủ tục về thuế, hoàn thành nghĩa vụ thuế theo thời hạn quy định tại Luật Doanh nghiệp (đối với doanh nghiệp) và các pháp luật khác có liên quan. Trường hợp Luật Doanh nghiệp và pháp luật khác có liên quan không quy định thời hạn người nộp thuế phải nộp hồ sơ đến cơ quan thuế thì người nộp thuế nộp hồ sơ đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày có quyết định chia, hợp đồng sáp nhập, hợp đồng hợp nhất, quyết định hoặc thông báo của doanh nghiệp, hợp tác xã về chấm dứt hoạt động chi nhánh, văn phòng đại diện, hoặc quyết định thu hồi giấy chứng nhận đăng ký hoạt động chi nhánh, văn phòng đại diện.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn. \n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iii) Chấm dứt hiệu lực mã số thuế đối với nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, nhà thầu nước ngoài.\n - Trình tự thực hiện: \n + Bước 1: Trong thời hạn 10 (mười) ngày làm việc kể từ ngày kết thúc hợp đồng, người điều hành, công ty điều hành chung, doanh nghiệp liên doanh, nhà thầu, nhà đầu tư tham gia hợp đồng, hiệp định dầu khí, công ty mẹ - Tập đoàn Dầu khí Quốc gia Việt Nam đại diện nước chủ nhà nhận phần lãi được chia từ các hợp đồng, hiệp định dầu khí và tổ chức được Chính phủ Việt Nam giao nhiệm vụ tiếp nhận phần được chia của Việt Nam thuộc các mỏ dầu khí tại vùng chồng lấn, nhà thầu nước ngoài có trách nhiệm gửi hồ sơ chấm dứt hiệu lực mã số thuế đến cơ quan thuế trực tiếp quản lý để làm thủ tục chấm dứt hiệu lực mã số thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iv) Chấm dứt hiệu lực mã số thuế đối với hộ gia đình, cá nhân có hoạt động sản xuất kinh doanh do chấm dứt hoạt động kinh doanh; chấm dứt hoạt động của địa điểm kinh doanh.\n - Trình tự thực hiện:\n + Bước 1: Hộ gia đình, cá nhân có hoạt động sản xuất kinh doanh nộp hồ sơ chấm dứt hiệu lực mã số thuế do chấm dứt hoạt động kinh doanh đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 ngày làm việc kể từ ngày chấm dứt hoạt động kinh doanh.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n ++++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n ++++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n +++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n+Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "(i) Chấm dứt hiệu lực mã số thuế đối với tổ chức kinh tế, tổ chức khác và đơn vị phụ thuộc (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh): \n + Thành phần hồ sơ, gồm: \n ++ Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bản sao quyết định giải thể, bản sao quyết định chia, bản sao hợp đồng hợp nhất, bản sao hợp đồng sáp nhập, bản sao quyết định thu hồi giấy chứng nhận đăng ký hoạt động của cơ quan có thẩm quyền, bản sao thông báo chấm dứt hoạt động, bản sao quyết định chuyển đổi.\n + Số lượng hồ sơ: 01 (bộ).\n (ii) Chấm dứt hiệu lực mã số thuế của doanh nghiệp, hợp tác xã bị chia, bị sáp nhập, bị hợp nhất; Chấm dứt hoạt động đơn vị phụ thuộc của doanh nghiệp và hợp tác xã.\n + Thành phần hồ sơ, gồm:\n ++ Đối với doanh nghiệp và hợp tác xã bị chia, bị sáp nhập, bị hợp nhất, gồm: \n +++ Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++ Bản sao quyết định chia, bản sao hợp đồng hợp nhất, bản sao hợp đồng sáp nhập.\n ++ Đối với đơn vị phụ thuộc của doanh nghiệp và hợp tác xã, gồm: \n +++ Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++ Bản sao quyết định hoặc thông báo của doanh nghiệp, hợp tác xã về chấm dứt hoạt động chi nhánh, văn phòng đại diện; bản sao quyết định thu hồi giấy chứng nhận đăng ký hoạt động chi nhánh, văn phòng đại diện của cơ quan nhà nước có thẩm quyền.\n + Số lượng hồ sơ: 01 bộ\n (iii) Chấm dứt hiệu lực mã số thuế đối với nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, nhà thầu nước ngoài.\n + Thành phần hồ sơ, gồm: \n ++ Thông báo đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bản sao bản thanh lý hợp đồng hoặc bản sao văn bản về việc chuyển nhượng toàn bộ phần vốn góp tham gia hợp đồng dầu khí đối với nhà đầu tư tham gia hợp đồng dầu khí.\n + Số lượng hồ sơ: 01 (bộ).\n (iv) Chấm dứt hiệu lực mã số thuế đối với hộ gia đình, cá nhân có hoạt động sản xuất kinh doanh do chấm dứt hoạt động kinh doanh; chấm dứt hoạt động của địa điểm kinh doanh.\n + Thành phần hồ sơ, gồm:\n ++ Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; Trường hợp cá nhân kinh doanh chấm dứt hoạt động của địa điểm kinh doanh ngoài địa điểm đăng ký trụ sở, cá nhân kinh doanh thông báo cho Chi cục thuế tại địa bàn nơi có địa điểm kinh doanh theo mẫu số 24.1/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Cơ quan thuế ban hành Thông báo người nộp thuế ngừng hoạt động và đang làm thủ tục chấm dứt hiệu lực mã số thuế theo mẫu số 17/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính và Thông báo chấm dứt hiệu lực mã số thuế mẫu số 18/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["24/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007607"}, {"ma": "1.008587", "ten": "Xác nhận số thuế đã nộp tại Việt Nam đối với đối tượng cư trú của nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Các tổ chức, cá nhân là đối tượng cư trú của nước ngoài chuẩn bị hồ sơ đề nghị xác nhận số thuế đã nộp tại Việt Nam gửi đến Thuế tỉnh, thành phố. Trường hợp một đối tượng cư trú của Nước ký kết Hiệp định thuế với Việt Nam phải nộp thuế thu nhập tại Việt Nam theo quy định của Hiệp định thuế và pháp luật thuế Việt Nam muốn xác nhận số thuế đã nộp tại Việt Nam để được khấu trừ vào số thuế phải nộp tại nước cư trú chuẩn bị hồ sơ đề nghị xác nhận số thuế đã nộp tại Việt Nam gửi đến Thuế tỉnh, thành phố nơi đăng ký nộp thuế theo quy định.\n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Giấy đề nghị xác nhận số thuế đã nộp tại Việt Nam theo Hiệp định thuế theo mẫu số 03/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC), \n ++ Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp (ghi rõ là đối tượng cư trú trong kỳ tính thuế nào) đã được hợp pháp hóa lãnh sự; \n ++ Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "không có", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật cư trú 68/2020/QH14 ngày 13/11/2020 của Ủy ban Thường vụ Quốc hội \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Nghị định số 122/2025/NĐ-CP ngày 11 tháng 6 năm 2025 của Chính phủ. \n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế; \n + Nghị định số 104/2022/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của các nghị định liên quan đến việc nộp, xuất trình sổ hộ khẩu, sổ tạm trú giấy khi thực hiện thủ tục hành chính, cung cấp dịch vụ công \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 40/2025/TT-BTC Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Thông tư số 94/2025/TT-BTC ngày 14/10/2025 sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03/HTQT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008587"}, {"ma": "1.007695", "ten": "Khai; miễn, giảm thuế sử dụng đất phi nông nghiệp/ Khai thuế sử dụng đất nông nghiệp", "cap_thuc_hien": "Cấp Bộ, Cấp Huyện", "doi_tuong": "i) Khai thuế sử dụng đất nông nghiệp: Tổ chức, cá nhân.\n(ii) Khai thuế sử dụng đất phi nông nghiệp: Tổ chức, hộ gia đình, cá nhân.\n(iii) Miễn, giảm thuế sử dụng đất phi nông nghiệp: Tổ chức, hộ gia đình, cá nhân.", "co_quan": "Thuế cơ sở", "trinh_tu": "(i) Khai thuế sử dụng đất nông nghiệp\n + Bước 1: Người nộp thuế sử dụng đất nông nghiệp nộp hồ sơ khai thuế, hồ sơ đề nghị miễn, giảm thuế sử dụng đất nông nghiệp cho Ủy ban nhân dân xã, phường, đặc khu nơi có đất chịu thuế, TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc qua Cổng DVC Quốc gia (trực tuyến).\n Thời hạn hộp hồ sơ khai thuế là 30 ngày, kể từ ngày phát sinh hoặc thay đổi nghĩa vụ thuế. Trường hợp địa phương có mùa vụ thu hoạch sản phẩm nông nghiệp không trùng với thời hạn nộp thuế quy định tại điểm này thì cơ quan thuế được phép lùi thời hạn thông báo nộp thuế và thời hạn nộp thuế không quá 60 (sáu mươi) ngày so với thời hạn quy định tại điểm này. Trường hợp người nộp thuế có yêu cầu nộp thuế một lần cho toàn bộ số thuế sử dụng đất nông nghiệp cả năm thì người nộp thuế phải thực hiện nộp tiền thuế theo thời hạn của kỳ nộp thứ nhất trong năm. Hàng năm, người nộp thuế không phải kê khai lại hồ sơ khai thuế nếu không phát sinh thay đổi tăng, giảm diện tích chịu thuế sử dụng đất nông nghiệp. Thời hạn nộp hồ sơ khai thuế năm của tổ chức chậm nhất là ngày cuối cùng của tháng đầu tiên năm dương lịch; chậm nhất 10 ngày kể từ ngày khai thác sản lượng thu hoạch đối với tổ chức nộp thuế cho diện tích trồng cây lâu năm thu hoạch một lần.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định.\n (ii) Khai thuế sử dụng đất phi nông nghiệp - Trường hợp khai thuế sử dụng đất phi nông nghiệp phải nộp của năm\n + Bước 1: \n ++ Đối với tổ chức\n Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày phát sinh nghĩa vụ thuế sử dụng đất phi nông nghiệp, Tổ chức sử dụng đất thuộc tượng chịu thuế sử dụng đất phi nông nghiệp nộp hồ sơ khai thuế sử dụng đất phi nông nghiệp tại cơ chế một cửa liên thông nơi có đất thuộc đối tượng chịu thuế, TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc qua Cổng DVC Quốc gia (trực tuyến). \n Trong chu kỳ ổn định, hàng năm tổ chức không phải kê khai lại thuế sử dụng đất phi nông nghiệp nếu không có sự thay đổi về người nộp thuế và các yếu tố dẫn đến thay đổi số thuế phải nộp.\n Kê khai khi có phát sinh thay đổi các yếu tố làm thay đổi căn cứ tính thuế dẫn đến tăng, giảm số thuế phải nộp và khai bổ sung khi phát hiện hồ sơ khai thuế đã nộp cho cơ quan thuế có sai sót ảnh hưởng đến số thuế phải nộp: Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày phát sinh thay đổi. \n Khai bổ sung hồ sơ khai thuế được áp dụng đối với: Trường hợp phát sinh các yếu tố làm thay đổi căn cứ tính thuế dẫn đến tăng, giảm số thuế phải nộp; trường hợp phát hiện hồ sơ khai thuế đã nộp cho cơ quan thuế có sai sót, nhầm lẫn gây ảnh hưởng đến số thuế phải nộp. \n ++ Đối với hộ gia đình, cá nhân:\n Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày phát sinh nghĩa vụ thuế sử dụng đất phi nông nghiệp. Người nộp thuế có trách nhiệm khai chính xác vào Tờ khai thuế các thông tin liên quan đến người nộp thuế như: tên, số CCCD, mã số thuế, địa chỉ nhận thông báo thuế; Các thông tin liên quan đến thửa đất chịu thuế như diện tích, mục đích sử dụng. Nếu đất đã được cấp Giấy chứng nhận thì phải khai đầy đủ các thông tin trên Giấy chứng nhận như số, ngày cấp, số tờ bản đồ, diện tích đất, hạn mức (nếu có), nộp hồ sơ khai thuế tại cơ chế một cửa liên thông nơi có đất thuộc đối tượng chịu thuế, TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc qua Cổng DVC Quốc gia (trực tuyến). \n Đối với hồ sơ khai thuế đất ở của hộ gia đình, cá nhân, cơ quan chuyên môn về nông nghiệp và môi trường thuộc Ủy ban nhân dân cấp xã hoặc văn phòng đăng ký quyền sử dụng đất có trách nhiệm xác nhận thông tin khai thuế sử dụng đất phi nông nghiệp cho người nộp thuế trong phạm vi nhiệm vụ của mình trong thời hạn 03 ngày làm việc kể từ khi nhận được đề nghị của người nộp thuế hoặc của cơ quan quản lý thuế. \n Hàng năm, người nộp thuế không phải thực hiện khai lại nếu không có sự thay đổi về người nộp thuế và các yếu tố dẫn đến thay đổi số thuế phải nộp. \n Trường hợp có phát sinh thay đổi các yếu tố làm thay đổi căn cứ tính thuế (trừ trường hợp thay đổi giá của 1m2 đất theo quy định của Ủy ban nhân dân cấp tỉnh) dẫn đến tăng, giảm số thuế phải nộp: Thời hạn nộp hồ sơ chậm nhất 30 ngày kể từ ngày phát sinh thay đổi.\n Trường hợp người nộp thuế đề nghị miễn, giảm thuế sử dụng đất phi nông nghiệp cùng hồ sơ khai thuế thì người nộp thuế kê khai thông tin đề nghị miễn giảm tại tờ khai thuế sử dụng đất phi nông nghiệp và nộp bản sao các giấy tờ chứng minh thuộc diện được miễn, giảm thuế kèm theo.\n + Bước 2. Cơ quan thuế tiếp nhận: Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định; Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định.\n (iii) Miễn, giảm thuế sử dụng đất phi nông nghiệp\n + Bước 1: \n Tổ chức, hộ gia đình, cá nhân nộp hồ sơ đề nghị miễn, giảm thuế sử dụng đất phi nông nghiệp tại tại TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc nộp qua Cổng DVC Quốc gia (trực tuyến).\n + Bước 2. Cơ quan thuế tiếp nhận: Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định); Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "* Thành phần hồ sơ:\n (i) Khai thuế sử dụng đất nông nghiệp\n + Tờ khai thuế sử dụng đất nông nghiệp dùng cho tổ chức theo mẫu số 01/SDDNN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC).\n + Tờ khai thuế sử dụng đất nông nghiệp dùng cho hộ gia đình, cá nhân theo mẫu số 02/SDDNN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC)..\n + Tờ khai thuế sử dụng đất nông nghiệp dùng cho khai thuế đối với đất trồng cây lâu năm thu hoạch một lần theo mẫu số 03/SDDNN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC)\n (ii) Khai thuế sử dụng đất phi nông nghiệp - Trường hợp khai thuế sử dụng đất phi nông nghiệp phải nộp của năm\n + Đối với tổ chức \n ++ Tờ khai thuế sử dụng đất phi nông nghiệp cho từng thửa đất chịu thuế theo mẫu số 02/TK-SDDPNN tại Phụ lục ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế \n ++ Bản sao các giấy tờ liên quan đến thửa đất chịu thuế: Giấy chứng nhận quyền sử dụng đất, Quyết định giao đất, Quyết định hoặc Hợp đồng cho thuê đất, Quyết định cho phép chuyển mục đích sử dụng đất;\n ++ Bản sao các giấy tờ chứng minh thuộc diện được miễn, giảm thuế (nếu có).\n + Đối với hộ gia đình, cá nhân \n ++ Tờ khai thuế sử dụng đất phi nông nghiệp (áp dụng đối với hộ gia đình, cá nhân theo mẫu số 01/TK-SDDPNN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế \n ++ Bản sao các giấy tờ liên quan đến thửa đất chịu thuế: Giấy chứng nhận quyền sử dụng đất, Quyết định giao đất, Quyết định hoặc Hợp đồng cho thuê đất, Quyết định cho phép chuyển mục đích sử dụng đất;\n ++ Bản sao các giấy tờ chứng minh thuộc diện được miễn, giảm thuế (nếu có).\n ++ Tờ khai tổng hợp thuế sử dụng đất phi nông nghiệp (áp dụng đối với hộ gia đình, cá nhân kê khai tổng hợp đất ở) theo mẫu số 03/TKTH-SDDPNN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC).\n (iii) Miễn, giảm thuế sử dụng đất phi nông nghiệp\n ++ Đối với trường hợp miễn thuế, giảm thuế sử dụng đất phi nông nghiệp, trừ trường hợp miễn tiền thuế sử dụng đất phi nông nghiệp đối với hộ gia đình, cá nhân có số thuế phải nộp hằng năm từ 50.000 VNĐ (50 nghìn đồng) trở xuống, thành phần hồ sơ miễn, giảm theo quy định tại Điều 57 Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao các giấy tờ liên quan đến thửa đất chịu thuế như: Giấy chứng nhận quyền sử dụng đất, Quyết định giao đất, Quyết định hoặc Hợp đồng cho thuê đất, Quyết định cho phép chuyển mục đích sử dụng đất;\n +++ Bản sao Giấy tờ chứng minh thuộc đối tượng miễn, giảm thuế sử dụng đất phi nông nghiệp.\n ++ Đối với trường hợp hộ gia đình, cá nhân có số thuế sử dụng đất phi nông nghiệp phải nộp hằng năm từ 50.000 VNĐ (50 nghìn đồng) trở xuống thì không phải nộp hồ sơ miễn thuế sử dụng đất phi nông nghiệp.\n * Số lượng hồ sơ: 01 bộ", "ket_qua": "(i) Khai thuế sử dụng đất nông nghiệp: Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019;\n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số Điều của Luật Quản lý thuế.\n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "01/SDDNN", "01/TK-SDDPNN", "02/SDDNN", "02/TK-SDDPNN", "03/SDDNN", "03/TKTH-SDDPNN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007695"}, {"ma": "1.010992", "ten": "Khai quyết toán tiền lãi dầu, khí nước chủ nhà đối với hoạt động dầu khí", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tập đoàn Công nghiệp-Năng lượng Quốc gia Việt Nam /Đơn vị được ủy quyền/Đại lý thuế.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính hoặc chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc hợp đồng dầu khí/Hiệp định Liên chính phủ. Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai quyết toán tiền lãi dầu, khí nước chủ nhà Mẫu số 02/LNCN-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Phụ lục phân chia tiền dầu, khí xuất bán Mẫu số 02-1/PL-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Báo cáo tài chính năm hoặc báo cáo tài chính đến thời điểm kết thúc hợp đồng dầu khí/Hiệp định liên Chính phủ kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).F3", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và các Nghị định thư sửa đổi, bổ sung. \n + Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 36/2021/NĐ-CP ngày 29/03/2021 của Chính phủ về việc ban hành quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và Nghị định thư 2013; \n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế, và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010992"}, {"ma": "1.008340", "ten": "Khai thuế thu nhập cá nhân tháng/quý của tổ chức, cá nhân trả thu nhập thực hiện khấu trừ thuế đối với thu nhập từ đầu tư vốn, từ chuyển nhượng chứng khoán, từ bản quyền, từ nhượng quyền thương mại, từ trúng thưởng của cá nhân cư trú và cá nhân không cư trú; từ kinh doanh của cá nhân không cư trú; Tổ chức, cá nhân khi nhận chuyển nhượng vốn góp của cá nhân không cư trú", "cap_thuc_hien": "Cấp Xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh,thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1.Tổ chức hợp tác kinh doanh với cá nhân; tổ chức chi trả các khoản thưởng, hỗ trợ đạt doanh số, khuyến mại, chiết khấu thanh toán, chi hỗ trợ bằng tiền hoặc không bằng tiền cho cá nhân chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo tháng hoặc chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo quý phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo quý.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "- Tờ khai thuế thu nhập cá nhân (áp dụng đối với tổ chức, cá nhân trả thu nhập khấu trừ thuế đối với thu nhập từ đầu tư vốn, từ chuyển nhượng chứng khoán, từ bản quyền, từ nhượng quyền thương mại, từ trúng thưởng của cá nhân cư trú và cá nhân không cư trú; từ kinh doanh của cá nhân không cư trú; tổ chức, cá nhân nhận chuyển nhượng vốn của cá nhân không cư trú) mẫu số 06/TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n - Phụ lục bảng kê chi tiết cá nhân có thu nhập trong năm tính thuế (kê khai vào hồ sơ khai thuế của tháng/quý cuối cùng trong năm tính thuế) mẫu số 06-1/BK-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n - Riêng đối với trúng thưởng xổ số điện toán thì không khai phụ lục bảng kê chi tiết cá nhân có thu nhập trong năm tính thuế mẫu số 06-1/BK-TNCN mà thực hiện khai Phụ lục bảng xác định số thuế thu nhập cá nhân phải nộp đối với thu nhập từ tiền lương, tiền công và trúng thưởng mẫu số 05-1/PBT-KK-TNCN theo Phụ lục II – Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 100/2021/TT-BTC ngày 15 tháng 11 năm 2021 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["05-1/PBT-KK-TNCN", "06-1/BK-TNCN", "06/TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008340"}, {"ma": "1.007022", "ten": "Khai thuế Giá trị gia tăng đối với phương pháp trực tiếp trên doanh thu", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế áp dụng phương pháp tính thuế GTGT theo phương pháp trực tiếp trên doanh thu theo quy định của pháp luật về thuế GTGT (bao gồm cả trường hợp khai riêng thuế GTGT đối với khoản thu hộ cho cơ quan nhà nước có thẩm quyền giao) lập tờ khai và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo tháng); chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo quý); chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo lần phát sinh). Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế. +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) gồm: Tờ khai thuế GTGT (áp dụng đối với người nộp thuế tính thuế theo phương pháp trực tiếp trên doanh thu) mẫu số 04/GTGT.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vựng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 48/2024/QH15\n + Luật Quản lý thuế ngày 13/6/2019;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["04/GTGT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007022"}, {"ma": "1.010993", "ten": "Khai quyết toán tiền lãi dầu, khí nước chủ nhà được chia từ Liên doanh Vietsovpetro tại Lô 09.1 (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tập đoàn Dầu khí Việt Nam/Đơn vị được ủy quyền/Đại lý thuế.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính hoặc chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc hợp đồng dầu khí.\nTrường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n+ Bước 2. Cơ quan thuế tiếp nhận:\nCơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\nTrường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế /Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế.\n+ Hoặc gửi qua hệ thống bưu chính.\n+ Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n++ Tờ khai quyết toán tiền lãi dầu, khí nước chủ nhà (Liên doanh Việt - Nga “Vietsovpetro”) Mẫu số 02/LNCN-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n++ Phụ lục phân chia tiền dầu, khí xuất bán Mẫu số 02-1/PL-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n+ Số lượng hồ sơ: 01 (hộ).", "ket_qua": "Không trả KQ cho NNT", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008 và các văn bản hướng dẫn thi hành; Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành;\n+ Các Luật thuế và các văn bản hướng dẫn hiện hành;\n+ Luật Quản lý thuế ngày 13/6/2019;\n+ Nghị định số 36/2021/NĐ-CP ngày 29/03/2021 của Chính phủ về việc ban hành quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n+ Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính;\n+ Thông tư số 56/2008/TT-BTC ngày 23/06/2008 của Bộ Tài chính Hướng dẫn thực hiện kê khai, nộp và quyết toán các khoản thu của Nhà nước quy định tại Điều 18 Quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam ban hành kèm theo Nghị định số 142/2007/NĐ-CP ngày 5/9/2007 của Chính phủ;\n+ Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n+ Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010993"}, {"ma": "1.007016", "ten": "Khai thuế Giá trị gia tăng đối với phương pháp trực tiếp trên giá trị gia tăng", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế có hoạt động mua bán, chế tác vàng bạc, đá quý áp dụng phương pháp tính thuế GTGT theo phương pháp trực tiếp trên GTGT theo quy định của pháp luật về thuế GTGT lập tờ khai và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo tháng); chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo quý).\n Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC), gồm: Tờ khai thuế GTGT (áp dụng đối với hoạt động mua bán, chế tác vàng bạc, đá quý theo phương pháp trực tiếp trên GTGT) mẫu số 03/GTGT. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Tờ khai gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vựng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 48/2024/QH15 \n + Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03/GTGT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007016"}, {"ma": "1.008572", "ten": "Miễn thuế Thu nhập cá nhân đối với Chuyên gia nước ngoài thực hiện các chương trình, dự án ODA", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1: Nhà thầu (công ty) hoặc Chủ dự án (tùy từng trường hợp Chuyên gia ký hợp đồng với Chủ dự án hay với nhà thầu (công ty)) gửi hồ sơ đề nghị miễn thuế Thu nhập cá nhân cho Chuyên gia đến cơ quan thuế địa phương nơi đặt trụ sở của mình.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n ++ Công văn đề nghị của Chủ dự án hoặc của nhà thầu (công ty) đề nghị miễn thuế Thu nhập cá nhân đối với Chuyên gia. \n ++ Xác nhận của Cơ quan chủ quản về việc Chuyên gia đáp ứng đủ điều kiện về ưu đãi và miễn trừ theo Mẫu số 1 kèm theo Thông tư liên tịch số 12/2010/TTLT-BKHĐT-BTC ngày 28/05/2010 của Bộ Kế hoạch và Đầu tư và Bộ Tài chính. \n ++ Các tài liệu liên quan đến thu nhập được miễn thuế của Chuyên gia (hợp đồng, chứng từ chi trả thu nhập,…). \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Xác nhận miễn thuế Thu nhập cá nhân cho Chuyên gia theo Mẫu số 2 kèm theo Thông tư liên tịch số 12/2010/TTLT-BKHĐT-BTC ngày 28/05/2010 của Bộ Kế hoạch và Đầu tư và Bộ Tài chính.", "dieu_kien": "không", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/Qh14; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n +Thông tư liên tịch số 12/2010/TTLT-BKHĐT-BTC ngày 28/05/2010 của Bộ Kế hoạch và Đầu tư và Bộ Tài chính quy định chi tiết và hướng dẫn thực hiện Quy chế chuyên gia nước ngoài thực hiện các chương trình, dự án ODA ban hành kèm theo Quyết định số 119/2009/QĐ-TTg ngày 01 tháng 10 năm 2009 của Thủ tướng Chính phủ;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008572"}, {"ma": "1.008544", "ten": "Xác nhận đối tượng cư trú của Việt Nam", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân yêu cầu xác nhận là đối tượng cư trú thuế của Việt Nam theo quy định tại Hiệp định thuế chuẩn bị hồ sơ đề nghị gửi đến Thuế tỉnh, thành phố nơi đăng ký thuế. \n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Giấy đề nghị xác nhận cư trú của Việt Nam theo mẫu số 06/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC) \n ++ Giấy ủy quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế. \n ++ Xác nhận của cơ quan chi trả thu nhập (nếu có). Trường hợp không có xác nhận này, đối tượng nộp đơn tự khai trong đơn và chịu trách nhiệm trước pháp luật. \n ++ Xác nhận của cơ quan quản lý hoặc giấy đăng ký thành lập đối với các tổ chức \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "không có", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật cư trú 68/2020/QH14 ngày 13/11/2020 của Ủy ban Thường vụ Quốc hội \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Nghị định số 122/2025/NĐ-CP ngày 11 tháng 6 năm 2025 của Chính phủ. \n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế; \n + Nghị định số 104/2022/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của các nghị định liên quan đến việc nộp, xuất trình sổ hộ khẩu, sổ tạm trú giấy khi thực hiện thủ tục hành chính, cung cấp dịch vụ công \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 40/2025/TT-BTC Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Thông tư số 94/2025/TT-BTC ngày 14/10/2025 sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["06/HTQT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008544"}, {"ma": "3.000109", "ten": "Đăng ký sử dụng dịch vụ T-VAN/Đăng ký thay đổi, bổ sung thông tin đăng ký sử dụng dịch vụ T-VAN/Đăng ký ngừng sử dụng dịch vụ T-VAN", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Người nộp thuế theo quy định tại Điều 2 theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính, đã được cấp chứng thư số hoặc mã xác thực giao dịch điện tử do hệ thống của cơ quan thuế hoặc các cơ quan có liên quan đến giao dịch điện tử cấp", "co_quan": "Cục Thuế - Bộ Tài chính", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) lập tờ khai đăng ký sử dụng dịch vụ T-VAN/đăng ký thay đổi, bổ sung thông tin đăng ký sử dụng dịch vụ T-VAN/đăng ký ngừng sử dụng dịch vụ T-VAN, ký điện tử và gửi đến Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính qua tổ chức cung cấp dịch vụ T-VAN.\n Sau khi hoàn thành việc thực hiện đăng ký giao dịch điện tử với cơ quan thuế theo quy định, NNT phải thực hiện đăng ký với ngân hàng nơi mở tài khoản theo quy định của ngân hàng (đối với trường hợp đăng ký để thực hiện nộp thuế điện tử).\n + Bước 2. Cục Thuế thực hiện tiếp nhận hồ sơ qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "Bằng phương thức điện tử, qua tổ chức cung cấp dịch vụ T-VAN để gửi đến đến Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n ++ Trường hợp (1): Đăng ký sử dụng dịch vụ T-VAN: Tờ khai đăng ký sử dụng dịch vụ T-VAN theo mẫu số 01/ĐK-T-VAN ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.\n ++ Trường hợp (2): Đăng ký thay đổi, bổ sung thông tin đăng ký sử dụng dịch vụ T-VAN: Tờ khai thay đổi, bổ sung thông tin đăng ký sử dụng dịch vụ T-VAN theo mẫu số 02/ĐK-T-VAN ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.\n ++ Trường hợp (3): Đăng ký ngừng sử dụng dịch vụ T-VAN: Tờ khai đăng ký ngừng sử dụng dịch vụ T-VAN theo mẫu số 03/ĐK-T-VAN ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính..\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Thông báo tài khoản giao dịch thuế điện tử theo mẫu số 03/TB-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "dieu_kien": "Đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế (theo quy định tại khoản 1 Điều 4; khoản 1 và khoản 2 Điều 7; điểm c khoản 1 Điều 10 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật Giao dịch điện tử số 51/2005/QH11 ngày 29/11/2005; Luật Công nghệ thông tin số 67/2006/QH11 ngày 29/06/2006;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 165/2018/NĐ-CP ngày 24/12/2018 của Chính phủ quy định về giao dịch điện tử trong hoạt động tài chính; Nghị định số 130/2018/NĐ-CP ngày 27/9/2018 của Chính phủ quy định chi tiết thi hành Luật giao dịch điện tử về chữ ký số và dịch vụ chứng thực chữ ký số; Nghị định số 45/2020/NĐ-CP ngày 08/4/2020 của Chính phủ về thực hiện thủ tục hành chính trên môi trường điện tử; Nghị định số 11/2020/NĐ-CP ngày 20/01/2020 của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn về giao dịch điện tử trong lĩnh vực thuế\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐK-T-VAN", "02/ĐK-T-VAN", "03/ĐK-T-VAN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=3.000109"}, {"ma": "1.008583", "ten": "Miễn, giảm thuế tài nguyên đối với trường hợp người nộp thuế tự xác định số thuế được miễn, giảm", "cap_thuc_hien": "Cấp tỉnh thành phố, Cấp xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế lập hồ sơ đề nghị miễn giảm thuế cho cơ quan thuế. Một số trường hợp cụ thể như sau: \n ++ Cá nhân được phép khai thác cành, ngọn, củi, tre, trúc, nứa, mai, giang, tranh, vầu, lồ ô do phục vụ sinh hoạt gửi văn bản đề nghị miễn thuế 01 lần trước khi khai thác đến Thuế cơ sở nơi cá nhân cư trú. \n ++ Hộ gia đình, cá nhân sử dụng nước thiên nhiên tự sản xuất thuỷ điện phục vụ sinh hoạt gửi Văn bản đề nghị miễn thuế 01 lần trước khi khai thác đến Thuế tỉnh, thành phố trực tiếp quản lý nơi khai thác. \n ++ Tổ chức, cá nhân được giao, được thuê đất tự khai thác và sử dụng tại chỗ trên diện tích đất được giao, được thuê hoặc đơn vị nhận thầu thi công; đất khai thác để san lấp, xây dựng công trình an ninh, quân sự, đê điều gửi văn bản đề nghị đến Thuế tỉnh, thành phố trực tiếp quản lý nơi khai thác trước khi khai thác để hưởng miễn thuế tài nguyên.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ và giải quyết theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Thành phần hồ sơ đối với cá nhân được phép khai thác cành, ngọn, củi, tre, trúc, nứa, mai, giang, tranh, vầu, lồ ô do phục vụ sinh hoạt gồm: \n +++ Văn bản đề nghị miễn thuế theo mẫu số 06/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, có xác nhận của Ủy ban nhân dân cấp xã nơi cư trú. \n ++ Thành phần hồ sơ đối với hộ gia đình, cá nhân sử dụng nước thiên nhiên tự sản xuất thuỷ điện phục vụ sinh hoạt gồm: \n +++ Văn bản đề nghị miễn thuế theo mẫu số 06/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021, kèm theo bản giải trình về thiết bị sản xuất thuỷ điện phục vụ cho sinh hoạt gia đình, có xác nhận của Ủy ban nhân dân cấp xã nơi cư trú. \n ++ Thành phần hồ sơ đối với tổ chức, cá nhân được giao, được thuê đất tự khai thác và sử dụng tại chỗ trên diện tích đất được giao, được thuê hoặc đơn vị nhận thầu thi công; đất khai thác để san lấp, xây dựng chương trình an ninh, quân sự, đê điều gồm: \n +++ Văn bản đề nghị theo mẫu số 06/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021, kèm theo bản sao hồ sơ được cơ quan có thẩm quyền phê duyệt về việc xây dựng công trình tại địa phương của chủ đầu tư. Trường hợp đơn vị nhận thầu thi công thì phải có văn bản giao thầu ký với chủ đầu tư. \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "Trường hợp hồ sơ được nộp thông qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế, Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi phản hồi tự động về việc xác nhận người nộp thuế đã gửi thành công và thông báo về thời điểm tiếp nhận chính thức hồ sơ, tài liệu của người nộp thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Luật Thuế tài nguyên; Luật số 71/2014/QH13 ngày 26/11/2014 sửa đổi, bổ sung một số điều của các Luật về Thuế; Luật Dầu khí 2022; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["06/MGTH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008583"}, {"ma": "1.008593", "ten": "Thông báo về phương pháp trích khấu hao TSCĐ/ Thông báo về việc chuyển lợi nhuận ra nước ngoài", "cap_thuc_hien": "Cấp Thuế tỉnh, thành phố", "doi_tuong": null, "co_quan": null, "trinh_tu": "+ Bước 1: Nhà đầu tư nước ngoài trực tiếp hoặc uỷ quyền cho doanh nghiệp mà nhà đầu tư nước ngoài tham gia đầu tư thực hiện thông báo việc chuyển lợi nhuận ra nước ngoài theo mẫu và gửi cho cơ quan thuế trực tiếp quản lý doanh nghiệp mà nhà đầu tư nước ngoài tham gia đầu tư, trước khi thực hiện chuyển lợi nhuận ra nước ngoài ít nhất 7 ngày làm việc. \n+ Bước 2. Cơ quan thuế tiếp nhận:\n++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế.", "cach_thuc": null, "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Mẫu thông báo chuyển lợi nhuận ra nước ngoài ban hành kèm theo Thông tư số 186/2011/TT-BTC\n+ Số lượng hồ sơ: 01 (bộ).", "ket_qua": null, "dieu_kien": null, "can_cu_phap_ly": "Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008593"}, {"ma": "3.000083", "ten": "Giảm thuế nhập cá nhân đối với cá nhân, hộ kinh doanh, cá nhân kinh doanh gặp khó khăn do thiên tai, hoả hoạn, do bị tai nạn; mắc bệnh hiểm nghèo", "cap_thuc_hien": "Cấp tỉnh, thành phố, Cấp xã", "doi_tuong": "Cá nhân, hộ kinh doanh, cá nhân kinh doanh gặp khó khăn do thiên tai, hoả hoạn; do tai nạn; mắc bệnh hiểm nghèo", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Cá nhân chuẩn bị hồ sơ giảm thuế và gửi đến cơ quan thuế quản lý trực tiếp. \n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Trường hợp (1): Người nộp thuế gặp khó khăn do thiên tai, hỏa hoạn\n +++ Văn bản đề nghị theo mẫu số 01/MGTH theo Phụ lục I - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài Chính;\n +++ Biên bản xác định mức độ, giá trị thiệt hại về tài sản của cơ quan có thẩm quyền và có xác nhận của chính quyền địa phương cấp xã nơi xảy ra thiên tai, hỏa hoạn theo mẫu số 02/MGTH theo Phụ lục I - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài Chính. Cơ quan có thẩm quyền xác định mức độ, giá trị thiệt hại là cơ quan tài chính hoặc các cơ quan giám định xác định mức độ, giá trị thiệt hại về tài sản;\n +++ Trường hợp thiệt hại về hàng hoá thì người nộp thuế cung cấp Biên bản giám định (chứng thư giám định) về mức độ thiệt hại của cơ quan giám định và cơ quan giám định phải chịu trách nhiệm pháp lý về tính chính xác của chứng thư giám định theo quy định của pháp luật;\n +++ Trường hợp thiệt hại về đất đai, hoa màu thì cơ quan tài chính có trách nhiệm xác định;\n +++ Giấy tờ xác định việc bồi thường của cơ quan bảo hiểm hoặc thỏa thuận bồi thường của người gây hỏa hoạn (nếu có);\n +++ Các chứng từ chi liên quan trực tiếp đến việc khắc phục thiên tai, hỏa hoạn;\n +++ Tờ khai quyết toán thuế thu nhập cá nhân mẫu số 02/QTTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính (nếu người nộp thuế đề nghị giảm thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công).\n ++ Trường hợp (2): Người nộp thuế gặp khó khăn do bị tai nạn\n +++ Văn bản đề nghị theo mẫu số 01/MGTH theo Phụ lục I - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài Chính;\n +++ Văn bản hoặc biên bản xác nhận tai nạn có xác nhận của cơ quan công an hoặc xác nhận mức độ thương tật của cơ quan y tế;\n +++ Giấy tờ xác định việc bồi thường của cơ quan bảo hiểm hoặc thỏa thuận bồi thường của người gây tai nạn (nếu có);\n +++ Các chứng từ chi liên quan trực tiếp đến việc khắc phục tai nạn;\n +++ Tờ khai quyết toán thuế thu nhập cá nhân mẫu số 02/QTTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính (nếu người nộp thuế đề nghị giảm thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công).\n ++ Trường hợp (3): Người nộp thuế mắc bệnh hiểm nghèo\n +++ Văn bản đề nghị theo mẫu số 01/MGTH theo Phụ lục I - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài Chính;\n +++ Bản sao hồ sơ bệnh án hoặc bản tóm tắt hồ sơ bệnh án hoặc sổ khám bệnh theo quy định của pháp luật về khám bệnh, chữa bệnh;\n +++ Các chứng từ chứng minh chi phí khám chữa bệnh do cơ quan y tế cấp; hoặc hóa đơn mua thuốc chữa bệnh kèm theo đơn thuốc của bác sỹ;\n +++ Tờ khai quyết toán thuế thu nhập cá nhân mẫu số 02/QTTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính (nếu người nộp thuế đề nghị giảm thuế thu nhập cá nhân đối với thu nhập từ tiền lương, tiền công).\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Quyết định giảm thuế theo mẫu số 03/MGTH hoặc Thông báo cho người nộp thuế không thuộc diện được giảm thuế theo mẫu số 04/MGTH", "dieu_kien": "Trường hợp người nộp thuế đăng ký khai thuế điện tử và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tửtại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019.\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 quy định chi tiết một số điều củaLuật Quản lý thuế\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "02/MGTH", "02/QTTT-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=3.000083"}, {"ma": "1.008567", "ten": "Thủ tục đăng ký điều chỉnh, chấm dứt việc bán hàng hoàn thuế giá trị gia tăng", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Doanh nghiệp", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố", "trinh_tu": "- Trường hợp điều chỉnh việc bán hàng hoàn thuế:\n + Doanh nghiệp gửi hồ sơ đến cơ quan thuế quản lý trực tiếp.\n + Thủ tục thực hiện như quy định tại khoản 3 Điều 13 Thông tư 72/2014/TT-BTC ngày 30/5/2014 của Bộ Tài chính và Khoản 9, Khoản 10 Điều 1 Thông tư số 92/2019/TT-BTC ngày 31/12/2019 của Bộ Tài chính.\n -Trường hợp chấm dứt việc bán hàng hoàn thuế:\n + Chậm nhất là 30 ngày trước ngày chấm dứt việc bán hàng hoàn thuế, doanh nghiệp gửi công văn thông báo chấm dứt việc bán hàng hoàn thuế giá trị gia tăng cho người nước ngoài đến cơ quan thuế quản lý trực tiếp;\n + Trong vòng 30 (ba mươi) ngày kể từ ngày nhận được công văn của doanh nghiệp, cơ quan thuế quản lý trực tiếp kiểm tra, có văn bản báo cáo Thuế tỉnh, thành phố trực thuộc Trung ương nơi doanh nghiệp đóng trụ sở chính để Thuế tỉnh, thành phố trực thuộc Trung ương có văn bản gửi doanh nghiệp, cơ quan hải quan, ngân hàng thương mại thông báo về việc chấm dứt bán hàng hoàn thuế đối với doanh nghiệp. \n + Doanh nghiệp tháo bỏ Biển thông báo doanh nghiệp bán hàng hoàn thuế giá trị gia tăng cho người nước ngoài đã dán tại cửa hàng khi chấm dứt bán hàng hoàn thuế. \n - Trường hợp doanh nghiệp vi phạm các quy định về việc hoàn thuế giá trị gia tăng, tùy hành vi và mức độ vi phạm, Cục Thuế tỉnh, thành phố trực thuộc Trung ương xử lý theo quy định. Trường hợp doanh nghiệp bị lập biên bản đến lần thứ hai về hành vi không lập hóa đơn kiêm tờ khai hoàn thuế theo mẫu ban hành kèm theo Phụ lục 3 Thông tư này hoặc lập hóa đơn kiêm tờ khai hoàn thuế nhưng không truyền đến Hệ thống, ngoài việc xử lý vi phạm hành chính (nếu có), Cục Thuế tỉnh, thành phố trực thuộc Trung ương xem xét, quyết định chấm dứt việc bán hàng hoàn thuế, truyền thông tin đến Hệ thống theo phương thức điện tử, đồng thời đăng trên trang thông tin điện tử của Cục Thuế và Tổng cục Thuế.”", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Trường hợp điều chỉnh việc bán hàng hoàn thuế: \n ++ Thành phần hồ sơ: \n +++ Công văn đăng ký điều chỉnh theo mẫu quy định tại Phụ lục 8 Thông tư 72/2014/TT-BTC; \n +++ Hợp đồng bán hàng đại lý ký giữa doanh nghiệp bán hàng hoàn thuế với cửa hàng nhận bán hàng đại lý cho doanh nghiệp (đối với trường hợp là cửa hàng đại lý bán hàng cho doanh nghiệp): 01 bản chụp có đóng dấu xác nhận của doanh nghiệp; \n ++ Số lượng hồ sơ: 01 bộ \n + Trường hợp chấm dứt việc bán hàng hoàn thuế: \n ++ Thành phần hồ sơ: Văn bản xin/yêu cầu chấm dứt vai trò doanh nghiệp bán hàng hoàn thuế giá trị gia tăng (bản chính); \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "Công văn của cơ quan thuế chấp nhận việc điều chỉnh bán hàng hoàn thuế; khi chấm dứt bán hàng hoàn thuế doanh nghiệp tháo bỏ Biển thông báo doanh nghiệp bán hàng hoàn thuế giá trị gia tăng cho người nước ngoài đã dán tại cửa hàng.", "dieu_kien": "+ Là doanh nghiệp được công nhận là doanh nghiệp bán hàng hoàn thuế giá trị gia tăng", "can_cu_phap_ly": "+ Luật thuế giá trị gia tăng số 13/2008/QH12 ngày 03/06/2008; Luật sửa đổi, bổ sung một số điều của Luật thuế giá trị gia tăng số 31/2013/QH13 ngày 19/06/2013; \n + Luật Quản lý thuế số 78/2006/QH10 ngày 29/11/2006; Luật sửa đổi, bổ sung một số điều của Luật quản lý thuế 21/2012/QH13 ngày 20/11/2012; \n + Nghị định số 83/2013/NĐ-CP ngày 22 tháng 7 năm 2013 của Chính phủ quy định chi tiết thi hành một số điều của Luật quản lý thuế và Luật sửa đổi, bổ sung một số điều của Luật quản lý thuế; \n + Nghị định số 209/2013/NĐ-CP ngày 18/12/2013 của Chính phủ quy định chi tiết và hướng dẫn một số điều Luật thuế giá trị gia tăng; \n + Nghị định số 215/2013/NĐ-CP ngày 23 tháng 12 năm 2013 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 72/2014/TT-BTC ngày 30/5/2014 của Bộ Tài chính quy định về hoàn thuế giá trị gia tăng đối với hàng hóa của người nước ngoài, người Việt Nam định cư ở nước ngoài mang theo khi xuất cảnh. \n + Thông tư số 92/2019/TT-BTC ngày 31/12/2019 của Bộ Tài chính sửa đổi, bổ sung Thông tư số 72/2014/TT-BTC ngày 30/5/2014 của Bộ Tài chính quy định về hoàn thuế giá trị gia tăng đối với hàng hóa của người nước ngoài, người Việt Nam định cư ở nước ngoài mang theo khi xuất cảnh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008567"}, {"ma": "1.007026", "ten": "Khai thuế thu nhập doanh nghiệp tính theo tỷ lệ % trên doanh thu", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế thu nhập doanh nghiệp tính thuế theo phương pháp tỷ lệ % trên doanh thu bán hàng hóa dịch vụ theo quy định của pháp luật về thuế thu nhập doanh nghiệp chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp. Người nộp thuế thu nhập doanh nghiệp tính thuế theo phương pháp tỷ lệ % trên doanh thu bán hàng hóa dịch vụ theo quy định của pháp luật về thuế thu nhập doanh nghiệp thực hiện tạm nộp thuế theo quý chậm nhất là ngày 30 của tháng đầu quý sau và khai quyết toán thuế thu nhập doanh nghiệp năm chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính đối với trường hợp khai quyết toán thuế thu nhập doanh nghiệp năm; chậm nhất là ngày thứ 45 (bốn mươi lăm), kể từ ngày có quyết định giải thể, phá sản, chấm dứt hoạt động hoặc tổ chức lại doanh nghiệp. Trường hợp chuyển đổi loại hình doanh nghiệp (không bao gồm doanh nghiệp nhà nước cổ phần hóa) mà doanh nghiệp chuyển đổi kế thừa toàn bộ nghĩa vụ về thuế của doanh nghiệp được chuyển đổi thì không phải khai quyết toán thuế đến thời điểm có quyết định về việc chuyển đổi doanh nghiệp, doanh nghiệp khai quyết toán khi kết thúc năm. Trường hợp người nộp thuế không phát sinh thường xuyên hoạt động kinh doanh hàng hoá, dịch vụ thuộc đối tượng chịu thuế thu nhập doanh nghiệp thì thực hiện kê khai thuế thu nhập doanh nghiệp theo từng lần phát sinh chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế và không phải khai quyết toán năm.\n ++ Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN), để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n ++ Trường hợp NNT nộp hồ sơ trực tiếp/bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh hoặc qua Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n +++ Kiểm tra, chấp nhận hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành. Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp hoặc gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC), gồm:\n ++ Hồ sơ khai quyết toán thuế theo năm:\n +++ Tờ khai thuế thu nhập doanh nghiệp (áp dụng đối với phương pháp tỷ lệ trên doanh thu) theo mẫu số 04/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC.\n +++ Báo cáo tài chính năm hoặc Báo cáo tài chính đến thời điểm có quyết định giải thể, phá sản, chấm dứt hoạt động hoặc tổ chức lại doanh nghiệp theo quy định của pháp luật về kế toán và pháp luật về kiểm toán độc lập (trừ trường hợp không phải lập báo cáo tài chính theo quy định).\n ++ Hồ sơ khai thuế theo từng lần phát sinh: Tờ khai thuế thu nhập doanh nghiệp (áp dụng đối với phương pháp tỷ lệ trên doanh thu) theo mẫu số 04/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC.\n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019 sửa đổi, bổ sung tại Luật số 56/2024/QH15 ngày 29/11/2024 của Quốc hội sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính;\n + Luật Thuế thu nhập doanh nghiệp ngày 03/6/2008 và các văn bản pháp luật quy định chi tiết, hướng dẫn thi hành và sửa đổi, bổ sung có liên quan;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế; + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["04/TNDN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007026"}, {"ma": "1.007037", "ten": "Hoàn thuế giá trị gia tăng của doanh nghiệp, tổ chức", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) thuộc trường hợp và đối tượng được hoàn thuế giá trị gia tăng đối với dự án đầu tư chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "1. Hoàn thuế giá trị gia tăng đối với dự án đầu tư \n + Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Bản sao Giấy chứng nhận đăng ký đầu tư hoặc giấy chứng nhận đầu tư hoặc giấy phép đầu tư đối với trường hợp phải làm thủ tục cấp giấy chứng nhận đăng ký đầu tư; \n + Đối với dự án có công trình xây dựng: Bản sao Giấy chứng nhận quyền sử dụng đất hoặc quyết định giao đất hoặc hợp đồng cho thuê đất của cơ quan có thẩm quyền; giấy phép xây dựng; \n + Bản sao Chứng từ góp vốn điều lệ; \n + Bản sao Giấy phép kinh doanh ngành, nghề đầu tư kinh doanh có điều kiện; Giấy chứng nhận đủ điều kiện kinh doanh ngành, nghề đầu tư kinh doanh có điều kiện; Văn bản của cơ quan nhà nước có thẩm quyền cho phép đầu tư kinh doanh ngành, nghề đầu tư kinh doanh có điều kiện theo quy định. \n + Quyết định thành lập Ban Quản lý dự án, Quyết định giao quản lý dự án đầu tư của chủ dự án đầu tư, Quy chế tổ chức và hoạt động của chi nhánh hoặc Ban quản lý dự án đầu tư (nếu chi nhánh, Ban quản lý dự án thực hiện hoàn thuế). \n Đối với NNT chưa gửi hóa đơn điện tử đến cơ quan thuế thì NNT phải nộp thêm: Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n 2. Hoàn thuế giá trị gia tăng đối với hàng hóa, dịch vụ xuất khẩu \n + Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT; \n + Danh sách tờ khai hải quan đã thông quan mẫu số 01-2/HT. \n Trường hợp NNT chưa gửi hóa đơn điện tử đến cơ quan thuế thì NNT phải nộp thêm Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n 3. Hoàn thuế giá trị gia tăng theo quyết định của cơ quan có thẩm quyền theo quy định của pháp luậ \n + Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định của cơ quan có thẩm quyền.", "ket_qua": "+ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế mẫu số 01/QĐHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp NNT lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 48/2024/QH15; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/HT", "01-2/HT", "01/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007037"}, {"ma": "1.008498", "ten": "Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân, người phụ thuộc", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh không thuộc đối tượng đăng ký kinh doanh qua cơ quan đăng ký kinh doanh.\n + Đối tượng thực hiện thủ tục hành chính: Hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh không thuộc đối tượng đăng ký kinh doanh qua cơ quan đăng ký kinh doanh.\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với ngân sách nhà nước (trừ cá nhân kinh doanh) - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Đối tượng thực hiện thủ tục hành chính: Cơ quan chi trả thu nhập\n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với NSNN (trừ cá nhân kinh doanh) - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế. \n + Đối tượng thực hiện thủ tục hành chính: Cá nhân.\n (iv) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Đối tượng thực hiện thủ tục hành chính: Cơ quan chi trả thu nhập.\n (v) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế.\n + Đối tượng thực hiện thủ tục hành chính: Cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh không thuộc đối tượng đăng ký kinh doanh qua cơ quan đăng ký kinh doanh.\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày: Bắt đầu hoạt động kinh doanh, người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định gửi đến Thuế cơ sở để làm thủ tục đăng ký thuế theo nơi nộp hồ sơ như sau:\n ++ Tại Thuế cơ sở nơi đặt địa điểm kinh doanh trong trường hợp hộ gia đình, cá nhân kinh doanh có địa điểm kinh doanh cố định, hoặc nơi cá nhân có bất động sản cho thuê.\n ++ Tại Thuế cơ sở nơi cư trú của cá nhân kinh doanh trong trường hợp cá nhân kinh doanh không có địa điểm kinh doanh cố định.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ gửi đến cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với ngân sách nhà nước (trừ cá nhân kinh doanh) - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Bước 1: Cá nhân có ủy quyền cho cơ quan chi trả thu nhập đăng ký thuế gửi hồ sơ cho cơ quan chi trả thu nhập. Trường hợp cá nhân nộp thuế thu nhập cá nhân tại nhiều cơ quan chi trả thu nhập trong cùng một kỳ nộp thuế, cá nhân chỉ uỷ quyền đăng ký thuế tại một cơ quan chi trả thu nhập và thông báo số định danh cá nhân của cá nhân (đối với người Việt Nam) hoặc mã số thuế đã được cấp (đối với người nước ngoài) với các cơ quan chi trả thu nhập khác để sử dụng vào việc khấu trừ, kê khai, nộp thuế.\n Cơ quan chi trả thu nhập tổng hợp và gửi tờ khai đăng ký thuế mẫu số 05-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính chậm nhất là 10 ngày làm việc kể từ ngày phát sinh nghĩa vụ thuế trong trường hợp cá nhân chưa có mã số thuế, gửi cơ quan thuế quản lý trực tiếp cơ quan chi trả thu nhập để đăng ký thuế thay cho cá nhân có uỷ quyền.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ gửi đến cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với NSNN (trừ cá nhân kinh doanh) - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế. \n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày: Phát sinh nghĩa vụ thuế thu nhập cá nhân hoặc phát sinh nghĩa vụ khác với ngân sách nhà nước, người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định, gửi đến cơ quan thuế để làm thủ tục đăng ký thuế theo nơi nộp hồ sơ như sau:\n ++ Tại Thuế tỉnh, thành phố nơi cá nhân làm việc đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công do các tổ chức Quốc tế, Đại sứ quán, Lãnh sự quán tại Việt Nam chi trả nhưng tổ chức này chưa thực hiện khấu trừ thuế;\n ++ Tại Thuế tỉnh, thành phố nơi phát sinh công việc tại Việt Nam đối với cá nhân có thu nhập từ tiền lương, tiền công do các tổ chức, cá nhân trả từ nước ngoài;\n ++ Tại Thuế cơ sở nơi cá nhân cư trú đối với những trường hợp khác.\n ++ Tại Thuế cơ sở nơi hộ gia đình, cá nhân có phát sinh nghĩa vụ với ngân sách nhà nước đối với cá nhân đăng ký thuế thông qua hồ sơ khai thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ gửi đến cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iv) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Bước 1: Cá nhân có ủy quyền cho cơ quan chi trả thu nhập đăng ký thuế cho người phụ thuộc gửi hồ sơ cho cơ quan chi trả thu nhập; Trường hợp cá nhân nộp thuế thu nhập cá nhân tại nhiều cơ quan chi trả thu nhập trong cùng một kỳ nộp thuế, cá nhân chỉ uỷ quyền đăng ký thuế tại một cơ quan chi trả thu nhập và thông báo số định danh cá nhân của người phụ thuộc (đối với người Việt Nam) hoặc mã số thuế đã được cấp cho người phụ thuộc (đối với người nước ngoài) với các cơ quan chi trả thu nhập khác để sử dụng vào việc khấu trừ, kê khai, nộp thuế.\n Cơ quan chi trả thu nhập có trách nhiệm tổng hợp và gửi tờ khai đăng ký thuế mẫu số 20-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính chính chậm nhất là 10 ngày làm việc kể từ ngày người nộp thuế đăng ký giảm trừ gia cảnh theo quy định của pháp luật trong trường hợp người phụ thuộc chưa có mã số thuế gửi cơ quan thuế quản lý trực tiếp cơ quan chi trả thu nhập để đăng ký thuế thay cho người phụ thuộc có ủy quyền.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ gửi đến cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (v) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế.\n + Bước 1: Cá nhân lập hồ sơ đăng ký thuế cho người phụ thuộc để giảm trừ gia cảnh và gửi đến cơ quan thuế để làm thủ tục đăng ký thuế theo nơi nộp hồ sơ như sau:\n ++ Tại Thuế tỉnh, thành phố nơi cá nhân làm việc đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công do các tổ chức Quốc tế, Đại sứ quán, Lãnh sự quán tại Việt Nam chi trả nhưng tổ chức này chưa thực hiện khấu trừ thuế;\n ++ Tại Thuế tỉnh, thành phố nơi phát sinh công việc tại Việt Nam đối với cá nhân có thu nhập từ tiền lương, tiền công do các tổ chức, cá nhân trả từ nước ngoài;\n ++ Tại Thuế cơ sở nơi cá nhân cư trú đối với những trường hợp khác.\n Thời hạn nộp hồ sơ đăng ký thuế cho người phụ thuộc để giảm trừ gia cảnh cùng với thời hạn thực hiện thủ tục đăng ký giảm trừ gia cảnh theo quy định của pháp luật thuế thu nhập cá nhân.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ gửi đến cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thôn", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh không thuộc đối tượng đăng ký kinh doanh qua cơ quan đăng ký kinh doanh.\n + Thành phần hồ sơ, gồm:\n ++ Đối với hộ gia đình, cá nhân có hoạt động kinh doanh là người Việt Nam:\n +++ Tờ khai đăng ký thuế mẫu số 03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hoặc hồ sơ khai thuế của hộ kinh doanh, cá nhân kinh doanh theo quy định của pháp luật về quản lý thuế.\n ++ Đối với cá nhân là người có quốc tịch nước ngoài:\n +++ Tờ khai đăng ký thuế mẫu số 03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hoặc hồ sơ khai thuế của hộ kinh doanh, cá nhân kinh doanh theo quy định của pháp luật về quản lý thuế;\n +++ Bản sao Hộ chiếu còn hiệu lực của cá nhân. Trường hợp cá nhân đã đăng ký và kích hoạt tài khoản định danh điện tử Mức độ 2 theo quy định tại khoản 2 Điều 10, khoản 2 Điều 11 và Điều 14 Nghị định số 69/2024/NĐ-CP để thực hiện thủ tục đăng ký thuế với cơ quan thuế thì không phải nộp bản sao hộ chiếu nếu đã được tích hợp vào tài khoản định danh điện tử.\n ++ Đối với hoặc cá nhân là người có quốc tịch Việt Nam sinh sống tại nước ngoài, cá nhân kinh doanh của các nước có chung đường biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu:\n +++ Tờ khai đăng ký thuế mẫu số 03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hoặc hồ sơ khai thuế của hộ kinh doanh, cá nhân kinh doanh theo quy định của pháp luật về quản lý thuế;\n +++ Bản sao giấy tờ có giá trị sử dụng đối với cá nhân kinh doanh thực hiện hoạt động mua bán, trao đổi hàng hoá tại chợ biên giới theo quy định tại Điều 16 Nghị định số 14/2018/NĐ-CP ngày 23/01/2018 của Chính phủ quy định chi tiết về hoạt động thương mại biên giới. Trường hợp cá nhân đã đăng ký và kích hoạt tài khoản định danh điện tử Mức độ 2 theo quy định tại khoản 2 Điều 10, khoản 2 Điều 11 và Điều 14 Nghị định số 69/2024/NĐ-CP để thực hiện thủ tục đăng ký thuế với cơ quan thuế thì không phải nộp bản sao hộ chiếu nếu đã được tích hợp vào tài khoản định danh điện tử.\n + Số lượng hồ sơ: 01 (bộ).\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với ngân sách nhà nước (trừ cá nhân kinh doanh) - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Thành phần hồ sơ, gồm:\n ++ Hồ sơ đăng ký thuế của cá nhân gồm gửi cho cơ quan chi trả thu nhập: Văn bản ủy quyền Mẫu số 41/UQ-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; bản sao Hộ chiếu còn hiệu lực đối với cá nhân là người có quốc tịch nước ngoài hoặc người có quốc tịch Việt Nam sinh sống tại nước ngoài) cho cơ quan chi trả thu nhập.\n ++ Cơ quan chi trả thu nhập có trách nhiệm tổng hợp thông tin đăng ký thuế của cá nhân vào tờ khai đăng ký thuế mẫu số 05-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi cơ quan thuế quản lý trực tiếp cơ quan chi trả thu nhập.\n + Số lượng hồ sơ: 01 (bộ). \n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với NSNN (trừ cá nhân kinh doanh) - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế. \n + Thành phần hồ sơ gồm:\n ++ Đối với cá nhân là người Việt Nam: Tờ khai đăng ký thuế mẫu số 05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hoặc hồ sơ khai thuế theo quy định của pháp luật về quản lý thuế trong trường hợp cá nhân đăng ký thuế thông qua hồ sơ khai thuế.\n ++ Đối với cá nhân là người có quốc tịch nước ngoài hoặc là người có quốc tịch Việt Nam sinh sống tại nước ngoài không có số định danh cá nhân được xác lập từ Cơ sở dữ liệu quốc gia về dân cư: \n +++ Tờ khai đăng ký thuế mẫu số 05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hoặc hồ sơ khai thuế theo quy định của pháp luật về quản lý thuế trong trường hợp cá nhân đăng ký thuế thông qua hồ sơ khai thuế.\n +++ Bản sao Hộ chiếu còn hiệu lực của cá nhân. Trường hợp cá nhân đã đăng ký và kích hoạt tài khoản định danh điện tử Mức độ 2 theo quy định tại khoản 2 Điều 10, khoản 2 Điều 11 và Điều 14 Nghị định số 69/2024/NĐ-CP để thực hiện thủ tục đăng ký thuế với cơ quan thuế thì không phải nộp bản sao hộ chiếu nếu đã được tích hợp vào tài khoản định danh điện tử.\n +++ Bản sao văn bản bổ nhiệm của Tổ chức sử dụng lao động trong trường hợp cá nhân người nước ngoài không cư trú tại Việt Nam theo quy định của pháp luật về thuế thu nhập cá nhân được cử sang Việt Nam làm việc nhưng nhận thu nhập tại nước ngoài.\n + Số lượng hồ sơ: 01 (bộ).\n (iv) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Thành phần hồ sơ gồm:\n ++ Hồ sơ đăng ký thuế của cá nhân gồm gửi cho cơ quan chi trả thu nhập: Văn bản ủy quyền Mẫu số 41/UQ-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; Bản sao Hộ chiếu còn hiệu lực của người phụ thuộc hoặc bản sao giấy tờ chứng thực cá nhân hợp pháp khác còn hiệu lực (nếu không có hộ chiếu) đối với người phụ thuộc là người có quốc tịch nước ngoài hoặc người có quốc tịch Việt Nam sinh sống tại nước ngoài) cho cơ quan chi trả thu nhập. \n ++ Cơ quan chi trả thu nhập có trách nhiệm tổng hợp thông tin đăng ký thuế của cá nhân vào tờ khai đăng ký thuế mẫu số 20-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi cơ quan thuế quản lý trực tiếp cơ quan chi trả thu nhập.\n +++ Phụ lục bảng kê khai về người phải trực tiếp nuôi dưỡng mẫu số 07/XN-NPT-TNCN tại văn bản quy phạm pháp luật quy định về đăng ký thuế;\n +++ Hồ sơ chứng minh NPT theo hướng dẫn tại điều 1 Thông tư số 79/2022/TT-BTC ngày 30/12/2022 của Bộ Tài chính \n + Số lượng hồ sơ: 01 (bộ).\n (v) Đăng ký thuế lần đầu cho người phụ thuộc để giảm trừ gia cảnh của người nộp thuế thu nhập cá nhân - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế.\n + Thành phần hồ sơ gồm:\n ++ Đối với người phụ thuộc là người Việt Nam: \n +++ Tờ khai đăng ký thuế mẫu số 20-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++ Phụ lục bảng kê khai về người phải trực tiếp nuôi dưỡng mẫu số 07/XN-NPT-TNCN tại văn bản quy phạm pháp luật quy định về đăng ký thuế;\n +++ Hồ sơ chứng minh NPT theo hướng dẫn tại điều 1 Thông tư số 79/2022/TT-BTC ngày 30/12/2022 của Bộ Tài chính \n ++ Đối với người phụ thuộc là người nước ngoài: \n +++ Tờ khai đăng ký thuế mẫu số 20-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++ Bản sao Hộ chiếu còn hiệu lực của người phụ thuộc hoặc bản sao giấy tờ chứng thực cá nhân hợp pháp khác còn hiệu lực (nếu không có hộ chiếu).\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "(i) - Kết quả thực hiện thủ tục hành chính: Giấy chứng nhận đăng ký thuế. (ii)- Kết quả thực hiện thủ tục hành chính: Thông báo mã số thuế cá nhân mẫu số 14-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. (iii) - Kết quả thực hiện thủ tục hành chính: + Đối với cá nhân Việt Nam: Được sử dụng số định danh cá nhân thay cho MST nếu thông tin đăng ký thuế khớp đúng với thông tin trong Cơ sở dữ liệu quốc gia về dân cư; Thông báo MST cá nhân do cơ quan thuế cấp được sử dụng đến hết ngày 30/6/2025. + Đối với cá nhân nước ngoài: Thông báo mã số thuế cá nhân. (iv) - Kết quả thực hiện thủ tục hành chính: + Đối với cá nhân Việt Nam: Được sử dụng số định danh cá nhân thay cho MST nếu thông tin đăng ký thuế khớp đúng với thông tin trong Cơ sở dữ liệu quốc gia về dân cư; Thông báo MST cá nhân do cơ quan thuế cấp được sử dụng đến hết ngày 30/6/2025. + Đối với cá nhân nước ngoài: Thông báo mã số thuế cá nhân. (v) - Kết quả thực hiện thủ tục hành chính: + Đối với cá nhân Việt Nam: Được sử dụng số định danh cá nhân thay cho MST nếu thông tin đăng ký thuế khớp đúng với thông tin trong Cơ sở dữ liệu quốc gia về dân cư; Thông báo MST cá nhân do cơ quan thuế cấp được sử dụng đến hết ngày 30/6/2025. + Đối với cá nhân nước ngoài: Thông báo mã số thuế cá nhân.", "dieu_kien": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh không thuộc đối tượng đăng ký kinh doanh qua cơ quan đăng ký kinh doanh.\n + Kết quả thực hiện thủ tục hành chính: Giấy chứng nhận đăng ký thuế.\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với ngân sách nhà nước (trừ cá nhân kinh doanh) - Trường hợp cá nhân ủy quyền đăng ký thuế cho cơ quan chi trả thu nhập.\n + Kết quả thực hiện thủ tục hành chính: Thông báo mã số thuế cá nhân mẫu số 14-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là cá nhân có thu nhập thuộc diện chịu thuế thu nhập cá nhân hoặc có nghĩa vụ với NSNN (trừ cá nhân kinh doanh) - Trường hợp cá nhân đăng ký thuế trực tiếp với cơ quan thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03-ĐK-TCT", "05-ĐK-TCT", "05-ĐK-TH-TCT", "07/XN-NPT-TNCN", "20-ĐK-TCT", "20-ĐK-TH-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008498"}, {"ma": "1.008526", "ten": "Khai cổ tức, lợi nhuận được chia cho phần vốn nhà nước tại công ty cổ phần, công ty trách nhiệm hữu hạn hai thành viên trở lên", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "công ty cổ phần, công ty trách nhiệm hữu hạn 2 thành viên trở lên có vốn nhà nước nhà nước do Bộ, cơ quan ngang Bộ, cơ quan trực thuộc Chính phủ, địa phương làm đại diện chủ sở hữu.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế, chậm nhất là ngày thứ 10 (mười) kể từ ngày phát sinh nghĩa vụ nộp cổ tức, lợi nhuận (ngày được nhận cổ tức, lợi nhuận) được chia cho phần vốn nhà nước tại công ty cổ phần, công ty trách nhiệm hữu hạn hai thành viên trở.\n + Bước 2 : Cơ quan thuế thực hiện tiếp nhận:\n ++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n Thành phần hồ sơ, gồm: Tờ khai cổ tức được chia cho phần vốn nhà nước tại công ty cổ phần, công ty trách nhiệm hữu hạn 2 thành viên trở lên có vốn nhà nước Mẫu số 01/CTLNĐC ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật Quản lý, sử dụng vốn nhà nước đầu tư vào sản xuất, kinh doanh tại doanh nghiệp số 69/2014/QH13 ngày 26 tháng 11 năm 2014; Luật số 68/2025/QH15 ngày 14/6/2025 về quản lý và đầu tư vốn nhà nước tại doanh nghiệp; \n + Nghị định số 91/2015/NĐ-CP ngày 13 tháng 10 năm 2015 của Chính phủ về đầu tư vốn nhà nước vào doanh nghiệp và quản lý, sử dụng vốn, tài sản tại doanh nghiệp; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008526"}, {"ma": "1.008570", "ten": "Khai miễn thuế thu nhập cá nhân đối với cá nhân là người Việt Nam làm việc tại cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Người nộp thuế chuẩn bị hồ sơ miễn thuế TNCN theo hướng dẫn tại Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam gửi hồ sơ miễn thuế đến Bộ Ngoại giao (Cục Lễ tân Nhà nước và Phiên dịch đối ngoại).\n Thời hạn nộp hồ sơ:\n ++ Tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam mới thành lập văn phòng đại diện tại Việt Nam gửi hồ sơ miễn thuế trong vòng 30 ngày kể từ ngày Người đứng đầu của tổ chức này trình Ủy nhiệm thư lên đại diện có thẩm quyền của Việt Nam.\n ++ Tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam đã có văn phòng đại diện tại Việt Nam trước ngày Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính có hiệu lực thi hành chưa gửi hồ sơ miễn thuế thu nhập cá nhân thì gửi hồ sơ miễn thuế thu nhập cá nhân theo hướng dẫn tại Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính trong vòng 30 ngày kể từ ngày Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính có hiệu lực thi hành. \n ++ Trường hợp cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam tuyển dụng mới hoặc chấm dứt hợp đồng lao động đối với Nhân viên Việt Nam thì gửi hồ sơ miễn thuế đối với Nhân viên Việt Nam có thay đổi chậm nhất là ngày thứ 20 của tháng tiếp theo liền kề tháng có phát sinh thay đổi.\n Bộ Ngoại giao (Cục Lễ tân Nhà nước và Phiên dịch đối ngoại) có trách nhiệm kiểm tra, xác nhận và gửi Danh sách Nhân viên Việt Nam được miễn thuế thu nhập cá nhân (theo mẫu số 01/DSMT-LHQ ban hành kèm theo Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính) hoặc Danh sách thay đổi Nhân viên Việt Nam được miễn thuế thu nhập cá nhân (theo mẫu số 02/TĐDSMT-LHQ ban hành kèm theo Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính) đến Thuế tỉnh/TP tỉnh, thành phố trực thuộc Trung ương nơi đặt văn phòng cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam để hoàn thành thủ tục miễn thuế, trong vòng 05 ngày làm việc kể từ ngày nhận được đầy đủ hồ sơ miễn thuế.\n + Bước 2. Cơ quan thuế thực hiện tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ khai thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "+ Thành phần hồ sơ : \n ++ Hồ sơ miễn thuế bao gồm: \n +++ Công hàm của cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam, kèm theo Danh sách Nhân viên Việt Nam được miễn thuế thu nhập cá nhân (theo mẫu số 01/DSMT-LHQ ban hành kèm theo Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính). \n +++ Bản sao Hợp đồng lao động. \n ++ Hồ sơ miễn thuế đối với trường hợp có thay đổi về Nhân viên Việt Nam do tuyển dụng mới hoặc chấm dứt hợp đồng bao gồm: \n +++ Công hàm của cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam, kèm theo Danh sách thay đổi Nhân viên Việt Nam được miễn thuế thu nhập cá nhân (theo mẫu số 02/TĐDSMT - LHQ ban hành kèm theo Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính); \n +++ Bản sao Hợp đồng lao động (đối với Nhân viên Việt Nam tuyển dụng mới). \n + Số lượng hồ sơ: 02 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan Thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14; \n +Quyết định số 07/2016/QĐ-TTg ngày 22/02/2016 của Thủ tướng Chính phủ về việc miễn thuế thu nhập cá nhân đối với cá nhân là người Việt Nam làm việc tại cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 97/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính hướng dẫn hồ sơ, thủ tục miễn thuế thu nhập cá nhân đối với cá nhân là người Việt Nam làm việc tại cơ quan đại diện của tổ chức quốc tế thuộc hệ thống Liên hợp quốc tại Việt Nam. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/DSMT-LHQ", "02/TĐDSMT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008570"}, {"ma": "1.008571", "ten": "Khai miễn thuế thu nhập cá nhân đối với Chuyên gia nước ngoài thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Cơ quan chủ quản hoặc Chủ Khoản viện trợ phi Chính phủ nước ngoài.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Chậm nhất là ngày thứ 30 kể từ ngày Hợp đồng Chuyên gia nước ngoài có hiệu lực hoặc khi có thay đổi Chuyên gia nước ngoài so với Xác nhận chuyên gia nước ngoài và đề nghị miễn thuế thu nhập cá nhân đã gửi cơ quan thuế, người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế.\n Nơi nộp hồ sơ miễn thuế\n ++ Trường hợp Chuyên gia nước ngoài ký hợp đồng với Cơ quan chủ quản: Nơi nộp hồ sơ miễn thuế là Thuế tỉnh/TP tỉnh, thành phố trực thuộc Trung ương nơi Cơ quan chủ quản đặt trụ sở.\n ++ Trường hợp Chuyên gia nước ngoài ký hợp đồng với Tổ chức phi Chính phủ nước ngoài hoặc ký hợp đồng với Chủ Khoản viện trợ phi Chính phủ nước ngoài: Nơi nộp hồ sơ miễn thuế là Thuế tỉnh/TP tỉnh, thành phố trực thuộc Trung ương nơi Chủ Khoản viện trợ phi Chính phủ nước ngoài đặt trụ sở.\n + Bước 2. Cơ quan thuế thực hiện tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ khai thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Xác nhận Chuyên gia nước ngoài và đề nghị miễn thuế thu nhập cá nhân theo mẫu số 01/XNCG-ĐNMT ban hành kèm theo Thông tư số 96/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính; \n ++ Bản sao Quyết định phê duyệt chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam. \n ++ Bản sao Văn kiện chương trình, dự án được cơ quan có thẩm quyền của Việt Nam phê duyệt. \n ++ Bản sao hợp đồng ký giữa Chuyên gia nước ngoài với Tổ chức phi Chính phủ nước ngoài hoặc với Cơ quan chủ quản hoặc với Chủ khoản viện trợ phi Chính phủ nước ngoài. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Xác nhận miễn thuế thu nhập cá nhân đối với thu nhập từ việc thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài theo mẫu số 02/XNMT hoặc thông báo về việc không đủ điều kiện được miễn thuế theo mẫu số 03/TB-KMT ban hành kèm theo Thông tư số 96/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính.", "dieu_kien": "trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế thu nhập cá nhân số 04/2007/QH12 ngày 21/11/2007; Luật sửa đổi, bổ sung một số điều của Luật thuế thu nhập cá nhân số 26/2012/QH13 ngày 22/11/2012 các Nghị định của Chính phủ quy định chi tiết thi hành; \n + Luật Quản lý thuế số 38/2019/QH14; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Nghị định 58/2022/NĐ-CP ngày 31/8/2022 của Chính phủ về đăng ký và quản lý hoạt động của các tổ chức phi chính phủ nước ngoài tại Việt Nam; \n + Nghị định 313/2025/NĐ-CP ngày 15/8/2025 của Chính phủ về quản lý và sử dụng viện trợ không hoàn lại không thuộc hỗ trợ phát triển chính thức của cơ quan, tổ chức, cá nhân nước ngoài dành cho Việt Nam; \n + Nghị định 29/2025/NĐ-CP ngày 24/02/2025 của Chính phủ ban hành quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Quyết định số 06/2016/QĐ-TTg ngày 22/02/2016 của Thủ tướng Chính phủ về việc miễn thuế thu nhập cá nhân đối với chuyên gia nước ngoài thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam; \n + Thông tư số 96/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính hướng dẫn hồ sơ, thủ tục miễn thuế thu nhập cá nhân đối với Chuyên gia nước ngoài thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/XNCG-ĐNMT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008571"}, {"ma": "1.008335", "ten": "Khai thuế thu nhập doanh nghiệp đối với hoạt động chuyển nhượng bất động sản, khai thuế thu nhập doanh nghiệp từ hoạt động bán toàn bộ Công ty TNHH một thành viên do tổ chức làm chủ sở hữu dưới hình thức chuyển nhượng vốn có gắn với bất động sản theo lần phát sinh", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế thu nhập doanh nghiệp tính thuế theo phương pháp tỷ lệ % trên doanh thu bán hàng hóa dịch vụ theo quy định của pháp luật về thuế thu nhập doanh nghiệp có phát sinh thu nhập từ hoạt động chuyển nhượng bất động sản, thuế thu nhập doanh nghiệp từ hoạt động bán toàn bộ Công ty TNHH một thành viên do tổ chức làm chủ sở hữu dưới hình thức chuyển nhượng vốn có gắn với bất động sản chuẩn bị số liệu, lập hồ sơ khai thuế theo lần phát sinh và gửi đến cơ quan thuế nơi có bất động sản được chuyển nhượng chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế.\n ++ Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN), để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp hoặc gửi qua đường bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh hoặc qua Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành. Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp hoặc gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua cổng Dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC), gồm: \n ++ Khai thuế thu nhập doanh nghiệp đối với hoạt động chuyển nhượng bất động sản theo từng lần phát sinh: Tờ khai thuế thu nhập doanh nghiệp (áp dụng đối với hoạt động chuyển nhượng bất động sản theo từng lần phát sinh) theo mẫu số 02/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC. \n Hoặc \n ++ Khai thuế thu nhập doanh nghiệp từ hoạt động bán toàn bộ Công ty TNHH một thành viên do tổ chức làm chủ sở hữu dưới hình thức chuyển nhượng vốn có gắn với bất động sản theo từng lần phát sinh: Tờ khai thuế thu nhập doanh nghiệp (áp dụng đối với hoạt động bán toàn bộ Công ty TNHH một thành viên do tổ chức làm chủ sở hữu dưới hình thức chuyển nhượng vốn có gắn với bất động sản) theo mẫu số 06/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019 sửa đổi, bổ sung tại Luật số 56/2024/QH15 ngày 29/11/2024 của Quốc hội sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính; \n + Luật Thuế thu nhập doanh nghiệp ngày 03/6/2008 và các văn bản pháp luật quy định chi tiết, hướng dẫn thi hành và sửa đổi, bổ sung có liên quan; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/TNDN", "06/TNDN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008335"}, {"ma": "1.008510", "ten": "Khôi phục mã số thuế", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Doanh nghiệp, hợp tác xã, tổ chức kinh tế, tổ chức khác, hộ kinh doanh.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế thuộc các trường hợp khôi phục mã số thuế theo quy định tại Điểm a, b, c, d Khoản 1 Điều 18, khoản 2 Điều 33 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính, lập hồ sơ và gửi đến cơ quan thuế quản lý trực tiếp để được khôi phục mã số thuế trong thời hạn như sau:\n ++ Người nộp thuế quy định tại Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính bị cơ quan có thẩm quyền thu hồi Giấy phép thành lập và hoạt động hoặc Giấy phép tương đương, cơ quan thuế đã chấm dứt hiệu lực mã số thuế theo quy định, nhưng sau đó cơ quan có thẩm quyền có văn bản hủy bỏ văn bản thu hồi thì người nộp thuế nộp hồ sơ đề nghị khôi phục mã số thuế đến cơ quan thuế quản lý trực tiếp chậm nhất là 10 (mười) ngày làm việc kể từ ngày cơ quan có thẩm quyền ban hành văn bản hủy bỏ văn bản thu hồi;\n ++ Sau khi cơ quan thuế có Thông báo về việc người nộp thuế không hoạt động tại địa chỉ đã đăng ký nhưng người nộp thuế chưa bị thu hồi Giấy chứng nhận đăng ký doanh nghiệp, Giấy chứng nhận đăng ký hợp tác xã, Giấy chứng nhận đăng ký hoạt động của chi nhánh, văn phòng đại diện, Giấy chứng nhận đăng ký hộ kinh doanh, Giấy phép thành lập và hoạt động hoặc Giấy phép tương đương và chưa bị chấm dứt hiệu lực mã số thuế thì người nộp thuế nộp Văn bản đề nghị khôi phục mã số thuế mẫu số 25/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính đến cơ quan thuế quản lý trực tiếp trước ngày cơ quan thuế ban hành Thông báo về việc chấm dứt hiệu lực mã số thuế theo quy định. \n ++ Người nộp thuế quy định tại Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính khi có nhu cầu tiếp tục hoạt động kinh doanh sau khi đã nộp hồ sơ chấm dứt hiệu lực mã số thuế gửi đến cơ quan thuế nhưng cơ quan thuế chưa ban hành Thông báo về việc chấm dứt hiệu lực mã số thuế theo quy định tại Điều 14, Điều 16 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính thì người nộp thuế nộp Văn bản đề nghị khôi phục mã số thuế mẫu số 25/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính đến cơ quan thuế quản lý trực tiếp trước ngày cơ quan thuế ban hành Thông báo về việc chấm dứt hiệu lực mã số thuế;\n ++ Doanh nghiệp, hợp tác xã, đơn vị phụ thuộc của doanh nghiệp, đơn vị phụ thuộc của hợp tác xã đã nộp hồ sơ chấm dứt hiệu lực mã số thuế do bị chia, bị hợp nhất, bị sáp nhập, hoặc chấm dứt hoạt động đơn vị phụ thuộc đến cơ quan thuế theo quy định tại khoản 2 Điều 14 Thông tư này, sau đó có văn bản hủy Quyết định chia, hợp đồng sáp nhập, hợp đồng hợp nhất hoặc văn bản hủy quyết định chấm dứt hoạt động đơn vị phụ thuộc và người nộp thuế chưa nộp hồ sơ chấm dứt hoạt động đến cơ quan đăng ký kinh doanh thì người nộp thuế nộp hồ sơ đề nghị khôi phục mã số thuế đến cơ quan thuế quản lý trực tiếp.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công Cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n ++++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n ++++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n +++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n +++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Văn bản đề nghị khôi phục mã số thuế mẫu số 25/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++ Bản sao không cần chứng thực văn bản hủy bỏ văn bản thu hồi Giấy phép thành lập và hoạt động hoặc Giấy phép tương đương của cơ quan có thẩm quyền (đối với trường hợp tổ chức kinh tế, tổ chức khác đề nghị khôi phục mã số thuế do cơ quan có thẩm quyền có văn bản hủy bỏ văn bản thu hồi Giấy phép thành lập và hoạt động hoặc Giấy phép tương đương); \n ++ Bản sao văn bản hủy bỏ Quyết định chia, Hợp đồng sáp nhập, Hợp đồng hợp nhất; hoặc bản sao văn bản hủy quyết định chấm dứt hoạt động đơn vị phụ thuộc. (đối với trường hợp Doanh nghiệp, hợp tác xã, đơn vị phụ thuộc của doanh nghiệp, đơn vị phụ thuộc của hợp tác xã đã nộp hồ sơ chấm dứt hiệu lực mã số thuế do bị chia, bị hợp nhất, bị sáp nhập, hoặc chấm dứt hoạt động đơn vị phụ thuộc đến cơ quan thuế, sau đó có văn bản hủy Quyết định chia, hợp đồng sáp nhập, hợp đồng hợp nhất hoặc văn bản hủy quyết định chấm dứt hoạt động đơn vị phụ thuộc và người nộp thuế chưa nộp hồ sơ chấm dứt hoạt động đến cơ quan đăng ký kinh doanh). \n ++ Trường hợp người nộp thuế đã thay đổi địa chỉ trụ sở nhưng không đăng ký thay đổi thông tin với cơ quan thuế hoặc cơ quan đăng ký kinh doanh, người nộp thuế phải ghi địa chỉ trụ sở hiện tại và giải trình lý do trong văn bản đề nghị khôi phục mã số thuế, đồng thời nộp kèm hồ sơ thay đổi thông tin đăng ký thuế theo quy định (đối với NNT đề nghị khôi phục mã số thuế sau khi cơ quan thuế có Thông báo về việc người nộp thuế không hoạt động tại địa chỉ đã đăng ký). \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Trường hợp NNT được khôi phục MST: \n ++ Thông báo khôi phục mã số thuế mẫu số 19/TB- ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++ Thông báo về việc mã số thuế được khôi phục theo đơn vị chủ quản mẫu số 37/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu NNT được khôi phục MST là đơn vị chủ quản). \n ++ Giấy chứng nhận đăng ký thuế hoặc Thông báo mã số thuế cho người nộp thuế trong trường hợp người nộp thuế đã nộp bản gốc cho cơ quan thuế theo hồ sơ chấm dứt hiệu lực mã số thuế. \n + Trường hợp người nộp thuế không được khôi phục mã số thuế: \n ++ Thông báo về việc mã số thuế không được khôi phục mẫu số 38/TB- ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử, đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n +Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["25/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008510"}, {"ma": "1.008758", "ten": "Khai quyết toán thuế tài nguyên đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên (trừ Lô 09.1)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính; Chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc hợp đồng dầu khí.\n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai quyết toán thuế tài nguyên đối với dầu khí Mẫu số 02/TAIN - DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++ Phụ lục chi tiết nghĩa vụ thuế của các nhà thầu dầu khí Mẫu số 01/PL- DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Phụ lục sản lượng và doanh thu xuất bán dầu khí Mẫu số 02-1/PL-DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/202Ò/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 36/2016/TT-BTC ngày 26/02/2016 của Bộ Tài chính hướng dẫn thực hiện quy định về thuế đối với tổ chức, cá nhân tiến hành hoạt động tìm kiếm thăm dò và khai thác dầu khí theo quy định của Luật dầu khí; \n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tải chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008758"}, {"ma": "2.002321", "ten": "Đăng ký thuế đối với trường hợp chuyển đổi mô hình hoạt động của tổ chức (Chuyển đơn vị phụ thuộc thành đơn vị độc lập hoặc ngược lại)", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức kinh tế, tổ chức khác; đơn vị phụ thuộc của tổ chức kinh tế, tổ chức khác.", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "- Bước 1: \n + Trường hợp chuyển đơn vị phụ thuộc thành đơn vị độc lập hoặc ngược lại:\n ++ Đơn vị phụ thuộc có Quyết định chuyển thành đơn vị độc lập hoặc ngược lại thì đơn vị độc lập, đơn vị phụ thuộc sau chuyển đổi phải thực hiện thủ tục đăng ký thuế với cơ quan thuế để được cấp mã số thuế mới trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n +++ Tổ chức kinh tế và đơn vị phụ thuộc (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi đặt trụ sở.\n +++ Tổ hợp tác, tổ chức khác, đơn vị phụ thuộc theo quy định tại Điểm b,c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Thuế cơ sở nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n ++ Đơn vị độc lập, đơn vị phụ thuộc trước chuyển đổi phải nộp hồ sơ chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày chấm dứt hoạt động theo quyết định chuyển đổi.\n + Trường hợp chuyển đơn vị độc lập thành đơn vị phụ thuộc của một đơn vị chủ quản khác:\n ++ Đơn vị độc lập có quyết định chuyển đổi phải nộp hồ sơ chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày chấm dứt hoạt động theo quyết định chuyển đổi. \n ++ Đơn vị phụ thuộc sau chuyển đổi phải thực hiện thủ tục đăng ký thuế với cơ quan thuế để được cấp mã số thuế mới trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n +++ Đơn vị phụ thuộc của tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi đặt trụ sở.\n +++ Đơn vị phụ thuộc của tổ chức khác theo quy định tại Điểm c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Thuế cơ sở nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n Đơn vị chủ quản của đơn vị phụ thuộc sau chuyển đổi phải kê khai bổ sung đơn vị phụ thuộc mới thành lập với cơ quan thuế quản lý trực tiếp theo bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n + Trường hợp chuyển đơn vị phụ thuộc của một đơn vị chủ quản thành đơn vị phụ thuộc của một đơn vị chủ quản khác\n ++ Đơn vị phụ thuộc cũ phải nộp hồ sơ chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày chấm dứt hoạt động theo quyết định chuyển đổi.\n ++ Đơn vị phụ thuộc mới phải thực hiện thủ tục đăng ký thuế với cơ quan thuế để được cấp mã số thuế mới trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n +++ Đơn vị phụ thuộc của tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi đặt trụ sở.\n +++ Đơn vị phụ thuộc của tổ chức khác theo quy định tại Điểm c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Thuế tỉnh, TP nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Thuế cơ sở nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n Đơn vị chủ quản của đơn vị phụ thuộc sau chuyển đổi phải kê khai bổ sung đơn vị phụ thuộc mới thành lập với cơ quan thuế quản lý trực tiếp theo bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n + Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n++ Đối với đơn vị chủ quản, đơn vị độc lập mới thành lập sau chuyển đổi:\n+++ Tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024:\n++++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê góp vốn của tổ chức, cá nhân mẫu số BK06-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bản sao Giấy phép thành lập và hoạt động, hoặc Quyết định thành lập, hoặc văn bản tương đương do cơ quan có thẩm quyền cấp, hoặc Giấy chứng nhận đăng ký kinh doanh theo quy định của pháp luật của nước có chung biên giới (đối với tổ chức của nước có chung biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu của Việt Nam).\n+++ Tổ chức khác và tổ hợp tác theo quy định tại Điểm b, c, n Khoản 2 Điều 4 Thông tư số Thông tư số 86/2024/TT-BTC ngày 23/12/2024:\n++++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024;\n++++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bản sao Giấy phép thành lập và hoạt động, hoặc Quyết định thành lập, hoặc văn bản tương đương do cơ quan có thẩm quyền cấp, hoặc Giấy chứng nhận đăng ký kinh doanh theo quy định của pháp luật của nước có chung biên giới (đối với tổ chức của nước có chung biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu của Việt Nam).\n++ Đối với đơn vị phụ thuộc mới thành lập sau chuyển đổi:\n+++ Đối với đơn vị phụ thuộc của tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính:\n++++ Tờ khai đăng ký thuế mẫu số 02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n++++ Bản sao Giấy chứng nhận đăng ký hoạt động đơn vị phụ thuộc, hoặc Quyết định thành lập, hoặc văn bản tương đương do cơ quan có thẩm quyền cấp, hoặc Giấy chứng nhận đăng ký kinh doanh theo quy định của pháp luật của nước có chung biên giới (đối với tổ chức của nước có chung biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu của Việt Nam).\n+++ Đối với đơn vị phụ thuộc của tổ chức khác và tổ hợp tác theo quy định tại Điểm b, c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024:\n++++ Tờ khai đăng ký thuế mẫu số 02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bản sao không yêu cầu chứng thực Quyết định thành lập, hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp.\n++ Đối với đơn vị bị chấm dứt MST sau chuyển đổi:\n+++Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n+++ Bản sao không yêu cầu chứng thực Quyết định chấm dứt hoạt động đơn vị phụ thuộc, hoặc Thông báo chấm dứt hoạt động của đơn vị chủ quản, hoặc Quyết định thu hồi giấy chứng nhận đăng ký hoạt động đối với đơn vị phụ thuộc của cơ quan có thẩm quyền;\n+ Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Đối với hồ sơ đăng ký thuế lần đầu: Giấy chứng nhận đăng ký thuế. + Đối với hồ sơ chấm dứt hiệu lực MST: Thông báo người nộp thuế ngừng hoạt động và đang làm thủ tục chấm dứt hiệu lực mã số thuế theo mẫu số 17/TB-ĐKT và Thông báo chấm dứt hiệu lực mã số thuế mẫu số 18/TB-ĐKT; Thông báo gửi cho đơn vị chủ quản, đơn vị phụ thuộc theo mẫu số 35/TB-ĐKT; Thông báo về việc chuyển nghĩa vụ thuế của người nộp thuế mẫu số 39/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-ĐK-TCT", "02-ĐK-TCT", "24/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002321"}, {"ma": "1.008759", "ten": "Đăng ký thuế trong trường hợp chia, tách, hợp nhất, sáp nhập tổ chức", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức kinh tế, tổ chức khác", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1: \n ++ Đối với trường hợp chia tổ chức: \n +++ Tổ chức bị chia: nộp hồ sơ đề nghị chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày có Quyết định chia tổ chức hoặc văn bản tương đương.\n +++ Các tổ chức mới thành lập từ tổ chức bị chia phải thực hiện thủ tục đăng ký thuế với cơ quan thuế trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n ++++ Tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi đặt trụ sở.\n ++++ Tổ hợp tác, tổ chức khác theo quy định tại Điểm b,c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Chi cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n ++ Đối với trường hợp tách tổ chức:\n +++ Tổ chức bị tách: nếu có phát sinh thay đổi thông tin đăng ký thuế sau khi tách thì phải thực hiện thủ tục thay đổi thông tin đăng ký thuế với cơ quan thuế quản lý trực tiếp trong thời hạn là 10 (mười) ngày làm việc kể từ ngày được cấp Giấy phép thành lập và hoạt động, Quyết định thành lập hoặc Văn bản tương đương khác của cơ quan nhà nước có thẩm quyền.\n +++ Tổ chức được tách: phải thực hiện thủ tục đăng ký thuế với cơ quan thuế trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n ++++ Tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi đặt trụ sở.\n ++++ Tổ hợp tác, tổ chức khác theo quy định tại Điểm b,c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Chi cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n ++ Đối với trường hợp sáp nhập tổ chức: \n +++ Tổ chức bị sáp nhập nộp hồ sơ đề nghị chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày có hợp đồng sáp nhập hoặc văn bản tương đương.\n +++ Tổ chức nhận sáp nhập nếu có phát sinh thay đổi thông tin đăng ký thuế sau khi sáp nhập thì trong thời hạn 10 (mười) làm việc ngày kể từ ngày được cấp Giấy phép thành lập và hoạt động, Quyết định thành lập hoặc Giấy tờ tương đương khác, tổ chức nhận sáp nhập phải thực hiện thủ tục thay đổi thông tin đăng ký thuế với cơ quan thuế quản lý trực tiếp. \n ++ Đối với trường hợp hợp nhất tổ chức:\n +++ Các tổ chức bị hợp nhất nộp hồ sơ đề nghị chấm dứt hiệu lực mã số thuế đến cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày có Hợp đồng hợp nhất hoặc văn bản tương đương.\n +++ Tổ chức hợp nhất phải thực hiện thủ tục đăng ký thuế với cơ quan thuế trong thời hạn 10 ngày làm việc kể từ ngày ghi trên giấy phép thành lập và hoạt động hoặc Giấy phép tương đương theo quy định tại Luật Quản lý thuế và Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính theo nơi nộp hồ sơ như sau:\n ++++ Tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi đặt trụ sở.\n ++++ Tổ hợp tác, tổ chức khác theo quy định tại Điểm b,c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC nộp hồ sơ đăng ký thuế tại Cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Chi cục Thuế nơi tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập và nơi tổ hợp tác đóng trụ sở.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "- Thời hạn giải quyết: \n+ Đối với tổ chức mới thành lập sau chia, tách, hợp nhất: 03 (ba) ngày làm việc kể từ ngày cơ quan thuế nhận được hồ sơ đăng ký thuế đầy đủ theo quy định.\n+ Đối với tổ chức bị chấm dứt hiệu lực mã số thuế do bị chia, bị sáp nhập, bị hợp nhất: \n++ Cơ quan thuế quản lý trực tiếp thực hiện:\n+++ Trong thời hạn 02 (hai) ngày làm việc kể từ ngày cơ quan thuế nhận đủ hồ sơ chấm dứt hiệu lực mã số thuế của người nộp thuế, cơ quan thuế phải thực hiện Thông báo người nộp thuế ngừng hoạt động và đang làm thủ tục chấm dứt hiệu lực mã số thuế theo mẫu số 17/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi cho người nộp thuế. Đồng thời chuyển trạng thái của người nộp thuế và các đơn vị phụ thuộc của người nộp thuế về trạng thái \"NNT ngừng hoạt động nhưng chưa hoàn thành thủ tục chấm dứt hiệu lực mã số thuế\" trên hệ thống ứng dụng đăng ký thuế.\n+++ Ban hành Thông báo gửi cho đơn vị chủ quản, đơn vị phụ thuộc theo mẫu số 35/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính trong trường hợp cơ quan thuế nhận được hồ sơ chấm dứt hiệu lực mã số thuế của đơn vị chủ quản nhưng các đơn vị phụ thuộc chưa thực hiện thủ tục chấm dứt hiệu lực mã số thuế.\n+++ Trường hợp đơn vị phụ thuộc chấm dứt hiệu lực mã số thuế nhưng không có khả năng hoàn thành nghĩa vụ còn phải nộp hoặc còn nợ sau khi đã thực hiện bù trừ hoặc hoàn trả kiêm bù trừ theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành thì đơn vị chủ quản đã có văn bản cam kết chịu trách nhiệm kế thừa toàn bộ khoản nghĩa vụ thuế của đơn vị phụ thuộc thì cơ quan thuế quản lý trực tiếp đơn vị phụ thuộc thực hiện chuyển nghĩa vụ của đơn vị phụ thuộc cho đơn vị chủ quản và ban hành Thông báo về việc chuyển nghĩa vụ thuế của người nộp thuế mẫu số 39/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi cho người nộp thuế là đơn vị chủ quản, đơn vị phụ thuộc.\n+++ Trường hợp đơn vị bị chia, bị sáp nhập, bị hợp nhất chấm dứt hiệu lực mã số thuế nhưng không có khả năng hoàn thành nghĩa vụ còn phải nộp hoặc còn nợ sau khi đã thực hiện bù trừ hoặc hoàn trả kiêm bù trừ theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành thi cơ quan thuế quản lý trực tiếp đơn vị bị chia, bị sáp nhập, bị hợp nhất thực hiện chuyển nghĩa vụ cho đơn vị mới và ban hành Thông báo về việc chuyển nghĩa vụ thuế của người nộp thuế mẫu số 39/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi người nộp thuế là đơn vị bị chia, bị sáp nhập, bị hợp nhất và đơn vị mới.\n+++ Trong thời hạn 03 (ba) ngày làm việc kể từ ngày người nộp thuế đã hoàn thành nghĩa vụ nộp thuế với cơ quan thuế và cơ quan hải quan hoặc cơ quan thuế hoàn thành việc chuyển toàn bộ nghĩa vụ nợ thuế và các khoản thu khác thuộc ngân sách nhà nước của đơn vị phụ thuộc sang đơn vị chủ quản, của đơn vị bị chia, bị sáp nhập, bị hợp nhất sang đơn vị mới theo quy định, cơ quan thuế ban hành Thông báo chấm dứt hiệu lực mã số thuế theo mẫu số 18/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gửi cho người nộp thuế.\n++ Cơ quan thuế quản lý khoản thu thực hiện:\n+++ Cập nhật thông tin người nộp thuế đã hoàn thành nghĩa vụ thuế đối với khoản thu thuộc cơ quan thuế quản lý vào Hệ thống ứng dụng đăng ký thuế ngay trong ngày làm việc hoặc chậm nhất vào đầu giờ ngày làm việc tiếp theo ngày người nộp thuế hoàn thành nghĩa vụ nộp thuế tại cơ quan thuế quản lý khoản thu.\n+ Đối với tổ chức bị tách, tổ chức nhận sáp nhập thay đổi thông tin ĐKT: \n++ Trong 02 ngày làm việc kể từ ngày nhận được đầy đủ hồ sơ thay đổi thông tin đăng ký thuế (đối với trường hợp không phải cấp lại Giấy chứng nhận đăng ký thuế).\n++ Trong 03 ngày làm việc kể từ ngày nhận được đầy đủ hồ sơ thay đổi thông tin đăng ký thuế (đối với trường hợp phải cấp lại Giấy chứng nhận đăng ký thuế).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n++ Đối với tổ chức mới được chia, tổ chức được tách, tổ chức hợp nhất là hồ sơ đăng ký thuế lần đầu gồm:\n+++ Tổ chức kinh tế (trừ tổ hợp tác) quy định tại Điểm a, b Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC:\n++++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê góp vốn của tổ chức, cá nhân mẫu số BK06-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bản sao không yêu cầu chứng thực Quyết định chia/Hợp đồng hợp nhất/Hợp đồng sáp nhập hoặc văn bản tương đương.\n+++ Tổ chức khác và tổ hợp tác theo quy định tại Điểm b, c, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC:\n++++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n++++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n++++ Bản sao không yêu cầu chứng thực Quyết định chia/Hợp đồng hợp nhất/Hợp đồng sáp nhập hoặc văn bản tương đương.\n++ Đối với tổ chức bị chia, tổ chức bị sáp nhập, tổ chức bị hợp nhất là hồ sơ chấm dứt hiệu lực mã số thuế gồm:\n+++ Văn bản đề nghị chấm dứt hiệu lực mã số thuế mẫu số 24/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n+++ Bản sao không yêu cầu chứng thực Quyết định chia/Hợp đồng hợp nhất/Hợp đồng sáp nhập hoặc văn bản tương đương;\n++ Đối với tổ chức bị tách, tổ chức nhận sáp nhập nếu có thay đổi thông tin đăng ký thuế thì hồ sơ thay đổi thông tin đăng ký thuế, gồm:\n+++Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST ban hành theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n+++ Bản sao Quyết định tách tổ chức hoặc Bản sao hợp đồng sáp nhập hoặc văn bản tương đương;\n+++ Bản sao Giấy phép thành lập và hoạt động, Quyết định thành lập hoặc Giấy tờ tương đương khác.\n+ Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Đối với tổ chức mới thành lập sau chia, tách, hợp nhất: Giấy chứng nhận đăng ký thuế (lần đầu)., + Đối với tổ chức bị chấm dứt hiệu lực mã số thuế do bị chia, bị sáp nhập, bị hợp nhất: Thông báo người nộp thuế ngừng hoạt động và đang làm thủ tục chấm dứt hiệu lực mã số thuế theo mẫu số 17/TB-ĐKT và Thông báo chấm dứt hiệu lực mã số thuế mẫu số 18/TB-ĐKT; Thông báo gửi cho đơn vị chủ quản, đơn vị phụ thuộc theo mẫu số 35/TB-ĐKT; Thông báo về việc chuyển nghĩa vụ thuế của người nộp thuế mẫu số 39/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính., + Đối với tổ chức bị tách, tổ chức nhận sáp nhập thay đổi thông tin ĐKT: Giấy chứng nhận đăng ký thuế (đối với trường hợp thay đổi thông tin trên Giấy chứng nhận đăng ký thuế).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n+ Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-ĐK-TCT", "08-MST", "24/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008759"}, {"ma": "1.008551", "ten": "Khai thuế tạm tính cho Liên doanh Vietsovpetro tại Lô 09.1 (chỉ áp dụng cho kỳ tính thuế trước ngày 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, Thành phố", "doi_tuong": "Liên doanh Vietsovpetro hoặc đơn vị được Vietsovpetro uỷ quyền.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế: \n ++ Đối với dầu thô, condensate: chậm nhất là ngày thứ 35 kể từ ngày xuất bán dầu thô, condensate. Ngày xuất bán là ngày hoàn thành việc xuất dầu thô, condensate tại điểm giao nhận. Trường hợp ngày thứ 35 trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó. \n ++ Đối với khí thiên nhiên: chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp ngày thứ 20 là ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó. \n + Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n Trường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế: \n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế \n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế. \n + Hoặc gửi qua hệ thống bưu chính. \n + Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ, gồm: Tờ khai thuế tạm tính Mẫu số 01/TK-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và Nghị định thư ký ngày 09 tháng 12 năm 2013 bổ sung cho Hiệp định 2010; \n + Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008, Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế , Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và Nghị định thư 2013; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư s ố 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính. \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008551"}, {"ma": "1.008529", "ten": "Khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ chuyển nhượng vốn góp, cá nhân chuyển nhượng chứng khoán khai trực tiếp với cơ quan thuế và tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân có thu nhập; cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh,thành phố/Thuế cơ sở.", "trinh_tu": "- Bước 1: \n + Đối với khai thay thuế thu nhập cá nhân đối với tổ chức có cá nhân chuyển nhượng phần vốn góp, chứng khoán trong trường hợp cá nhân chưa hoàn thành nghĩa vụ thuế: Trong thời hạn 10 (mười) ngày kể từ ngày cá nhân chuyển nhượng vốn góp, chứng khoán, tổ chức nơi cá nhân chuyển nhượng vốn góp, chứng khoán khai thay thuế thu nhập cá nhân cho cá nhân chuyển nhượng vốn góp, chứng khoán chuẩn bị hồ sơ khai thuế, gửi đến cơ quan thuế quản lý đơn vị phát hành.\n + Đối với khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ chuyển nhượng phần vốn góp, chứng khoán trong trường hợp góp vốn bằng phần vốn góp, chứng khoán: Trong thời hạn 10 (mười) ngày kể từ ngày chuyển nhượng vốn, rút vốn, cá nhân góp vốn bằng phần vốn góp chuẩn bị hồ sơ khai thuế đối với thu nhập từ chuyển nhượng phần vốn góp, chứng khoán khi góp vốn gửi đến cơ quan Thuế quản lý tổ chức phát hành vốn góp, tổ chức phát hành chứng khoán.\n + Đối với khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ chuyển nhượng vốn góp, chứng khoán khai trực tiếp với cơ quan thuế: Trong thời hạn 10 (mười) ngày kể từ ngày cá nhân chuyển nhượng vốn góp, chứng khoán, cá nhân thuộc diện khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ chuyển nhượng vốn góp, chứng khoán chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế quản lý đơn vị phát hành.\n + Đối với khai thuế thu nhập cá nhân đối với tổ chức nơi cá nhân góp vốn khai thay cho cá nhân trong trường hợp cá nhân góp vốn bằng phần vốn góp, chứng khoán: Trong thời hạn 10 (mười) ngày kể từ ngày cá nhân phát sinh chuyển nhượng chứng khoán, chuyển nhượng vốn, rút vốn thì tổ chức nơi cá nhân góp vốn bằng phần vốn góp, chứng khoán chuẩn bị hồ sơ khai thuế thu nhập cá nhân từ chuyển nhượng phần vốn góp, chứng khoán khi góp vốn, gửi đến cơ quan thuế quản lý tổ chức phát hành vốn góp, tổ chức phát hành chứng khoán.\n - Bước 2: Cơ quan thuế thực hiện tiếp nhận: \n + Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n + Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ(và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n - Đối với khai thuế thu nhập cá nhân đối với tổ chức nơi cá nhân góp vốn khai thay cho cá nhân trong trường hợp cá nhân góp vốn bằng phần vốn góp, chứng khoán: \n Cơ quan thuế thực hiện tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế (NNT) trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n + Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n + Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "- Đối với tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân: \n + Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân có thu nhập từ chuyển nhượng vốn góp, cá nhân chuyển nhượng chứng khoán khai trực tiếp với cơ quan thuế và tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân) mẫu số 04/CNV-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n + Phụ lục bảng kê chi tiết cá nhân chuyển nhượng vốn (áp dụng đối với tổ chức khai thuế thay, nộp thuế thay cho nhiều cá nhân) mẫu số 04-1/CNV-TNCN (áp dụng đối với tổ chức khai thuế thay, nộp thuế thay cho nhiều cá nhân) theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n + Bản sao Hợp đồng chuyển nhượng vốn (Trong trường hợp góp vốn bằng phần vốn góp thì Hợp đồng chuyển nhượng vốn được thay bằng bản sao Hợp đồng góp vốn.)/Bản sao Hợp đồng góp vốn. \n + Bản sao tài liệu xác định trị giá vốn góp theo sổ sách kế toán, trường hợp vốn góp do mua lại thì phải có hợp đồng chuyển nhượng khi mua \n + Bản sao các chứng từ chứng minh chi phí liên quan đến việc xác định thu nhập từ hoạt động chuyển nhượng vốn góp \n Số lượng hồ sơ: 01 (bộ). \n - Đối với cá nhân khai trực tiếp với cơ quan thuế: \n + Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân có thu nhập từ chuyển nhượng vốn góp, cá nhân chuyển nhượng chứng khoán khai trực tiếp với cơ quan thuế và tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân) mẫu số 04/CNV-TNCN tại Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính; \n + Bản sao Hợp đồng góp vốn; \n + Bản sao tài liệu xác định trị giá vốn góp theo sổ sách kế toán, trường hợp vốn góp do mua lại thì phải có hợp đồng chuyển nhượng khi mua (nếu góp vốn bằng phần vốn góp); \n + Bản sao các chứng từ chứng minh chi phí liên quan đến việc xác định thu nhập từ hoạt động chuyển nhượng vốn góp (nếu góp vốn bằng phần vốn góp). \n Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả trả từ cơ quan thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["04-1/CNV-TNCN", "04/CNV-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008529"}, {"ma": "1.008503", "ten": "Đăng ký thay đổi thông tin đăng ký thuế không làm thay đổi cơ quan thuế quản lý trực tiếp (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh)", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "i). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh thay đổi các thông tin đăng ký thuế không làm thay đổi cơ quan thuế quản lý trực tiếp (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh).\n - Đối tượng thực hiện thủ tục hành chính: Tổ chức, hộ/cá nhân kinh doanh (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh).\n (ii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - trường hợp cá nhân đăng ký thay đổi thông tin qua cơ quan chi trả thu nhập.\n - Đối tượng thực hiện thủ tục hành chính: Cơ quan chi trả thu nhập.\n (iii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - Trường hợp cá nhân đăng ký thay đổi thông tin trực tiếp tại cơ quan thuế.\n - Đối tượng thực hiện thủ tục hành chính: Cá nhân.\n (iv) Đăng ký thay đổi thông tin đăng ký thuế đối với nhà thầu, nhà đầu tư dầu khí khi chuyển nhượng phần vốn góp trong tổ chức kinh tế hoặc chuyển nhượng một phần quyền lợi tham gia hợp đồng dầu khí.\n - Đối tượng thực hiện thủ tục hành chính: Nhà thầu, nhà đầu tư dầu khí.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "- Trình tự thực hiện: \n (i). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh thay đổi các thông tin đăng ký thuế không làm thay đổi cơ quan thuế quản lý trực tiếp (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh). \n + Bước 1: \n NNT đã đăng ký thuế với cơ quan thuế, khi có thay đổi một trong các thông tin trên tờ khai đăng ký thuế, bảng kê kèm theo tờ khai đăng ký thuế phải thực hiện thủ tục thay đổi thông tin đăng ký thuế với cơ quan thuế quản lý trực tiếp trong thời hạn 10 (mười) ngày làm việc kể từ ngày phát sinh thông tin thay đổi; \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn; \n + Bước 2: Cơ quan thuế tiếp nhận: \n ++ Đối với hồ sơ bằng giấy: \n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ. \n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n ++ Đối với hồ sơ điện tử: \n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế. \n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ. \n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ. \n (ii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - trường hợp cá nhân đăng ký thay đổi thông tin qua cơ quan chi trả thu nhập. \n - Trình tự thực hiện: \n + Bước 1: Trường hợp cá nhân có ủy quyền cho tổ chức, cá nhân chi trả thu nhập thực hiện đăng ký thay đổi thông tin đăng ký thuế cho cá nhân và người phụ thuộc thì phải gửi văn bản ủy quyền (đối với trường hợp chưa có văn bản ủy quyền cho cơ quan chi trả thu nhập trước đó) và bản sao các giấy tờ có thay đổi thông tin liên quan đến đăng ký thuế của cá nhân hoặc người phụ thuộc của người có quốc tịch nước ngoài hoặc người có quốc tịch Việt Nam sinh sống tại nước ngoài không có số định danh cá nhân cho tổ chức chi trả thu nhập chậm nhất là 10 ngày làm việc kể từ ngày phát sinh thông tin thay đổi; tổ chức chi trả thu nhập có trách nhiệm tổng hợp thông tin thay đổi của cá nhân, người phụ thuộc vào tờ khai đăng ký thuế và gửi cho cơ quan quản lý thuế chậm nhất là 10 ngày làm việc kể từ ngày nhận được ủy quyền của cá nhân. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn; \n + Bước 2: Cơ quan thuế tiếp nhận: \n ++ Đối với hồ sơ bằng giấy: \n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ. \n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n ++ Đối với hồ sơ điện tử: \n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế. \n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ. \n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ. \n (iii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - Trường hợp cá nhân đăng ký thay đổi thông tin trực tiếp tại cơ quan thuế. \n - Trình tự thực hiện: \n + Bước 1: Người nộp thuế là cá nhân đăng ký thuế trực tiếp với cơ quan thuế khi có thay đổi thông tin đăng ký thuế thì phải thông báo cho Chi cục Thuế nơi cá nhân thường trú hoặc tạm trú trong thời hạn 10 ngày làm việc kể từ ngày phát sinh thông tin thay đổi. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn. \n + Bước 2: Cơ quan thuế tiếp nhận: \n ++ Đối với hồ sơ bằng giấy: \n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ. \n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n ++ Đối với hồ sơ điện tử: \n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế. \n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ. \n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ. \n (iv) Đăng ký thay đổi thông tin đăng ký thuế đối với nhà thầu, nhà đầu tư dầu khí khi chuyển nhượng phần vốn góp trong tổ chức kinh tế hoặc chuyển nhượng một phần quyền lợi tham gia hợp đồng dầu khí. \n - Trình tự thực hiện: \n + Bước 1 : Nhà thầu, nhà đầu tư dầu khí khi chuyển nhượng phần vốn góp trong tổ chức kinh tế hoặc chuyển nhượng một phần quyền lợi tham gia hợp đồng dầu khí phải thực hiện thủ tục thay đổi thông tin đăng ký thuế với Cục thuế nơi người điều hành đặt trụ sở hoặc tại Cục Thuế doanh nghiệp lớn trong trường hợp người điều hành được phân công cho Cục Thuế doanh nghiệp lớn quản lý trong thời hạn 10 (mười) ngày làm việc kể từ ngày phát sinh thông tin thay đổi. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử : Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn; \n + Bước 2 : Cơ quan thuế tiếp nhận: \n ++ Đối với hồ sơ bằng giấy: \n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ. \n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n ++ Đối với hồ sơ điện tử: \n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế. \n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ. \n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia", "thanh_phan_ho_so": "- Thành phần, số lượng hồ sơ: \n i). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh thay đổi các thông tin đăng ký thuế không làm thay đổi cơ quan thuế quản lý trực tiếp (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh). \n + Thành phần hồ sơ, gồm: \n ++ Đối với NNT là tổ chức (trừ trường hợp đăng ký theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh; tổ chức, cá nhân nước ngoài và tổ chức ở Việt Nam sử dụng tiền viện trợ nhân đạo, viện trợ không hoàn lại của nước ngoài mua hàng hoá, dịch vụ có thuế giá trị gia tăng ở Việt Nam để viện trợ không hoàn lại, viện trợ nhân đạo; các cơ quan đại diện ngoại giao, cơ quan lãnh sự và cơ quan đại diện của tổ chức quốc tế tại Việt Nam thuộc đối tượng được hoàn thuế giá trị gia tăng đối với đối tượng hưởng ưu đãi miễn trừ ngoại giao; Chủ dự án ODA thuộc diện được hoàn thuế giá trị gia tăng, Văn phòng đại diện nhà tài trợ dự án ODA, tổ chức do phía nhà tài trợ nước ngoài chỉ định quản lý chương trình, dự án ODA không hoàn lại) hồ sơ gồm: \n +++ Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế theo mẫu 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n +++ Bản sao Giấy phép thành lập và hoạt động, hoặc Giấy chứng nhận đăng ký hoạt động đơn vị phụ thuộc, hoặc Quyết định thành lập, hoặc Giấy phép tương đương do cơ quan có thẩm quyền cấp nếu thông tin trên các Giấy tờ này có thay đổi. \n ++ Đối với Tổ chức, cá nhân nước ngoài và tổ chức ở Việt Nam sử dụng tiền viện trợ nhân đạo, viện trợ không hoàn lại của nước ngoài mua hàng hoá, dịch vụ có thuế giá trị gia tăng ở Việt Nam để viện trợ không hoàn lại, viện trợ nhân đạo; các cơ quan đại diện ngoại giao, cơ quan lãnh sự và cơ quan đại diện của tổ chức quốc tế tại Việt Nam thuộc đối tượng được hoàn thuế giá trị gia tăng đối với đối tượng hưởng ưu đãi miễn trừ ngoại giao; Chủ dự án ODA thuộc diện được hoàn thuế giá trị gia tăng, Văn phòng đại diện nhà tài trợ dự án ODA, tổ chức do phía nhà tài trợ nước ngoài chỉ định quản lý chương trình, dự án ODA không hoàn lại, hồ sơ gồm: \n Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế theo mẫu 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++ Đối với hộ gia đình, cá nhân có hoạt động sản xuất, kinh doanh hàng hóa, dịch vụ theo quy định của pháp luật nhưng không phải đăng ký hộ kinh doanh qua cơ quan đăng ký kinh doanh theo quy định của Chính phủ về hộ kinh doanh; cá nhân kinh doanh của các nước có chung đường biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu. Hồ sơ gồm: \n +++ Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST ban hành kèm theo Thông tư 86/2024/TT-BTC ngày 23/12/2024 hoặc Hồ sơ khai thuế theo quy định của pháp luật về quản lý thuế; \n +++ Bản sao Hộ chiếu còn hiệu lực của cá nhân nếu thông tin trên giấy tờ này có thay đổi đối với cá nhân là người nước ngoài hoặc người Việt Nam sinh sống tại nước ngoài không có số định danh cá nhân. \n + Số lượng hồ sơ: 01 (bộ). \n (ii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - trường hợp cá nhân đăng ký thay đổi thông tin qua cơ quan chi trả thu nhập. \n + Thành phần hồ sơ, gồm: \n ++ Đối với cá nhân: Tờ khai đăng ký mẫu số 05-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n ++ Đối với người phụ thuộc: Tờ khai đăng ký mẫu số 20-ĐK-TH-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ). \n (iii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - Trường hợp cá nhân đăng ký thay đổi thông tin trực tiếp tại cơ quan thuế. \n + Thành phần hồ sơ, gồm: \n ++Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST hoặc mẫu số 20-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. Trường hợp cá nhân hoặc người phụ thuộc thuộc trường hợp cơ quan thuế cấp mã số thuế (là người có quốc tịch nước ngoài hoặc là người có quốc tịch Việt Nam sinh sống tại nước ngoài không có số định danh cá nhân được xác lập từ Cơ sở dữ liệu quốc gia về dân cư) thì nộp kèm theo bản sao Hộ chiếu còn hiệu lực của cá nhân hoặc người phụ thuộc trong trường hợp thông tin đăng ký thuế trên giấy tờ này có thay đổi. \n + Số lượng hồ sơ: 01 (bộ). \n (iv) Đăng ký thay đổi thông tin đăng ký thuế đối với nhà thầu, nhà đầu tư dầu khí khi chuyển nhượng phần vốn góp trong tổ chức kinh tế hoặc chuyển nhượng một phần quyền lợi tham gia hợp đồng dầu khí. \n + Thành phần hồ sơ, gồm: \n Tờ khai điều chỉnh , bổ sung thông tin đăng ký thuế theo mẫu 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ) .", "ket_qua": "i). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh thay đổi các thông tin đăng ký thuế không làm thay đổi cơ quan thuế quản lý trực tiếp (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh). - Kết quả thực hiện thủ tục hành chính: Giấy chứng nhận đăng ký thuế hoặc Thông báo mã số thuế (trường hợp người nộp thuế thay đổi các thông tin trên Giấy chứng nhận đăng ký thuế hoặc Thông báo mã số thuế). (ii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - trường hợp cá nhân đăng ký thay đổi thông tin qua cơ quan chi trả thu nhập. - Kết quả thực hiện thủ tục hành chính: + Đối với cá nhân Việt Nam: Cập nhật thông tin thay đổi nếu khớp đúng với thông tin trong Cơ sở dữ liệu quốc gia về dân cư. + Đối với cá nhân nước ngoài: Thông báo mã số thuế cá nhân mẫu số 14-MST đã cập nhật thông tin thay đổi. (iii). Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là cá nhân có phát sinh thu nhập chịu thuế thu nhập cá nhân (trừ cá nhân kinh doanh) và người phụ thuộc - Trường hợp cá nhân đăng ký thay đổi thông tin trực tiếp tại cơ quan thuế. - Kết quả thực hiện thủ tục hành chính: + Đối với cá nhân Việt Nam: Cập nhật thông tin thay đổi nếu khớp đúng với thông tin trong Cơ sở dữ liệu quốc gia về dân cư. + Đối với cá nhân nước ngoài: Thông báo mã số thuế cá nhân (nếu có thay đổi). (iv) Đăng ký thay đổi thông tin đăng ký thuế đối với nhà thầu, nhà đầu tư dầu khí khi chuyển nhượng phần vốn góp trong tổ chức kinh tế hoặc chuyển nhượng một phần quyền lợi tham gia hợp đồng dầu khí. - Kết quả thực hiện thủ tục hành chính: Giấy chứng nhận đăng ký thuế (trường hợp người nộp thuế thay đổi các thông tin trên Giấy chứng nhận đăng ký thuế).", "dieu_kien": "+ Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. + + Cá nhân là người Việt Nam phải kê khai các thông tin về họ và tên, ngày tháng năm sinh, số định danh cá nhân của người phụ thuộc chính xác so với các thông tin được lưu trữ tại Cơ sở dữ liệu quốc gia về dân cư, trường hợp chưa được cấp số định danh cá nhân thì cá nhân phải liên hệ với cơ quan Công an cấp xã để thu thập thông tin vào Cơ sở dữ liệu quốc gia về dân cư và cấp số định", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["05-ĐK-TH-TCT", "08-MST", "20-ĐK-TCT", "20-ĐK-TH-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008503"}, {"ma": "1.008317", "ten": "Khai phí/Khai quyết toán phí bảo vệ môi trường đối với khai thác khoáng sản", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1: \n++ Tổ chức, cá nhân khai thác khoáng sản phải nộp hồ sơ khai phí bảo vệ môi trường chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp tổ chức, cá nhân khai thác khoáng sản (trừ dầu thô, khí thiên nhiên và khí than; tổ chức thu mua gom khoáng sản từ người khai thác nhỏ lẻ) thì nộp hồ sơ khai phí bảo vệ môi trường với cơ quan thuế nơi khai thác khoáng sản. Trường hợp khai thác dầu thô, khí thiên nhiên và khí than; tổ chức thu mua gom khoáng sản từ người khai thác nhỏ lẻ thì nộp hồ sơ khai phí bảo vệ môi trường với cơ quan thuế quản lý trực tiếp. \n++ Tổ chức khai thác khoáng sản không thường xuyên đã được cơ quan nhà nước có thẩm quyền cấp phép hoặc không thuộc trường hợp phải cấp phép theo quy định của pháp luật thì phải nộp hồ sơ khai phí bảo vệ môi trường chậm nhất là ngày tứ 10 kể từ ngày phát sinh nghĩa vụ thuế. \n+ Bước 2. Cơ quan thuế tiếp nhận:\nCơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n+ Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm:\n++ Tờ khai phí bảo vệ môi trường đối với khai thác khoáng sản theo tháng mẫu số 01/PBVMT tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n Số lượng hồ sơ: 01 bộ", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n+ Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/PBVMT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008317"}, {"ma": "1.010999", "ten": "Khai thuế giá trị gia tăng, thu nhập cá nhân, thu nhập doanh nghiệp đối với hoạt động khai thác tài sản bảo đảm trong thời gian chờ xử lý (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tổ chức tín dụng hoặc bên thứ 3 được tổ chức tín dụng ủy quyền khai thác TSBĐ trong thời gian chờ xử lý.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập tờ khai và gửi đến cơ quan thuế chậm nhất vào ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế.\n+ Bước 2. Cơ quan thuế tiếp nhận:\n++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n++ Trường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n+++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế\n+++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế;\n+ Hoặc gửi qua hệ thống bưu chính;\n+ Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n++ Tờ khai thuế đối với hoạt động khai thác tài sản bảo đảm (TSBĐ) trong thời gian chờ xử lý theo mẫu số 01/KTTSBĐ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n++ Bảng kê chi tiết số thuế phải nộp đối với hoạt động khai thác TSBĐ trong thời gian chờ xử lý theo mẫu số 01-1 /KTTSBĐ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n++ Bản sao hợp đồng, phụ lục hợp đồng khai thác tài sản bảo đảm trong thời gian chờ xử lý đối với lần khai thuế đầu tiên của hợp đồng, phụ lục hợp đồng.\n+ Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến CQT huế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n+ Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính;\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1", "01/KTTSBĐ"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010999"}, {"ma": "1.008573", "ten": "Miễn thuế, giảm thuế theo Hiệp định thuế đối với cá nhân là đối tượng cư trú của nước ngoài và cá nhân người nước ngoài là đối tượng cư trú của Việt Nam", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX), Tổ chức nước ngoài", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Cá nhân là đối tượng cư trú của nước ngoài, trong thời hạn 15 (mười lăm) ngày trước khi thực hiện hợp đồng với các tổ chức, cá nhân Việt Nam: cá nhân nước ngoài gửi cho bên Việt Nam ký kết hợp đồng hoặc chi trả thu nhập Hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế để nộp cho Cơ quan thuế quản lý trực tiếp của Bên Việt Nam cùng với hồ sơ khai thuế của lần khai thuế đầu tiên. \n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n ++ Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.\n Văn bản đề nghị theo mẫu số 01/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC)\n2. Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú của nước cư trú do Cơ quan thuế cấp ngay trước năm đề nghị miễn, giảm thuế theo Hiệp định thuế đã được hợp pháp hóa lãnh sự; \n3. Giấy ủy quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế\n4. Trường hợp là đối tượng cư trú của nước ngoài:\n- Bản sao hộ chiếu sử dụng cho việc xuất nhập cảnh tại Việt Nam và cá nhân ký cam kết chịu trách nhiệm vào bản sao đó;\n- Bản sao Hợp đồng lao động với người sử dụng lao động ở nước ngoài và cá nhân ký cam kết chịu trách nhiệm vào bản sao đó (nếu có);\n- Bản sao Hợp đồng lao động với người sử dụng lao động tại Việt Nam (đối với thu nhập từ tiền lương, tiền công và thu nhập từ kinh doanh) hoặc bản sao giấy tờ pháp lý chứng minh nguồn gốc của khoản thu nhập (đối với các loại thu nhập khác) và cá nhân ký cam kết chịu trách nhiệm vào bản sao đó;\n- Bản sao đăng ký kinh doanh hoặc giấy phép hành nghề, giấy chứng nhận đăng ký thuế do nước cư trú cấp đối với cá nhân có thu nhập từ hoạt động hành nghề độc lập (thu nhập của thầy thuốc, luật sư, kỹ sư, kiến trúc sư, nha sĩ, kế toán viên) có xác nhận của người nộp thuế;\n- Bản sao hợp đồng ký kết với các tổ chức, cá nhân tại Việt Nam có xác nhận của người nộp thuế. Cụ thể: \n +++ Trường hợp chuyển nhượng bất động sản: bản sao hợp đồng chuyển nhượng bất động sản. \n+++ Trường hợp chuyển nhượng vốn: bản sao hợp đồng chuyển nhượng vốn; bản sao giấy chứng nhận đầu tư của công ty Việt Nam mà nhà đầu tư nước ngoài góp vốn có xác nhận của người nộp thuế. \n+++ Trường hợp chuyển nhượng chứng khoán: bản sao hợp đồng mua bán chứng khoán. Trường hợp hoạt động mua bán chứng khoán không có hợp đồng mua bán chứng khoán thì người nộp thuế nộp giấy chứng nhận tài khoản lưu ký cổ phiếu, trái phiếu do ngân hàng lưu ký hoặc công ty chứng khoán xác nhận theo mẫu số 01/TNKDCK ban hành kèm theo Thông tư.\n- Trường hợp năm trước đó đã có hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế thì các năm tiếp theo chỉ cần gửi các bản sao Hợp đồng lao động ký kết với các tổ chức, cá nhân tại Việt Nam và nước ngoài mới (nếu có). Trong thời hạn 15 (mười lăm) ngày trước khi kết thúc hợp đồng làm việc tại Việt Nam hoặc trước khi kết thúc năm tính thuế (tuỳ theo thời điểm nào diễn ra trước) cá nhân gửi Giấy chứng nhận cư trú của năm tính thuế đó và bản sao hộ chiếu cho bên Việt Nam ký kết hợp đồng hoặc chi trả thu nhập. Trong phạm vi 03 (ba) ngày làm việc kể từ ngày nhận được Giấy chứng nhận cư trú, bên Việt Nam ký kết hợp đồng hoặc chi trả thu nhập có trách nhiệm nộp cho Cơ quan thuế Giấy chứng nhận cư trú này. Trường hợp vào thời điểm trên vẫn chưa có được giấy xác nhận cư trú thì cá nhân nước ngoài có nghĩa vụ cam kết gửi Giấy chứng nhận cư trú trong quý ngay sau ngày kết thúc năm tính thuế. Trường hợp cá nhân thuộc nước hoặc vùng lãnh thổ đã ký kết Hiệp định thuế với Việt Nam không có quy định cấp giấy chứng nhận cư trú, cá nhân cung cấp bản sao hộ chiếu thay cho Giấy chứng nhận cư trú. Trường hợp tại thời điểm nộp bản sao hộ chiếu chưa xác định được cá nhân là đối tượng cư trú của nước hoặc vùng lãnh thổ nào, cá nhân có nghĩa vụ cam kết gửi bản sao hộ chiếu trong quý I của năm tiếp theo.\n5. Trường hợp cá nhân người nước ngoài là đối tượng cư trú của Việt Nam\n- Giấy chứng nhận của cơ quan đại diện Việt Nam liên quan đến các hoạt động phát sinh thu nhập đề nghị miễn thuế theo Hiệp định thuế", "ket_qua": "Thông báo 03-1/MGTH", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế;\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021của Bộ Tài chính hướng dẫn giao dich điện tử trong lĩnh vực thuế;\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n+ Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính ửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n+ Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/HTQT", "01/TNKDCK"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008573"}, {"ma": "2.002235", "ten": "Khai thuế thu nhập cá nhân tháng/quý của tổ chức, cá nhân trả thu nhập khấu trừ thuế đối với tiền lương, tiền công", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Tổ chức, cá nhân trả thu nhập chịu thuế từ tiền lương, tiền công", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+Bước 1. \n ++ Tổ chức, cá nhân trả thu nhập có phát sinh khấu trừ thuế chuẩn bị hồ sơ khai thuế, gửi đến cơ quan Thuế. Thời hạn nộp hồ sơ khai thuế tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Thời hạn nộp hồ sơ khai thuế quý chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo quý phát sinh nghĩa vụ thuế.\n (Thủ tục đăng ký chứng từ khấu trừ thuế TNCN được thực hiện riêng theo quy định tại Nghị định 70/2025/NĐ-CP của Chính phủ).\n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai thuế thu nhập cá nhân (áp dụng đối với tổ chức, cá nhân trả các khoản thu nhập từ tiền lương, tiền công) mẫu số 05/KK-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng xác định số thuế thu nhập cá nhân phải nộp cho các địa phương được hưởng nguồn thu mẫu số 05-1/PBT-KK-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["05-1/PBT-KK-TNCN", "05/KK-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002235"}, {"ma": "1.008566", "ten": "Thủ tục lựa chọn doanh nghiệp bán hàng hoàn thuế giá trị gia tăng", "cap_thuc_hien": "Cấp Bộ, Cấp Huyện", "doi_tuong": "Doanh nghiệp", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố", "trinh_tu": "+ Doanh nghiệp gửi hồ sơ đăng ký đến cơ quan thuế quản lý trực tiếp doanh nghiệp. Trường hợp doanh nghiệp đăng ký bán hàng hoàn thuế tại chi nhánh, cửa hàng của doanh nghiệp khác tỉnh, thành phố với trụ sở chính thì chi nhánh, cửa hàng gửi hồ sơ đăng ký đến cơ quan thuế quản lý trực tiếp chi nhánh, cửa hàng của doanh nghiệp;\n + Cơ quan thuế quản lý trực tiếp doanh nghiệp tiếp nhận, kiểm tra hồ sơ và xử lý như sau:\n ++ Nếu hồ sơ chưa đầy đủ, trong thời hạn ba (03) ngày làm Việc, kể từ ngày tiếp nhận hồ sơ có văn bản thông báo cho doanh nghiệp bổ sung hồ sơ;\n ++ Nếu hồ sơ không đáp ứng điều kiện quy định, trong thời hạn 07 (bảy) ngày làm iệc, kể từ ngày nhận đủ hồ sơ có văn bản trả lời cho doanh nghiệp;\n ++ Nếu hồ sơ đầy đủ, đáp ứng các điều kiện quy định, trong thời hạn 07 (bảy) ngày làm việc kể từ ngày nhận đủ hồ sơ theo quy định, Cục Thuế tỉnh, thành phố trực thuộc Trung ương nơi doanh nghiệp đóng trụ sở chính có văn bản công nhận theo mẫu ban hành kèm theo Phụ lục 2 Thông tư này và gửi cho doanh nghiệp (đối với trường hợp cơ quan thuế quản lý trực tiếp doanh nghiệp là Cục Thuế tỉnh, thành phố trực thuộc Trung ương) hoặc Chi cục thuế gửi hồ sơ đề nghị Cục Thuế tỉnh, thành phố trực thuộc Trung ương nơi doanh nghiệp đóng trụ sở chính có văn bản công nhận doanh nghiệp bán hàng hoàn thuế giá trị gia tăng (đối với trường hợp cơ quan thuế quản lý trực tiếp doanh nghiệp là Chi cục thuế). Trong thời hạn 05 ngày làm việc kể từ ngày nhận được đề nghị của Chi cục thuế, Cục Thuế tỉnh, thành phố trực thuộc Trung ương nơi doanh nghiệp đóng trụ sở chính có văn bản công nhận theo mẫu ban hành kèm theo Phụ lục 2 Thông tư 92/2019/TT-BTC ngày 31/12/2019 và gửi cho doanh nghiệp.”", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Công văn đăng ký tham gia bán hàng theo mẫu quy định tại Phụ lục 1 Thông tư này; \n + Giấy chứng nhận đăng ký kinh doanh hoặc giấy chứng nhận đăng ký doanh nghiệp: 01 bản chụp có đóng dấu xác nhận của doanh nghiệp; \n + Hợp đồng bán hàng đại lý ký giữa doanh nghiệp đăng ký bán hàng với cửa hàng bán hàng đại lý cho doanh nghiệp (đối với trường hợp là cửa hàng đại lý bán hàng cho doanh nghiệp): 01 bản chụp có đóng dấu xác nhận của doanh nghiệp.", "ket_qua": "Công văn thông báo công nhận doanh nghiệp bán hàng hoàn thuế giá trị gia tăng.", "dieu_kien": "+ Doanh nghiệp được thành lập và hoạt động theo quy định của pháp luật Việt Nam, có đăng ký bán hàng hoàn thuế giá trị gia tăng, kinh doanh các mặt hàng được hoàn thuế theo quy định tại Điều 11 Thông tư này tại một trong các địa điểm sau đây: \n ++ Trụ sở chính của doanh nghiệp; \n ++ Chi nhánh, cửa hàng của doanh nghiệp; \n ++ Địa điểm đặt đại lý bán hàng cho doanh nghiệp. \n + Thực hiện chế độ kế toán, hóa đơn, chứng từ theo quy định của pháp luật; kê khai nộp thuế GTGT theo phương pháp khấu trừ.", "can_cu_phap_ly": "+ Luật thuế giá trị gia tăng số 13/2008/QH12 ngày 03/06/2008; Luật sửa đổi, bổ sung một số điều của Luật thuế giá trị gia tăng số 31/2013/QH13 ngày 19/06/2013; \n + Luật Quản lý thuế số 78/2006/QH10 ngày 29/11/2006; Luật sửa đổi, bổ sung một số điều của Luật quản lý thuế 21/2012/QH13 ngày 20/11/2012; \n + Nghị định số 83/2013/NĐ-CP ngày 22 tháng 7 năm 2013 của Chính phủ quy định chi tiết thi hành một số điều của Luật quản lý thuế và Luật sửa đổi, bổ sung một số điều của Luật quản lý thuế; \n + Nghị định số 209/2013/NĐ-CP ngày 18/12/2013 của Chính phủ quy định chi tiết và hướng dẫn một số điều Luật thuế giá trị gia tăng; \n + Nghị định số 215/2013/NĐ-CP ngày 23 tháng 12 năm 2013 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 72/2014/TT-BTC ngày 30/5/2014 của Bộ Tài chính quy định về hoàn thuế giá trị gia tăng đối với hàng hóa của người nước ngoài, người Việt Nam định cư ở nước ngoài mang theo khi xuất cảnh. \n + Thông tư số 92/2019/TT-BTC ngày 31/12/2019 của Bộ Tài chính sửa đổi, bổ sung Thông tư số 72/2014/TT-BTC ngày 30/5/2014 của Bộ Tài chính quy định về hoàn thuế giá trị gia tăng đối với hàng hóa của người nước ngoài, người Việt Nam định cư ở nước ngoài mang theo khi xuất cảnh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008566"}, {"ma": "1.014405", "ten": "Thông báo đơn vị hợp thành chịu trách nhiệm kê khai và danh sách các đơn vị hợp thành thuộc đối tượng áp dụng Nghị quyết 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội", "cap_thuc_hien": "Cục thuế", "doi_tuong": "+ Đơn vị hợp thành được chỉ định chịu trách nhiệm kê khai của tập đoàn đa quốc gia;\n + Liên doanh không phải thành viên của tập đoàn liên doanh áp dụng quy định QDMTT;\n + Công ty được chỉ định chịu trách nhiệm kê khai của tập đoàn liên doanh áp dụng quy định QDMTT;\n + Đơn vị hợp thành được chỉ định chịu trách nhiệm kê khai của tập đoàn con có công ty mẹ tối cao là chủ sở hữu thiểu số áp dụng quy định QMDTT;\n + Đơn vị hợp thành có công ty mẹ tối cao là chủ sở hữu thiểu số không phải là thành viên của tập đoàn con có công ty mẹ tối cao là chủ sở hữu thiểu số áp dụng quy định QDMTT.", "co_quan": "Chi cục Thuế Doanh nghiệp lớn.", "trinh_tu": "+ Tập đoàn đa quốc gia thuộc đối tượng áp dụng Nghị quyết số 107/2023/QH15 hoặc đơn vị hợp thành được Tập đoàn giao trách nhiệm gửi thông báo đơn vị hợp thành chịu trách nhiệm kê khai và danh sách các đơn vị hợp thành thuộc đối tượng áp dụng Nghị quyết số 107/2023/QH15 tới cơ quan thuế được giao nhiệm vụ quản lý thuế thu nhập doanh nghiệp bổ sung theo Quy định về thuế tối thiểu toàn cầu trong thời hạn 30 ngày kể từ ngày kết thúc năm tài chính báo cáo.\n + Trường hợp tập đoàn đa quốc gia có thay đổi đơn vị hợp thành chịu trách nhiệm kê khai hoặc danh sách các đơn vị hợp thành thuộc đối tượng áp dụng Nghị quyết số 107/2023/QH15 thì đơn vị hợp thành chịu trách nhiệm kê khai phải gửi lại thông báo tới cơ quan thuế được giao nhiệm vụ quản lý thuế thu nhập doanh nghiệp bổ sung theo Quy định về thuế tối thiểu toàn cầu chậm nhất là ngày hết hạn nộp Tờ khai thông tin, Tờ khai thuế thu nhập doanh nghiệp bổ sung theo Quy định về thuế tối thiểu toàn cầu của năm tài chính báo cáo phát sinh thay đổi.", "cach_thuc": "+ Trực tiếp: Tại Bộ phận Một cửa.\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;.\n + Trực tuyến: Nộp hồ sơ điện tử qua cổng giao dịch điện tử.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n Thông báo đơn vị hợp thành chịu trách nhiệm kê khai và danh sách các đơn vị hợp thành thuộc đối tượng áp dụng Nghị quyết 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội theo mẫu số 01/TB-ĐVHT ban hành kèm theo Nghị định số 236/2025/NĐ-CP.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Nghị quyết 107/2023/QH15 ngày 29/11/2023 của Quốc hội về áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 236/2025/NĐ-CP ngày 29/8/2025 của Chính phủ quy định chi tiết một số điều của Nghị quyết số 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội về việc áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/TB-ĐVHT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014405"}, {"ma": "1.014979", "ten": "Hoàn nộp thừa các loại thuế đối với hộ kinh doanh, cá nhân kinh doanh", "cap_thuc_hien": null, "doi_tuong": "Công dân Việt Nam, Doanh nghiệp", "co_quan": "Thuế cơ sở", "trinh_tu": "Bước 1: + Hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thuế suất nhân (x) với doanh thu tính thuế nộp hồ sơ đề nghị hoàn thuế nộp thừa theo mẫu số 01/TKN-CNKD ban hành kèm theo Thông tư số 50/2026/TT-BTC ngày 13/5/2026 sửa đổi, bổ sung một số điều của Thông tư số 18/2026/TT-BTC. + Hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thu nhập tính thuế nhân (x) với thuế suất nộp hồ sơ đề nghị hoàn thuế nộp thừa theo mẫu số 02/TNCN-CNKD-QTT ban hành kèm theo Thông tư số 18/2026/TT-BTC.\n Bước 2: Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế: + Đề nghị hoàn thuế bằng hồ sơ giấy Trường hợp người nộp thuế nộp hồ sơ đề nghị hoàn thuế bằng giấy tại trung tâm phục vụ hành chính công cấp xã, công chức thuế kiểm tra tính đầy đủ của hồ sơ theo quy định. Trường hợp hồ sơ chưa đầy đủ, công chức thuế đề nghị người nộp thuế hoàn thiện hồ sơ theo quy định. Trường hợp hồ sơ đầy đủ, công chức thuế gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ cho người nộp thuế và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế. Trường hợp người nộp thuế gửi hồ sơ qua đường bưu chính, công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế. Trong thời hạn ba (03) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi Thông báo về việc chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT hoặc Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Thông tư số 80/2021/TT-BTC đối với hồ sơ gửi qua đường bưu chính. + Đề nghị hoàn thuế bằng hồ sơ điện tử Người nộp thuế gửi hồ sơ đề nghị hoàn thuế điện tử qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế; hoặc Cổng dịch vụ công quốc gia. Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế; hoặc Cổng dịch vụ công quốc gia gửi thông báo tiếp nhận hoặc thông báo lý do không tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của người nộp thuế. + Kiểm tra để chấp nhận hồ sơ: ++ Hồ sơ được chấp nhận/không chấp nhận: Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế. ++ Hồ sơ không đúng thủ tục: Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC.\n Bước 3: Giải quyết hồ sơ hoàn trả tiền nộp thừa Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ đề nghị hoàn thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành: Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi người nộp thuế Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC. Trường hợp chưa đủ thông tin để xác định hồ sơ hoàn thuế của người nộp thuế thuộc đối tượng và trường hợp được hoàn thuế, cơ quan thuế lập Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế gửi người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày cơ quan thuế tiếp nhận hồ sơ đề nghị hoàn thuế của người nộp thuế. Trong thời hạn 10 ngày làm việc kể từ ngày cơ quan thuế ban hành Thông báo, người nộp thuế có trách nhiệm gửi văn bản giải trình hoặc bổ sung thông tin, tài liệu theo Thông báo của cơ quan thuế. Hết thời hạn theo Thông báo của cơ quan thuế nhưng người nộp thuế không giải trình, bổ sung hồ sơ hoàn thuế; hoặc có văn bản giải trình, bổ sung nhưng không chứng minh được số thuế đã khai là đúng thì cơ quan thuế chuyển hồ sơ hoàn thuế sang diện kiểm tra trước hoàn thuế và gửi Thông báo về việc chuyển hồ sơ sang diện kiểm tra trước hoàn thuế theo mẫu số 05/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế trong thời hạn 06 ngày làm việc kể từ ngày chấp nhận hồ sơ hoàn thuế.\n Bước 4: Cơ quan thuế trả kết quả giải quyết hồ sơ đề nghị hoàn thuế: Cơ quan thuế ban hành: + Quyết định hoàn thuế theo mẫu số 01/QĐHT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả theo mẫu số 01/PL-HTNT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp người nộp thuế không còn tiền thuế nợ. + Hoặc Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước theo mẫu số 02/QĐHT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả mẫu số 01/PL-HTNT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ 01/PL-BT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp người nộp thuế còn tiền thuế nợ hoặc người nộp thuế đề nghị bù trừ số thuế được hoàn trả với khoản nợ, khoản thu phát sinh của người nộp thuế khác. + Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp hồ sơ không thuộc diện được hoàn thuế.", "cach_thuc": "Hình thức nộp\n Thời gian\n Phí, lệ phí\n Mô tả\n Trực tiếp\n 6 Ngày làm việc\n Miễn phí\n Đối với hồ sơ thuộc diện hoàn thuế trước: Chậm nhất 06 ngày làm việc kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.\n Trực tiếp\n 40 Ngày\n Miễn phí\n Đối với hồ sơ thuộc diện kiểm tra trước hoàn thuế: Chậm nhất là 40 ngày kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.\n Trực tuyến\n 6 Ngày làm việc\n Miễn phí\n Đối với hồ sơ thuộc diện hoàn thuế trước: Chậm nhất 06 ngày làm việc kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.\n Trực tuyến\n 40 Ngày\n Miễn phí\n Đối với hồ sơ thuộc diện kiểm tra trước hoàn thuế: Chậm nhất là 40 ngày kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.\n Dịch vụ bưu chính\n 6 Ngày làm việc\n Miễn phí\n Đối với hồ sơ thuộc diện hoàn thuế trước: Chậm nhất 06 ngày làm việc kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.\n Dịch vụ bưu chính\n 40 Ngày\n Miễn phí\n Đối với hồ sơ thuộc diện kiểm tra trước hoàn thuế: Chậm nhất là 40 ngày kể từ ngày cơ quan quản lý thuế có thông báo bằng văn bản về việc chấp nhận hồ sơ và thời hạn giải quyết hồ sơ hoàn thuế.", "thanh_phan_ho_so": "Đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thuế suất nhân (x) với doanh thu tính thuế\n Tên giấy tờ\n Mẫu đơn, tờ khai\n Số lượng\n Tờ khai thuế đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thuế suất nhân (x) với doanh thu tính thuế (Mẫu số 01/TKN-CNKD Thông tư số 18/2026/TT-BTC sửa đổi, bổ sung bởi Thông tư số 50/2026))\n Mẫu số 01 TKN-CNKD.docx\n 1 bản chính\n Đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thu nhập tính thuế nhân (x) với thuế suất\n Tên giấy tờ\n Mẫu đơn, tờ khai\n Số lượng\n Tờ khai thuế đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế thu nhập cá nhân theo phương pháp thu nhập tính thuế nhân (x) với thuế suất (Mẫu số 02/QTT-TNCN-CNKD Thông tư số 18/2026/TT-BTC)\n Mẫu 02 CNKD-TNCN-QTT.docx\n 1 bản chính", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Tên văn bản pháp lý\n Mã văn bản\n Nghị định số 118/2025/NĐ-CP của Chính phủ: Về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia\n 118/2025/NĐ-CP\n sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n 46/2024/TT-BTC\n Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế\n 19/2021/TT-BTC\n Nghị định số 68/2026/NĐ-CP ngày 05/3/2026 quy định về chính sách thuế và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 68/2026/NĐ-CP\n Thông tư số 18/2026/TT-BTC ngày 05/3/2026 quy định về hồ sơ, thủ tục quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 18/2026/TT-BTC\n Nghị định 126/2020/NĐ-CP\n 126/2020/NĐ-CP\n Nghị định số 141/2026/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của Nghị định số 68/2026/NĐ-CP quy định về chính sách thuế đối với hộ kinh doanh, cá nhân kinh doanh và Nghị định số 320/2025/NĐ-CP quy định chi tiết một số điều và biện pháp để tổ chức, hướng dẫn thi hành Luật Thuế thu nhập doanh nghiệp\n 141/2026/NĐ-CP\n Luật số 108/2025/QH15 của Quốc hội: Luật Quản lý thuế\n 108/2025/QH15\n Thông tư số 50/2026/TT-BTC của Bộ Tài chính: Sửa đổi, bổ sung một số điều của Thông tư số 18/2026/TT-BTC ngày 05 tháng 3 năm 2026 của Bộ trưởng Bộ Tài chính quy định về hồ sơ, thủ tục quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 50/2026/TT-BTC\n Thông tư 80/2021/TT-BTC\n 80/2021/TT-BTC\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014979"}, {"ma": "1.008585", "ten": "Miễn thuế, giảm thuế theo Điều ước quốc tế không phải là Hiệp định tránh đánh thuế hai lần", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân nước ngoài thuộc diện được hưởng miễn, giảm thuế theo Điều ước quốc tế không phải là Hiệp định tránh đánh thuế hai lần (sau đây gọi là điều ước quốc tế) chuẩn bị hồ sơ đề nghị miễn, giảm thuế theo quy định. Hồ sơ được gửi cho Cơ quan thuế nơi đăng ký thuế (trong trường hợp tổ chức, cá nhân nước ngoài đăng ký kê khai, nộp thuế trực tiếp với Cơ quan thuế) hoặc gửi cho Bên Việt Nam để gửi Cơ quan thuế nơi Bên Việt Nam đăng ký thuế (trong trường hợp tổ chức, cá nhân nước ngoài không đăng ký kê khai, nộp thuế trực tiếp với Cơ quan thuế).\n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Văn bản đề nghị theo mẫu số 01/DUQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính có xác nhận của cơ quan đề xuất ký kết Điều ước quốc tế; \n ++ Bản sao Điều ước quốc tế; \n ++ Bản sao hợp đồng với Bên Việt Nam có xác nhận của tổ chức, cá nhân nước ngoài hoặc đại diện được uỷ quyền; \n ++ Bản tóm tắt hợp đồng có xác nhận của tổ chức, cá nhân nước ngoài hoặc đại diện được uỷ quyền. Bản tóm tắt hợp đồng gồm các nội dung sau: tên hợp đồng và tên các điều khoản của hợp đồng, phạm vi công việc của hợp đồng, nghĩa vụ thuế tại hợp đồng; \n ++ Giấy ủy quyền trong trường hợp tổ chức, cá nhân nước ngoài ủy quyền cho một tổ chức hoặc cá nhân Việt Nam thực hiện các thủ tục đề nghị miễn, giảm thuế. Giấy ủy quyền cần có đủ chữ ký của đại diện hai bên. Trường hợp do đặc thù của giao dịch tổ chức, cá nhân nước ngoài không thể cung cấp hợp đồng với Bên Việt Nam, tổ chức, cá nhân nước ngoài nộp các tài liệu có giá trị tương đương hợp đồng và giải trình cụ thể tại Văn bản đề nghị theo mẫu số 01/DUQT ban hành kèm theo Thông tư để cơ quan thuế xem xét, quyết định. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "không có", "dieu_kien": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX) \n - Cơ quan thực hiện thủ tục hành chính: Thuế tỉnh, thành phố. \n - Kết quả thực hiện thủ tục hành chính: không có \n - Phí, lệ phí: Không. \n - Tên mẫu đơn, mẫu tờ khai: \n Văn bản đề nghị theo mẫu số 01/DUQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính có xác nhận của cơ quan đề xuất ký kết Điều ước quốc tế; \n - Yêu cầu, điều kiện thực hiện thủ tục hành chính: Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật cư trú 68/2020/QH14 ngày 13/11/2020 của Ủy ban Thường vụ Quốc hội \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Nghị định số 122/2025/NĐ-CP ngày 11 tháng 6 năm 2025 của Chính phủ. \n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế; \n + Nghị định số 104/2022/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của các nghị định liên quan đến việc nộp, xuất trình sổ hộ khẩu, sổ tạm trú giấy khi thực hiện thủ tục hành chính, cung cấp dịch vụ công \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 40/2025/TT-BTC Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Thông tư số 94/2025/TT-BTC ngày 14/10/2025 sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/DUQT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008585"}, {"ma": "1.011011", "ten": "Đề nghị áp dụng Thủ tục thỏa thuận song phương theo Hiệp định tránh đánh thuế hai lần", "cap_thuc_hien": "Cấp Bộ", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Cục Thuế.", "trinh_tu": "+ Bước 1: Người nộp thuế là đối tượng cư trú của Việt Nam đề nghị áp dụng thủ tục thỏa thuận song phương với cơ quan thuế Việt Nam khi nhận thấy việc giải quyết của cơ quan thuế nước ngoài đã hoặc sẽ làm cho người nộp thuế phải nộp thuế không đúng với quy định của Hiệp định thuế. Người nộp thuế là đối tượng cư trú của nước ngoài đề nghị áp dụng thủ tục thỏa thuận song phương với cơ quan thuế nước ngoài nơi người nộp thuế là đối tượng cư trú. Hướng dẫn này không bao gồm thủ tục thỏa thuận song phương đối với Thỏa thuận trước về phương pháp xác định giá tính thuế (APA). Người nộp thuế đề nghị áp dụng thủ tục thỏa thuận song phương trong thời hạn được quy định tại Điều Thủ tục thỏa thuận song phương của từng Hiệp định thuế. Người nộp thuế gửi hồ sơ đề nghị áp dụng thủ tục thỏa thuận song phương đến Tổng cục Thuế. \n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Văn bản đề nghị áp dụng thủ tục thỏa thuận song phương theo Mẫu số 01/DTA-MAP ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính);\n ++ Báo cáo tài chính và tờ khai thuế liên quan đến đề nghị áp dụng thủ tục thỏa thuận song phương;\n ++ Tài liệu liên quan đến thông báo xác định nghĩa vụ thuế của cơ quan thuế nước ngoài;\n ++ Hồ sơ xác định giá giao dịch liên kết của người nộp thuế của kỳ tính thuế đề nghị áp dụng thủ tục thỏa thuận song phương (đối với thủ tục thỏa thuận song phương về xác định giá chuyển nhượng);\n ++ Thông tin, tài liệu, hợp đồng, mô tả chi tiết thực tế về giao dịch, hoạt động liên quan đến việc xác định nghĩa vụ thuế và cơ sở lập luận của người đề nghị áp dụng MAP về điều khoản Hiệp định thuế mà cơ quan thuế nước ngoài áp dụng chưa phù hợp với quy định của Hiệp định thuế, phân tích của người đề nghị liên quan đến việc xác định nghĩa vụ thuế;\n ++ Tài liệu chứng minh việc nộp thuế trong trường hợp người đề nghị đã nộp số thuế liên quan đến đề nghị áp dụng thủ tục thỏa thuận song phương;\n ++ Bản sao văn bản đề nghị áp dụng thủ tục thỏa thuận song phương và các tài liệu kèm theo trong trường hợp người đề nghị đã hoặc sẽ nộp đề nghị áp dụng thủ tục thỏa thuận song phương cho cơ quan thuế nước ngoài;\n ++ Bản sao văn bản đề nghị khiếu nại và tài liệu kèm theo trong trường hợp người đề nghị đã hoặc sẽ nộp văn bản khiếu nại theo cơ chế giải quyết khiếu nại khác trong và ngoài Việt Nam và kết quả giải quyết khiếu nại (nếu có).\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Cục Thuế tiếp nhận đề nghị áp dụng thủ tục thỏa thuận song phương của người nộp thuế là đối tượng cư trú của Việt Nam và thực hiện thủ tục thỏa thuận song phương với cơ quan thuế nước ngoài theo quy định của Hiệp định thuế", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011011"}, {"ma": "9.999999", "ten": "Thủ tục khác", "cap_thuc_hien": null, "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": null, "trinh_tu": null, "cach_thuc": null, "thanh_phan_ho_so": null, "ket_qua": "Công văn của cơ quan thuế chấp nhận việc điều chỉnh bán hàng hoàn thuế; khi chấm dứt bán hàng hoàn thuế doanh nghiệp tháo bỏ Biển thông báo doanh nghiệp bán hàng hoàn thuế giá trị gia tăng cho người nước ngoài đã dán tại cửa hàng.", "dieu_kien": "Là doanh nghiệp được công nhận là doanh nghiệp bán hàng hoàn thuế giá trị gia tăng.", "can_cu_phap_ly": "Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=9.999999"}, {"ma": "1.008342", "ten": "Khai thuế thu nhập cá nhân của tổ chức khẩu trừ thuế đối với cá nhân trực tiếp ký hợp đồng làm đại lý xổ số, đại lý bảo hiểm, đại lý bán hàng đa cấp, cá nhân có thu nhập từ phí tích luỹ bảo hiểm nhân thọ, bảo hiểm không bắt buộc khác", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Doanh nghiệp xổ số, doanh nghiệp bảo hiểm, doanh nghiệp bán hàng đa cấp trả tiền hoa hồng cho cá nhân trực tiếp ký hợp đồng làm đại lý bán đúng giá; doanh nghiệp bảo hiểm trả phí tích luỹ bảo hiểm nhân thọ, bảo hiểm không bắt buộc khác, chuẩn bị hồ sơ và gửi đến cơ quan thuế. \n Thời hạn nộp hồ sơ khai thuế tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Thời hạn nộp hồ sơ khai thuế quý chậm nhất là ngày cuối cùng của tháng đầu quý tiếp theo quý phát sinh nghĩa vụ thuế.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai khấu trừ thuế thu nhập cá nhân (Áp dụng cho doanh nghiệp xổ số, bảo hiểm, bán hàng đa cấp trả tiền hoa hồng cho cá nhân trực tiếp ký hợp đồng làm đại lý bán đúng giá; doanh nghiệp bảo hiểm trả phí tích lũy bảo hiểm nhân thọ, bảo hiểm không bắt buộc khác) mẫu số 01/XSBHĐC theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng kê chi tiết cá nhân có phát sinh doanh thu từ hoạt động đại lý xổ số, đại lý bảo hiểm, bán hàng đa cấp (Kèm theo Tờ khai 01/KK-XSBHĐC kê khai vào hồ sơ khai thuế của tháng/quý cuối cùng trong năm tính thuế) mẫu số 01-1/BK-XSBHĐC theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/BK-XSBHĐC", "01/XSBHĐC"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008342"}, {"ma": "1.011049", "ten": "Thông báo mất, cháy/kết quả hủy tem điện tử thuốc lá hoặc tem điện tử rượu sản xuất để tiêu thụ trong nước", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1:\n Trường hợp mất, cháy tem điện tử thuốc lá hoặc tem điện tử rượu: Tổ chức, cá nhân phát hiện mất, cháy tem truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để lập báo cáo mất, cháy tem chậm nhất không quá năm (05) ngày làm việc kể từ ngày phát hiện việc mất, cháy tem theo Mẫu số 04/TEM, Phụ lục 3 ban hành kèm Thông tư số 31/2025/TT-BTC.\n Trường hợp tem điện tử thuốc lá hoặc tem điện tử rượu sản xuất để tiêu thụ trong nước bị hỏng: Doanh nghiệp sản xuất sản phẩm thuốc lá hoặc tổ chức, cá nhân sản xuất rượu tiêu thụ trong nước, phải thực hiện hủy tem điện tử thuốc lá hoặc tem điện tử rượu bị hỏng không tiếp tục sử dụng. Tổ chức, cá nhân truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để lập thông báo kết quả hủy tem điện tử thuốc lá hoặc tem điện tử rượu chậm nhất không quá năm (05) ngày làm việc kể từ ngày hủy tem hỏng theo Mẫu số 04/TEM, Phụ lục 3 ban hành kèm theo Thông tư số 31/2025/TT-BTC.\n + Bước 2. Cơ quan thuế tiếp nhận và giải quyết hồ sơ của người nộp thuế:\n Kể từ khi Hệ thống thông tin giải quyết thủ tục hành chính ngành Thuế tiếp nhận thành công hồ sơ, Hệ thống tự động kiểm tra và tự động trả Thông báo chấp nhận/không chấp nhận thông qua Cổng thông tin điện tử mà người nộp thuế lựa chọn để lập và gửi hồ sơ.", "cach_thuc": "Nộp trực tuyến qua Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: tờ khai theo Mẫu 04/TEM ban hành theo Phụ lục 3 Thông tư số 31/2025/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Mẫu số 02/TB/TEM, Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC về việc chấp nhận/không chấp nhận thông báo mất, cháy/kết quả hủy tem điện tử. \n Trường hợp không được chấp nhận, tổ chức, cá nhân bổ sung hồ sơ theo hướng dẫn của cơ quan thuế trước khi gửi lại Mẫu số 04/TEM theo đúng quy định.", "dieu_kien": "Không.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13 tháng 6 năm 2019; \n + Luật Giao dịch điện tử số 20/2023/QH15 ngày 22 tháng 6 năm 2023; \n + Luật Công nghệ thông tin số 67/2006/QH11 ngày 29 tháng 6 năm 2006; \n + Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành Luật Phòng, chống tác hại của thuốc lá về kinh doanh thuốc lá; Nghị định số 106/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ; \n + Nghị định số 105/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ về kinh doanh rượu; \n + Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ và Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định số 123/202/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ; \n + Nghị định số 17/2020/NĐ-CP ngày 05 tháng 2 năm 2020 của Chính phủ sửa đổi, bổ sung một số điều của các Nghị định liên quan đến điều kiện đầu tư kinh doanh thuộc lĩnh vực quản lý nhà nước của Bộ Công Thương; \n + Nghị định số 29/2025/NĐ-CP ngày 24 tháng 02 năm 2025 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Thông tư số 31/2025/TT-BTC ngày 31/5/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011049"}, {"ma": "1.008324", "ten": "Khai thuế giá trị gia tăng đối với phương pháp khấu trừ thuế đối với dự án đầu tư thuộc diện được hoàn thuế", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế mới thành lập từ dự án đầu tư hoặc người nộp thuế đang hoạt động có dự án đầu tư thuộc diện được hoàn thuế GTGT thì phải lập hồ sơ khai thuế riêng cho từng dự án đầu tư và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo tháng); chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo quý).\n Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC),bao gồm: Tờ khai thuế GTGT (áp dụng đối với người nộp thuế tính thuế theo phương pháp khấu trừ có dự án đầu tư thuộc diện được hoàn thuế) mẫu số 02/GTGT. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Tờ khai gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vựng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 48/2024/QH15 \n + Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/GTGT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008324"}, {"ma": "1.011051", "ten": "Đề nghị chuyển số lượng tem còn tồn khi sáp nhập, chia, tách/chuyển cơ quan thuế quản lý tem điện tử thuốc lá hoặc tem điện tử rượu sản xuất để tiêu thụ trong nước", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Tổ chức, cá nhân chia, tách, sáp nhập hoặc chuyển cơ quan thuế quản lý có nhu cầu tiếp tục sử dụng số tem còn tồn, truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để đăng ký điều chỉnh số tem còn tồn tại tổ chức, cá nhân chia, tách, sáp nhập sang tên, Mã số thuế của Tổ chức, cá nhân sau chia, tách, sáp nhập theo Mẫu số 06/TEM, Phụ lục 3 ban hành kèm theo Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n Cơ quan thuế thực hiện tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả, nếu có kết quả) trong vòng 01 ngày làm việc thông qua Cổng thông tin điện tử mà người nộp thuế lựa chọn để lập và gửi hồ sơ.", "cach_thuc": "Nộp trực tuyến qua Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Đơn đề nghị theo Mẫu số 06/TEM Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Mẫu số 02/TB/TEM, Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC về việc chấp nhận/không chấp nhận thông báo mất, cháy/kết quả hủy tem điện tử. \n Trường hợp không được chấp nhận, tổ chức, cá nhân bổ sung hồ sơ theo hướng dẫn của cơ quan thuế trước khi gửi lại Mẫu số 06/TEM theo đúng quy định.", "dieu_kien": "Không.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13 tháng 6 năm 2019; \n + Luật Giao dịch điện tử số 20/2023/QH15 ngày 22 tháng 6 năm 2023; \n + Luật Công nghệ thông tin số 67/2006/QH11 ngày 29 tháng 6 năm 2006; \n + Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành Luật Phòng, chống tác hại của thuốc lá về kinh doanh thuốc lá; Nghị định số 106/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ; \n + Nghị định số 105/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ về kinh doanh rượu; \n + Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ và Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định số 123/202/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ; \n + Nghị định số 17/2020/NĐ-CP ngày 05 tháng 2 năm 2020 của Chính phủ sửa đổi, bổ sung một số điều của các Nghị định liên quan đến điều kiện đầu tư kinh doanh thuộc lĩnh vực quản lý nhà nước của Bộ Công Thương; \n + Nghị định số 29/2025/NĐ-CP ngày 24 tháng 02 năm 2025 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá và Thông tư số 31/2025/TT-BTC ngày 31/5/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011051"}, {"ma": "2.002267", "ten": "Đề nghị cung cấp dịch vụ T-VAN/ Thay đổi, bổ sung thông tin cung cấp dịch vụ T-VAN hoặc thông tin kết nối/Ngừng cung cấp dịch vụ T-VAN", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Là doanh nghiệp theo quy định tại khoản 1 Điều 15 Nghị định số 165/2018/NĐ-CP ngày 24/12/2018 của Chính phủ quy định về giao dịch điện tử trong hoạt động tài chính đáp ứng đầy đủ các tiêu chí tại khoản 2 Điều 41 Thông tư số 19 /2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "co_quan": "Cục Thuế - Bộ Tài chính", "trinh_tu": "+ Bước 1. Tổ chức hoạt động trong lĩnh vực công nghệ thông tin lập văn bản đề nghị kết nối (kèm theo các tài liệu, hồ sơ chứng minh hệ thống đáp ứng tiêu chuẩn và đề án cung cấp dịch vụ T-VAN)/Thay đổi, bổ sung thông tin cung cấp dịch vụ T-VAN hoặc thông tin kết nối/Ngừng cung cấp dịch vụ T-VAN và gửi đến Cục Thuế.\n Thời hạn nộp hồ sơ: \n ++ Chậm nhất là 10 ngày làm việc kể từ ngày phát sinh thay đổi, bổ sung thông tin liên quan đến thỏa thuận đã ký với Cục Thuế (đối với trường hợp thay đổi, bổ sung thông tin liên quan đến thỏa thuận đã ký);\n ++ Trước thời hạn ngừng/tạm ngừng cung cấp dịch vụ 30 ngày, tổ chức cung cấp dịch vụ T-VAN phải trao đổi và thống nhất với Cục Thuế bằng văn bản (đối với trường hợp tạm ngừng/ngừng cung cấp dịch vụ T-VAN).\n + Bước 2. Cục Thuế thực hiện tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế;\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: tại Trung tâm Phục vụ hành chính công cấp tỉnh, xã.\n+ Bưu chính: Qua dịch vụ bưu chính.\n+ Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n ++ Trường hợp (1): Đề nghị ký thoả thuận cung cấp dịch vụ T-VAN:\n +++ Văn bản đề nghị kết nối;\n +++ Các tài liệu, hồ sơ chứng minh hệ thống đáp ứng tiêu chuẩn;\n +++ Đề án cung cấp dịch vụ T-VAN.\n ++ Trường hợp (2): Thay đổi, bổ sung thông tin cung cấp dịch vụ T-VAN hoặc thông tin kết nối: Văn bản đề nghị thay đổi, bổ sung thông tin kèm theo các tài liệu hồ sơ liên quan đến nội dung thay đổi.\n ++ Trường hợp (3): Ngừng cung cấp dịch vụ T-VAN: Văn bản đề nghị tạm ngừng/ngừng cung cấp dịch vụ T-VAN.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Trường hợp (1): Văn bản thỏa thuận kết nối giữa tổ chức cung cấp dịch vụ T-VAN và Cục Thuế. \n + Trường hợp (2): Văn bản thỏa thuận bổ sung thống nhất giữa tổ chức cung cấp dịch vụ T-VAN và Cục Thuế. \n + Trường hợp (3): Văn bản chấm dứt thỏa thuận kết nối với tổ chức cung cấp dịch vụ T-VAN.", "dieu_kien": "+ Trường hợp (1): Văn bản thỏa thuận kết nối giữa tổ chức cung cấp dịch vụ T-VAN và Cục Thuế.\n + Trường hợp (2): Văn bản thỏa thuận bổ sung thống nhất giữa tổ chức cung cấp dịch vụ T-VAN và Cục Thuế.\n + Trường hợp (3): Văn bản chấm dứt thỏa thuận kết nối với tổ chức cung cấp dịch vụ T-VAN.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật Giao dịch điện tử số 51/2005/QH11 ngày 29/11/2005; Luật Công nghệ thông tin số 67/2006/QH11 ngày 29/06/2006;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 165/2018/NĐ-CP ngày 24/12/2018 của Chính phủ quy định về giao dịch điện tử trong hoạt động tài chính; Nghị định số 130/2018/NĐ-CP ngày 27/9/2018 của Chính phủ quy định chi tiết thi hành Luật giao dịch điện tử về chữ ký số và dịch vụ chứng thực chữ ký số; Nghị định số 45/2020/NĐ-CP ngày 08/4/2020 của Chính phủ về thực hiện thủ tục hành chính trên môi trường điện tử; Nghị định số 11/2020/NĐ-CP ngày 20/01/2020 của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn về giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002267"}, {"ma": "1.013659", "ten": "Xử lý chứng từ điện tử đã lập sai", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức đăng ký sử dụng hóa đơn điện tử/chứng từ điện tử", "co_quan": "Thuế tỉnh/thành phố, Thuế cơ sở.", "trinh_tu": "+ Bước 1: Trường hợp chứng từ điện tử đã lập đã gửi cơ quan thuế bị sai về tên, địa chỉ của tổ chức, cá nhân bị khấu trừ nhưng không sai mã số thuế, số định danh cá nhân, giấy tờ tùy thân hoặc số hộ chiếu và các nội dung khác không sai: \n ++ Tổ chức, cá nhân trả thu nhập thông báo cho người bị khấu trừ thuế về việc chứng từ khấu trừ thuế bị sai và không phải lập lại chứng từ mới. \n ++ Tổ chức trả thu nhập thực hiện thông báo với cơ quan thuế về chứng từ điện tử đã lập sai theo Mẫu số 04/SS-CTĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ. \n + Bước 2: Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế tự động tiếp nhận thông báo về việc tiếp nhận Mẫu 04/SS-CTĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP, qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử.\n Bước 3: Cơ quan thuế tiếp nhận hồ sơ và giải quyết theo quy định.", "cach_thuc": "Bằng phương thức điện tử qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hoá đơn điện tử.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Mẫu 04/SS-CTĐT Thông báo chứng từ điện tử đã lập sai; \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi phản hồi tự động về việc xác nhận người nộp thuế đã gửi thành công và thông báo về thời điểm tiếp nhận chính thức hồ sơ, tài liệu của người nộp thuế khi nhận Mẫu 04/SS-CTĐT.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Khoản 22 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 của Chính phủ quy định về hóa đơn, chứng từ. \n + Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ về hóa đơn, chứng từ.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.013659"}, {"ma": "1.009825", "ten": "Thông báo/thay đổi thông tin số tài khoản/số hiệu ví điện tử", "cap_thuc_hien": null, "doi_tuong": "Hộ kinh doanh, cá nhân kinh doanh", "co_quan": "Thuế cơ sở", "trinh_tu": "Bước 1: Hộ kinh doanh, cá nhân kinh doanh đang hoạt động thuộc đối tượng quy định tại điểm b khoản 4 Điều 17 Nghị định số 68/2026/NĐ-CP gửi Thông báo số tài khoản/số hiệu ví điện tử theo Mẫu số 01/BK-STK ban hành kèm theo Thông tư số 18/2026/TT-BTC chậm nhất là ngày 20 tháng 4 năm 2026. Hộ kinh doanh, cá nhân kinh doanh khi thay đổi thông tin số tài khoản/số hiệu ví điện tử thì thông báo cho cơ quan thuế theo quy định của pháp luật quản lý thuế\n Bước 2: Cơ quan thuế tiếp nhận hồ sơ theo quy định.", "cach_thuc": "Hình thức nộp\n Thời gian\n Phí, lệ phí\n Mô tả\n Trực tiếp\n Không\n Không có thông tin\n Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã\n Trực tuyến\n Không\n Không có thông tin\n Qua Cổng dịch vụ công Quốc gia hoặc Ứng dụng định danh quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính\n Dịch vụ bưu chính\n Không\n Không có thông tin\n Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật", "thanh_phan_ho_so": "Tên giấy tờ\n Mẫu đơn, tờ khai\n Số lượng\n Thông báo số tài khoản/số hiệu ví điện tử (Mẫu số 01/BK-STK Thông tư số 18/2026/TT-BTC)\n Mẫu số 01 BK-STK.docx\n 1 bản chính", "ket_qua": "Không phải trả kết quả cho người nộp thuế", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Tên văn bản pháp lý\n Mã văn bản\n Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế\n 19/2021/TT-BTC\n Nghị định số 68/2026/NĐ-CP ngày 05/3/2026 quy định về chính sách thuế và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 68/2026/NĐ-CP\n Thông tư số 18/2026/TT-BTC ngày 05/3/2026 quy định về hồ sơ, thủ tục quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 18/2026/TT-BTC\n Nghị định số 118/2025/NĐ-CP của Chính phủ: Về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia\n 118/2025/NĐ-CP\n sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n 46/2024/TT-BTC\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.009825"}, {"ma": "1.014976", "ten": "Quyết toán thuế thu nhập cá nhân đối với hộ kinh doanh, cá nhân kinh doanh", "cap_thuc_hien": null, "doi_tuong": "Công dân Việt Nam, Doanh nghiệp", "co_quan": "Thuế cơ sở", "trinh_tu": "Bước 1: Đối với hộ kinh doanh, cá nhân kinh doanh thuộc đối tượng nộp thuế thu nhập cá nhân theo phương pháp thu nhập tính thuế nhân (x) với thuế suất thực hiện khai hồ sơ khai quyết toán thuế thu nhập cá nhân theo mẫu Tờ khai số 02/CNKD-TNCN-QTT ban hành kèm theo Thông tư số 18/2026/TT-BTC.\n Bước 2: Cơ quan thuế tiếp nhận hồ sơ theo quy định.", "cach_thuc": "Hình thức nộp\n Thời gian\n Phí, lệ phí\n Mô tả\n Trực tiếp\n Không\n Không có thông tin\n Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã\n Dịch vụ bưu chính\n Không\n Không có thông tin\n Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật\n Trực tuyến\n Không\n Không có thông tin\n Qua Cổng dịch vụ công Quốc gia hoặc Ứng dụng định danh quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính", "thanh_phan_ho_so": "Tên giấy tờ\n Mẫu đơn, tờ khai\n Số lượng\n Tờ khai quyết toán thuế thu nhập cá nhân (Mẫu số 02/CNKD-TNCN-QTT Thông tư số 18/2026/TT-BTC)\n Mẫu số 02 CNKD-TNCN-QTT.docx\n 1 bản chính", "ket_qua": "Không phải trả kết quả cho người nộp thuế", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Tên văn bản pháp lý\n Mã văn bản\n Luật Quản lý thuế\n 38/2019/QH14\n Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế\n 19/2021/TT-BTC\n Nghị định số 68/2026/NĐ-CP ngày 05/3/2026 quy định về chính sách thuế và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 68/2026/NĐ-CP\n Thông tư số 18/2026/TT-BTC ngày 05/3/2026 quy định về hồ sơ, thủ tục quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n 18/2026/TT-BTC\n Nghị định số 118/2025/NĐ-CP của Chính phủ: Về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia\n 118/2025/NĐ-CP\n sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n 46/2024/TT-BTC\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014976"}, {"ma": "1.011013", "ten": "Xử lý không hoàn trả số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa đối với trường hợp người nộp thuế từ chối nhận lại số tiền nộp thừa", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Người nộp thuế có khoản nộp thừa.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "Bước 1. Người nộp thuế có khoản nộp thừa gửi Văn bản từ chối nhận lại số tiền nộp thừa theo mẫu số 01/ĐNKHT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) đến cơ quan thuế. + Bước 2. Cơ quan thuế tiếp nhận văn bản của người nộp thuế Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có theo quy định); Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định. Trường hợp đề nghị của người nộp thuế không khớp đúng với dữ liệu trên hệ thống quản lý thuế, cơ quan thuế ban hành Thông báo yêu cầu giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế cho người nộp thuế để giải trình, bổ sung thông tin. + Bước 3. Cơ quan thuế trả kết quả giải quyết Văn bản từ chối nhận lại số tiền nộp thừa của người nộp thuế Cơ quan thuế ban hành Quyết định không hoàn trả khoản nộp thừa theo mẫu số 01/QĐ-KHTNT hoặc Thông báo về việc khoản nộp thừa không đủ điều kiện thực hiện tất toán theo mẫu số 02/TB-KHTNT tại phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC và gửi cho NNT theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ: Văn bản từ chối nhận lại số tiền nộp thừa theo mẫu số 01/ĐNKHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. + Số lượng hồ sơ: 01 bộ.", "ket_qua": "+ Quyết định không hoàn trả khoản nộp thừa theo mẫu số 01/QĐ-KHTNT \n + Hoặc Thông báo về việc khoản nộp thừa không đủ điều kiện thực hiện tất toán theo mẫu số 02/TB-KHTNT.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐNKHT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011013"}, {"ma": "1.008578", "ten": "Miễn thuế, giảm thuế theo Hiệp định thuế đối với nhà thầu nước ngoài có thu nhập phát sinh tại Việt Nam (trừ thu nhập từ hoạt động vận tải quốc tế và thu nhập từ tái bảo hiểm nước ngoài)", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX), Tổ chức nước ngoài", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Nhà thầu nước ngoài thực hiện nộp thuế GTGT theo phương pháp khấu trừ, nộp thuế TNDN theo tỷ lệ % tính trên doanh thu, phương pháp khấu trừ, nộp thuế TNDN trên cơ sở kê khai doanh thu, chi phí và phương pháp trực tiếp thuộc diện được miễn thuế, giảm thuế do áp dụng Hiệp định tránh đánh thuế hai lần giữa Việt Nam và nước, vùng lãnh thổ khác chuẩn bị hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế gửi đến Thuế tỉnh, thành phố. Trong thời hạn 15 (mười lăm) ngày trước thời hạn khai thuế, nhà thầu nước ngoài gửi cho cơ quan thuế nơi đăng ký thuế hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế. \n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n ++ Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "1. Văn bản đề nghị theo mẫu số 01/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC) \n 2. Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp ngay trước năm đề nghị miễn, giảm thuế theo Hiệp định thuế đã được hợp pháp hoá lãnh sự; \n 3. Bản sao hợp đồng ký kết với các tổ chức, cá nhân tại Việt Nam có xác nhận của người nộp thuế; \n 4. Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế. \n 5. Trường hợp hoạt động mua bán chứng khoán không có hợp đồng mua bán chứng khoán thì người nộp thuế nộp Giấy chứng nhận tài khoản lưu ký cổ phiếu, trái phiếu do Ngân hàng lưu ký hoặc Công ty chứng khoán xác nhận theo mẫu số 01/TNKDCK ban hành kèm theo Thông tư \n 6. Đối với thu nhập từ hoạt động chuyển nhượng vốn: người nộp thuế nộp thêm bản sao có xác nhận của người nộp thuế hợp đồng chuyển nhượng vốn, bản sao Giấy chứng nhận đầu tư của Công ty Việt Nam mà nhà đầu tư nước ngoài góp vốn có xác nhận của người nộp thuế \n 7. Đối với trường hợp các cơ quan Chính phủ nước ngoài có thu nhập thuộc diện được miễn thuế theo quy định của điều khoản về lãi từ tiền cho vay của Hiệp định: người nộp thuế nộp bản sao hợp đồng vay vốn được ký kết giữa cơ quan Chính phủ nước ngoài với tổ chức, cá nhân tại Việt Nam có xác nhận của người nộp thuế \n 8. Trường hợp năm trước đó đã có hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế thì các năm tiếp theo chỉ cần gửi các bản sao hợp đồng kinh tế mới ký kết với các tổ chức, cá nhân tại Việt Nam và nước ngoài có xác nhận của người nộp thuế (nếu có). \n ++ Trong thời hạn 15 (mười lăm) ngày trước khi kết thúc hợp đồng làm việc tại Việt Nam hoặc trước khi kết thúc năm tính thuế (tuỳ theo thời điểm nào diễn ra trước) Nhà thầu nước ngoài gửi bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú đã được hợp pháp hoá lãnh sự của năm tính thuế đó cho bên Việt Nam ký kết hợp đồng hoặc chi trả thu nhập. Trong phạm vi 03 (ba) ngày làm việc kể từ ngày nhận được Giấy chứng nhận cư trú, bên Việt Nam ký kết hợp đồng hoặc chi trả thu nhập có trách nhiệm nộp cho Cơ quan thuế bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú này. \n ++ Trường hợp vào thời điểm trên vẫn chưa có được Giấy chứng nhận cư trú thì nhà thầu nước ngoài có nghĩa vụ cam kết gửi Giấy chứng nhận cư trú đã được hợp pháp hoá lãnh sự trong quý ngay sau ngày kết thúc năm tính thuế.", "ket_qua": "Thông báo về việc người nộp thuế thuộc hoặc không thuộc diện được miễn thuế theo Hiệp định thuế hoặc Điều ước quốc tế khác (Mẫu số 03-1/MGTH).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/HTQT", "01/TNKDCK"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008578"}, {"ma": "1.008325", "ten": "Khai/ Khai quyết toán phí, lệ phí khác thuộc ngân sách nhà nước", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở.", "trinh_tu": "+ Bước 1: \n ++ Đối với khai phí, lệ phí khác thuộc ngân sách nhà nước: Hàng tháng, chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ thuế, cơ quan, tổ chức được giao nhiệm vụ thu phí, lệ phí thuộc ngân sách nhà nước nộp hồ sơ khai phí, lệ phí cho cơ quan thuế quản lý trực tiếp.\n ++ Đối với khai quyết toán phí, lệ phí khác thuộc ngân sách nhà nước: Cơ quan, tổ chức được giao nhiệm vụ thu phí, lệ phí thuộc Ngân sách Nhà nước nộp hồ sơ khai quyết toán phí, lệ phí cho cơ quan thuế quản lý trực tiếp chậm nhất là ngày thứ 90 (chín mươi), kể từ ngày kết thúc năm dương lịch hoặc năm tài chính.\n + Bước 2:\n Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Đối với khai phí, lệ phí khác thuộc ngân sách nhà nước: \n +++ Tờ khai phí theo mẫu số 01/PH tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n +++ Tờ khai lệ phí theo mẫu số 01/LP tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC. \n ++ Đối với khai quyết toán phí, lệ phí khác thuộc ngân sách nhà nước: \n Tờ khai quyết toán phí, lệ phí năm theo mẫu số 02/PH tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "không phải trả kết quả cho NNT", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/LP", "01/PH", "02/PH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008325"}, {"ma": "1.008332", "ten": "Khai thuế thu nhập doanh nghiệp đối với thu nhập từ chuyển nhượng quyền lợi tham gia hợp đồng dầu khí", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Bên chuyển nhượng, Nhà thầu đứng tên trong hợp đồng dầu khí tại VN (đối với trường hợp chuyển nhượng làm thay đổi chủ sở hữu của nhà thầu đang nắm giữ quyền lợi tham gia trong hợp đồng dầu khí tại Việt Nam).", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế. \n Thời hạn nộp hồ sơ khai thuế chậm nhất là ngày thứ mười (10) kể từ ngày phát sinh nghĩa vụ thuế. Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế/Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thuế thu nhập doanh nghiệp đối với thu nhập từ chuyển nhượng quyền lợi tham gia hợp đồng dầu khí Mẫu số 03/TNDN-DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC). \n ++ Bản sao hợp đồng chuyển nhượng (bản tiếng Anh và bản dịch tiếng Việt); \n ++ Giấy xác nhận của nhà điều hành, công ty điều hành chung, các bên tham gia doanh nghiệp liên doanh, Tập đoàn Dầu khí Việt Nam về tổng số chi phí mà bên chuyển nhượng gánh chịu tương ứng với giá vốn của phần quyền lợi chuyển nhượng của bên chuyển nhượng và các tài liệu chứng minh; \n ++ Chứng từ gốc của các khoản chi phí liên quan đến giao dịch chuyển nhượng; \n ++ Đối với trường hợp chuyển nhượng làm thay đổi chủ sở hữu của nhà thầu đang nắm giữ quyền lợi tham gia trong hợp đồng dầu khí tại Việt Nam, nhà thầu nước ngoài tham gia trực tiếp vào hợp đồng dầu khí tại Việt Nam có trách nhiệm báo cáo và cung cấp thêm các tài liệu sau: \n +++ Cơ cấu cổ phần của công ty trước và sau khi chuyển nhượng. \n +++ Báo cáo tài chính 02 năm của doanh nghiệp nước ngoài và các công ty con/chi nhánh nắm giữ trực tiếp hoặc gián tiếp quyền lợi tham gia hợp đồng dầu khí tại Việt Nam. \n +++ Báo cáo đánh giá tài sản và các tài liệu định giá khác sử dụng để xác định giá trị chuyển nhượng của cổ phiếu, vốn đầu tư ở nước ngoài theo hợp đồng. \n +++ Báo cáo tình hình nộp thuế thu nhập của doanh nghiệp nước ngoài liên quan đến việc chuyển nhượng làm thay đổi chủ sở hữu của nhà thầu đang nắm giữ quyền lợi tham gia trong hợp đồng dầu khí tại Việt Nam. \n +++ Báo cáo mối quan hệ giữa doanh nghiệp nước ngoài chuyển nhượng và các chi nhánh/công ty con nắm giữ trực tiếp hay gián tiếp quyền lợi tham gia hợp đồng dầu khí tại Việt Nam về: vốn góp, hoạt động sản xuất kinh doanh, doanh thu, chi phí, các tài khoản, tài sản, nhân sự .... \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 45/2023/NĐ-CP ngày 01/7/2023 của Chính quy định chi tiết một số điều của luật dầu khí; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 36/2016/TT-BTC ngày 26/02/2016 của Bộ Tài chính hướng dẫn thực hiện quy định về thuế đối với tổ chức, cá nhân tiến hành hoạt động tìm kiếm thăm dò và khai thác dầu khí theo quy định của Luật dầu khí; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008332"}, {"ma": "1.011047", "ten": "Kế hoạch mua/mua bổ sung/đơn đề nghị mua tem điện tử thuốc lá hoặc tem điện tử rượu sản xuất để tiêu thụ trong nước", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1:\n ++ Đối với Kế hoạch mua/mua bổ sung:\n Căn cứ kế hoạch sản xuất sản phẩm thuốc lá, kế hoạch sản xuất rượu để tiêu thụ trong nước hàng năm, chậm nhất là ngày 15 tháng 5 của năm liền trước năm kế hoạch, doanh nghiệp sản xuất sản phẩm thuốc lá hoặc tổ chức, cá nhân sản xuất rượu để tiêu thụ trong nước truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để đăng ký kế hoạch mua tem điện tử theo Mẫu số 02/TEM, Phụ lục 3 kèm theo Thông tư số 31/2025/TT-BTC ngày 31/5/2025 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá.\n Trường hợp trong năm, tổ chức, cá nhân có biến động về sản xuất dẫn đến tăng nhu cầu mua tem điện tử, cũng như các tổ chức, cá nhân có Giấy phép sản xuất sản phẩm thuốc lá, rượu để tiêu thụ trong nước sau ngày 15 tháng 5: Trước ngày đề nghị mua tem điện tử ít nhất ba mươi (30) ngày làm việc, tổ chức, cá nhân truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để đăng ký điều chỉnh số lượng tem điện tử cần mua hoặc mua thêm của năm kế hoạch theo Mẫu số 02/TEM, Phụ lục 3 ban hành kèm theo Thông tư số 31/2025/TT-BTC.\n ++ Đối với Đơn đề nghị mua:\n Căn cứ kế hoạch mua, kế hoạch mua bổ sung tem điện tử của năm kế hoạch đã đăng ký với cơ quan thuế quản lý trực tiếp, tổ chức, cá nhân truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để đăng ký mua tem điện tử theo Mẫu số 02/TEM, Phụ lục 3 ban hành kèm theo Thông tư số 31/2025/TT-BTC.\n + Bước 2: Cơ quan thuế tiếp nhận và giải quyết hồ sơ của người nộp thuế:\n Cơ quan thuế thực hiện tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả, nếu có kết quả) trong vòng 01 ngày làm việc thông qua Cổng thông tin điện tử mà người nộp thuế lựa chọn để lập và gửi hồ sơ.", "cach_thuc": "Nộp trực tuyến qua Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Tờ khai theo Mẫu 02/TEM ban hành theo Phụ lục 3 Thông tư số 31/2025/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Mẫu số 02/TB/TEM, Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC về việc chấp nhận/không chấp nhận việc đăng ký kế hoạch mua/mua bổ sung/ đơn đề nghị mua tem điện tử thuốc lá, tem điện tử rượu. \n Trường hợp không chấp nhận, tổ chức, cá nhân bổ sung hồ sơ theo thông báo của cơ quan thuế trước khi gửi lại Mẫu số 02/TEM theo đúng quy định.", "dieu_kien": "Không.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13 tháng 6 năm 2019; \n + Luật Giao dịch điện tử số 20/2023/QH15 ngày 22 tháng 6 năm 2023; \n + Luật Công nghệ thông tin số 67/2006/QH11 ngày 29 tháng 6 năm 2006; \n + Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành Luật Phòng, chống tác hại của thuốc lá về kinh doanh thuốc lá; Nghị định số 106/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ; \n + Nghị định số 105/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ về kinh doanh rượu; \n + Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ và Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định số 123/202/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ; \n + Nghị định số 17/2020/NĐ-CP ngày 05 tháng 2 năm 2020 của Chính phủ sửa đổi, bổ sung một số điều của các Nghị định liên quan đến điều kiện đầu tư kinh doanh thuộc lĩnh vực quản lý nhà nước của Bộ Công Thương; \n + Nghị định số 29/2025/NĐ-CP ngày 24 tháng 02 năm 2025 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Thông tư số 31/2025/TT-BTC ngày 31/5/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011047"}, {"ma": "1.007721", "ten": "Miễn, giảm thuế tài nguyên đối với trường hợp cơ quan thuế quyết định miễn, giảm", "cap_thuc_hien": "Cấp tỉnh, thành phố/Cấp xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế tài nguyên gặp thiên tai, hỏa hoạn, tai nạn bất ngờ gây tổn thất đến tài nguyên đã kê khai, nộp thuế, lập hồ sơ và gửi đến cơ quan thuế.\n + Bước 2: Cơ quan thuế tiếp nhận hồ sơ và giải quyết theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Đối với trường hợp miễn, giảm thuế tài nguyên do thiên tai, hỏa hoạn gây tổn thất đến tài nguyên đã kê khai nộp thuế, hồ sơ miễn, giảm thuế gồm: \n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n +++ Biên bản xác định mức độ, giá trị thiệt hại về tài nguyên tổn thất của cơ quan có thẩm quyền và có xác nhận của chính quyền địa phương cấp xã nơi xảy ra thiên tai, hoả hoạn theo mẫu số 02/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC. \n +++ Cơ quan có thẩm quyền xác định mức độ, giá trị thiệt hại là cơ quan tài chính hoặc các cơ quan giám định xác định mức độ, giá trị thiệt hại về tài sản. \n +++ Trường hợp thiệt hại về hàng hóa: người nộp thuế cung cấp Biên bản giám định (chứng thư giám định) về mức độ thiệt hại của cơ quan pháp lý về tính chính xác của chứng thư giám định theo quy định của pháp luật. giám định và cơ quan giám định phải chịu trách nhiệm. \n ++ Đối với trường hợp miễn thuế, giảm thuế tài nguyên do tai nạn bất ngờ gây tổn thất đến tài nguyên đã kê khai nộp thuế, hồ sơ miễn, giảm thuế gồm: \n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC; \n +++ Văn bản hoặc biên bản xác nhận tai nạn có xác nhận của cơ quan công an hoặc xác nhận mức độ thương tật của cơ quan y tế; \n +++ Giấy tờ xác định việc bồi thường của cơ quan bảo hiểm hoặc thỏa thuận bồi thường của người gây tai nạn (nếu có); \n +++ Các chứng từ chi liên quan trực tiếp đến việc khắc phục tai nạn. \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "+ Quyết định miễn thuế, giảm thuế theo mẫu số 03/MGTH ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. \n + Thông báo không được miễn thuế, giảm thuế theo mẫu số 04/MGTH ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Luật Thuế tài nguyên; Luật số 71/2014/QH13 ngày 26/11/2014 sửa đổi, bổ sung một số điều của các Luật về Thuế; Luật Dầu khí 2022; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "02/MGTH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007721"}, {"ma": "1.008333", "ten": "Khai thuế/ Khai quyết toán đối với Nhà thầu nước ngoài, Nhà thầu phụ nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức", "co_quan": "Thuế tỉnh, thành phố/ Thuế Cơ sở", "trinh_tu": "(i) Khai thuế đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài\n + Bước 1. Nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT tính trực tiếp trên GTGT, nộp thuế TNDN theo tỷ lệ % tính trên doanh thu đối với hoạt động kinh doanh và các loại thu nhập khác; Nhà thầu nước ngoài, Nhà thầu phụ nước ngoài nộp thuế GTGT theo phương pháp khấu trừ, thuế TNDN theo tỷ lệ % tính trên doanh thu lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp của bên Việt Nam;\n ++ Khai theo từng lần phát sinh thanh toán tiền cho Nhà thầu nước ngoài. Thời hạn nộp hồ sơ khai thuế theo từng lần phát sinh nghĩa vụ thuế chậm nhất là ngày thứ muời, kể từ ngày phát sinh nghĩa vụ thuế.\n ++ Trường hợp bên Việt Nam thanh toán cho Nhà thầu nước ngoài nhiều lần trong tháng thì có thể đăng ký khai thuế theo tháng thay cho việc khai theo từng lần phát sinh thanh toán tiền cho Nhà thầu nước ngoài. Thời hạn nộp hồ sơ khai thuế tháng chậm nhất là ngày thứ hai mươi của tháng tiếp theo tháng phát sinh nghĩa vụ thuế.\n Đối với hợp đồng nhà thầu là hợp đồng xây dựng, lắp đặt thì nộp hồ sơ khai thuế, hồ sơ khai quyết toán thuế cho Thuế tỉnh, thành phố hoặc Thuế cơ sở do Trưởng thuế tỉnh, thành phố nơi diễn ra hoạt động xây dựng, lắp đặt quy định.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n (ii) Khai quyết toán thuế nhà thầu nước ngoài, nhà thầu phụ nước ngoài\n + Bước 1. Nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT tính trực tiếp trên GTGT, nộp thuế TNDN theo tỷ lệ % tính trên doanh thu đối với hoạt động kinh doanh và các loại thu nhập khác; Nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT theo phương pháp khấu trừ, thuế TNDN theo tỷ lệ % tính trên doanh thu lập hồ sơ khai quyết toán thuế khi kết thúc hợp đồng nhà thầu và gửi đến cơ quan thuế quản lý trực tiếp của bên Việt Nam.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n (i) Khai thuế đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài\n (i1) Đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT theo phương pháp tính trực tiếp trên GTGT, nộp thuế TNDN theo tỷ lệ % tính trên doanh thu đối với hoạt động kinh doanh và các loại thu nhập khác gồm:\n ++ Tờ khai thuế 01/NTNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n ++ Bản sao hợp đồng nhà thầu, hợp đồng nhà thầu phụ có xác nhận của người nộp thuế (đối với lần khai thuế đầu tiên của hợp đồng nhà thầu);\n (i2) Đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài trực tiếp thực hiện khai thuế GTGT theo phương pháp khấu trừ, thuế TNDN theo tỷ lệ % tính trên doanh thu\n ++ Tờ khai thuế nhà thầu nước ngoài (áp dụng đối với NTNN nộp thuế TNDN theo tỷ lệ trên doanh thu) mẫu biểu số 03/NTNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n ++ Bản sao hợp đồng nhà thầu, hợp đồng nhà thầu phụ có xác nhận của người nộp thuế (đối với lần khai thuế đầu tiên của hợp đồng nhà thầu);\n (ii) Khai quyết toán thuế đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài\n (i3) Đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT theo phương pháp tính trực tiếp trên GTGT, nộp thuế TNDN theo tỷ lệ % tính trên doanh thu đối với hoạt động kinh doanh và các loại thu nhập khác gồm:\n ++ Tờ khai thuế 02/NTNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n ++ Phụ lục Bảng kê các Nhà thầu nước ngoài theo mẫu số 02-1/NTNN do Bộ Tài chính ban hành; \n ++ Phụ lục Bảng kê các nhà thầu phụ tham gia thực hiện hợp đồng nhà thầu theo mẫu số 02-2/NTNN do Bộ tài chính ban hành.\n (i4) Đối với nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế GTGT theo phương pháp khấu trừ, thuế TNDN theo tỷ lệ % tính trên doanh thu\n ++ Tờ khai thuế nhà thầu nước ngoài (áp dụng đối với NTNN nộp thuế TNDN theo tỷ lệ trên doanh thu) mẫu biểu số 04/NTNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n ++ Phụ lục Bảng kê các nhà thầu phụ tham gia thực hiện hợp đồng nhà thầu theo mẫu số 02-2/NTNN do Bộ tài chính ban hành;\n ++ Bảng kê chứng từ nộp thuế;\n ++ Bản Thanh lý hợp đồng nhà thầu (nếu có).\n (Thành phần hồ sơ ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế ) \n + Số lượng hồ sơ: 1 bộ", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC của 09/07/2025 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật số sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02-1/NTNN", "02-2/NTNN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008333"}, {"ma": "1.010998", "ten": "Khai phí, lệ phí và các khoản thu khác do cơ quan đại diện nước Cộng hòa Xã hội Chủ nghĩa Việt Nam ở nước ngoài thực hiện thu", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức.", "co_quan": "Thuế tỉnh, thành phố/Chi cục thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập tờ khai và gửi đến cơ quan thuế chậm nhất vào ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ phí, lệ phí và các khoản thu khác do cơ quan đại diện nước Cộng hòa xã hội chủ nghĩa Việt Nam ở nước ngoài thực hiện thu (hồ sơ nộp theo quý); chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch đối với hồ sơ quyết toán năm.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Hồ sơ khai quý: Tờ khai phí, lệ phí và các khoản thu khác do cơ quan đại diện nước Cộng hòa xã hội chủ nghĩa Việt Nam ở nước ngoài thực hiện thu theo mẫu số 01/PHLPNG ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14 và Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Hồ sơ khai quyết toán năm gồm: \n +++ Tờ khai quyết toán năm phí, lệ phí và các khoản thu khác do cơ quan đại diện nước Cộng hòa xã hội chủ nghĩa Việt Nam ở nước ngoài thực hiện thu theo mẫu số 02/PHLPNG ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14 và Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n +++ Bảng kê phí, lệ phí và các khoản thu khác phải nộp theo từng cơ quan đại diện nước Cộng hòa xã hội chủ nghĩa Việt Nam ở nước ngoài thực hiện thu theo mẫu số 02-1/PHLPNG ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14 và Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/PHLPNG", "02-1/PHLPNG", "02/PHLPNG"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010998"}, {"ma": "1.007042", "ten": "Đăng ký thuế trong trường hợp tạm ngừng hoạt động, kinh doanh; tiếp tục hoạt động, kinh doanh trước thời hạn", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, hộ gia đình, cá nhân kinh doanh không thuộc diện đăng ký kinh doanh.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Tổ chức, hộ gia đình, cá nhân kinh doanh không thuộc diện đăng ký kinh doanh thực hiện gửi Thông báo mẫu số 23/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính đến cơ quan thuế quản lý trực tiếp chậm nhất là 01 ngày làm việc trước khi tạm ngừng hoạt động, kinh doanh hoặc tiếp tục hoạt động, kinh doanh trước thời hạn đã thông báo.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n Thông báo đăng ký tạm ngừng hoạt động, kinh doanh hoặc tiếp tục hoạt động sau tạm ngừng hoạt động, kinh doanh trước thời hạn mẫu số 23/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Thông báo chấp thuận/hoặc không chấp thuận tạm ngừng hoạt động, kinh doanh mẫu số 27/TB-ĐKT, Thông báo về việc tạm ngừng hoạt động, kinh doanh theo đơn vị chủ quản mẫu số 33/TB-ĐKT (nếu có), Thông báo về việc tiếp tục hoạt động, kinh doanh trước thời hạn theo đơn vị chủ quản mẫu số 34/TB-ĐKT (nếu có) ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["23/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007042"}, {"ma": "1.008309", "ten": "Khai quyết toán thuế thu nhập cá nhân đối với tổ chức, cá nhân trả thu nhập từ tiền lương, tiền công", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Tổ chức, cá nhân trả thu nhập chịu thuế từ tiền lương, tiền công.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân trả thu nhập chuẩn bị hồ sơ khai quyết toán thuế. Thời hạn nộp hồ sơ quyết toán thuế năm chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính.\n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai quyết toán thuế thu nhập cá nhân (áp dụng đối với tổ chức, cá nhân trả thu nhập chịu thuế từ tiền lương, tiền công) mẫu số 05/QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng kê chi tiết cá nhân thuộc diện tính thuế theo biểu luỹ tiến từng phần mẫu số 05-1/BK-QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng kê chi tiết cá nhân thuộc diện tính thuế theo thuế suất toàn phần mẫu số 05-2/BK-QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng kê chi tiết người phụ thuộc giảm trừ gia cảnh mẫu số 05-3/BK-QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["05-1/BK-QTT-TNCN", "05-2/BK-QTT-TNCN", "05-3/BK-QTT-TNCN", "05/QTT-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008309"}, {"ma": "1.010339", "ten": "Cấp/Điều chỉnh/Thay thế hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "+ Doanh nghiệp, tổ chức kinh tế, hộ kinh doanh, cá nhân kinh doanh thuộc đối tượng được cấp hóa đơn của cơ quan thuế theo từng lần phát sinh", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Trường hợp (1): Cấp mới hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh \n + Đối với hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh là hóa đơn bán hàng: \n Bước 1: Lập hồ sơ đề nghị cấp/điều chỉnh/thay thế hóa đơn điện tử có mã của cơ quan thuế\n Thực hiện lập hồ sơ đề nghị cấp/điều chỉnh/thay thế hóa đơn điện tử có mã của cơ quan thuế theo Mẫu số 06/ĐN-PSĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ quy định về hóa đơn, chứng từ và gửi đến Cục Thuế.\n Bước 2: Người nộp thuế truy cập vào hệ thống lập hóa đơn điện tử của cơ quan thuế để lập hóa đơn điện tử theo quy định.\n Bước 3: Cơ quan Thuế tiếp nhận, kiểm tra hồ sơ và cấp mã của cơ quan thuế trên hóa đơn điện tử do doanh nghiệp, tổ chức kinh tế, tổ chức khác lập.\n + Đối với hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh là hóa đơn giá trị gia tăng:\n Bước 1: Lập hồ sơ đề nghị cấp/điều chỉnh/thay thế hóa đơn điện tử có mã của cơ quan thuế\n Thực hiện lập hồ sơ đề nghị cấp/điều chỉnh/thay thế hóa đơn điện tử có mã của cơ quan thuế theo Mẫu số 06/ĐN-PSĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ và gửi đến Cục Thuế.\n Bước 2: Người nộp thuế truy cập vào hệ thống lập hóa đơn điện tử của cơ quan thuế để lập hóa đơn điện tử theo quy định.\n Bước 3: Cơ quan Thuế tiếp nhận, kiểm tra hồ sơ và cấp mã của cơ quan thuế trên hóa đơn điện tử do doanh nghiệp, tổ chức kinh tế, tổ chức khác lập.\n Trường hợp (2): Điều chỉnh/thay thế hóa đơn điện tử có mã của Cơ quan thuế theo từng lần phát sinh\n Trường hợp hóa đơn điện tử theo từng lần phát sinh cần phải lập hóa đơn điều chỉnh hoặc thay thế, doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh gửi đơn đề nghị cấp hóa đơn điện tử có mã của cơ quan thuế theo Mẫu số 06/ĐN-PSĐT Phụ lục IA ban hành kèm theo Nghị định này đến cơ quan thuế để được cấp hóa đơn điện tử điều chỉnh hoặc thay thế cho hóa đơn đã lập.\n Bước 1: Lập hồ sơ đề nghị cấp/điều chỉnh/thay thế hóa đơn điện tử có mã của cơ quan thuế: NNT đã được cấp hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh. \n Bước 2: Người nộp thuế truy cập vào hệ thống lập hóa đơn điện tử của cơ quan thuế để cấp/điều chỉnh/thay thế hóa đơn điện tử theo quy định.\n Bước 3: Cơ quan Thuế tiếp nhận, kiểm tra hồ sơ và cấp mã của cơ quan thuế trên hóa đơn điện tử do doanh nghiệp, tổ chức kinh tế, tổ chức khác lập.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Mẫu số 06/ĐN-PSĐT Đơn đề nghị cấp hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh Phụ lục IA ban hành kèm theo Nghị định 70/2025/NĐ-CP.\n+ Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Cấp/Điều chỉnh/Thay thế Hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh.", "dieu_kien": "+ Cấp/Điều chỉnh/Thay thế Hóa đơn điện tử có mã của cơ quan thuế theo từng lần phát sinh", "can_cu_phap_ly": "+ Khoản 10 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ sửa đổi, bổ sung Nghị định số 123/2020/NĐ-CP ngày 19/10/2025 quy định về hóa đơn, chứng từ.\n+ Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010339"}, {"ma": "1.011020", "ten": "Khai thuế đối với tổ chức khai thuế thay, nộp thuế thay cho cá nhân hợp tác kinh doanh", "cap_thuc_hien": "Cấp tỉnh, thành phố/Cấp xã", "doi_tuong": "Tổ chức.", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở.", "trinh_tu": "+ Bước 1.Tổ chức hợp tác kinh doanh với cá nhân; tổ chức chi trả các khoản thưởng, hỗ trợ đạt doanh số, khuyến mại, chiết khấu thanh toán, chi hỗ trợ bằng tiền hoặc không bằng tiền cho cá nhân chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo tháng hoặc chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo quý phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo quý.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai thuế đối với hộ kinh doanh, cá nhân kinh doanh mẫu số 01/CNKD theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục Bảng kê chi tiết cá nhân kinh doanh mẫu số 01-1/BK-CNKD (Kèm theo Tờ khai 01/CNKD áp dụng đối với tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân; cá nhân hợp tác kinh doanh với tổ chức; tổ chức chi trả cho cá nhân đạt doanh số; theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Bản sao hợp đồng hợp tác kinh doanh (nếu là lần khai thuế đầu tiên của hợp đồng). Cơ quan thuế có quyền yêu cầu xuất trình bản chính để đối chiếu, xác nhận tính chính xác của bản sao so với bản chính. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+Luật Quản lý thuế thu nhập cá nhân số 04/2007/QH12 ngày 21/11/2007; Luật sửa đổi, bổ sung một số điều của Luật thuế thu nhập cá nhân số 26/2012/QH13 ngày 22/11/2012 các Nghị định của Chính phủ quy định chi tiết thi hành; \n + Luật Quản lý thuế số 38/2019/QH14; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Nghị định 58/2022/NĐ-CP ngày 31/8/2022 của Chính phủ về đăng ký và quản lý hoạt động của các tổ chức phi chính phủ nước ngoài tại Việt Nam; \n + Nghị định 313/2025/NĐ-CP ngày 15/8/2025 của Chính phủ về quản lý và sử dụng viện trợ không hoàn lại không thuộc hỗ trợ phát triển chính thức của cơ quan, tổ chức, cá nhân nước ngoài dành cho Việt Nam; \n + Nghị định 29/2025/NĐ-CP ngày 24/02/2025 của Chính phủ ban hành quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Quyết định số 06/2016/QĐ-TTg ngày 22/02/2016 của Thủ tướng Chính phủ về việc miễn thuế thu nhập cá nhân đối với chuyên gia nước ngoài thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam; \n + Thông tư số 96/2016/TT-BTC ngày 28/6/2016 của Bộ Tài chính hướng dẫn hồ sơ, thủ tục miễn thuế thu nhập cá nhân đối với Chuyên gia nước ngoài thực hiện chương trình, dự án viện trợ phi Chính phủ nước ngoài tại Việt Nam \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/BK-CNKD", "01/CNKD"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011020"}, {"ma": "1.011046", "ten": "Đăng ký/thay đổi thông tin sử dụng tem điện tử", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Doanh nghiệp có Giấy phép sản xuất sản phẩm thuốc lá hoặc tổ chức, cá nhân có Giấy phép sản xuất rượu đê tiêu thụ trong nước còn hiệu lực do cơ quan có thẩm quyền cấp, căn cứ sản lượng và thời hạn được phép sản xuất, truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia) để đăng ký sử dụng/thay đổi thông tin sử dụng tem điện tử theo Mẫu số 01/TEM, Phụ lục 3 ban hành kèm theo Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá.\n + Bước 2: Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế.\n Cơ quan thuế thực hiện tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả, nếu có kết quả) trong vòng 01 ngày làm việc thông qua Cổng thông tin điện tử mà người nộp thuế lựa chọn để lập và gửi hồ sơ.", "cach_thuc": "Nộp trực tuyến qua Hệ thống thông tin giải quyết các thủ tục hành chính ngành Thuế/Cổng Dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Tờ khai đăng ký sử dụng tem điện tử theo Mẫu số 01/TEM Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Mẫu số 02/TB/TEM, Phụ lục 3 kèm theo Thông tư số 23/2021/TT-BTC về việc chấp nhận hay không chấp nhận việc đăng ký sử dụng tem điện tử thuốc lá, tem điện tử rượu. \n Trường hợp không được chấp nhận, tổ chức, cá nhân bổ sung hồ sơ theo thông báo của cơ quan thuế trước khi gửi lại đăng ký sử dụng tem điện tử theo phương thức điện tử.", "dieu_kien": "Không.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13 tháng 6 năm 2019; \n + Luật Giao dịch điện tử số 20/2023/QH15 ngày 22 tháng 6 năm 2023; \n + Luật Công nghệ thông tin số 67/2006/QH11 ngày 29 tháng 6 năm 2006; \n + Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành Luật Phòng, chống tác hại của thuốc lá về kinh doanh thuốc lá; Nghị định số 106/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 67/2013/NĐ-CP ngày 27 tháng 6 năm 2013 của Chính phủ; \n + Nghị định số 105/2017/NĐ-CP ngày 14 tháng 9 năm 2017 của Chính phủ về kinh doanh rượu; \n + Nghị định số 123/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ và Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung một số điều của Nghị định số 123/202/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định về hóa đơn, chứng từ; \n + Nghị định số 17/2020/NĐ-CP ngày 05 tháng 2 năm 2020 của Chính phủ sửa đổi, bổ sung một số điều của các Nghị định liên quan đến điều kiện đầu tư kinh doanh thuộc lĩnh vực quản lý nhà nước của Bộ Công Thương; \n + Nghị định số 29/2025/NĐ-CP ngày 24 tháng 02 năm 2025 của Chính phủ quy định chức năng, nhiệm vụ, quyền hạn và cơ cấu tổ chức của Bộ Tài chính; \n + Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá và Thông tư số 31/2025/TT-BTC ngày 31/5/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 23/2021/TT-BTC ngày 30/03/2021 của Bộ Tài chính hướng dẫn việc in, phát hành, quản lý và sử dụng tem điện tử rượu và tem điện tử thuốc lá; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011046"}, {"ma": "1.008525", "ten": "Khai quyết toán lợi nhuận sau thuế còn lại sau khi trích lập các quỹ của doanh nghiệp do Nhà nước nắm giữ 100% vốn điều lệ", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Doanh nghiệp do nhà nước nắm giữ 100% vốn điều lệ.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1:\n ++ Người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế, chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính.\n + Bước 2 : Cơ quan thuế thực hiện tiếp nhận:\n ++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử..", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;.\n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "Thành phần hồ sơ, gồm:\n + Tờ khai quyết toán lợi nhuận sau thuế còn lại sau khi trích lập các quỹ phải nộp ngân sách nhà nước của doanh nghiệp do nhà nước nắm giữ 100% vốn điều lệ mẫu số 01/QT-LNCL ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Phụ lục bảng phân bổ số lợi nhuận còn lại phải nộp cho các địa phương được hưởng nguồn thu đối với hoạt động kinh doanh xổ số điện toán theo mẫu 01-1/QT-LNCN (áp dụng đối với doanh nghiệp có hoạt động kinh doanh xổ số điện toán ) ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan Thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019;\n + Luật Quản lý, sử dụng vốn nhà nước đầu tư vào sản xuất, kinh doanh tại doanh nghiệp số 69/2014/QH13 ngày 26 tháng 11 năm 2014; Luật số 68/2025/QH15 ngày 14/6/2025 về quản lý và đầu tư vốn nhà nước tại doanh nghiệp;\n + Nghị định số 91/2015/NĐ-CP ngày 13 tháng 10 năm 2015 của Chính phủ về đầu tư vốn nhà nước vào doanh nghiệp và quản lý, sử dụng vốn, tài sản tại doanh nghiệp, Nghị định số 167/2024/NĐ-CP ngày 26 tháng 12 năm 2024 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 91/2015/NĐ-CP ngày 13 tháng 10 năm 2015 của Chính phủ về đầu tư vốn nhà nước vào doanh nghiệp và quản lý, sử dụng vốn, tài sản tại doanh nghiệp đã được sửa đổi, bổ sung tại Nghị định số 32/2018/NĐ-CP ngày 08 tháng 3 năm 2018 của Chính phủ và Nghị định số 140/2020/NĐ-CP ngày 30 tháng 11 năm 2020 của Chính phủ, Nghị định số 148/2021/NĐ-CP ngày 31 tháng 12 năm 2021 của Chính phủ về quản lý, sử dụng nguồn thu từ chuyển đổi sở hữu doanh nghiệp, đơn vị sự nghiệp công lập, nguồn thu từ chuyển nhượng vốn nhà nước và chênh lệch vốn chủ sở hữu lớn hơn vốn điều lệ tại doanh nghiệp.\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản;\n + Nghị định số 122/2017/NĐ-CP quy định một số nội dung đặc thù về cơ chế quản lý tài chính và đánh giá hiệu quả hoạt động đối với doanh nghiệp kinh doanh xổ số; Sở Giao dịch Chứng khoán và Trung tâm Lưu ký Chứng khoán Việt Nam, Nghị định số 59/2021/NĐ-CP ngày 18 tháng 6 năm 2021 quy định một số nội dung đặc thù về cơ chế quản lý tài chính, đánh giá hiệu quả hoạt động đối với Sở Giao dịch Chứng khoán Việt Nam, Tổng Công ty lưu ký và bù trừ Chứng khoán Việt Nam;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia;\n + Thông tư số 138/2017/TT-BTC ngày 25/12/2017 của Bộ Tài chính hướng dẫn một số khoản chi phí đặc thù đối với doanh nghiệp kinh doanh xổ số quy định tại Nghị định số 122/2017/NĐ-CP ngày 13/11/2017 của Chính phủ.\n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/QT-LNCN", "01/QT-LNCL"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008525"}, {"ma": "1.008589", "ten": "Không tính tiền chậm nộp", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế (NNT) thuộc trường hợp không tính tiền chậm nộp chuẩn bị hồ sơ đề nghị không tính tiền chậm nộp theo đúng quy định và gửi tới cơ quan thuế quản lý trực tiếp hoặc cơ quan thuế quản lý khoản thu.\n ++ Đối với trường hợp hồ sơ không tính tiền chậm nộp điện tử: NNT truy cập vào Hệ thống thông tin giải quyết TTHC mà NNT lựa chọn (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN)/ Cổng thông tin điện tử của Cục Thuế (trường hợp TTHC đã toàn trình như chưa tích hợp lên cổng dịch vụ công quốc gia) để lập văn bản đề nghị không tính tiền chậm nộp và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm phục vụ hành chính công (TTPVHCC) cấp tỉnh, xã hoặc qua dịch vụ bưu chính: công chức thuế tiếp nhận, giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Văn bản đề nghị không tính tiền chậm nộp theo mẫu số 01/KTCN ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính; \n ++ Văn bản có xác nhận của đơn vị sử dụng ngân sách nhà nước về việc người nộp thuế chưa được thanh toán theo mẫu số 02/KTCN ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (bản chính hoặc bản sao có chứng thực); \n ++ Hợp đồng cung ứng hàng hoá, dịch vụ ký với chủ đầu tư (bản chính hoặc bản sao có xác nhận của người nộp thuế). \n ++ Các tài liệu liên quan khác (nếu có). \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "++ Thông báo không chấp thuận không tính tiền chậm nộp (mẫu số 04/KTCN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính). \n ++ Hoặc Thông báo chấp thuận không tính tiền chậm nộp (mẫu số 05/KTCN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/KTCN", "02/KTCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008589"}, {"ma": "1.007690", "ten": "Khai thuế năm đối với cá nhân trực tiếp ký hợp đồng làm đại lý xổ số, đại lý bảo hiểm, đại lý bán hàng đa cấp và hoạt động kinh doanh khác.", "cap_thuc_hien": "Cấp Xã", "doi_tuong": "Cá nhân", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1. Cá nhân trực tiếp ký hợp đồng làm đại lý xổ số, đại lý bảo hiểm, đại lý bán hàng đa cấp mà trong năm chưa khấu trừ thuế do chưa đến mức phải nộp thuế đến cuối năm cá nhân xác định thuộc diện phải nộp thuế thì cá nhân chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế nơi cá nhân cư trú, chậm nhất là ngày cuối cùng của tháng đầu tiên của năm dương lịch hoặc năm tài chính.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai thuế năm (áp dụng đối với cá nhân trực tiếp ký hợp đồng làm đại lý xổ số, bảo hiểm, bán hàng đa cấp, hoạt động kinh doanh khác chưa khấu trừ, nộp thuế trong năm) mẫu số 01/TKN-CNKD theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Bản sao hợp đồng kinh tế (cung cấp hàng hoá, dịch vụ, hợp tác kinh doanh, đại lý). \n ++ Bản sao biên bản nghiệm thu, thanh lý hợp đồng (nếu có). \n Cơ quan thuế có quyền yêu cầu xuất trình bản chính để đối chiếu, xác nhận tính chính xác của bản sao so với bản chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/TKN-CNKD"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007690"}, {"ma": "1.010701", "ten": "Thông báo sử dụng dịch vụ của Đại lý thuế/Thông báo tạm dừng, chấm dứt sử dụng dịch vụ của Đại lý thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Cá nhân, tổ chức.", "co_quan": "Cơ quan thuế quản lý.", "trinh_tu": "+ Bước 1: Người nộp thuế thực hiện\n Chậm nhất 05 ngày làm việc trước khi đại lý thuế thực hiện lần đầu các công việc dịch vụ làm thủ tục về thuế nêu trong hợp đồng hoặc chậm nhất 05 ngày làm việc kể từ khi tạm dừng, chấm dứt dịch vụ theo hợp đồng đã ký với đại lý thuế, người nộp thuế (NNT) phải gửi thông báo cho cơ quan thuế quản lý trực tiếp.\n + Bước 2: Cơ quan thuế quản lý trực tiếp NNT tiếp nhận hồ sơ theo quy định.", "cach_thuc": "Nộp trực tuyến qua Cổng DVC Quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Thông báo về việc thực hiện hợp đồng dịch vụ với đại lý thuế theo Mẫu 2.10 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Không.", "dieu_kien": "Người nộp thuế gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân theo các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019;\n + Nghị định số 118/2025/NĐ-CP ngày 09/06/025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia\n + Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010701"}, {"ma": "1.008501", "ten": "Cấp lại Giấy chứng nhận đăng ký thuế, Thông báo mã số thuế", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. \n ++ Người nộp thuế khi bị mất, rách, nát, cháy Giấy chứng nhận đăng ký thuế, Thông báo mã số thuế thì gửi hồ sơ đề nghị cấp lại Giấy chứng nhận đăng ký thuế, Thông báo mã số thuế đến cơ quan thuế trực tiếp quản lý.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Văn bản đề nghị cấp lại Giấy chứng nhận đăng ký thuế/ Thông báo mã số thuế theo mẫu số 13-MST ban hành kèm theo Thông tư số 86/2024/TT-BCT ngày 23/12/2024 của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Giấy chứng nhận đăng ký thuế /Thông báo mã số thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["13-MST"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008501"}, {"ma": "1.008321", "ten": "Khai quyết toán phí bảo vệ môi trường đối với khai thác khoáng sản", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở.", "trinh_tu": "+ Bước 1: Tổ chức, cá nhân thuộc đối tượng khai quyết toán phí bảo vệ môi trường đối với khai thác khoáng sản lập hồ sơ và gửi đến cơ quan thuế.\n Khai quyết toán phí bảo vệ môi trường đối với khai thác khoáng sản bao gồm khai quyết toán năm và khai quyết toán đến thời điểm chấm dứt hoạt động khai thác khoáng sản, chấm dứt hoạt động thu mua gom khoáng sản, chấm dứt hoạt động thu mua gom khoáng sản, chấm dứt hoạt động kinh doanh, chấm dứt hợp đồng chuyển đổi hình thức sở hữu doanh nghiệp hoặc tổ chức lại doanh nghiệp. \n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm: \n ++ Tờ khai quyết toán phí bảo vệ môi trường đối với khai thác khoáng sản mẫu số 02/PBVMT tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC). \n Số lượng hồ sơ: 01 bộ", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/PBVMT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008321"}, {"ma": "1.010344", "ten": "Đăng ký cung cấp giải pháp hóa đơn điện tử/ dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn với cơ quan thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức (không bao gồm doanh nghiệp, HTX), Tổ chức nước ngoài", "co_quan": "Cục Thuế", "trinh_tu": "+ Trường hợp (1) Đăng ký cung cấp giải pháp hóa đơn điện tử Bước 1: Tổ chức cung cấp giải pháp hóa đơn điện tử đáp ứng các tiêu chí tại khoản 1 Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính thực hiện lập hồ sơ chứng minh đáp ứng các tiêu chí tại khoản 1 Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính kèm theo tài liệu mô tả dịch vụ, cam kết thực hiện và gửi đến Tổng cục Thuế. Bước 2: Tổng cục Thuế thực hiện tiếp nhận hồ sơ theo quy định. Trong thời hạn 10 ngày kể từ ngày nhận được hồ sơ, Tổng cục Thuế đăng công khai tài liệu mô tả dịch vụ và cam kết của tổ chức lên Cổng thông tin điện tử của Tổng cục Thuế. Các tổ chức phải chịu trách nhiệm về hồ sơ văn bản cung cấp. Trong quá trình hoạt động, trường hợp phát hiện tổ chức cung cấp dịch vụ không đúng quy định, Tổng cục Thuế thông báo và hủy thông tin công khai của tổ chức trên Cổng thông tin điện tử của Tổng cục Thuế. + Trường hợp (2) Đăng ký cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn với cơ quan thuế. Bước 1: Tổ chức đáp ứng đầy đủ các điều kiện quy định tại khoản 2 Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính gửi văn bản đề nghị ký hợp đồng cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn kèm theo hồ sơ chứng minh tới Tổng cục Thuế. Bước 2: Tổng cục Thuế thực hiện tiếp nhận hồ sơ theo quy định. Trong thời hạn 10 ngày làm việc kể từ ngày tổ chức cung cấp đầy đủ hồ sơ chứng minh, Tổng cục Thuế phối hợp với tổ chức thực hiện kết nối kỹ thuật và kiểm tra truyền nhận dữ liệu giữa hai bên. Sau khi kết nối thành công, Tổng cục Thuế và tổ chức ký hợp đồng cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn với cơ quan thuế. Thông tin về tổ chức cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn của cơ quan thuế sẽ được công khai trên Cổng thông tin điện tử của Tổng cục Thuế", "cach_thuc": "Hình thức nộp \n Thời hạn giải quyết \n Phí, lệ phí \n Mô tả \n Trực tiếp \n 10 Ngày \n 10 ngày kể từ ngày nhận được hồ sơ. \n Trực tuyến \n 10 Ngày \n 10 ngày kể từ ngày nhận được hồ sơ. \n Dịch vụ bưu chính \n 10 Ngày \n 10 ngày kể từ ngày nhận được hồ sơ.", "thanh_phan_ho_so": "Tên giấy tờ \n Mẫu đơn, tờ khai \n Số lượng \n ++ Trường hợp (1) Đăng ký cung cấp giải pháp hóa đơn điện tử, hồ sơ gồm: +++ Hồ sơ chứng minh đáp ứng các tiêu chí tại khoản 1 Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính; +++ Tài liệu mô tả dịch vụ; +++ Cam kết thực hiện. ++ Trường hợp (2) Đăng ký cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn với cơ quan thuế, hồ sơ gồm: +++ Văn bản đề nghị; +++ Hồ sơ chứng minh đáp ứng đầy đủ các điều kiện quy định tại khoản 2 Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính. \n Bản chính: 1\n Bản sao: 1 \n số lượng hồ sơ: 01 bộ \n Bản chính: 1\n Bản sao: 1", "ket_qua": "Ttin về tài liệu mô tả dịch vụ và cam kết của tổ chức cung cấp giải pháp hóa đơn điện tử được đăng tải lên Cổng thông tin điện tử của Tổng cục Thuế., +++ Hợp đồng cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn được ký kêt. +++ Và thông tin về tổ chức cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn của cơ quan thuế sẽ được công khai trên Cổng thông tin điện tử của Tổng cục Thuế", "dieu_kien": "Đảm bảo đầy đủ các điều kiện theo quy định tại Điều 10 Thông tư số 78/2021/TT-BTC ngày 17/9/2021 của Bộ Tài chính. Trường hợp tổ chức cung cấp giải pháp hóa đơn điện tử, tổ chức cung cấp dịch vụ nhận, truyền, lưu trữ dữ liệu hóa đơn với cơ quan thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định về giao dịch điện tử của Bộ Tài chính", "can_cu_phap_ly": "Số ký hiệu \n Trích yếu \n Ngày ban hành \n Cơ quan ban hành \n 38/2019/QH14 \n Luật 38/2019/QH14 \n 13-06-2019 \n 78/2021/TT-BTC \n Thông tư 78/2021/TT-BTC \n 17-09-2021 \n 123/2020/NĐ-CP \n Nghị định 123/2020/NĐ-CP \n 19-10-2020 \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010344"}, {"ma": "3.000088", "ten": "Miễn tiền chậm nộp", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế (NNT) thuộc trường hợp được nộp dần tiền thuế nợ chuẩn bị hồ sơ đề nghị miễn tiền chậm nộp đầy đủ theo đúng quy định và gửi tới cơ quan thuế quản lý trực tiếp hoặc cơ quan thuế quản lý khoản thu.\n ++ Đối với trường hợp hồ sơ miễn tiền chậm nộp điện tử: NNT truy cập vào Hệ thống thông tin giải quyết TTHC mà NNT lựa chọn (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN)/ Cổng thông tin điện tử của Cục Thuế (trường hợp TTHC đã toàn trình như chưa tích hợp lên cổng dịch vụ công quốc gia) để lập văn bản đề nghị miễn tiền chậm nộp và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm phục vụ hành chính công (TTPVHCC) cấp tỉnh, xã hoặc qua dịch vụ bưu chính: công chức thuế tiếp nhận, giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Văn bản đề nghị miễn tiền chậm nộp của người nộp thuế theo mẫu số 01/MTCN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính; \n ++ Tùy từng trường hợp, hồ sơ đề nghị miễn tiền chậm nộp phải có thêm các tài liệu sau: \n (*) Trường hợp do thiên tai, thảm họa, dịch bệnh, hoả hoạn, tai nạn bất ngờ, phải có: \n - Tài liệu xác nhận về thời gian, địa điểm xảy ra thiên tai, thảm họa, dịch bệnh, hỏa hoạn, tai nạn bất ngờ của cơ quan có thẩm quyền (bản chính hoặc bản sao có xác nhận của người nộp thuế); \n - Văn bản xác định giá trị thiệt hại vật chất của cơ quan tài chính hoặc cơ quan giám định độc lập (bản chính hoặc bản sao có chứng thực); \n - Văn bản (bản chính hoặc bản sao có xác nhận của người nộp thuế) quy định trách nhiệm của tổ chức, cá nhân phải bồi thường thiệt hại (nếu có); \n - Các chứng từ (bản chính hoặc bản sao có xác nhận của người nộp thuế) liên quan đến việc bồi thường thiệt hại (nếu có). \n (*) Trường hợp bất khả kháng khác theo quy định tại khoản 1 Điều 3 Nghị định số 126/2020/NĐ-CP của Chính phủ, phải có: \n - Văn bản xác định giá trị thiệt hại vật chất của cơ quan tài chính hoặc cơ quan giám định độc lập xác định mức độ, giá trị thiệt hại đối với trường hợp do chiến tranh, bạo loạn, đình công mà người nộp thuế phải ngừng, nghỉ sản xuất, kinh doanh (bản chính hoặc bản sao có xác nhận của người nộp thuế); \n - Tài liệu chứng minh rủi ro không thuộc nguyên nhân, trách nhiệm chủ quan của người nộp thuế mà người nộp thuế không có khả năng nguồn tài chính nộp ngân sách nhà nước đối với trường hợp rủi ro không thuộc nguyên nhân, trách nhiệm chủ quan của người nộp thuế (bản chính hoặc bản sao có xác nhận của người nộp thuế); \n - Các chứng từ (bản chính hoặc bản sao có xác nhận của người nộp thuế) liên quan đến việc bồi thường thiệt hại của cơ quan bảo hiểm (nếu có). \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "++ Thông báo không chấp thuận miễn tiền chậm nộp (mẫu số 03/MTCN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính). \n ++ Hoặc Quyết định miễn tiền chậm nộp (mẫu số 02/MTCN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MTCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=3.000088"}, {"ma": "1.008538", "ten": "Khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ nhận thừa kế, quà tặng là các tài sản khác phải đăng ký quyền sở hữu, không phải là bất động sản", "cap_thuc_hien": "Cấp Xã", "doi_tuong": "Cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh,thành phố/Thuế cơ sở.", "trinh_tu": "- Bước 1: Cá nhân thuộc diện khai thuế thu nhập cá nhân đối với cá nhân có thu nhập từ nhận thừa kế, quà tặng (trừ bất động sản), chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế. Thời hạn nộp hồ sơ khai thuế chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế.\n Nơi nộp hồ sơ khai thuế như sau:\n + Cá nhân có thu nhập từ thừa kế, quà tặng là chứng khoán, phần vốn góp nộp hồ sơ khai thuế tại cơ quan thuế quản lý đơn vị phát hành Trường hợp có nhiều cơ quan thuế quản lý nhiều đơn vị phát hành thì nộp hồ sơ khai thuế tại cơ quan thuế nơi cá nhân nhận thừa kế, quà tặng cư trú.\n + Cá nhân có thu nhập từ nhận thừa kế, quà tặng là tài sản khác phải đăng ký quyền sở hữu, quyền sử dụng nộp hồ sơ khai thuế tại cơ quan thuế nơi nộp hồ sơ khai lệ phí trước bạ.\n - Bước 2: Cơ quan thuế thực hiện tiếp nhận: \n + Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n + Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "- Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân nhận thừa kế, quà tặng không phải là bất động sản) mẫu số 04/TKQT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n - Bản sao giấy tờ pháp lý chứng minh quyền nhận thừa kế, quà tặng và cá nhân ký cam kết chịu trách nhiệm vào bản sao đó \n - Hồ sơ xác định đối tượng được miễn thuế thu nhập cá nhân, không phải nộp thuế thu nhập cá nhân, tạm thời chưa phải nộp thuế thu nhập cá nhân theo quy định \n Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Thông báo nộp thuế của cơ quan thuế mẫu 04/TB-TKQT-TNCN ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["04/TKQT-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008538"}, {"ma": "1.011043", "ten": "Đăng ký mới/bổ sung thông tin đăng ký/thu hồi tài khoản truy cập Cổng thông tin điện tử đề khai thác sử dụng thông tin hóa đơn điện tử", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "+ Các cơ quan quản lý nhà nước sử dụng thông tin hóa đơn điện tử để thực hiện các thủ tục hành chính theo quy định của pháp luật, các tổ chức tín dụng, tổ chức cung cấp dịch vụ hóa đơn điện tử có văn bản về việc tra cứu, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử,…", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Đăng ký mới/bổ sung thông tin đăng ký\n Bước 1: \n + Đối tượng: Các cơ quan quản lý nhà nước sử dụng thông tin hóa đơn điện tử để thực hiện các thủ tục hành chính theo quy định của pháp luật, các tổ chức tín dụng, tổ chức cung cấp dịch vụ hóa đơn điện tử có văn bản về việc tra cứu, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử,…\n Bên sử dụng thông tin có trách nhiệm phân công đầu mối đăng ký sử dụng thông tin hóa đơn điện tử và thông báo cho Cơ quan thuế bằng văn bản.\n + Đầu mối đăng ký của bên sử dụng thông tin gửi 01 văn bản đến Cơ quan thuế để đề nghị đăng ký mới hoặc bổ sung thông tin hoặc thu hồi tài khoản theo Mẫu số 01/CCTT-ĐK Phụ lục II ban hành kèm theo Nghị định 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ.\n Bước 2: Gửi văn bản đề nghị đến cơ quan thuế.\n Bước 3: Cơ quan thuế tiếp nhận và xử lý theo quy định.\n Trong thời hạn không quá 02 ngày làm việc kể từ khi nhận được văn bản đề nghị, cơ quan thuế thực hiện việc cấp tài khoản mới hoặc bổ sung thông tin hoặc thu hồi tài khoản và thông báo với bên sử dụng thông tin bằng văn bản. Cơ quan thuế thực hiện cấp tối đa 02 tài khoản khai thác sử dụng thông tin điện tử.\n Trường hợp không chấp nhận đăng ký tài khoản hoặc không bổ sung thời hạn sử dụng của tài khoản phải nêu rõ lý do; Các tài khoản đăng ký mới cấp cho từng cá nhân được thông báo bằng hình thức gửi thư điện tử.\n Thời hạn sử dụng tài khoản truy cập Cổng thông tin điện tử đối với trường hợp đăng ký mới và bổ sung thông tin là 12 tháng hoặc do bên sử dụng thông tin đề nghị nhưng không quá 12 tháng tính từ ngày Cơ quan thuế gửi văn bản thông báo kết quả đăng ký mới hoặc bổ sung thời hạn sử dụng cho đầu mối đăng ký của bên sử dụng thông tin.\n Cơ quan thuế thu hồi tài khoản truy cập trong các trường hợp sau:\n a) Khi có đề nghị từ đầu mối đăng ký của bên sử dụng thông tin;\n b) Thời hạn sử dụng đã hết;\n c) Tài khoản truy cập Cổng thông tin điện tử không thực hiện việc tra cứu thông tin trong thời gian 06 tháng liên tục;\n d) Phát hiện trường hợp sử dụng thông tin hóa đơn điện tử không đúng mục đích, phục vụ cho hoạt động nghiệp vụ theo chức năng, nhiệm vụ của bên sử dụng thông tin, không đúng quy định của pháp luật về bảo vệ bí mật nhà nước.\n Chậm nhất là 05 ngày làm việc trước thời điểm chính thức chấm dứt sử dụng các hình thức cung cấp, sử dụng thông tin hóa đơn điện tử của bên sử dụng thông tin (trừ trường hợp đầu mối đăng ký của bên sử dụng thông tin có đề nghị bằng văn bản), Cơ quan thuế thông báo bằng hình thức điện tử cho bên sử dụng thông tin về việc chấm dứt sử dụng các hình thức cung cấp, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử.\n Bước 4: Cơ quan thuế thông báo theo Mẫu số 01/CCTT-TB Phụ lục II ban hành kèm theo Nghị định số 123/2020/NĐ-CP thông báo về việc tiếp nhận và kết quả xư lý về việc đăng ký mới hoặc bổ sung nội dung cung cấp thông tin/tài khoản truy cập hóa đơn điện tử, chứng từ điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Trường hợp bên sử dụng thông tin đề nghị: Mẫu số 01/CCTT-ĐK Đề nghị đăng ký mới hoặc bổ sung tài khoản truy cập/nội dung cung cấp thông tin hóa đơn điện tử, chứng từ điện tử. \n + Trường hợp Cơ quan thuế chủ động chấm dứt: Cơ quan thuế thông báo bằng hình thức điện tử cho bên sử dụng thông tin về việc chấm dứt sử dụng các hình thức cung cấp, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử trừ trường hợp đầu mối đăng ký của bên sử dụng thông tin có đề nghị bằng văn bản (không có mẫu) \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Trường hợp bên sử dụng thông tin đề nghị: Tài khoản được đăng ký mới/bổ sung thông tin đăng ký: trả Mẫu 01/CCTT-TB Thông báo về việc tiếp nhận và kết quả xử lý về việc đăng ký mới hoặc bổ sung nội dung cung cấp thông tin/tài khoản truy cập hóa đơn điện tử, chứng từ điện tử. \n + Trường hợp Cơ quan thuế chủ động chấm dứt: Không trả thông báo, Cơ quan thuế thu hồi tài khoản.", "dieu_kien": "+ Các cơ quan quản lý nhà nước sử dụng thông tin hóa đơn điện tử để thực hiện các thủ tục hành chính theo quy định của pháp luật, các tổ chức tín dụng, tổ chức cung cấp dịch vụ hóa đơn điện tử có văn bản về việc tra cứu, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử có văn bản về việc tra cứu, sử dụng thông tin hóa đơn điện tử, chứng từ điện tử. \n + Đảm bảo cơ sở hạ tầng CNTT để nhận dữ liệu tới cơ quan thuế bằng phương thức điện tử", "can_cu_phap_ly": "+ Căn cứ Khoản 29, khoản 31, khoản 32 Điều 1 Nghị định số 70/225/NĐ-CP ngày 20/3/2025 của Chính phủ. \n + Căn cứ Điều 49, Điều 50 Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 quy định về hóa đơn, chứng từ. \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011043"}, {"ma": "1.010995", "ten": "Khai thuế và các khoản thu khác đối với hoạt động dầu khí và bán dầu khí (áp dụng cho các hợp đồng dầu khí)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung.", "co_quan": "Thuế tỉnh, thành phố/Chi cục thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính hoặc chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc hợp đồng dầu khí. \n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai quyết toán phụ thu theo mẫu số 02/PTHU-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế c \n ++ Phụ lục bảng kê sản lượng và giá bán dầu thô khai thác Mẫu số 04/PTHU-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP) và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC). \n ++ Phụ lục bảng kê số phụ thu tạm tính đã nộp Mẫu số 05/PTHU-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 100/2009/NĐ-CP ngày 03/11/2009 của Chính phủ Quy định thu phụ thu đối với phần dầu lãi được chia của nhà thầu dầu khí khi giá dầu thô biến động tăng; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 22/2010/TT-BTC ngày 12/02/2010 của Bộ Tài chính hướng dẫn thực hiện Nghị định số 100/2009/NĐ-CP ngày 03/11/2009 của Chính phủ quy định thu phụ thu đối với phần dầu lãi được chia của nhà thầu dầu khí khi giá dầu thô biến động tăng; \n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/PTHU-DK"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010995"}, {"ma": "1.008504", "ten": "Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh có thay đổi thông tin về địa chỉ trụ sở dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp thực hiện tại cơ quan thuế nơi người nộp thuế chuyển đi; doanh nghiệp/hợp tác xã/tổ hợp tác/hộ kinh doanh thực hiện nộp hồ sơ tại CQT nơi chuyển đi trước khi thực hiện thủ tục thay đổi với cơ quan đăng ký kinh doanh", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Doanh nghiệp, hợp tác xã, tổ hợp tác, hộ kinh doanh, tổ chức, hộ gia đình/cá nhân kinh doanh.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "(i) Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh có thay đổi thông tin về địa chỉ trụ sở dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp thực hiện tại cơ quan thuế nơi người nộp thuế chuyển đi; doanh nghiệp/hợp tác xã/tổ hợp tác/hộ kinh doanh thực hiện nộp hồ sơ tại CQT nơi chuyển đi trước khi thực hiện thủ tục thay đổi với cơ quan đăng ký kinh doanh (Mã 1.008504)\n + Bước 1: Người nộp thuế đăng ký thuế trực tiếp với CQT khi có thay đổi thông tin về địa chỉ trụ sở trên tờ khai đăng ký thuế dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp phải thực hiện thủ tục thay đổi thông tin đăng ký thuế trong thời hạn 10 ngày làm việc kể từ ngày phát sinh thông tin thay đổi gửi đến cơ quan thuế quản lý trực tiếp (CQT nơi chuyển đi).\n Người nộp thuế đăng ký thuế cùng với đăng ký doanh nghiệp/hợp tác xã/tổ hợp tác/hộ kinh doanh khi có thay đổi địa chỉ trụ sở sang tỉnh, thành phố trực thuộc Trung ương khác hoặc thay đổi địa chỉ trụ sở sang địa bàn cấp huyện khác nhưng cùng địa bàn tỉnh, thành phố trực thuộc Trung ương làm thay đổi cơ quan thuế quản lý trực tiếp thì người nộp thuế phải nộp hồ sơ thay đổi cho cơ quan thuế quản lý trực tiếp (cơ quan thuế nơi chuyển đi) để thực hiện các thủ tục về thuế trước khi đăng ký thay đổi địa chỉ trụ sở đến cơ quan đăng ký kinh doanh. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (ii) Đăng ký hủy chuyển địa điểm tại cơ quan thuế nơi chuyển đi (Mã 1.010694)\n + Bước 1: Trong thời hạn 10 (mười) ngày làm việc kể từ ngày cơ quan thuế nơi chuyển đi ban hành Thông báo về việc người nộp thuế chuyển địa điểm mẫu số 09-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hướng dẫn về đăng ký thuế, nếu người nộp thuế không thực hiện chuyển địa điểm thì nộp Văn bản đăng ký hủy chuyển địa điểm đến cơ quan thuế nơi chuyển đi theo mẫu số 31/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính hướng dẫn về đăng ký thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "(i) Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh có thay đổi thông tin về địa chỉ trụ sở dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp thực hiện tại cơ quan thuế nơi người nộp thuế chuyển đi; doanh nghiệp/hợp tác xã/tổ hợp tác/hộ kinh doanh thực hiện nộp hồ sơ tại CQT nơi chuyển đi trước khi thực hiện thủ tục thay đổi với cơ quan đăng ký kinh doanh (Mã 1.008504) \n + Thành phần hồ sơ, gồm: \n * Đối với người nộp thuế là doanh nghiệp, hợp tác xã, tổ hợp tác, hộ kinh doanh: Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; \n + Đối với người nộp thuế là tổ chức kinh tế, tổ chức khác theo quy định tại Điểm a, b, c, đ, h, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gồm: \n ++ Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; \n ++ Bản sao Giấy phép thành lập và hoạt động hoặc văn bản tương đương do cơ quan có thẩm quyền cấp trong trường hợp địa chỉ trên các Giấy tờ này có thay đổi. \n * Đối với người nộp thuế theo quy định tại Điểm d, i Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính: Tờ khai điều chỉnh, bổ sung thông tin đăng ký thuế mẫu số 08-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; \n + Số lượng hồ sơ: 01 (bộ). \n (ii) Đăng ký hủy chuyển địa điểm tại cơ quan thuế nơi chuyển đi (Mã 1.010694) \n + Thành phần hồ sơ, gồm: \n Văn bản đăng ký hủy chuyển địa điểm mẫu số 31/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "(i) Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh có thay đổi thông tin về địa chỉ trụ sở dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp thực hiện tại cơ quan thuế nơi người nộp thuế chuyển đi; doanh nghiệp/hợp tác xã/tổ hợp tác/hộ kinh doanh thực hiện nộp hồ sơ tại CQT nơi chuyển đi trước khi thực hiện thủ tục thay đổi với cơ quan ĐKKD. \n Thông báo người nộp thuế chuyển địa điểm mẫu số 09-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính. \n (ii) Đăng ký hủy chuyển địa điểm tại cơ quan thuế nơi chuyển đi. \n Thông báo về việc xác nhận người nộp thuế hủy chuyển địa điểm mẫu số 36/TB-ĐKT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["08-MST", "31/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008504"}, {"ma": "1.010994", "ten": "Khai phụ thu tạm tính đối với phần dầu lãi được chia của nhà thầu dầu khí khi giá dầu thô biến động tăng (trừ Lô 09.1)", "cap_thuc_hien": "Cấp Tỉnh, Thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế.\n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã;\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;.\n+ Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Tờ khai phụ thu tạm tính Mẫu số 01/PTHU-DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "'+ Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành;\n + Luật quản lý thuế ngày 13/6/2019;\n + Nghị định số 100/2009/NĐ-CP ngày 03/11/2009 của Chính phủ Quy định thu phụ thu đối với phần dầu lãi được chia của nhà thầu dầu khí khi giá dầu thô biến động tăng;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia;\n + Thông tư số 22/2010/TT-BTC ngày 12/02/2010 của Bộ Tài chính hướng dẫn thực hiện Nghị định số 100/2009/NĐ-CP ngày 03/11/2009 của Chính phủ quy định thu phụ thu đối với phần dầu lãi được chia của nhà thầu dầu khí khi giá dầu thô biến động tăng;\n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010994"}, {"ma": "1.014032", "ten": "Thủ tục kê khai, nộp thuế đối với cá nhân không cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Cá nhân không cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán theo quy định tại Nghị định số 117/2025/NĐ-CP", "co_quan": "Chi cục Thuế Thương mại điện tử.", "trinh_tu": "Cá nhân không cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán trực tiếp thực hiện nộp thuế GTGT và thuế TNCN đối với hàng hóa, dịch vụ kinh doanh trên nền tảng thương mại điện tử theo tỷ lệ phần trăm trên doanh thu theo quy định của Luật thuế GTGT, Luật thuế TNCN. Cá nhân không cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán thực hiện đăng ký giao dịch thuế điện tử, đăng ký thuế lần đầu thông qua hồ sơ khai thuế. Cá nhân không cư trú thực hiện khai thuế GTGT đối với việc mua bán hàng hóa trong nước, cung cấp dịch vụ trên nền tảng thương mại điện tử, khai thuế TNCN và nộp thuế cho Chi cục thuế thương mại điện tử theo từng lần phát sinh. Thời hạn nộp hồ sơ khai thuế theo từng lần phát sinh chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế. Nộp thuế: Thực hiện theo quy định tại Luật quản lý thuế. Thời hạn nộp thuế chậm nhất là ngày cuối cùng của thời hạn nộp hồ sơ khai thuế.", "cach_thuc": "Bằng phương thức điện tử qua Hệ thống thông tin giải quyết TTHC của cơ quan thuế /Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thuế đối với cá nhân không cư trú kinh doanh nên nền tảng thương mại điện tử theo mẫu số 03/CNNN-TMĐT.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Cổng thông tin điện tử của Cục Thuế gửi phản hồi tự động về việc tiếp nhận và xử lý hồ sơ khai thuế theo quy định. \n + Cổng thông tin điện tử xử lý chứng từ nộp tiền và trả Thông báo liên quan tại Hệ thống Thuế điện tử Etax/Cổng dịch vụ công quốc gia/Cổng thanh toán điện tử của Ngân hàng.", "dieu_kien": "++ Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Điều 9 Nghị định số 117/2025/NĐ-CP ngày 09/6/2025 của Chính phủ quy định về quản lý thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số của hộ, cá nhân.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03/CNNN-TMĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014032"}, {"ma": "1.011006", "ten": "Khai tiền thuê đất", "cap_thuc_hien": "Cấp xã", "doi_tuong": "Cơ quan, tổ chức, hộ gia đình, cá nhân.", "co_quan": "Thuế cơ sở", "trinh_tu": "+ Bước 1: \n Người nộp thuế nộp hồ sơ khai tiền thuê đất tại cơ chế một cửa liên thông, TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc qua Cổng DVC Quốc gia (trực tuyến). \n Đối với trường hợp thuê đất mà hồ sơ xác định nghĩa vụ tài chính về tiền thuê đất theo quy định tại cơ chế một cửa liên thông đồng thời là hồ sơ khai thuế: Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày cơ quan nhà nước có thẩm quyền ký quyết định cho thuê đất. Trường hợp chưa có quyết định nhưng có hợp đồng cho thuê đất thì thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày ký hợp đồng. \n Đối với trường hợp thuê đất chưa có quyết định cho thuê, hợp đồng cho thuê đất: Thời hạn nộp hồ sơ khai tiền thuê đất chậm nhất là 30 ngày kể từ ngày sử dụng đất vào mục đích thuộc đối tượng phải thuê đất. \n Thời hạn nộp hồ sơ khai tiền thuê đất đối với trường hợp trong năm có sự thay đổi các yếu tố để xác định nghĩa vụ tài chính về tiền thuê đất chậm nhất là 30 ngày kể từ ngày được cấp có thẩm quyền ban hành văn bản ghi nhận sự thay đổi.\n Người nộp thuế trong năm không có sự thay đổi các yếu tố dẫn đến thay đổi số tiền thuê đất phải nộp thì không phải kê khai năm tiếp theo. \n + Bước 2. Cơ quan thuế tiếp nhận: Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định; Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm: \n ++ Trường hợp đã có quyết định cho thuê đất hoặc chưa có quyết định nhưng đã có hợp đồng cho thuê đất \n +++ Hồ sơ khai để xác định nghĩa vụ tài chính về tiền thuê đất theo quy định tại cơ chế một cửa liên thông; \n +++ Văn bản của người sử dụng đất đề nghị được miễn, giảm các khoản nghĩa vụ tài chính về đất đai (bản chính) theo mẫu 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư 40/2025/TT-BTC và Thông tư 94/2025/TT-BTC) và bản sao các giấy tờ chứng minh thuộc đối tượng được miễn, giảm theo quy định của pháp luật (nếu có); \n +++ Tài liệu, giấy tờ liên quan đến các khoản được trừ vào tiền thuê đất phải nộp theo quy định của pháp luật (nếu có). \n ++ Trường hợp chưa có quyết định, hợp đồng cho thuê đất. \n ++ Tờ khai tiền thuê đất mẫu 01/TMĐN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư 40/2025/TT-BTC và Thông tư 94/2025/TT-BTC). \n ++ Các giấy tờ khác liên quan (nếu có). \n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Thông báo nộp tiền thuê đất theo Mẫu số 01a hoặc Mẫu số 01b tại Phụ lục II ban hành kèm theo Nghị định số 103/2024/NĐ-CP ngày 30/7/2024 của Chính phủ (sửa đổi, bổ sung tại Nghị định số 291/2025/NĐ-CP ngày 06/11/2025 của Chính phủ).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế ; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 103/2024/NĐ-CP ngày 30/7/2024 của Chính phủ quy định về tiền sử dụng đất, tiền thuê đất; \n + Nghị định số 291/2025/NĐ-CP ngày 06/11/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 103/2024/NĐ-CP ngày 30 tháng 7 năm 2024 của Chính phủ quy định về tiền sử dụng đất, tiền thuê đất và Nghị định số 104/2024/NĐ-CP ngày 31 tháng 7 năm 2024 của Chính phủ quy định về quỹ phát triển đất; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "01/TMĐN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011006"}, {"ma": "1.008553", "ten": "Khai thuế thu nhập doanh nghiệp tạm tính đối với thu nhập từ tiền kết dư của phần dầu để lại/ Khai phụ thu tạm tính đối với dầu lãi từ tiền kết dư của phần dầu để lại áp dụng cho Liên doanh Vietsovpetro tại Lô 09.1", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Liên doanh Vietsovpetro hoặc đơn vị được Vietsovpetro uỷ quyền.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế: \n Thời hạn nộp hồ sơ: Chậm nhất là ngày thứ 10 kể từ ngày Hội đồng Liên doanh quyết định số tiền kết dư của phần dầu để lại theo Nghị quyết từng kỳ họp Hội đồng Liên doanh nhưng không chậm hơn ngày 31 tháng 12 hàng năm.\n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Trường hợp (1) khai thuế thu nhập doanh nghiệp tạm tính đối với thu nhập từ tiền kết dư của phần dầu để lại, hồ sơ gồm: Tờ khai thuế thu nhập doanh nghiệp tạm tính Mẫu số 01-1/TNDN-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Trường hợp (2) khai phụ thu tạm tính đối với dầu lãi từ tiền kết dư của phần dầu để lại, hồ sơ gồm: Tờ khai phụ thu tạm tính Mẫu số 01-1/PTHU-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và Nghị định thư sửa đổi, bổ sung; \n + Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và Nghị định thư 2013; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008553"}, {"ma": "1.008345", "ten": "Tra soát, điều chỉnh thông tin thu, nộp ngân sách nhà nước", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế phát hiện thông tin đã ghi nhận trong hệ thống ứng dụng quản lý thuế của ngành thuế do cơ quan thuế cung cấp định kỳ theo quy định có sai khác với thông tin theo dõi của người nộp thuế hoặc phát hiện thông tin đã khai trên chứng từ nộp ngân sách nhà nước không chính xác gửi hồ sơ đề nghị tra soát đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn ( Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN)/Cổng thông tin điện tử của Cục Thuế (trường hợp TTHC đã toàn trình nhưng chưa tích hợp lên cổng DVC quốc gia) để lập hồ sơ khai và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại TTPVHCC cấp tỉnh, xã hoặc hồ sơ được gửi qua dịch vụ bưu chính công ích: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị tra soát cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Ccục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 01 (một) ngày làm việc kể từ ngày gửi Thông báo tiếp nhận hồ sơ đề nghị tra soát điện tử.\n + Bước 3. Cơ quan thuế xử lý hồ sơ đề nghị tra soát\n Cơ quan thuế thực hiện đối chiếu thông tin đề nghị tra soát của người nộp thuế với dữ liệu trên hệ thống ứng dụng quản lý thuế. Trường hợp thông tin theo dõi thực hiện nghĩa vụ thuế của người nộp thuế chưa đủ thông tin thì Thông báo yêu cầu bổ sung thông tin theo mẫu 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế để người nộp thuế giải trình, bổ sung thông tin, tài liệu. Kể từ ngày nhận được đủ hồ sơ đề nghị tra soát của NNT:\n ++ Trường hợp thông tin theo dõi thực hiện nghĩa vụ thuế của NNT trên hệ thống ứng dụng quản lý thuế có sai sót so với căn cứ theo dõi nghĩa vụ thuế của NNT thì cơ quan thuế thực hiện điều chỉnh thông tin trên hệ thống theo đúng căn cứ theo dõi nghĩa vụ thuế của NNT.\n ++ Trường hợp thông tin theo dõi thực hiện nghĩa vụ thuế của NNT là chính xác với căn cứ theo dõi nghĩa vụ thuế thì cơ quan thuế gửi thông báo không điều chỉnh cho NNT được biết.\n ++ Trường hợp nội dung đề nghị điều chỉnh chứng từ của NNT đáp ứng đủ các điểu kiện để điều chỉnh thông tin theo quy định thì cơ quan thuế lập Văn bản đề nghị điểu chỉnh thu NSNN gửi Kho bạc Nhà nước để đề nghị điều chỉnh. Căn cứ thông tin chứng từ điểu chỉnh của Kho bạc Nhà nước gửi đến qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện hạch toán theo thông tin điều chỉnh của Kho bạc Nhà nước, điều chỉnh số tiền chậm nộp tăng hoặc giảm phát sinh của khoản điểu chỉnh (nếu có). Đồng thời, gửi thông báo giải quyết văn bản đề nghị tra soát cho người nộp thuế. \n ++ Trường hợp nội dung đề nghị điều chỉnh chứng từ của người nộp thuế không đáp ứng đủ điều kiện thì cơ quan thuế gửi thông báo không điều chỉnh, ghi rõ lý do cho người nộp thuế biết. \n + Bước 4. Cơ quan thuế trả kết quả xử lý hồ sơ đề nghị tra soát\n Cơ quan thuế ban hành Thông báo về việc điều chỉnh/không điều chỉnh thông tin đề nghị tra soát mẫu 01/TB-TS ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "Thành phần hồ sơ theo Điều 69 và Danh mục mẫu biểu tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC gồm: \n + Văn bản đề nghị tra soát theo mẫu số 01/TS; \n + Tài liệu chứng minh (nếu có): Bản sao chứng từ nộp ngân sách nhà nước của người nộp thuế hoặc bản sao các quyết định, thông báo, chứng từ có liên quan. \n Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Thông báo về việc điều chỉnh/không điều chỉnh thông tin đề nghị tra soát mẫu 01/TB-TS;", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/TS"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008345"}, {"ma": "1.008008", "ten": "Đăng ký giao dịch với cơ quan thuế bằng phương thức điện tử/Đăng ký thay đổi, bổ sung thông tin giao dịch điện tử", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Người nộp thuế (NNT) theo quy định tại Điều 2 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn về giao dịch điện tử trong lĩnh vực thuế đã được cấp chứng thư số hoặc mã xác thực giao dịch điện tử do hệ thống của cơ quan thuế hoặc hệ thống của các cơ quan có liên quan đến giao dịch điện tử cấp.", "co_quan": "Cục Thuế - Bộ Tài chính", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) thực hiện truy cập vào Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính /Cổng của tổ chức cung cấp dịch vụ T-VAN thực hiện đăng ký giao dịch/Đăng ký thay đổi, bổ sung thông tin, ký điện tử và gửi đến Cục Thuế.\n Riêng đối với NNT là cá nhân đã có mã số thuế chưa được cấp chứng thư số và sử dụng mã xác thực giao dịch điện tử sau khi thực hiện đăng ký giao dịch điện tử phải đến cơ quan thuế bất kỳ xuất trình chứng minh thư nhân dân; hoặc hộ chiếu hoặc thẻ căn cước công dân để nhận và kích hoạt tài khoản giao dịch thuế điện tử. \n NNT là cá nhân đã đăng ký và kích hoạt tài khoản định danh điện tử Mức độ 2; đồng thời hệ thống định danh, xác thực điện tử và Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính đã được kết nối, vận hành thì NNT được sử dụng tài khoản định danh điện tử thay thế cho việc xuất trình chứng minh thư nhân dân hoặc hộ chiếu/thẻ căn cước công dân/thẻ căn cước để thực hiện thủ tục đăng ký, kích hoạt tài khoản giao dịch điện tử.\n Sau khi hoàn thành việc thực hiện đăng ký giao dịch điện tử với cơ quan thuế theo quy định qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính hoặc qua tổ chức cung cấp dịch vụ T-VAN, NNT phải thực hiện đăng ký với ngân hàng nơi mở tài khoản theo quy định của ngân hàng (đối với trường hợp đăng ký để thực hiện nộp thuế điện tử).\n + Bước 2. Cục Thuế thực hiện tiếp nhận hồ sơ qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế..", "cach_thuc": "Bằng phương thức điện tử qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính hoặc qua tổ chức cung cấp dịch vụ T-VAN.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n ++ Trường hợp (1): Đăng ký giao dịch với cơ quan thuế bằng phương thức điện tử: Tờ khai đăng ký giao dịch với cơ quan thuế bằng phương thức điện tử theo mẫu số 01/ĐK-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.\n ++ Trường hợp (2): Đăng ký thay đổi, bổ sung thông tin giao dịch điện tử: Tờ khai đăng ký thay đổi, bổ sung thông tin giao dịch thuế điện tử theo mẫu số 02/ĐK-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.\n + Số lượng hồ sơ gồm: 01 (bộ)", "ket_qua": "Thông báo tài khoản giao dịch thuế điện tử theo mẫu số 03/TB-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "dieu_kien": "Đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế (theo quy định tại khoản 1 Điều 4, khoản 1 và khoản 2 Điều 7, điểm c khoản 1 và khoản 5 Điều 10 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính).", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật Giao dịch điện tử số 51/2005/QH11 ngày 29/11/2005; Luật Công nghệ thông tin số 67/2006/QH11 ngày 29/06/2006;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 165/2018/NĐ-CP ngày 24/12/2018 của Chính phủ quy định về giao dịch điện tử trong hoạt động tài chính; Nghị định số 130/2018/NĐ-CP ngày 27/9/2018 của Chính phủ quy định chi tiết thi hành Luật giao dịch điện tử về chữ ký số và dịch vụ chứng thực chữ ký số; Nghị định số 45/2020/NĐ-CP ngày 08/4/2020 của Chính phủ về thực hiện thủ tục hành chính trên môi trường điện tử; Nghị định số 11/2020/NĐ-CP ngày 20/01/2020 của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn về giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/7/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐK-TĐT", "02/ĐK-TĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008008"}, {"ma": "1.010337", "ten": "Đăng ký sử dụng hoá đơn điện tử/ Thay đổi nội dung đăng ký sử dụng hoá đơn điện tử/ ủy nhiệm lập hóa đơn điện tử/ Chuyển đổi áp dụng hóa đơn điện tử có mã của cơ quan thuế/Khai thác dữ liệu của chi nhánh, đơn vị phụ thuộc/Thông báo tạm ngừng sử dụng hóa đơn điện tử/Tích hợp hóa đơn điện tử với biên lai thu thuế, phí, lệ phí”", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Doanh nghiệp; tổ chức kinh tế, tổ chức khác; hộ kinh doanh, cá nhân kinh doanh; Cơ quan thuế hoặc cơ quan được giao nhiệm vụ tổ chức, xử lý tài sản công; Nhà cung cấp ở nước ngoài không có sơ sở thường trú tại Việt Nam có hoạt động kinh doanh thương mại điện tử, kinh doanh dựa trên nền tảng số và các dịch vụ khác.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Bước 1: \n (i) Doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh thuộc trường hợp được sử dụng hóa đơn điện tử;\n (ii) Trường hợp sử dụng hóa đơn điện tử có mã của cơ quan thuế không phải trả tiền dịch vụ;\n (iii) Cơ quan thuế hoặc cơ quan được giao nhiệm vụ tổ chức, xử lý tài sản công;\n (iv) Doanh nghiệp là tổ chức kết nối chuyển dữ liệu hóa đơn điện tử theo hình thức gửi trực tiếp.\n Thực hiện truy cập vào Cổng thông tin điện tử hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử, để đăng ký sử dụng hoá đơn điện tử/ Thay đổi nội dung đăng ký sử dụng hoá đơn điện tử/ Ủy nhiệm lập hóa đơn điện tử/ Chuyển đổi áp dụng hóa đơn điện tử có mã của cơ quan thuế/khai thác dữ liệu của chi nhánh, đơn vị phụ thuộc/ Thông báo tạm ngừng sử dụng hóa đơn điện tử/Tích hợp hóa đơn điện tử với biên lai thu thuế, phí, lệ phí.\n (v) Nhà cung cấp ở nước ngoài không có sơ sở thường trú tại Việt Nam có hoạt động kinh doanh thương mại điện tử, kinh doanh dựa trên nền tảng số và các dịch vụ khác. \n Thực hiện truy cập vào Cổng thông tin điện tử dành cho nhà cung cấp ở nước ngoài của Cục Thuế để đăng ký sử dụng hoá đơn điện tử/ Thay đổi nội dung đăng ký sử dụng hoá đơn điện tử.\n + Trường hợp (1): Đăng ký sử dụng hoá đơn điện tử\n ++ Đăng ký qua tổ chức cung cấp dịch vụ hóa đơn điện tử: \n Doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh không thuộc đối tượng ngừng sử dụng hóa đơn theo quy định tại khoản 12 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 (sửa đổi khoản 1 Điều 16 Nghị định số 123/2020/NĐ-CP) của Chính phủ quy định về hóa đơn, chứng từ đăng ký sử dụng hóa đơn điện tử (bao gồm cả đăng ký hóa đơn điện tử bán tài sản công, hóa đơn điện tử bán hàng dự trữ quốc gia).\n ++ Đăng ký qua Cổng thông tin điện tử: \n Doanh nghiệp là tổ chức kết nối chuyển dữ liệu hóa đơn điện tử theo hình thức gửi trực tiếp đến cơ quan thuế thì đăng ký sử dụng hóa đơn điện tử.\n +++ Đăng ký qua Cổng thông tin điện tử dành cho nhà cung cấp ở nước ngoài của Cục Thuế\n Nhà cung cấp ở nước ngoài không có sơ sở thường trú tại Việt Nam có hoạt động kinh doanh thương mại điện tử, kinh doanh dựa trên nền tảng số và các dịch vụ khác. \n ++ Đăng ký qua Cổng thông tin điện tử hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử được Cục Thuế ủy thác cung cấp dịch vụ hóa đơn điện tử có mã của cơ quan thuế không phải trả tiền dịch vụ: \n Doanh nghiệp nhỏ và vừa, hợp tác xã, sử dụng hóa đơn điện tử có mã của cơ quan thuế không phải trả tiền dịch vụ theo quy định tại khoản 1 Điều 14 Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ, thì có thể đăng ký sử dụng hóa đơn điện tử.\n Cơ quan thuế hoặc cơ quan được giao nhiệm vụ tổ chức, xử lý tài sản công theo quy định tại khoản 11 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025. \n Người nộp thuế gửi Mẫu 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP\n + Trường hợp (2): Thay đổi nội dung đăng ký sử dụng hoá đơn điện tử\n ++Trường hợp Người nộp thuế thay đổi thông tin sử dụng hóa đơn điện tử do thay đổi thông tin về người đại diện theo pháp luật; đại diện hộ kinh doanh, cá nhân kinh doanh, thành viên góp vốn, chủ sở hữu thì trình tự thủ tục thực hiện theo trường hợp (1)\n ++Trường hợp Người nộp thuế thay đổi thông tin sử dụng hóa đơn điện tử khác thì Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi yêu cầu đề nghị Người nộp thuế xác nhận qua địa chỉ thư điện tử hoặc điện thoại của chủ doanh nghiệp hoặc người đại diện theo pháp luật theo thông tin trong hồ sơ đăng ký thuế.\n Sau đó, Người nộp thuế gửi Mẫu 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử thì Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế tiếp nhận mẫu đăng ký thay đổi nội dung đăng ký sử dụng hóa đơn điện tử.\n + Trường hợp (3): Ủy nhiệm lập hóa đơn điện tử/chấm dứt trước thời hạn ủy nhiệm lập hóa đơn điện tử: Bên thứ ba (bên nhận ủy nhiệm lập hóa đơn điện tử (HĐĐT)) là đối tượng đủ điều kiện sử dụng HĐĐT và không thuộc trường hợp ngừng sử dụng HĐĐT theo quy định tại khoản 12 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 (sửa đổi khoản 1 Điều 16 Nghị định số 123/2020/NĐ-CP) của Chính phủ.\n Hóa đơn được ủy nhiệm cho bên thứ ba lập phải thể hiện tên đơn vị bán là bên ủy nhiệm. Việc ủy nhiệm phải được xác định bằng văn bản giữa bên ủy nhiệm và bên nhận ủy nhiệm thể hiện đầy đủ các thông tin về hóa đơn ủy nhiệm (mục đích ủy nhiệm; thời hạn ủy nhiệm; phương thức thanh toán hóa đơn ủy nhiệm) và phải thông báo cho cơ quan thuế khi đăng ký sử dụng hóa đơn điện tử. Trường hợp hóa đơn ủy nhiệm là hóa đơn điện tử không có mã của cơ quan thuế thì bên ủy nhiệm phải chuyển dữ liệu hóa đơn điện tử đến cơ quan thuế thông qua tổ chức cung cấp dịch vụ theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ.\n + Trường hợp (4): Chuyển đổi áp dụng hóa đơn điện tử có mã của cơ quan thuế:\n ++ Chuyển từ sử dụng hóa đơn điện tử không có mã sang hóa đơn điện tử có mã của cơ quan thuế:\n Trong thời gian mười (10) ngày làm việc kể từ ngày cơ quan thuế phát hành thông báo Mẫu số 01/TB-KTT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ về việc chuyển đổi áp dụng hóa đơn điện tử có mã của cơ quan thuế hoặc khi người nộp thuế đang sử dụng hóa đơn điện tử không có mã nếu có nhu cầu chuyển đổi áp dụng hóa đơn điện tử có mã của cơ quan thuế, phải thay đổi thông tin sử dụng hóa đơn điện tử (chuyển từ sử dụng hóa đơn điện tử không có mã sang hóa đơn điện tử có mã của cơ quan thuế), theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ, và gửi cơ quan thuế quản lý, qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử.\n ++ Chuyển từ sử dụng hóa đơn điện tử có mã của cơ quan thuế sang hóa đơn điện tử không có mã của cơ quan thuế:\n Sau 12 tháng kể từ thời điểm chuyển sang sử dụng hóa đơn điện tử có mã của cơ quan thuế, nếu người nộp thuế có nhu cầu sử dụng hóa đơn điện tử không có mã thì người nộp thuế thay đổi thông tin sử dụng hóa đơn điện tử, theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ, và gửi cơ quan thuế quản lý, qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử.\n + Trường hợp (5): khai thác dữ liệu chi nhánh, đơn vị phụ thuộc\n Trường hợp Công ty mẹ cần khai thác dữ liệu của các chi nhánh, đơn vị phụ thuộc thì thông báo tới cơ quan thuế quản lý trực tiếp công ty mẹ theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP.\n + Trường hợp (6): Thông báo tạm ngừng sử dụng hóa đơn điện tử\n Trường hợp Doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh tạm ngừng kinh doanh hoặc tạm ngừng sử dụng hóa đơn điện tử thì gửi Mẫu 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP tới có quan thuế quản lý .\n + Trường hợp (7): Tích hợp Hóa đơn điện tử với biên lai thu thuế, phí, lệ phí\n Trường hợp tổ chức thu thuế, phí, lệ phí và người cung cấp dịch vụ cùng thực hiện thu thuế, phí, lệ phí và tiền bán hàng hóa, cung cấp dịch vụ của một khách hàng thì được tích hợp biên lai thu thuế, phí, lệ phí và hóa đơn trên cùng một định dạng điện tử để giao cho người mua. Hóa đơn điện tử tích hợp phải đảm bảo có đủ nội dung của hóa đơn điện tử, biên lai điện tử và theo đúng định dạng do cơ quan thuế quy định. Người bán hàng hóa, cung cấp dịch vụ và tổ chức thu thuế, phí, lệ phí có trách nhiệm thỏa thuận về đơn vị chịu trách nhiệm lập hóa đơn điện tử tích hợp cho khách hàng và phải thông báo đến cơ quan thuế quản lý trực tiếp theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP\n Bước 2: Người nộp thuế ký và gửi đến cơ quan thuế quản lý qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử, hoặc Công thông tin điện tử dành cho nhà cung cấp ở nước ngoài không có cơ sở thường trú tại Việt Nam của Cục Thuế.\n Bước 3: Cục Thuế tiếp nhận hồ sơ theo Mẫu số 01/TB-TNĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử, hoặc Cổng thông tin điện tử dành cho nhà cung cấp ở nước ngoài không có cơ sở thường trú tại Việt Nam của Cục Thuế thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế và trả thông báo trực tiếp theo Mẫu số Thông báo số 01/TB-ĐKĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20 /3/2025.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Tờ khai đăng ký/ Thay đổi thông tin sử dụng hoá đơn điện tử theo Mẫu số 01/ĐKTĐ-HĐĐT Phụ lục IA kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Thông báo số 01/TB-TNĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP của Chính phủ về việc tiếp nhận/không tiếp nhận tờ khai đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/chứng từ điện tử \n + Thông báo số 01/TB-ĐKĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP của Chính phủ về việc chấp nhận/không chấp nhận đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/chứng từ điện tử.", "dieu_kien": "+ Đáp ứng điều kiện được sử dụng hóa đơn điện tử theo quy định. \n + Đảm bảo cơ sở hạ tầng CNTT để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử", "can_cu_phap_ly": "+ Khoản 3, khoản 11, khoản 12 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ quy định về hóa đơn, chứng từ. \n + Điều 14, Điều 15 Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ. \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010337"}, {"ma": "1.008568", "ten": "Miễn, giảm tiền thuê đất, tiền sử dụng đất", "cap_thuc_hien": "Cấp tỉnh, thành phố; Cấp xã", "doi_tuong": "(i) Miễn, giảm tiền thuê đất, thuê mặt nước: Tổ chức kinh tế; tổ chức, cá nhân nước ngoài, người Việt nam định cư ở nước ngoài.\n(ii) Miễn, giảm tiền sử dụng đất: Tổ chức và hộ gia đình, cá nhân.", "co_quan": "Thuế tỉnh, thành phố/ Thuế Cơ sở", "trinh_tu": "(i) Miễn, giảm tiền thuê đất\n + Bước 1: \n Tổ chức kinh tế, tổ chức cá nhân nước ngoài, người Việt Nam định cư ở nước ngoài nộp hồ sơ đề nghị miễn, giảm tiền thuê đất tại TTPVHCC cấp tỉnh, xã, cơ quan tiếp nhận hồ sơ thực hiện thủ tục hành chính về đất đai theo quy định tại cơ chế một cửa liên thông (trực tiếp) hoặc nộp qua Cổng DVC Quốc gia (trực tuyến). Trường hợp nộp hồ sơ miễn, giảm tiền thuê đất tại cơ quan tiếp nhận hồ sơ thực hiện thủ tục hành chính về đất đai theo quy định tại cơ chế một cửa liên thông thì việc luân chuyển hồ sơ cho cơ quan thuế theo quy định của pháp luật về trình tự, thủ tục tiếp nhận, luân chuyển hồ sơ xác định nghĩa vụ tài chính về đất đai của người sử dụng đất.\n Đối với trường hợp thuê đất mà hồ sơ xác định nghĩa vụ tài chính về tiền thuê đất theo quy định tại cơ chế một cửa liên thông đồng thời là hồ sơ khai thuế: Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày cơ quan nhà nước có thẩm quyền ký quyết định cho thuê đất. Trường hợp chưa có quyết định nhưng có hợp đồng cho thuê đất thì thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày ký hợp đồng.\n + Bước 2:\n Cơ quan thuế tiếp nhận: Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định; Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định (trường hợp thực hiện qua cơ chế 1 cửa liên thông thì đề nghị cơ quan tiếp nhận hồ sơ thực hiện thủ tục hành chính về đất đai theo quy định tại cơ chế một cửa liên thông yêu cầu người nộp thuế hoàn thiện).\n (ii) Miễn, giảm tiền sử dụng đất\n + Bước 1: \n Người sử dụng đất nộp văn bản của người sử dụng đất đề nghị được giảm tiền sử dụng đất và Giấy tờ chứng minh thuộc đối tượng được giảm tiền sử dụng đất theo Mẫu quy định tại pháp luật về quản lý thuế tại cơ quan có thẩm quyền theo quy định tại Nghị định về cấp giấy chứng nhận, TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc qua Cổng DVC Quốc gia (trực tuyến). Trên cơ sở đó, Văn phòng đăng ký đất đai hoặc cơ quan có chức năng quản lý đất đai hoặc bộ phận một cửa liên thông chuyển Phiếu chuyển thông tin cho cơ quan thuế để tính tiền sử dụng đất theo quy định của pháp luật.\n Đối với trường hợp được Nhà nước giao đất, chuyển mục đích sử dụng đất, công nhận quyền sử dụng đất mà hồ sơ xác định nghĩa vụ tài chính về tiền sử dụng đất theo quy định tại cơ chế một cửa liên thông đồng thời là hồ sơ khai thuế: Thời hạn nộp hồ sơ chậm nhất là 30 ngày kể từ ngày phát sinh nghĩa vụ với ngân sách nhà nước.\n + Bước 2:\n Cơ quan thuế tiếp nhận: Cơ quan thuế tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định; Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định (trường hợp thực hiện qua cơ chế 1 cửa liên thông thì đề nghị cơ quan tiếp nhận hồ sơ thực hiện thủ tục hành chính về đất đai theo quy định tại cơ chế một cửa liên thông yêu cầu người nộp thuế hoàn thiện).\n Đối với các trường hợp Hồ sơ “miễn tiền sử dụng đất trong hạn mức giao đất ở đối với hộ nghèo, hộ đồng bào dân tộc thiểu số ở vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn, biên giới, hải đảo theo danh mục các xã do cơ quan nhà nước có thẩm quyền ban hành; hồ sơ “giảm tiền sử dụng đất trong hạn mức giao đất ở đối với hộ nghèo, hộ đồng bào dân tộc thiểu số không thuộc vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn, biên giới, hải đảo”; Hồ sơ “Miễn tiền sử dụng đất trong hạn mức giao đất ở khi cấp Giấy chứng nhận đất lần đầu đối với đất do chuyển mục đích sử dụng từ đất không phải là đất ở sang đất ở do tách hộ đối với hộ đồng bào dân tộc thiểu số, hộ nghèo tại các xã đặc biệt khó khăn vùng đồng bào dân tộc và miền núi.” Cơ quan thuế có trách nhiệm khai thác thông tin trong Cơ sở dữ liệu quốc gia về dân cư theo quy định để xác định nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số, hộ nghèo tại địa phương thuộc vùng có đất ở được miễn, giảm tiền sử dụng đất; nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số, hộ nghèo tại các xã đặc biệt khó khăn vùng đồng bào dân tộc và miền núi.\n Trường hợp không thể khai thác được thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư thì cơ quan thuế yêu cầu cung cấp các giấy tờ, hồ sơ để xác định nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số, hộ nghèo tại địa phương thuộc vùng có đất ở được miễn, giảm tiền sử dụng đất theo quy định; nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số, hộ nghèo tại các xã đặc biệt khó khăn vùng đồng bào dân tộc và miền núi.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ\n (i) Miễn, giảm tiền thuê đất\n ++ Hồ sơ miễn tiền thuê đất trong thời gian xây dựng cơ bản, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư); \n +++ Bản sao Quyết định chủ trương đầu tư của cấp có thẩm quyền theo pháp luật về đầu tư (trừ trường hợp dự án đầu tư không thuộc diện phải cấp Quyết định chủ trương đầu tư theo pháp luật về đầu tư) hoặc văn bản chấp thuận chủ trương đầu tư theo pháp luật về đầu tư hoặc văn bản phê duyệt dự án theo quy định của pháp luật;\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền.\n ++Hồ sơ miễn, giảm tiền thuê đất theo quy định pháp luật về đầu tư, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư và trường hợp được Nhà nước giao đất không thu tiền sử dụng đất nay chuyển sang thuê đất hoặc được Nhà nước cho thuê đất nay thuộc đối tượng được miễn, giảm tiền thuê đất);\n +++ Bản sao Quyết định chủ trương đầu tư của cấp có thẩm quyền theo pháp luật về đầu tư (trừ trường hợp dự án đầu tư không thuộc diện phải cấp Quyết định chủ trương đầu tư theo pháp luật về đầu tư) hoặc văn bản chấp thuận chủ trương đầu tư theo pháp luật về đầu tư hoặc văn bản phê duyệt dự án theo quy định của pháp luật;\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền.\n ++ Hồ sơ miễn, giảm tiền thuê đất đối với Hợp tác xã, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư);\n +++ Bản sao Quyết định chủ trương đầu tư của cấp có thẩm quyền theo pháp luật về đầu tư (trừ trường hợp dự án đầu tư không thuộc diện phải cấp Quyết định chủ trương đầu tư theo pháp luật về đầu tư) hoặc văn bản chấp thuận chủ trương đầu tư theo pháp luật về đầu tư hoặc văn bản phê duyệt dự án theo quy định của pháp luật;\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền.\n ++ Hồ sơ đối với các trường hợp miễn tiền thuê đất không gắn với việc cho thuê đất mới theo quy định của Chính phủ, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền;\n +++ Bản sao Giấy tờ chứng minh thuộc đối tượng được miễn, giảm tiền thuê đất.\n ++ Hồ sơ miễn tiền thuê đất đối với hộ nông dân, hộ nông trường viên, xã viên hợp tác xã nông nghiệp nhận giao khoán của doanh nghiệp, hợp tác xã sản xuất nông nghiệp theo quy định của Chính phủ, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định cho thuê đất hoặc Hợp đồng cho thuê đất theo quy định của pháp luật đất đai;\n +++ Bản sao Giấy tờ chứng minh thuộc đối tượng được miễn, giảm tiền thuê đất.\n ++ Đối với trường hợp chủ đầu tư thực hiện dự án xây dựng nhà ở cho công nhân thuê trên đất thuê lại của doanh nghiệp kinh doanh kết cấu hạ tầng khu công nghiệp, cụm công nghiệp, hồ sơ bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC) của doanh nghiệp kinh doanh kết cấu hạ tầng đề nghị được miễn tiền thuê đất đối với diện tích đất cho nhà đầu tư thứ cấp thuê lại đất để thực hiện Dự án xây dựng nhà ở cho công nhân;\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC) của nhà đầu tư thứ cấp thuê lại đất của doanh nghiệp kinh doanh kết cấu hạ tầng đề nghị được miễn tiền thuê đất để thực hiện dự án xây dựng nhà ở cho công nhân;\n +++ Bản sao dự án xây dựng nhà ở cho công nhân được lập, thẩm định, phê duyệt theo quy định của pháp luật đầu tư, nhà ở;\n +++ Bản sao Quyết định phê duyệt dự án đầu tư xây dựng nhà ở cho công nhân theo quy định của pháp luật;\n +++ Bản sao Hợp đồng thuê lại đất giữa chủ đầu tư thực hiện dự án xây dựng nhà ở cho công nhân và doanh nghiệp kinh doanh kết cấu hạ tầng khu công nghiệp, cụm công nghiệp.\n ++ Hồ sơ miễn, giảm tiền thuê đất đối với đất xây dựng cơ sở nghiên cứu khoa học, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận doanh nghiệp công nghệ cao, doanh nghiệp khoa học và công nghệ, tổ chức khoa học và công nghệ;\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền.\n ++ Hồ sơ miễn, giảm tiền thuê đất theo quy định khác của Chính phủ, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư và trường hợp được Nhà nước giao đất không thu tiền sử dụng đất nay chuyển sang thuê đất hoặc được Nhà nước cho thuê đất nay thuộc đối tượng được miễn, giảm tiền thuê đất);\n +++ Bản sao Quyết định chủ trương đầu tư của cấp có thẩm quyền theo pháp luật về đầu tư (trừ trường hợp dự án đầu tư không thuộc diện phải cấp Quyết định chủ trương đầu tư theo pháp luật về đầu tư) hoặc văn bản chấp thuận chủ trương đầu tư theo pháp luật về đầu tư hoặc văn bản phê duyệt dự án theo quy định của pháp luật;\n +++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền;\n +++ Bản sao Giấy tờ chứng minh thuộc đối tượng được miễn, giảm tiền thuê đất.\n (ii) Miễn, giảm tiền sử dụng đất\n ++ Thành phần hồ sơ đối với đất trong hạn mức giao đất ở khi sử dụng đất để thực hiện chính sách nhà ở, đất ở đối với người có công với cách mạng, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Giấy tờ có liên quan chứng minh thuộc diện được miễn, giảm tiền sử dụng đất theo quy định của pháp luật về người có công với cách mạng;\n +++ Quyết định hoặc văn bản theo quy định của pháp luật về miễn, giảm tiền sử dụng đất của Ủy ban nhân dân cấp tỉnh hoặc của cơ quan được Ủy ban nhân dân cấp tỉnh ủy quyền, phân cấp.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất trong hạn mức giao đất ở đối với hộ nghèo, hộ đồng bào dân tộc thiểu số ở vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn, biên giới, hải đảo theo danh mục các xã do cơ quan nhà nước có thẩm quyền ban hành; hồ sơ giảm tiền sử dụng đất trong hạn mức giao đất ở đối với hộ nghèo, hộ đồng bào dân tộc thiểu số không thuộc vùng có điều kiện kinh tế - xã hội đặc biệt khó khăn, biên giới, hải đảo, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Đối với hộ gia đình là đồng bào dân tộc thiểu số: Cơ quan thuế có trách nhiệm khai thác thông tin trong Cơ sở dữ liệu quốc gia về dân cư theo quy định tại Điều 84 Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi, bổ sung tại Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính), để xác định nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số tại địa phương thuộc vùng có đất ở được miễn, giảm tiền sử dụng đất. Trường hợp không thể khai thác được thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư thì cơ quan thuế yêu cầu cung cấp bản sao Xác nhận thông tin về cư trú hoặc Thông báo số định danh cá nhân và thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư.\n +++ Đối với hộ nghèo: Cơ quan thuế có trách nhiệm khai thác thông tin trong Cơ sở dữ liệu quốc gia về dân cư theo quy định tại Điều 84 Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi, bổ sung tại Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính), để xác định nơi thường trú của hộ nghèo tại địa phương thuộc vùng có đất ở được miễn, giảm tiền sử dụng đất. Trường hợp không thể khai thác được thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư thì cơ quan thuế yêu cầu cung cấp bản sao Xác nhận thông tin về cư trú hoặc Thông báo số định danh cá nhân và thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư; Xác nhận của cơ quan có thẩm quyền về hộ nghèo theo quy định của Bộ Lao động - Thương binh và Xã hội.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất trong hạn mức giao đất ở khi cấp Giấy chứng nhận đất lần đầu đối với đất do chuyển mục đích sử dụng từ đất không phải là đất ở sang đất ở do tách hộ đối với hộ đồng bào dân tộc thiểu số, hộ nghèo tại các xã đặc biệt khó khăn vùng đồng bào dân tộc và miền núi, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Văn bản xác nhận của cơ quan nhà nước có thẩm quyền về chuyển mục đích sử dụng từ đất không phải là đất ở sang đất ở do tách hộ;\n +++ Cơ quan thuế có trách nhiệm khai thác thông tin trong Cơ sở dữ liệu quốc gia về dân cư theo quy định tại Điều 84 Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi, bổ sung tại Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính), để xác định nơi thường trú của hộ gia đình đồng bào dân tộc thiểu số, hộ nghèo tại các xã đặc biệt khó khăn vùng đồng bào dân tộc và miền núi. Trường hợp không thể khai thác được thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư thì cơ quan thuế yêu cầu cung cấp bản sao Xác nhận thông tin về cư trú hoặc Thông báo số định danh cá nhân và thông tin công dân trong Cơ sở dữ liệu quốc gia về dân cư. Đối với hộ nghèo phải có xác nhận của cơ quan có thẩm quyền về hộ nghèo theo quy định của Bộ Lao động- Thương binh và Xã hội.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với diện tích đất được giao trong hạn mức giao đất ở cho các hộ dân làng chài, dân sống trên sông nước, đầm phá di chuyển đến định cư tại các khu, điểm tái định cư theo quy hoạch, kế hoạch và dự án được cấp có thẩm quyền phê duyệt, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền;\n +++ Bản sao văn bản của cơ quan nhà nước có thẩm quyền về thực hiện dự án.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với phần diện tích đất được giao trong hạn mức giao đất ở để bố trí tái định cư hoặc giao cho các hộ gia đình, cá nhân trong các cụm, tuyến dân cư vùng ngập lũ theo dự án được cấp có thẩm quyền phê duyệt, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định giao đất ở để bố trí tái định cư của cơ quan nhà nước có thẩm quyền;\n +++ Bản sao văn bản của cơ quan nhà nước có thẩm quyền phê duyệt về thực hiện dự án.\n ++ Thành phần hồ sơ đối với miễn, giảm tiền sử dụng đất đối với dự án đầu tư vào lĩnh vực xã hội hoá được nhà nước giao đất có thu tiền sử dụng đất theo quy định pháp luật trước ngày Luật Đất đai năm 2013 có hiệu lực thi hành, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư);\n +++ Bản sao Quyết định chủ trương đầu tư của cấp có thẩm quyền theo pháp luật về đầu tư (trừ trường hợp dự án đầu tư không thuộc diện phải cấp Quyết định chủ trương đầu tư theo pháp luật về đầu tư) hoặc văn bản chấp thuận chủ trương đầu tư theo pháp luật về đầu tư hoặc văn bản phê duyệt dự án theo quy định của pháp luật;\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền để thực hiện dự án đầu tư.\n ++ Thành phần hồ sơ đối với miễn, giảm tiền sử dụng đất đối với dự án khuyến khích đầu tư, dự án đầu tư hạ tầng nghĩa trang, nghĩa địa theo quy định của pháp luật về đầu tư, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ trường hợp thuộc đối tượng không phải cấp các loại giấy tờ này theo pháp luật về đầu tư); hoặc Giấy chứng nhận doanh nghiệp khoa học và công nghệ, đối với doanh nghiệp khoa học và công nghệ);\n +++ Bản sao Quyết định chủ trương đầu tư (trừ trường hợp thuộc đối tượng không phải cấp Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư theo pháp luật về đầu tư);\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền để thực hiện dự án đầu tư.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với chủ đầu tư dự án xây dựng nhà ở xã hội theo quy định tại khoản 1 Điều 53 Luật nhà ở năm 2014, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định hoặc văn bản chấp thuận chủ trương đầu tư, phê duyệt dự án đầu tư của cấp có thẩm quyền theo quy định của pháp luật;\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với dự án nhà ở xã hội đầu tư theo quy định tại khoản 2 Điều 53 Luật nhà ở năm 2014 (trừ trường hợp miễn cho người lao động trong đơn vị mình thuê), gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định hoặc văn bản chấp thuận chủ trương đầu tư, phê duyệt dự án đầu tư của cấp có thẩm quyền theo quy định của pháp luật;\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền;\n +++ Cam kết của doanh nghiệp, hợp tác xã về giá cho thuê nhà không vượt quá giá thuê do Ủy ban nhân dân cấp tỉnh ban hành theo quy định của pháp luật nhà ở.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với dự án nhà ở xã hội đầu tư theo quy định tại khoản 2 Điều 53 Luật nhà ở năm 2014 cho người lao động trong đơn vị mình thuê, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định hoặc văn bản chấp thuận chủ trương đầu tư, phê duyệt dự án đầu tư của cấp có thẩm quyền theo quy định của pháp luật;\n +++ Bản sao Quyết định giao đất của cơ quan nhà nước có thẩm quyền;\n +++ Bản sao danh sách người lao động của doanh nghiệp, hợp tác xã được bố trí nhà ở có xác nhận của cơ quan nhà nước có thẩm quyền theo quy định của pháp luật nhà ở;\n +++ Cam kết của doanh nghiệp, hợp tác xã về giá cho thuê nhà không vượt quá giá thuê do Ủy ban nhân dân cấp tỉnh ban hành theo quy định của pháp luật nhà ở.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với dự án nhà ở xã hội đầu tư theo quy định tại khoản 3 Điều 53 Luật nhà ở năm 2014, gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Quyết định hoặc văn bản chấp thuận chủ trương đầu tư, phê duyệt dự án đầu tư của cấp có thẩm quyền theo quy định của pháp luật;\n +++ Bản sao Giấy tờ của cơ quan nhà nước quản lý về đất đai chứng nhận diện tích đất ở hợp pháp của chủ đầu tư theo quy định của pháp luật đất đai để đầu tư xây dựng nhà ở xã hội.\n ++ Thành phần hồ sơ đối với miễn tiền sử dụng đất đối với các trường hợp khác theo Quyết định của Thủ tướng Chính phủ, bao gồm:\n +++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n +++ Bản sao Giấy chứng nhận đầu tư hoặc Giấy phép đầu tư hoặc Giấy chứng nhận đăng ký đầu tư (trừ tr", "ket_qua": "+ Quyết định miễn thuế, giảm thuế theo mẫu số 03/MGTH ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. + Thông báo không được miễn thuế, giảm thuế theo mẫu số 04/MGTH ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "dieu_kien": "Không", "can_cu_phap_ly": "'+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Luật Cư trú ngày 13/11/2020;\n + Nghị định số 104/2022/NĐ-CP ngày 21/12/2022 của Chính phủ sửa đổi, bổ sung một số điều của các nghị định liên quan đến việc nộp, xuất trình sổ hộ khẩu, sổ tạm trú giấy khi thực hiện thủ tục hành chính, cung cấp dịch vụ công;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 123/2017/NĐ-CP của Chính phủ sửa đổi, bổ sung một số điều của các Nghị định quy định về thu tiền sử dụng đất, thu tiền thuê đất, thuê mặt nước;\n + Nghị định số 103/2024/NĐ-CP ngày 30/7/2024 của Chính phủ về tiền sử dụng đất, tiền thuê đất;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n + Thông tư số 76/2014/TT-BTC ngày 16/6/2014 của Bộ Tài chính hướng dẫn một số điều của Nghị định số 45/2014/NĐ-CP ngày 15/5/2014 của Chính phủ quy định về thu tiền sử dụng đất.\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp;\n + Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.N6\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008568"}, {"ma": "1.008505", "ten": "Đăng ký thay đổi thông tin đăng ký thuế đối với người nộp thuế là tổ chức, hộ gia đình/cá nhân kinh doanh có thay đổi thông tin về địa chỉ trụ sở dẫn đến làm thay đổi cơ quan thuế quản lý trực tiếp (thực hiện tại cơ quan thuế nơi người nộp thuế chuyển đến), trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, hộ gia đình/cá nhân kinh doanh.", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Trong thời hạn 10 (mười) ngày làm việc kể từ ngày cơ quan thuế nơi chuyển đi ban hành Thông báo người nộp thuế chuyển địa điểm (mẫu số 09-MST ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính Quy định về đăng ký thuế, người nộp thuế phải lập hồ sơ, gửi đến cơ quan thuế nơi chuyển đến theo nơi nộp hồ sơ như sau:\n - Người nộp thuế theo quy định tại điểm a, b, d, đ, h khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (trừ tổ hợp tác) nộp hồ sơ tại Cục Thuế nơi đặt trụ sở mới.\n - Người nộp thuế là tổ hợp tác, hộ gia đình/cá nhân kinh doanh theo quy định tại điểm b, i khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính nộp hồ sơ tại Chi cục Thuế, Chi cục Thuế khu vực nơi đặt trụ sở mới. \n - Người nộp thuế theo quy định tại điểm c, n khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính nộp hồ sơ tại Cục Thuế nơi người nộp thuế đóng trụ sở (tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập); tại Chi cục Thuế, Chi cục Thuế khu vực nơi tổ chức đóng trụ sở (tổ chức do cơ quan cấp huyện ra quyết định thành lập).\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n * Đối với người nộp thuế là tổ chức kinh tế, tổ chức khác theo quy định tại Điểm a, b, c, đ, h, n Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính gồm: \n ++ Văn bản đăng ký chuyển địa điểm tại cơ quan thuế nơi người nộp thuế chuyển đến mẫu số 30/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; \n ++ Bản sao Giấy phép thành lập và hoạt động hoặc văn bản tương đương do cơ quan có thẩm quyền cấp trong trường hợp địa chỉ trên các Giấy tờ này có thay đổi. \n * Đối với người nộp thuế theo quy định tại Điểm d, i Khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính: Văn bản đăng ký chuyển địa điểm tại cơ quan thuế nơi người nộp thuế chuyển đến mẫu số 30/ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính; \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Cơ quan thuế tiếp nhận hồ sơ có trách nhiệm cập nhật các thông tin thay đổi vào Hệ thống ứng dụng đăng ký thuế. Đồng thời, ban hành Giấy chứng nhận đăng ký thuế hoặc Thông báo mã số thuế đã cập nhật thông tin thay đổi gửi cho người nộp thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["30/ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008505"}, {"ma": "1.008326", "ten": "Khai thuế tạm tính đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên/Khai quyết toán thuế TNDN đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên (trừ Lô 09.1)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung, Liên doanh Vietsovpetro hoặc đơn vị được Vietsovpetro ủy quyền.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "(i) Trường hợp khai thuế tạm tính đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên\n + Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế:\n ++ Đối với dầu thô, condensate: chậm nhất là ngày thứ 35 kể từ ngày xuất bán dầu thô, condensate. Ngày xuất bán là ngày hoàn thành việc xuất bán dầu thô, condensate tại điểm giao nhận. Trường hợp ngày thứ 35 trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n ++ Đối với khí thiên nhiên: chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp ngày thứ 20 là ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.\n (ii) Trường hợp Khai quyết toán thuế TNDN đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên (trừ Lô 09.1):\n + Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính; Chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc hợp đồng dầu khí.\n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++Trường hợp (1) khai thuế tạm tính đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên \n +++ Tờ khai thuế tạm tính đối với dầu khí Mẫu số 01/TK-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n +++ Phụ lục chi tiết nghĩa vụ thuế của các nhà thầu dầu khí Mẫu số 01/PL-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++Trường hợp (2) Khai quyết toán thuế TNDN đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên (trừ Lô 09.1) \n +++ Tờ khai quyết toán thuế TNDN đối với dầu khí Mẫu số 02/TNDN–DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP) và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC). \n +++ Phụ lục chi tiết nghĩa vụ thuế của các nhà thầu dầu khí Mẫu số 01/PL-DK ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n +++ Báo cáo tài chính năm hoặc báo cáo tài chính đến thời điểm kết thúc hợp đồng dầu khí ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và các Nghị định thư sửa đổi, bổ sung. \n + Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n +Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và các Nghị định thư sửa đổi, bổ sung; \n + Thông tư số 36/2016/TT-BTC ngày 26/02/2016 của Bộ Tài chính hướng dẫn thực hiện quy định về thuế đối với tổ chức, cá nhân tiến hành hoạt động tìm kiếm thăm dò và khai thác dầu khí theo quy định của Luật dầu khí; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008326"}, {"ma": "1.008543", "ten": "Khấu trừ số thuế đã nộp tại nước ngoài vào thuế phải nộp tại Việt Nam", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Các tổ chức, cá nhân là đối tượng cư trú của Việt Nam đã nộp thuế tại Nước ký kết Hiệp định thuế với Việt Nam và số thuế đã nộp là đúng với quy định của luật nước ngoài và quy định của Hiệp định chuẩn bị hồ sơ đề nghị khấu trừ số thuế đã nộp tại nước ngoài vào thuế phải nộp tại Việt Nam gửi đến cơ quan thuế quản lý trực tiếp. \n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Giấy đề nghị khấu trừ thuế nước ngoài vào thuế phải nộp tại Việt Nam theo Hiệp định thuế theo mẫu số 02/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC), \n ++ Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế \n ++ Bản sao hợp đồng với Bên Việt Nam có xác nhận của tổ chức, cá nhân nước ngoài hoặc đại diện được uỷ quyền; \n ++ Trường hợp khấu trừ trực tiếp: Người nộp thuế đã nộp thuế tại Nước ký kết Hiệp định với Việt Nam, và được khấu trừ vào số thuế phải nộp tại Việt Nam theo quy định của Hiệp định thuế \n +++ Bản sao Tờ khai thuế thu nhập ở nước ngoài có xác nhận của người nộp thuế; \n +++ Bản sao chứng từ nộp thuế ở nước ngoài có xác nhận của người nộp thuế; \n +++ Bản gốc xác nhận của Cơ quan thuế nước ngoài về số thuế đã nộp. \n ++ Trường hợp khấu trừ số thuế khoán: Người nộp thuế có thu nhập và lẽ ra phải nộp thuế tại Nước ký kết Hiệp định với Việt Nam, nhưng theo quy định tại luật của Nước ký kết đó được miễn hoặc giảm như một biện pháp ưu đãi đặc biệt, được khấu trừ vào số thuế phải nộp tại Việt Nam theo quy định của Hiệp định thuế. \n +++ Bản sao Tờ khai thuế thu nhập ở nước ngoài có xác nhận của người nộp thuế; \n +++ Bản sao đăng ký kinh doanh hoặc các chứng từ pháp lý xác nhận hoạt động kinh doanh tại nước ngoài có xác nhận của người nộp thuế; \n +++ Thư xác nhận của Nhà chức trách có thẩm quyền nước ngoài về số thuế đã miễn, giảm và xác nhận việc đề nghị khấu trừ số thuế khoán là phù hợp với Hiệp định thuế và luật pháp của Nước ký kết Hiệp định thuế có liên quan \n ++ Trường hợp khấu trừ gián tiếp: Người nộp thuế đã nộp thuế thu nhập doanh nghiệp đối với thu nhập trước khi được chia cho đối tượng đó tại Nước ký kết Hiệp định với Việt Nam và được khấu trừ vào số thuế phải nộp tại Việt Nam theo quy định của Hiệp định thuế. \n +++ Các tài liệu pháp lý chứng minh quan hệ và tỉ lệ góp vốn của đối tượng đề nghị khấu trừ; \n +++ Bản sao Tờ khai thuế thu nhập ở nước ngoài của công ty chia lãi cổ phần mà đối tượng tham gia góp vốn có xác nhận của người nộp thuế; \n +++ Bản sao Tờ khai thuế khấu trừ tại nguồn đối với lợi tức cổ phần được chia có xác nhận của người nộp thuế; \n +++ Xác nhận của Cơ quan thuế nước ngoài về số thuế đã nộp đối với cổ phần được chia và số thuế thu nhập công ty đã nộp trước khi chia lãi cổ phần \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "không có", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật cư trú 68/2020/QH14 ngày 13/11/2020 của Ủy ban Thường vụ Quốc hội \n + Nghị định số 126 /2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Nghị định số 122/2025/NĐ-CP ngày 11 tháng 6 năm 2025 của Chính phủ. \n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Thông tư số 1 9/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế; \n + Nghị định số 104/2022/NĐ-CP của Chính phủ: Sửa đổi, bổ sung một số điều của các nghị định liên quan đến việc nộp, xuất trình sổ hộ khẩu, sổ tạm trú giấy khi thực hiện thủ tục hành chính, cung cấp dịch vụ công \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 40/2025/TT-BTC Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Thông tư số 94/2025/TT-BTC ngày 14/10/2025 sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/HTQT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008543"}, {"ma": "1.008579", "ten": "Miễn thuế, giảm thuế theo Hiệp định thuế đối với thu nhập từ hoạt động vận tải quốc tế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Người nước ngoài, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức nước ngoài", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "'+ Bước 1. Hãng hàng không nước ngoài và hãng vận tải nước ngoài thuộc diện được miễn thuế, giảm thuế do áp dụng Hiệp định tránh đánh thuế hai lần giữa Việt Nam và nước, vùng lãnh thổ khác chuẩn bị hồ sơ đề nghị miễn, giảm thuế theo quy định. Đối với hãng hàng không nước ngoài: trong thời hạn 15 (mười lăm) ngày trước khi khai thác thị trường bay hoặc trước kỳ tính thuế đầu tiên của năm (tuỳ theo thời điểm nào diễn ra trước), văn phòng tại Việt Nam của hãng Hàng không nước ngoài gửi cho cơ quan thuế hồ sơ thông báo thuộc diện miễn, giảm thuế theo Hiệp định thuế; Đối với hãng vận tải nước ngoài: khi quyết toán thuế đối với hãng vận tải nước ngoài, hãng vận tải nước ngoài hoặc đại lý của hãng vận tải nước ngoài phải gửi cho cơ quan thuế hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n ++ Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "1. Văn bản đề nghị theo mẫu số 01/HTQT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC)\n2. Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp ngay trước năm thông báo thuộc diện miễn, giảm thuế theo Hiệp định thuế đã được hợp pháp hoá lãnh sự;\n3. Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế.\n4. Trường hợp là hãng hàng không nước ngoài:\n++ Bản sao giấy phép khai thác thị trường Việt Nam (phép bay) của Cục hàng không dân dụng cấp theo quy định của Luật Hàng không dân dụng có xác nhận của người nộp thuế;\n++ Trường hợp năm trước đó đã có hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế thì các năm tiếp theo chỉ cần gửi các bản sao giấy phép khai thác thị trường Việt Nam (phép bay) của Cục hàng không dân dụng mới có xác nhận của người nộp thuế (nếu có).\n++ Trong thời hạn 15 (mười lăm) ngày trước khi kết thúc hợp đồng làm việc tại Việt Nam hoặc trước khi kết thúc năm tính thuế (tuỳ theo thời điểm nào diễn ra trước) văn phòng tại Việt Nam của hãng Hàng không nước ngoài gửi Giấy chứng nhận cư trú đã được hợp pháp hoá lãnh sự của năm tính thuế đó và Bảng kê thu nhập vận tải quốc tế dành cho trường hợp bán vé tại thị trường Việt Nam theo mẫu số 01-1/HKNN, Bảng kê thu nhập vận tải quốc tế dành cho trường hợp hoán đổi, chia chỗ trong vận tải hàng không quốc tế theo mẫu số 01-2/HKNN của năm tính thuế liên quan cho cơ quan thuế làm căn cứ áp dụng miễn, giảm thuế thu nhập doanh nghiệp từ hoạt động vận tải quốc tế của hãng Hàng không nước ngoài.\n5. Trường hợp là hãng vận tải nước ngoài:\n++ Đại lý của hãng vận tải nước ngoài tại Việt Nam hoặc Văn phòng Đại diện của hãng vận tải nước ngoài có trách nhiệm lưu trữ các hồ sơ, tài liệu, chứng từ theo quy định của Luật kế toán, Nghị định hướng dẫn Luật kế toán và Bộ Luật Hàng hải và xuất trình khi cơ quan thuế yêu cầu\n++ Kết thúc năm, hãng vận tải nước ngoài hoặc đại lý của hãng vận tải nước ngoài gửi cơ quan thuế Giấy chứng nhận cư trú đã được hợp pháp hóa lãnh sự của hãng tàu cho năm đó\n++ Trường hợp năm trước đó đã có hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế, thì các năm tiếp theo hãng vận tải nước ngoài hoặc đại lý của hãng vận tải nước ngoài chỉ cần thông báo bất kỳ sự thay đổi nào về các thông tin đã đề nghị tại mẫu số 01/HTQT của năm trước đó và cung cấp các tài liệu tương ứng với việc thay đổi\n++ Trường hợp các hãng vận tải nước ngoài có các đại lý tại nhiều địa phương ở Việt Nam hoặc các đại lý của hãng vận tải nước ngoài có các chi nhánh hoặc văn phòng đại diện (sau đây gọi chung là chi nhánh) tại nhiều địa phương ở Việt Nam thì các hãng vận tải nước ngoài hoặc đại lý của hãng vận tải nước ngoài nộp bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú đã hợp pháp hóa lãnh sự cho Cục Thuế địa phương nơi đại lý của hãng vận tải nước ngoài có trụ sở chính; gửi bản sao Giấy chứng nhận cư trú đã hợp pháp hóa lãnh sự tại các Cục Thuế địa phương nơi hãng vận tải nước ngoài có chi nhánh và ghi rõ nơi đã nộp bản gốc (hoặc bản sao đã được chứng thực) trong Văn bản đề nghị miễn, giảm thuế theo Hiệp định thuế.", "ket_qua": "Thông báo về việc người nộp thuế thuộc hoặc không thuộc diện được miễn thuế theo Hiệp định thuế hoặc Điều ước quốc tế khác (Mẫu số 03-1/MGTH).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế;\n+ Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/HKNN", "01-2/HKNN", "01/HTQT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008579"}, {"ma": "1.014031", "ten": "Thủ tục kê khai, nộp thuế của cá nhân cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán (chỉ áp dụng cho kỳ tính thuế nhỏ hơn ngày 06/04/2026)", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Hộ, cá nhân cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán", "co_quan": "Thuế tỉnh, thành phố; Thuế cơ sở", "trinh_tu": "Hộ, cá nhân cư trú có hoạt động kinh doanh trên nền tảng thương mại điện tử không có chức năng thanh toán trực tiếp thực hiện nghĩa vụ thuế GTGT, thuế TNCN, thuế tiêu thụ đặc biệt, thuế bảo vệ môi trường, thuế tài nguyên và các khoản thu khác phải nộp ngân sách nhà nước do cơ quan thuế quản lý thu theo quy định của pháp luật về thuế và pháp luật khác có liên quan. \n Khai thuế: Hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử thực hiện kê khai theo tháng và Hộ, cá nhân có hoạt động kinh doanh không thường xuyên trên nền tảng thương mại điện tử thực hiện kê khai theo từng lần phát sinh. Thời hạn nộp hồ sơ khai thuế theo tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế; Thời hạn nộp hồ sơ khai thuế theo từng lần phát sinh chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế.\n Nộp thuế: Nộp thuế qua Cổng thông tin tiếp nhận và xử lý thủ tục hành chính của Cục Thuế/ Nộp thuế qua Cổng dịch vụ Công quốc gia/ Nộp thuế qua dịch vụ thanh toán của ngân hàng thương mại (NHTM), chi nhánh ngân hàng nước ngoài. Thời hạn nộp thuế chậm nhất là ngày cuối cùng của thời hạn nộp hồ sơ khai thuế.", "cach_thuc": "Bằng phương thức điện tử qua Hệ thống thông tin giải quyết TTHC của cơ quan thuế /Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thuế đối với hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử theo mẫu số 02/CNKD-TMĐT\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Cổng thông tin điện tử của Cục Thuế gửi phản hồi tự động về việc tiếp nhận và xử lý hồ sơ khai thuế theo quy định. \n + Cổng thông tin điện tử xử lý chứng từ nộp tiền và trả Thông báo liên quan tại Hệ thống Thuế điện tử Etax/Cổng dịch vụ công quốc gia/Cổng thanh toán điện tử của Ngân hàng.", "dieu_kien": "++ Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Điều 8 Nghị định số 117/2025/NĐ-CP ngày 09/6/2025 của Chính phủ quy định về quản lý thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số của hộ, cá nhân.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/CNKD-TMĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014031"}, {"ma": "1.008563", "ten": "Hoàn thuế theo Hiệp định tránh đánh thuế hai lần và Điều ước quốc tế khác", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX)", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân thuộc diện hoàn thuế theo Hiệp định tránh đánh thuế hai lần hoặc Điều ước quốc tế khác chuẩn bị hồ sơ đề nghị hoàn thuế và gửi đến Thuế tỉnh, thành phố quản lý nơi tổ chức có trụ sở điều hành, nơi cá nhân có cơ sở thường trú hoặc Thuế tỉnh, thành phố nơi tổ chức, cá nhân đã nộp số thuế đề nghị hoàn. \n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "1. Giấy đề nghị hoàn thuế theo Hiệp định tránh đánh thuế hai lần và Điều ước quốc tế khác mẫu số 02/HT ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC); \n 2. Giấy ủy quyền trong trường hợp tổ chức, cá nhân uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế. Trường hợp tổ chức, cá nhân lập giấy uỷ quyền để uỷ quyền cho đại diện hợp pháp thực hiện thủ tục hoàn thuế vào tài khoản của đối tượng khác cần thực hiện thủ tục hợp pháp hóa lãnh sự (nếu việc uỷ quyền được thực hiện ở nước ngoài) hoặc công chứng (nếu việc uỷ quyền được thực hiện tại Việt Nam) theo quy định; \n 3. Bảng kê chứng từ nộp thuế mẫu số 02-1/HT ban hành kèm theo Thông tư. \n 4. Trường hợp đề nghị hoàn thuế theo Hiệp định thuế: \n ++ Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp đã được hợp pháp hóa lãnh sự trong đó ghi rõ là đối tượng cư trú trong năm tính thuế nào; \n ++ Bản sao hợp đồng kinh tế, hợp đồng cung cấp dịch vụ, hợp đồng đại lý, hợp đồng uỷ thác, hợp đồng chuyển giao công nghệ hoặc hợp đồng lao động ký với tổ chức, cá nhân Việt Nam, giấy chứng nhận tiền gửi tại Việt Nam, giấy chứng nhận góp vốn vào Công ty tại Việt Nam (tuỳ theo loại thu nhập trong từng trường hợp cụ thể) có xác nhận của người nộp thuế; \n ++ Văn bản xác nhận của tổ chức, cá nhân Việt Nam ký kết hợp đồng về thời gian và tình hình hoạt động thực tế theo hợp đồng (trừ trường hợp hoàn thuế đối với hãng vận tải nước ngoài); \n 5. Trường hợp đề nghị hoàn thuế theo Điều ước quốc tế khác\\ \n ++ Bản sao Điều ước quốc tế \n ++ Bản sao hợp đồng với Bên Việt Nam có xác nhận của tổ chức, cá nhân nước ngoài hoặc đại diện được uỷ quyền; \n ++ Bản tóm tắt hợp đồng có xác nhận của tổ chức, cá nhân nước ngoài hoặc đại diện được uỷ quyền. Bản tóm tắt hợp đồng gồm các nội dung sau: tên hợp đồng và tên các điều khoản của hợp đồng, phạm vi công việc của hợp đồng, nghĩa vụ thuế tại hợp đồng;", "ket_qua": "Quyết định hoàn thuế kiêm bù trừ thu Ngân sách nhà nước, Thông báo về việc không được hoàn thuế (Mẫu số 04/TB-HT), Quyết định hoàn thuế (Mẫu số 01/QĐHT), Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ (Mẫu số 01/PL-BT)", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021của Bộ Tài chính hướng dẫn giao dich điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính ửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế \n + Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02-1/HT", "02/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008563"}, {"ma": "1.008548", "ten": "Báo cáo dự kiến sản lượng dầu khí khai thác và tỷ lệ tạm nộp thuế (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế: \n ++ Trường hợp hợp đồng dầu khí có thỏa thuận kỳ tính thuế tài nguyên theo năm thì căn cứ sản lượng dầu thô, khí thiên nhiên dự kiến khai thác năm tiếp theo, người nộp thuế xác định tỷ lệ thuế tài nguyên tạm tính thông báo cho cơ quan thuế địa phương nơi đăng ký thuế biết chậm nhất là ngày 01 tháng 12 của kỳ tính thuế năm trước. \n Trong kỳ tính thuế, trường hợp dự kiến sản lượng dầu thô, khí thiên nhiên khai thác, dự kiến số ngày khai thác dầu khí 6 tháng cuối năm thay đổi dẫn đến tăng hoặc giảm tỷ lệ tạm nộp thuế tài nguyên từ 15% trở lên so với tỷ lệ tạm nộp thuế tài nguyên tạm tính đã thông báo với cơ quan thuế thì người nộp thuế có trách nhiệm xác định và thông báo tỷ lệ thuế tài nguyên tạm tính mới cho cơ quan thuế biết chậm nhất là ngày 01 tháng 5 năm đó. \n ++ Trường hợp hợp đồng dầu khí bắt đầu được đưa vào khai thác thương mại, người nộp thuế có trách nhiệm xác định và thông báo tỷ lệ thuế tài nguyên tạm tính cho cơ quan thuế khi khai nộp thuế tài nguyên tạm tính đối với các chuyến dầu thô, khí thiên nhiên đầu tiên được khai thác và xuất bán trong diện tích hợp đồng. \n + Bước 2. Cơ quan thuế tiếp nhận: \n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n Trường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế: \n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế \n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế. \n + Hoặc gửi qua hệ thống bưu chính. \n + Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Báo cáo dự kiến sản lượng dầu khí khai thác và tỷ lệ tạm nộp thuế số 01/BCTL-DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008, Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 33/2013/NĐ-CP ngày 22/4/2013 của Chính phủ Ban hành hợp đồng mẫu của Hợp đồng Chia sản phẩm dầu khí, Nghị định số 45/2023/NĐ-CP ngày 01/7/2023 của Chính quy định chi tiết một số điều của luật dầu khí ; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế , Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 36/2016/TT-BTC ngày 26/02/2016 của Bộ Tài chính hướng dẫn thực hiện quy định về thuế đối với tổ chức, cá nhân tiến hành hoạt động tìm kiếm thăm dò và khai thác dầu khí theo quy định của Luật dầu khí; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư s ố 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính. \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008548"}, {"ma": "1.007700", "ten": "Khai lệ phí trước bạ/ Miễn lệ phí trước bạ đối với tài sản khác theo quy định của pháp luật về lệ phí trước bạ (trừ tàu thuyền đánh cá, tàu thuyền vận tải thuỷ nội địa, tàu biển nếu thiếu hồ sơ gốc hoặc đóng mới tại Việt Nam)", "cap_thuc_hien": "Cấp xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1: Tổ chức, cá nhân khi đăng ký quyền sử dụng, quyền sở hữu tài sản trừ nhà, đất (bao gồm cả các trường hợp thuộc diện miễn lệ phí trước bạ theo quy định của pháp luật về lệ phí trước bạ) nộp hồ sơ khai lệ phí trước bạ tại cơ quan thuế nơi đăng ký quyền sở hữu, quyền sử dụng hoặc địa điểm do Ủy ban nhân dân cấp tỉnh quyết định.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm: \n ++ Tờ khai lệ phí trước bạ theo mẫu số 02/LPTB tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC); \n ++ Bản sao các Giấy tờ về mua bán, chuyển giao tài sản hợp pháp; \n ++ Bản sao Giấy đăng ký quyền sở hữu, sử dụng tài sản của chủ cũ hoặc bản sao Giấy chứng nhận thu hồi đăng ký, biển số xe của cơ quan Công an xác nhận (đối với tài sản đăng ký quyền sở hữu, sử dụng tại Việt Nam từ lần thứ 2 trở đi) \n ++ Bản sao các giấy tờ chứng minh tài sản hoặc chủ tài sản thuộc đối tượng được miễn lệ phí trước bạ (nếu có). \n Giấy tờ chứng minh tài sản (hoặc chủ tài sản) thuộc diện miễn lệ phí trước bạ trong một số trường hợp quy định tại Thông tư số 80/2021/TT-BTC. \n ++ Bản sao Giấy chứng nhận chất lượng an toàn kỹ thuật và bảo vệ môi trường do cơ quan Đăng kiểm Việt Nam cấp (đối với ô tô, rơ moóc hoặc sơ mi rơ moóc được kéo bởi ô tô, các loại xe tương tự) \n Số lượng hồ sơ: 01 bộ", "ket_qua": "Thông báo nộp lệ phí trước bạ trong vòng 01 ngày làm việc kể từ khi nhận đủ hồ sơ hợp lệ.Trường hợp hồ sơ không hợp lệ thì Thuế cơ sở trả lại hồ sơ cho người có tài sản.", "dieu_kien": "Không có", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/LPTB"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007700"}, {"ma": "1.115132", "ten": "Thủ tục Khai thuế thu nhập doanh nghiệp, thuế thu nhập cá nhân đối với thu nhập từ chuyển nhượng tài sản mã hóa của tổ chức được thành lập theo quy định của pháp luật nước ngoài (tổ chức nước ngoài) và cá nhân (bao gồm cả cá nhân cư trú và cá nhân không cư trú) do Tổ chức cung cấp dịch vụ tài sản mã hóa khấu trừ, khai thay, nộp thay", "cap_thuc_hien": "Cục Thuế", "doi_tuong": "Tổ chức cung cấp dịch vụ tài sản mã hóa là doanh nghiệp thực hiện, cung cấp một hoặc một số dịch vụ, hoạt động sau: Tổ chức thị trường giao dịch tài sản mã hóa; Tự doanh tài sản mã hóa; Lưu ký tài sản mã hóa; Cung cấp nền tảng phát hành tài sản mã hóa .", "co_quan": "Cơ quan thuế quản lý trực tiếp Tổ chức cung cấp dịch vụ do Cục trưởng Cục Thuế quyết định", "trinh_tu": "+ Bước 1: T ổ chức có hoạt động cung cấp dịch vụ tài sản mã hóa theo quy định tại khoản 3 Điều 3 Nghị quyết số 05/2025/NQ-CP chuẩn bị hồ sơ khai thuế và nộp đến cơ quan thuế. Thời gian nộp hồ sơ khai thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. \n T ổ chức có hoạt động cung cấp dịch vụ tài sản mã hóa thực hiện truy cập vào Cổng dịch vụ công Quốc gia hoặc Ứng dụng định danh quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính để khai tờ khai, ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn . \n + Bước 2: Cơ quan thuế tiếp nhận , kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "Trực tuyến q ua Cổng dịch vụ công quốc gia hoặc Ứng dụng định danh quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính.", "thanh_phan_ho_so": "Thành phần hồ sơ bao gồm: \n + Tờ khai khấu trừ thuế đối với cá nhân cư trú, cá nhân không cư trú và tổ chức nước ngoài có hoạt động chuyển nhượng tài sản mã hóa mẫu số 01/TSMH kèm theo Thông tư số 41/2026/TT-BTC ngày 06 tháng 4 năm 2026 của Bộ Tài chính hướng dẫn việc kê khai, khấu trừ, nộp thuế, quyết toán thuế trên thị trường tài sản mã hóa. \n + Phụ lục Bảng kê chi tiết số thuế đã khấu trừ của cá nhân cư trú, cá nhân không cư trú và tổ chức nước ngoài có hoạt động chuyển nhượng tài sản mã hóa mẫu số 01-1/TSMH kèm theo Thông tư số 41/2026/TT-BTC ngày 06 tháng 4 năm 2026 của Bộ Tài chính hướng dẫn việc kê khai, khấu trừ, nộp thuế, quyết toán thuế trên thị trường tài sản mã hóa. \n Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Người nộp thuế gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18 tháng 3 năm 2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18 tháng 3 năm 2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 được sửa đổi, bổ sung bởi Luật số 56/2024/QH15; \n + Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của N ghị định số 126/2020/ NĐ-CP ngày 19 tháng 10 năm 2020 của C hính phủ quy định chi tiết một số điều của L uật Q uản lý thuế ; Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của N ghị định số 126/2020/ NĐ-CP ngày 19 tháng 10 năm 2020 của C hính phủ quy định chi tiết một số điều của L uật Q uản lý thuế ; \n + Nghị quyết số 05/2025/NQ-CP ngày 09 tháng 9 năm 2025 của Chính phủ về việc triển khai thí điểm thị trường tài sản mã hóa tại Việt Nam; \n + Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13 tháng 6 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của T hông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của C hính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 21/2026/TT-BTC ngày 17 tháng 3 năm 2026 của Bộ Tài chính sửa đổi, bổ sung một số điều của T hông tư số 80/2021 /TT-BTC ngày 29 tháng 9 năm 2021 của B ộ T ài chính hướng dẫn thi hành một số điều của L uật Q uản lý thuế và Ng hị định số 126/2020/ NĐ-CP ngày 19 tháng 10 năm 2020 của C hính phủ quy định chi tiết một số điều của L uật Q uản lý thuế ; \n + Thông tư số 19/2021/TT-BTC ngày 18 tháng 3 năm 2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế ; Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của T hông tư số 19/2021/TT-BTC ngày 18 tháng 3 năm 2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế \n + Thông tư số 41/2026/TT-BTC ngày 06 tháng 4 năm 2026 của Bộ Tài chính hướng dẫn việc kê khai, khấu trừ, nộp thuế, quyết toán thuế trên thị trường tài sản mã hóa. \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TSMH", "01/TSMH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.115132"}, {"ma": "1.010990", "ten": "Khai tạm tính tiền lãi dầu, khí nước chủ nhà đối với hoạt động dầu khí", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tập đoàn Công nghệ-Năng lượng Quốc gia Việt Nam/Đơn vị được ủy quyền/Đại lý thuế.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế:\n ++ Đối với dầu thô, condensate: chậm nhất là ngày thứ 35 kể từ ngày xuất bán dầu thô, condensate. Ngày xuất bán là ngày hoàn thành việc xuất bán dầu thô, condensate tại điểm giao nhận. Trường hợp ngày thứ 35 trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n ++ Đối với khí thiên nhiên: chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp ngày thứ 20 là ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Tờ khai tạm tính tiền lãi dầu, khí nước chủ nhà Mẫu số 01/LNCN-DK ban hành kèm theo theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và các Nghị định thư sửa đổi, bổ sung. \n + Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành. \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 36/2021/NĐ-CP ngày 29/03/2021 của Chính phủ ban hành quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010990"}, {"ma": "1.010991", "ten": "Khai tạm tính tiền lãi dầu, khí nước chủ nhà được chia từ Liên doanh Vietsovpetro tại Lô 09.1 (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tập đoàn Dầu khí Việt Nam/Đơn vị được ủy quyền/Đại lý thuế.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế:\n++ Đối với dầu thô, condensate: chậm nhất là ngày thứ 35 kể từ ngày xuất bán dầu thô, condensate. Ngày xuất bán là ngày hoàn thành việc xuất dầu thô, condensate tại điểm giao nhận. Trường hợp ngày thứ 35 trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n++ Đối với khí thiên nhiên: chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp ngày thứ 20 là ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n+ Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\nTrường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế ;\n+ Hoặc gửi qua hệ thống bưu chính ;\n+ Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Tờ khai tạm tính tiền lãi dầu, khí nước chủ nhà theo mẫu số 01/LNCN-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n+ Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008 và các văn bản hướng dẫn thi hành; Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành;\n+ Luật thuế và các văn bản hướng dẫn hiện hành;\n+ Luật Quản lý thuế ngày 13/6/2019;\n+ Nghị định số 36/2021/NĐ-CP ngày 29/03/2021 của Chính phủ ban hành quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n+ Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính;\n+ Thông tư số 56/2008/TT-BTC ngày 23/06/2008 của Bộ Tài chính Hướng dẫn thực hiện kê khai, nộp và quyết toán các khoản thu của Nhà nước quy định tại Điều 18 Quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam ban hành kèm theo Nghị định số 142/2007/NĐ-CP ngày 5/9/2007 của Chính phủ;\n+ Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/LNCN-VSP"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010991"}, {"ma": "3.000084", "ten": "Giảm thuế tiêu thụ đặc biệt đối với người nộp thuế sản xuất hàng hóa thuộc diện chịu thuế tiêu thụ đặc biệt gặp khó khăn do thiên tai, tai nạn bất ngờ theo pháp luật về thuế tiêu thụ đặc biệt", "cap_thuc_hien": "Cấp tỉnh, thành phố, Cấp xã", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Thuế tỉnh/thuế cơ sở", "trinh_tu": "+ Bước 1: Người nộp thuế sản xuất hàng hóa thuộc diện chịu thuế tiêu thụ đặc biệt gặp khó khăn do thiên tai, tai nạn bất ngờ thì lập hồ sơ đề nghị giảm thuế cho cơ quan thuế\n+ Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\nCơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối với hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả, nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế;\n+ Hoặc gửi qua hệ thống bưu chính;\n+ Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \nĐối với người nộp thuế gặp khó khăn do thiên tai, hồ sơ giảm thuế gồm:\n++ Văn bản đề nghị theo mẫu số 01/MGTH ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ;\n++ Biên bản xác định mức độ, giá trị thiệt hại về tài sản của cơ quan có thẩm quyền và có xác nhận của chính quyền địa phương cấp xã nơi xảy ra thiên tai theo mẫu số 02/MGTH ban hành kèm theo phụ lục I Thông tư 80/2021/TT-BTC;\n++ Báo cáo tài chính (nếu là doanh nghiệp) kèm theo giải trình phân tích xác định số bị thiệt hại, số lỗ do bị thiệt hại.\nĐối với người nộp thuế gặp khó khăn do tai nạn bất ngờ, hồ sơ miễn, giảm thuế gồm:\n++ Văn bản đề nghị theo mẫu số 01/MGTH ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC;\n++ Văn bản hoặc biên bản xác nhận tai nạn có xác nhận của cơ quan công an hoặc xác nhận mức độ thương tật của cơ quan y tế;\n++ Giấy tờ xác định việc bồi thường của cơ quan bảo hiểm hoặc thỏa thuận bồi thường của người gây tai nạn (nếu có);\n++ Các chứng từ chi liên quan trực tiếp đến việc khắc phục tai nạn.\n+ Số lượng hồ sơ: 01 bộ", "ket_qua": "+ Quyết định miễn thuế, giảm thuế mẫu số 03/MGTH ban hành kèm theo ban hành kèm theo Thông tư số 80/2021/TT-BTC đối với trường hợp thuộc diện được miễn thuế, giảm thuế. + hoặc: Thông báo không được miễn thuế, giảm thuế mẫu số 04/MGTH ban hành kèm theo Thông tư số 80/2021/TT-BTC và nêu rõ lý do đối với trường không thuộc diện được miễn thuế, giảm", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n+ Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "02/MGTH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=3.000084"}, {"ma": "1.007699", "ten": "Khai lệ phí trước bạ tàu thuyền đánh cá, tàu thuyền vận tải thuỷ nội địa, tàu biển nếu thiếu hồ sơ gốc hoặc đóng mới tại Việt Nam", "cap_thuc_hien": "Cấp xã", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Tổ chức (không bao gồm doanh nghiệp, HTX), Hợp tác xã", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1: Tổ chức, cá nhân khi đăng ký quyền sử dụng, quyền sở hữu tài sản trừ nhà, đất (bao gồm cả các trường hợp thuộc diện miễn lệ phí trước bạ theo quy định của pháp luật về lệ phí trước bạ) nộp hồ sơ khai lệ phí trước bạ tại cơ quan thuế nơi đăng ký quyền sở hữu, quyền sử dụng hoặc địa điểm do Ủy ban nhân dân cấp tỉnh quyết định.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm: \n ++ Tờ khai lệ phí trước bạ theo mẫu số 02/LPTB tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC). \n ++ Bản sao Phiếu báo hoặc xác nhận của cơ quan có thẩm quyền về việc tàu thuyền thuộc đối tượng được đăng ký sở hữu. \n Số lượng hồ sơ: 01 bộ", "ket_qua": "Thông báo nộp lệ phí trước bạ trong vòng 01 ngày làm việc kể từ khi nhận đủ hồ sơ hợp lệ. Trường hợp hồ sơ không hợp lệ thì Thuế cơ sở trả lại hồ sơ cho người có tài sản.", "dieu_kien": "Không có", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/LPTB"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007699"}, {"ma": "1.008344", "ten": "Khai thuế thu nhập doanh nghiệp đối với hoạt động chuyển nhượng vốn của nhà thầu nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân nhận chuyển nhượng vốn có trách nhiệm khai thay nhà thầu nước ngoài chuẩn bị số liệu, lập hồ sơ khai thuế theo từng lần phát sinh và gửi đến cơ quan thuế quản lý trực tiếp doanh nghiệp nơi nhà thầu nước ngoài đầu tư vốn. Trường hợp tổ chức, cá nhân nhận chuyển nhượng vốn cũng là nhà thầu nước ngoài thì tổ chức thành lập theo pháp luật Việt Nam nơi nhà thầu nước ngoài đầu tư vốn lập hồ sơ khai thuế theo từng lần phát sinh và gửi đến cơ quan thuế quản lý trực tiếp doanh nghiệp nơi nhà thầu nước ngoài đầu tư vốn. Thời hạn nộp hồ sơ khai thuế chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế.\n ++ Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN), để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh hoặc qua Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành. Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp hoặc gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP) và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC),, gồm: \n ++ Tờ khai thuế thu nhập doanh nghiệp (áp dụng đối với thu nhập từ chuyển nhượng vốn) theo mẫu số 05/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC; \n ++ Bản sao hợp đồng chuyển nhượng, Bản sao chứng nhận vốn góp, chứng từ gốc của các khoản chi phí (nếu có). \n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019 sửa đổi, bổ sung tại Luật số 56/2024/QH15 ngày 29/11/2024 của Quốc hội sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính; \n + Luật Thuế thu nhập doanh nghiệp ngày 03/6/2008 và các văn bản pháp luật quy định chi tiết, hướng dẫn thi hành và sửa đổi, bổ sung có liên quan; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["05/TNDN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008344"}, {"ma": "1.008549", "ten": "Khai quyết toán thuế tài nguyên đối với cơ sở khai thác tài nguyên", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Thuế tỉnh/thuế cơ sở", "trinh_tu": "+ Bước 1: \n ++ Tổ chức, cá nhân khai thác tài nguyên thiên nhiên lập hồ sơ khai quyết toán thuế tài nguyên và gửi đến cơ quan thuế quản lý trực tiếp (trường hợp Tổ chức, cá nhân khai thác tài nguyên thiên nhiên có trụ sở chính tại tỉnh, thành phố này nhưng có hoạt động khai thác tài nguyên tại tỉnh, thành phố khác thì nộp hồ sơ khai thuế tại Thuế tỉnh, thành phố hoặc Thuế cơ sở do Trưởng Thuế tỉnh, thành phố nơi phát sinh hoạt động khai thác tài nguyên quy định).\n ++ Tổ chức, cá nhân có nhà máy sản xuất thuỷ điện thực hiện lập hồ sơ khai quyết toán thuế tài nguyên theo mẫu số 02/TAIN, gửi cho cơ quan thuế quản lý khoản thu ngân sách nhà nước nơi có hoạt động khai thác tài nguyên nước. Trường hợp tổ chức, cá nhân có hoạt động sản xuất thủy điện mà hồ thủy điện của nhà máy thủy điện nằm trên nhiều tỉnh thì nộp hồ sơ khai quyết toán thuế tài nguyên và phụ lục bảng phân bổ số thuế tài nguyên phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động sản xuất thủy điện của nhà máy thủy điện tại cơ quan thuế nơi có văn phòng điều hành nhà máy thủy điện và nộp số tiền thuế phân bổ cho tỉnh nơi có hồ thủy điện theo quy định.\n ++ Thời hạn nộp hồ sơ: Chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính hoặc là ngày thứ 45 kể từ ngày chấm dứt hoạt động, chấm dứt hợp đồng hoặc tổ chức lại doanh nghiệp.\n + Bước 2: Cơ quan thuế tiếp nhận hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n ++ Tờ khai quyết toán thuế tài nguyên mẫu số 02/TAIN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n ++ Phụ lục bảng phân bổ số thuế tài nguyên phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động sản xuất thủy điện mẫu số 01-1/TAIN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (áp dụng đối với cơ sở sản xuất thủy điện có hồ thủy điện nằm trên nhiều tỉnh).\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan Thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019;\n + Luật Thuế tài nguyên số 45/2009/QH12 ngày 25 tháng 11 năm 2009; Luật Dầu khí số 12/2022/QH15 ngày 14 tháng 11 năm 2022, Luật sửa đổi, bổ sung một số điều của các Luật về thuế số 71/2014/QH13 ngày 26 tháng 11 năm 2014;\n + Luật Khoáng sản số 60/2010/QH12 ngày 17 tháng 11 năm 2010, Luật Địa chất và Khoáng sản số 54/2024/QH15 ngày 29 tháng 11 năm 2024;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản;\n + Nghị định số 50/2010/NĐ-CP ngày 14 tháng 5 năm 2010 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Luật Thuế tài nguyên, Nghị định số 12/2015/NĐ-CP của Chính phủ ngày 12 tháng 02 năm 2015 quy định chi tiết thi hành luật sửa đổi, bổ sung một số điều của các Luật về thuế và sửa đổi, bổ sung một số điều của các Nghị định về thuế;\n + Điều 4 Nghị định số 12/2015/NĐ-CP ngày 12/2/2015 của Chính phủ quy định chi tiết thi hành Luật sửa đổi, bổ sung một số điều của các Luật về thuế và sửa đổi, bổ sung một số điều của Nghị định về thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n + Thông tư số 152/2015/TT-BTC ngày 02/10/2015 của Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 41/2024/TT-BTC ngày 20 tháng 5 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 44/2017/TT-BTC ngày 12 tháng 05 năm 2017 của Bộ trưởng Bộ Tài chính quy định khung giá tính thuế tài nguyên đối với nhóm, loại tài nguyên có tính chất lý, hóa giống nhau và Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 của Bộ trưởng Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 174/2016/TT-BTC ngày 28 tháng 10 năm 2016 của Bộ Tài chính sửa đổi, bổ sung điểm a khoản 4 điều 6 Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 của Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 12/2016/TT-BTC ngày 20 tháng 01 năm 2016 của Bộ Tài chính sửa đổi, bổ sung khoản 1 điều 7 Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 hướng dẫn về thuế tài nguyên;\n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TAIN", "02/TAIN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008549"}, {"ma": "1.008346", "ten": "Khai quyết toán thuế thu nhập doanh nghiệp theo phương pháp doanh thu - chi phí", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. \n Người nộp thuế thu nhập doanh nghiệp tính thuế theo phương pháp doanh thu - chi phí theo quy định của pháp luật về thuế thu nhập doanh nghiệp chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính đối với trường hợp khai quyết toán thuế thu nhập doanh nghiệp năm; chậm nhất là ngày thứ 45 (bốn mươi lăm), kể từ ngày có quyết định giải thể, phá sản, chấm dứt hoạt động hoặc tổ chức lại doanh nghiệp. Trường hợp người nộp thuế có đơn vị phụ thuộc, địa điểm kinh doanh khác tỉnh, thành phố nơi có trụ sở chính có thu nhập được hưởng ưu đãi thuế thu nhập doanh nghiệp thì lập hồ sơ khai quyết toán thuế đối với hoạt động được hưởng ưu đãi thuế thu nhập doanh nghiệp theo mẫu số 03-3A/TNDN, 03-3B/TNDN, 03-3C/TNDN, 03-3D/TNDN ban hành kèm theo phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính, gửi đến cơ quan thuế nơi có đơn vị được hưởng ưu đãi khác tỉnh chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính đối với trường hợp khai quyết toán thuế thu nhập doanh nghiệp năm; chậm nhất là ngày thứ 45 (bốn mươi lăm), kể từ ngày có quyết định giải thể, phá sản, chấm dứt hoạt động hoặc tổ chức lại doanh nghiệp; đồng thời người nộp thuế gửi các Phụ lục này cùng hồ sơ khai quyết toán thuế 03/TNDN ban hành kèm theo phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính đến cơ quan thuế quản lý trực tiếp.\n Trường hợp chuyển đổi loại hình doanh nghiệp (không bao gồm doanh nghiệp nhà nước cổ phần hóa) mà doanh nghiệp chuyển đổi kế thừa toàn bộ nghĩa vụ về thuế của doanh nghiệp được chuyển đổi thì không phải khai quyết toán thuế đến thời điểm có quyết định về việc chuyển đổi doanh nghiệp, doanh nghiệp khai quyết toán khi kết thúc năm.\n Trường hợp người nộp thuế thu nhập doanh nghiệp tính thuế theo phương pháp doanh thu - chi phí theo quy định của pháp luật về thuế thu nhập doanh nghiệp thực hiện tạm nộp thuế thu nhập doanh nghiệp theo quý (bao gồm cả tạm phân bổ số thuế thu nhập doanh nghiệp cho địa bàn cấp tỉnh nơi có đơn vị phụ thuộc, địa điểm kinh doanh, nơi có bất động sản chuyển nhượng khác với nơi người nộp thuế đóng trụ sở chính) chậm nhất là ngày 30 của tháng đầu quý sau và khai quyết toán thuế thu nhập doanh nghiệp năm.\n ++ Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN), để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp hoặc gửi qua đường bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh hoặc qua Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành. Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp hoặc gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n - + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ: Theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 /10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP) và Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung; sau đây gọi là Thông tư số 80/2021/TT-BTC), Nghị định số 132/2020/NĐ-CP ngày 05/11/2020 của Chính phủ quy định về quản lý thuế đối với doanh nghiệp có giao dịch liên kết; Nghị định số 20/2025/NĐ-CP ngày 10/02/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 132/2020/NĐ-CP ngày 05 tháng 11 năm 2020 của Chính phủ quy định về quản lý thuế đối với doanh nghiệp có giao dịch liên kết, gồm:\n (i) Hồ sơ khai quyết toán thuế theo năm:\n - Tờ khai quyết toán thuế thu nhập doanh nghiệp (áp dụng đối với phương pháp doanh thu - chi phí) theo mẫu số 03/TNDN ban hành kèm theo Thông tư số 80/2021/TT-BTC;\n - Báo cáo tài chính năm hoặc Báo cáo tài chính đến thời điểm có quyết định giải thể, phá sản, chấm dứt hoạt động hoặc tổ chức lại doanh nghiệp theo quy định của pháp luật về kế toán và pháp luật về kiểm toán độc lập (trừ trường hợp không phải lập báo cáo tài chính theo quy định);\n - Một hoặc một số phụ lục kèm theo tờ khai (tuỳ theo thực tế phát sinh của người nộp thuế) ban hành kèm theo Thông tư số 80/2021/TT-BTC:\n + Phụ lục chuyển lỗ theo mẫu số 03-2/TNDN;\n + Phụ lục ưu đãi đối với thu nhập từ dự án đầu tư mới, thu nhập của doanh nghiệp được hưởng ưu đãi thuế thu nhập doanh nghiệp theo mẫu số 03-3A/TNDN;\n + Phụ lục ưu đãi đối với cơ sở kinh doanh đầu tư mở rộng quy mô, nâng cao công suất, đổi mới công nghệ sản xuất (dự án đầu tư mở rộng) theo mẫu số 03-3B/TNDN;\n + Phụ lục ưu đãi đối với doanh nghiệp sử dụng lao động là người dân tộc thiểu số hoặc doanh nghiệp hoạt động sản xuất, xây dựng, vận tải sử dụng nhiều lao động nữ theo mẫu số 03-3C/TNDN;\n + Phụ lục ưu đãi đối với doanh nghiệp khoa học công nghệ hoặc doanh nghiệp thực hiện chuyển giao công nghệ thuộc lĩnh vực ưu tiên chuyển giao theo mẫu số 03-3D/TNDN;\n + Phụ lục thuế thu nhập doanh nghiệp đã nộp ở nước ngoài theo mẫu số 03-4/TNDN; \n + Phụ lục thuế thu nhập doanh nghiệp đối với hoạt động chuyển nhượng bất động sản theo mẫu số 03-5/TNDN;\n + Phụ lục báo cáo trích, sử dụng quỹ khoa học và công nghệ theo mẫu số 03-6/TNDN;\n + Phụ lục bảng phân bổ số thuế thu nhập doanh nghiệp phải nộp cho các địa phương nơi được hưởng nguồn thu đối với cơ sở sản xuất theo mẫu 03-8/TNDN;\n + Phụ lục bảng phân bổ số thuế thu nhập doanh nghiệp phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động chuyển nhượng bất động sản theo mẫu 03-8A/TNDN;\n + Phụ lục bảng phân bổ số thuế thu nhập doanh nghiệp phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động sản xuất thủy điện theo mẫu 03-8B/TNDN;\n + Phụ lục bảng phân bổ số thuế thu nhập doanh nghiệp phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động kinh doanh xổ số điện toán theo mẫu 03-8C/TNDN;\n + Phụ lục bảng kê chứng từ nộp tiền thuế thu nhập doanh nghiệp tạm nộp của hoạt động chuyển nhượng bất động sản thu tiền theo tiến độ chưa bàn giao trong năm theo mẫu 03-9/TNDN.\n - Trường hợp doanh nghiệp có dự án đầu tư ở nước ngoài, ngoài các hồ sơ nêu trên, doanh nghiệp phải bổ sung: Bản chụp Tờ khai thuế thu nhập ở nước ngoài có xác nhận của người nộp thuế; Bản chụp chứng từ nộp thuế ở nước ngoài có xác nhận của người nộp thuế hoặc bản gốc xác nhận của cơ quan thuế nước ngoài về số thuế đã nộp hoặc bản chụp chứng từ có giá trị tương đương có xác nhận của người nộp thuế. \n - Trường hợp người nộp thuế có quan hệ liên kết và phát sinh giao dịch liên kết thuộc đối tượng áp dụng và phạm vi điều chỉnh của Nghị định số 132/2020/NĐ-CP ngày 05/11/2020 của Chính phủ về quản lý thuế đối với doanh nghiệp có giao dịch liên kết (đã được sửa đổi, bổ sung, sau đây gọi là: Nghị định số 132/2020/NĐ-CP ngày 05/11/2020 của Chính phủ). Phụ lục thông tin về quan hệ liên kết và giao dịch liên kết theo: Phụ lục I ban hành kèm theo Nghị định số 20/2025/NĐ-CP ngày 10/02/2025 của Chính phủ; phụ lục II, phụ lục III, phụ lục IV ban hành kèm theo Nghị định số 132/2020/NĐ-CP ngày 5/11/2020 của Chính phủ và nộp cùng tờ khai quyết toán thuế TNDN được sửa đổi, bổ sung. Trong đó:\n + Phụ lục I - Thông tin về quan hệ liên kết và giao dịch liên kết của người nộp thuế thuộc đối tượng áp dụng của Nghị định số 132/2020/NĐ-CP và Nghị định số 20/2025/NĐ-CP ngày 10/02/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 132/2020/NĐ-CP. Tất cả người nộp thuế thuộc đối tượng áp dụng của Nghị định số 132/2020/NĐ-CP và Nghị định số 20/2025/NĐ-CP ngày 10/02/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 132/2020/NĐ-CP.\n + Phụ lục II - Danh mục các thông tin, tài liệu cần cung cấp tại hồ sơ quốc gia: Tất cả người nộp thuế thuộc đối tượng áp dụng của Nghị định số 132/2020/NĐ-CP (trừ người nộp thuế thuộc đối tượng được miễn trừ nghĩa vụ theo quy định tại Điều 19 Nghị định 132/2020/NĐ-CP).\n + Phụ lục III- Danh mục các thông tin, tài liệu cần cung cấp tại hồ sơ toàn cầu: Tất cả người nộp thuế thuộc đối tượng áp dụng của Nghị định số 132/2020/NĐ-CP (trừ người nộp thuế thuộc đối tượng được miễn trừ nghĩa vụ theo quy định tại Điều 19 Nghị định 132/2020/NĐ-CP). Hồ sơ, tài liệu kèm theo phụ lục II và phụ lục III người nộp thuế lập và lưu tại Doanh nghiệp. Hồ sơ, tài liệu kèm theo phụ lục II và phụ lục III người nộp thuế lập và lưu tại Doanh nghiệp.\n + Phụ lục IV:\n ++ Người nộp thuế thuộc đối tượng áp dụng của Nghị định số 132/2020/NĐ-CP và là công ty mẹ tối cao của tập đoàn, có doanh thu hợp nhất toàn cầu trong kỳ tính thuế từ 18.000 tỷ đồng trở lên lập Báo cáo lợi nhuận liên quốc gia tại Hồ sơ xác định giá giao dịch liên kết theo Phụ lục IV ban hành kèm theo Nghị định này. Thời hạn nộp Báo cáo cho Cơ quan thuế chậm nhất là 12 tháng sau ngày kết thúc năm tài chính của Công ty mẹ tối cao. \n ++ Người nộp thuế tại Việt Nam có công ty mẹ tối cao tại nước ngoài mà công ty mẹ tối cao có nghĩa vụ lập Báo cáo lợi nhuận liên quốc gia theo quy định của nước cư trú phải nộp cho Cơ quan thuế trong các trường hợp sau:\n +++ Quốc gia, vùng lãnh thổ nơi Công ty mẹ tối cao là đối tượng cư trú có Thỏa thuận quốc tế về thuế với Việt Nam nhưng không có Thỏa thuận của Nhà chức trách có thẩm quyền tại thời điểm đến hạn nộp Báo cáo theo quy định tại điểm a khoản này.\n +++ Quốc gia, vùng lãnh thổ nước ngoài nơi Công ty mẹ tối cao là đối tượng cư trú có Thoả thuận giữa Nhà chức trách có thẩm quyền với Việt Nam nhưng đã đình chỉ cơ chế trao đổi thông tin tự động hoặc không tự động cung cấp được cho Việt Nam Báo cáo lợi nhuận liên quốc gia của tập đoàn là đối tượng cư trú tại các quốc gia, vùng lãnh thổ nước ngoài đó.\n +++ Trường hợp tập đoàn đa quốc gia có nhiều hơn 01 người nộp thuế tại Việt Nam và Công ty mẹ tối cao tại nước ngoài có văn bản thông báo chỉ định một trong những người nộp thuế tại Việt Nam nộp Báo cáo lợi nhuận liên quốc gia thì người nộp thuế được chỉ định có nghĩa vụ nộp Báo cáo lợi nhuận liên quốc gia cho Cơ quan thuế. Người nộp thuế có nghĩa vụ nộp văn bản thông báo chỉ định của Công ty mẹ tối cao cho Cơ quan thuế trước hoặc vào ngày kết thúc năm tài chính của Công ty mẹ tối cao của người nộp thuế.\n ++ Người nộp thuế tại Việt Nam có công ty mẹ tối cao tại nước ngoài mà công ty mẹ tối cao có nghĩa vụ lập Báo cáo lợi nhuận liên quốc gia theo quy định của nước cư trú không phải nộp báo cáo lợi nhuận liên quốc gia cho Cơ quan thuế trong trường hợp Công ty mẹ tối cao của người nộp thuế tại Việt Nam chỉ định một tổ chức thay mặt nộp Báo cáo lợi nhuận liên quốc gia cho Cơ quan thuế nước sở tại trước hoặc vào ngày cuối cùng tháng thứ 12 sau ngày kết thúc năm tài chính của Công ty mẹ tối cao và đáp ứng các điều kiện sau:\n +++ Quốc gia, vùng lãnh thổ nơi tổ chức thay mặt nộp báo cáo là đối tượng cư trú có quy định yêu cầu nộp Báo cáo lợi nhuận liên quốc gia.\n +++ Quốc gia, vùng lãnh thổ nơi tổ chức thay mặt nộp báo cáo là đối tượng cư trú có Thoả thuận giữa Nhà chức trách có thẩm quyền với Việt Nam là một bên ký kết tại thời điểm đến hạn nộp Báo cáo theo quy định tại điểm a khoản này.\n +++ Quốc gia, vùng lãnh thổ nơi tổ chức thay mặt nộp báo cáo là đối tượng cư trú có Thoả thuận giữa Nhà chức trách có thẩm quyền với Việt Nam, không đình chỉ cơ chế trao đổi thông tin tự động và cung cấp được cho Việt Nam Báo cáo lợi nhuận liên quốc gia của tập đoàn là đối tượng cư trú tại quốc gia, vùng lãnh thổ nước ngoài đó.\n +++ Tổ chức thay mặt nộp báo cáo có văn bản thông báo được chỉ định nộp Báo cáo lợi nhuận liên quốc gia cho Cơ quan thuế nước cư trú vào trước hoặc vào ngày kết thúc năm tài chính của Công ty mẹ tối cao của tập đoàn.\n +++ Văn bản thông báo chỉ định tổ chức thay mặt nộp báo cáo được người nộp thuế tại Việt Nam cung cấp cho Cơ quan thuế Việt Nam theo quy định tại điểm b khoản này.\n +++ Người nộp thuế tại Việt Nam có văn bản thông báo cho Cơ quan thuế Việt Nam về tên, mã số thuế và nước cư trú của Công ty mẹ tối cao hoặc tổ chức thay mặt nộp báo cáo trước hoặc vào ngày cuối cùng của năm tài chính của tập đoàn.\n ++ Trường hợp người nộp thuế có Công ty mẹ tối cao tại nước ngoài phải nộp Báo cáo lợi nhuận liên quốc gia theo quy định của nước cư trú, Cơ quan thuế thực hiện trao đổi thông tin tự động theo cam kết tại các Thoả thuận quốc tế về thuế của Việt Nam.\n ++ Trường hợp người nộp thuế có Công ty mẹ tối cao không bắt buộc phải nộp Báo cáo lợi nhuận liên quốc gia theo quy định của nước cư trú thì thực hiện theo điều ước quốc tế về thuế. \n Các trường hợp người nộp thuế được miễn kê khai, miễn lập Hồ sơ xác định giá giao dịch liên kết quy định tại Điều 19 Nghị định số 132/2020/NĐ-CP:\n (1). Người nộp thuế được miễn kê khai xác định giá giao dịch liên kết tại mục III, mục IV Phụ lục I ban hành kèm theo Nghị định, miễn lập Hồ sơ xác định giá giao dịch liên kết theo quy định tại Nghị định này trong trường hợp chỉ phát sinh giao dịch với các bên liên kết là đối tượng nộp thuế thu nhập doanh nghiệp tại Việt Nam, áp dụng cùng mức thuế suất thuế thu nhập doanh nghiệp với người nộp thuế và không bên nào được hưởng ưu đãi thuế thu nhập doanh nghiệp trong kỳ tính thuế, nhưng phải kê khai căn cứ miễn trừ tại mục I, mục II tại Phụ lục I ban hành kèm theo Nghị định này. \n (2). Người nộp thuế có trách nhiệm kê khai xác định giá giao dịch liên kết theo Phụ lục I ban hành kèm theo Nghị định này nhưng được miễn lập Hồ sơ xác định giá giao dịch liên kết trong các trường hợp sau:\n (2.1). Người nộp thuế có phát sinh giao dịch liên kết nhưng tổng doanh thu phát sinh của kỳ tính thuế dưới 50 tỷ đồng và tổng giá trị tất cả các giao dịch liên kết phát sinh trong kỳ tính thuế dưới 30 tỷ đồng;\n (2.2). Người nộp thuế đã ký kết Thoả thuận trước về phương pháp xác định giá tính thuế thực hiện nộp Báo cáo thường niên theo quy định pháp luật về Thoả thuận trước về phương pháp xác định giá tính thuế. Các giao dịch liên kết không thuộc phạm vi áp dụng Thoả thuận trước về phương pháp xác định giá tính thuế, người nộp thuế có trách nhiệm kê khai xác định giá giao dịch liên kết theo quy định tại Điều 18 Nghị định này;\n (2.3). Người nộp thuế thực hiện kinh doanh với chức năng đơn giản, không phát sinh doanh thu, chi phí từ hoạt động khai thác, sử dụng tài sản vô hình, có doanh thu dưới 200 tỷ đồng, áp dụng tỷ suất lợi nhuận thuần chưa trừ chi phí lãi vay và thuế thu nhập doanh nghiệp (không bao gồm chênh lệch doanh thu và chi phí của hoạt động tài chính) trên doanh thu thuần, bao gồm các lĩnh vực như sau:\n - Phân phối: Từ 5% trở lên; \n - Sản xuất: Từ 10% trở lên;\n - Gia công: Từ 15% trở lên.\n Trường hợp người nộp thuế theo dõi, hạch toán riêng doanh thu, chi phí của từng lĩnh vực thì áp dụng tỷ suất lợi nhuận thuần chưa trừ chi phí lãi vay và thuế thu nhập doanh nghiệp trên doanh thu thuần tương ứng với từng lĩnh vực.\n Trường hợp người nộp thuế theo dõi, hạch toán riêng được doanh thu nhưng không theo dõi, hạch toán riêng được chi phí phát sinh của từng lĩnh vực trong hoạt động sản xuất, kinh doanh thì thực hiện phân bổ chi phí theo tỷ lệ doanh thu của từng lĩnh vực để áp dụng tỷ suất lợi nhuận thuần chưa trừ chi phí lãi vay và thuế thu nhập doanh nghiệp trên doanh thu thuần tương ứng với từng lĩnh vực.\n Trường hợp người nộp thuế không theo dõi, hạch toán riêng được doanh thu và chi phí của từng lĩnh vực hoạt động sản xuất, kinh doanh để xác định tỷ suất lợi nhuận thuần chưa trừ chi phí lãi vay và thuế thu nhập doanh nghiệp tương ứng với từng lĩnh vực thì áp dụng tỷ suất lợi nhuận thuần chưa trừ chi phí lãi vay và thuế thu nhập doanh nghiệp trên doanh thu thuần của lĩnh vực có tỷ suất cao nhất.\n Trường hợp người nộp thuế không áp dụng theo mức tỷ suất lợi nhuận thuần quy định tại điểm này thì phải lập Hồ sơ xác định giá giao dịch liên kết theo quy định.\n + Số lượng hồ sơ: 01 bộ.\n (ii) Hồ sơ khai quyết toán đối với người nộp thuế có đơn vị phụ thuộc, địa điểm kinh doanh khác tỉnh, thành phố nơi có trụ sở chính có thu nhập được hưởng ưu đãi thuế thu nhập doanh nghiệp:\n Thành phần hồ sơ, gồm: \n + Tờ khai quyết toán thuế thu nhập doanh nghiệp (áp dụng đối với phương pháp doanh thu - chi phí) theo mẫu số 03/TNDN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP) và Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC). \n + Phụ lục Thuế thu nhập doanh nghiệp được ưu đãi đối với thu nhập từ dự án đầu tư mới, thu nhập của doanh nghiệp được hưởng ưu đãi thuế thu nhập doanh nghiệp theo mẫu số 03-3A/TNDN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC; \n + Phụ lục Thuế thu nhập doanh nghiệp được ưu đãi đối với cơ sở kinh doanh đầu tư mở rộng quy mô, nâng cao công suất, đổi mới công nghệ sản xuất (dự án đầu tư mở rộng) theo mẫu số 03-3B/TNDN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC.\n + Phụ lục Thuế thu nhập doanh nghiệp được ưu đãi đối với doanh nghiệp sử dụng lao động là người dân tộc thiểu số hoặc doanh nghiệp hoạt động sản xuất, xây dựng, vận tải sử dụng nhiều lao động nữ theo mẫu số 03-3C/TNDN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC.\n + Phụ lục Thuế thu nhập doanh nghiệp được ưu đãi đối với doanh nghiệp khoa học công nghệ hoặc doanh nghiệp thực hiện chuyển giao công nghệ thuộc lĩnh vực ưu tiên chuyển giao theo mẫu số 03-3D/TNDN tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP và phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC.\n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Hồ sơ gửi đến cơ quan Thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; sửa đổi, bổ sung tại Luật số 56/2024/QH15 ngày 29/11/2024 của Quốc hội sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính;\n + Luật Thuế thu nhập doanh nghiệp ngày 03/6/2008 và các văn bản pháp luật quy định chi tiết, hướng dẫn thi hành và sửa đổi, bổ sung có liên quan;\n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 9/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03-2/TNDN", "03-3A/TNDN", "03-3B/TNDN", "03-3C/TNDN", "03-3D/TNDN", "03-4/TNDN", "03-5/TNDN", "03-6/TNDN", "03-8/TNDN", "03-8A/TNDN", "03-8B/TNDN", "03-8C/TNDN", "03-9/TNDN", "03/TNDN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008346"}, {"ma": "1.008552", "ten": "Khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên áp dụng cho Liên doanh Vietsovpetro tại Lô 09.1 (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Liên doanh Vietsovpetro hoặc đơn vị được Vietsovpetro uỷ quyền.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế: \n Thời hạn nộp hồ sơ khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên cùng với thời hạn nộp hồ sơ khai quyết toán thuế: chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính hoặc chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc Hiệp định 2010 và Nghị định thư 2013 (trong trường hợp ngày kết thúc Hiệp định 2010 và Nghị định thư 2013 khác với ngày kết thúc năm dương lịch). \n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó. \n + Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n Trường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế: \n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế \n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế. \n + Hoặc gửi qua hệ thống bưu chính. \n + Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số ….ngày …. của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, gồm: Tờ khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên theo mẫu số 01/ĐCĐB-VSP. \n + Thành phần hồ sơ, gồm: Tờ khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên Mẫu số 01/ĐCĐB-VSP ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và Nghị định thư ký ngày 09 tháng 12 năm 2013 bổ sung cho Hiệp định 2010; \n + Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008, Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế , Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và Nghị định thư 2013; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư s ố 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính. \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐCĐB-VSP"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008552"}, {"ma": "1.007689", "ten": "Khai thuế đối với hoạt động cho thuê tài sản đối với cá nhân có hoạt động cho thuê tài sản trực tiếp khai thuế với cơ quan thuế và tổ chức khai cho cá nhân.", "cap_thuc_hien": "Cấp Xã", "doi_tuong": "Cá nhân.", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1. \n ++ Cá nhân có tài sản cho thuê chuẩn bị hồ sơ khai thuế theo từng lần phát sinh hoặc theo năm.\n ++ Thời hạn nộp hồ sơ khai thuế: chậm nhất là ngày cuối cùng của tháng đầu tiên của năm dương lịch hoặc năm tài chính nếu cá nhân lựa chọn khai thuế một lần theo năm; hoặc chậm nhất là ngày thứ 10 kể từ ngày bắt đầu thời hạn cho thuê của kỳ thanh toán nếu cá nhân khai thuế theo từng lần phát sinh kỳ thanh toán. \n ++ Nơi nộp hồ sơ khai thuế: Cá nhân có thu nhập từ cho thuê tài sản (trừ bất động sản tại Việt Nam) nộp hồ sơ khai thuế tại cơ quan thuế nơi cá nhân cư trú. Cá nhân có thu nhập từ cho thuê bất động sản tại Việt Nam nộp hồ sơ khai thuế tại cơ quan thuế nơi có bất động sản cho thuê.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai thuế đối với hoạt động cho thuê tài sản (áp dụng đối với cá nhân có hoạt động cho thuê tài sản trực tiếp khai thuế với cơ quan thuế và tổ chức khai thay cho cá nhân) mẫu số 01/TTS theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính; \n ++ Phụ lục bảng kê chi tiết hợp đồng cho thuê tài sản (áp dụng đối với cá nhân có hoạt động cho thuê tài sản trực tiếp khai thuế với cơ quan thuế nếu là lần khai thuế đầu tiên của Hợp đồng hoặc Phụ lục hợp đồng) mẫu số 01-1/BK-TTS theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính; \n ++ Bản sao hợp đồng thuê tài sản, phụ lục hợp đồng (nếu là lần khai thuế đầu tiên của Hợp đồng hoặc Phụ lục hợp đồng); \n ++ Bản sao Giấy ủy quyền theo quy định của pháp luật (trường hợp cá nhân cho thuê tài sản ủy quyền cho đại diện hợp pháp thực hiện thủ tục khai, nộp thuế). \n Cơ quan thuế có quyền yêu cầu xuất trình bản chính để đối chiếu, xác nhận tính chính xác của bản sao so với bản chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 100/2021/TT-BTC ngày 15 tháng 11 năm 2021 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/BK-TTS", "01/TTS"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007689"}, {"ma": "2.002225", "ten": "Đăng ký thuế lần đầu đối với người nộp thuế là tổ chức (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh)", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "(i).\n + Tổ chức kinh tế bao gồm:\n +++ Doanh nghiệp hoạt động trong các lĩnh vực chuyên ngành không phải đăng ký doanh nghiệp qua cơ quan đăng ký kinh doanh theo quy định của pháp luật chuyên ngành\n +++ Đơn vị sự nghiệp, tổ chức kinh tế của lực lượng vũ trang, tổ chức kinh tế của các tổ chức chính trị, chính trị-xã hội, xã hội, xã hội-nghề nghiệp hoạt động kinh doanh theo quy định của pháp luật nhưng không phải đăng ký doanh nghiệp qua cơ quan đăng ký kinh doanh; tổ chức của các nước có chung đường biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu; văn phòng đại diện của tổ chức nước ngoài tại Việt Nam; tổ hợp tác được thành lập và tổ chức hoạt động theo quy định tại Nghị định số 77/2019/NĐ-CP ngày 10/10/2019 của Chính phủ về tổ hợp tác nhưng không thuộc trường hợp đăng ký kinh doanh qua cơ quan đăng ký kinh doanh theo quy định tại khoản 2 Điều 107 Luật Hợp tác xã.\n + Tổ chức khác bao gồm:\n +++ Tổ chức được thành lập bởi cơ quan có thẩm quyền không có hoạt động sản xuất, kinh doanh nhưng phát sinh nghĩa vụ với ngân sách nhà nước.\n +++ Tổ chức khác có nghĩa vụ với ngân sách nhà nước.", "co_quan": "Thuế tỉnh, thành phố/ Thuế Cơ sở", "trinh_tu": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là tổ chức kinh tế, tổ chức khác có phát sinh nghĩa vụ với NSNN và đơn vị phụ thuộc (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh).\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày: Được cấp giấy phép thành lập và hoạt động, giấy chứng nhận đăng ký đầu tư, quyết định thành lập hoặc văn bản tương đương; hoặc bắt đầu hoạt động kinh doanh đối với tổ chức không thuộc diện đăng ký kinh doanh; hoặc phát sinh nghĩa vụ với ngân sách nhà nước, người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định, gửi đến cơ quan thuế để làm thủ tục đăng ký thuế theo nơi nộp hồ sơ như sau: \n ++ Tổ chức kinh tế, đơn vị phụ thuộc của tổ chức kinh tế (trừ tổ hợp tác) theo quy định tại Điểm a, b khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính nộp hồ sơ đăng ký thuế lần đầu tại Thuế tỉnh, TP nơi tổ chức kinh tế, đơn vị phụ thuộc của tổ chức kinh tế đặt trụ sở.\n ++ Tổ hợp tác, tổ chức khác, đơn vị phụ thuộc của tổ chức khác theo quy định tại Điểm b, c, n khoản 2 Điều 4 Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính nộp hồ sơ đăng ký thuế lần đầu tại Thuế tỉnh, TP nơi tổ chức, đơn vị phụ thuộc của tổ chức đóng trụ sở đối với tổ chức do cơ quan trung ương và cơ quan cấp tỉnh ra quyết định thành lập; tại Thuế cơ sở nơi tổ chức, đơn vị phụ thuộc của tổ chức đóng trụ sở đối với tổ chức do cơ quan cấp huyện ra quyết định thành lập hoặc nơi tổ hợp tác đóng trụ sở.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là Người điều hành, công ty điều hành chung, doanh nghiệp liên doanh, tổ chức được Chính phủ Việt Nam giao nhiệm vụ tiếp nhận phần được chia của Việt Nam thuộc các mỏ dầu khí tại vùng chồng lấn.\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày ký hợp đồng, hiệp định dầu khí thì người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định, gửi đến Thuế tỉnh, TP nơi đặt trụ sở hoặc Chi Cục Thuế doanh nghiệp lớn trong trường hợp người nộp thuế được phân công cho Chi Cục Thuế doanh nghiệp lớn quản lý để làm thủ tục đăng ký thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, công ty mẹ - Tập đoàn Dầu khí Quốc gia Việt Nam đại diện nước chủ nhà nhận phần lãi được chia từ các hợp đồng dầu khí. \n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày ký hợp đồng, hiệp định dầu khí, người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định, gửi đến Thuế tỉnh, TP nơi đặt trụ sở hoặc Chi Cục Thuế doanh nghiệp lớn trong trường hợp người nộp thuế được phân công cho Chi Cục Thuế doanh nghiệp lớn quản lý để làm thủ tục đăng ký thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, cồng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (iv) Đăng ký thuế lần đầu đối với người nộp thuế là nhà thầu, nhà thầu phụ nước ngoài trực tiếp kê khai, nộp thuế nhà thầu hoặc các nghĩa vụ thuế khác trừ thuế nhà thầu do bên Việt Nam khấu trừ nộp thay với cơ quan thuế.\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày ký hợp đồng nhận thầu đối với nhà thầu, nhà thầu phụ nước ngoài kê khai nộp thuế nhà thầu trực tiếp với cơ quan thuế; phát sinh nghĩa vụ thuế thu nhập cá nhân, phát sinh nghĩa vụ khác với ngân sách nhà nước, nhà thầu nước ngoài, nhà thầu phụ nước ngoài thực hiện nộp hồ sơ đến Thuế tỉnh, TP nơi đóng trụ sở.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (v) Đăng ký thuế lần đầu đối với người nộp thuế là cơ quan đại diện ngoại giao, cơ quan lãnh sự và cơ quan đại diện của tổ chức quốc tế tại Việt Nam thuộc đối tượng được hoàn thuế GTGT đối với đối tượng hưởng ưu đãi miễn trừ ngoại giao.\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày phát sinh yêu cầu được hoàn thuế, NNT thực hiện nộp hồ sơ đến Thuế tỉnh, TP nơi đóng trụ sở. \n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.\n (vi) Đăng ký thuế lần đầu đối với người nộp thuế là Tổ chức, cá nhân nước ngoài và tổ chức ở Việt Nam sử dụng tiền viện trợ nhân đạo, viện trợ không hoàn lại của nước ngoài mua hàng hóa, dịch vụ có thuế giá trị gia tăng ở Việt Nam để viện trợ không hoàn lại, viện trợ nhân đạo; Chủ dự án ODA thuộc diện được hoàn thuế giá trị gia tăng, Văn phòng đại diện nhà tài trợ dự án ODA, tổ chức do phía nhà tài trợ nước ngoài chỉ định quản lý chương trình, dự án ODA không hoàn lại.\n + Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày phát sinh yêu cầu được hoàn thuế, tổ chức, cá nhân thuộc diện được hoàn thuế giá trị gia tăng thực hiện nộp hồ sơ đến Thuế tỉnh, TP nơi tổ chức đóng trụ sở hoặc nơi cá nhân có địa chỉ thường trú tại Việt Nam.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "(i) Đăng ký thuế lần đầu đối với người nộp thuế là tổ chức kinh tế, tổ chức khác có phát sinh nghĩa vụ với NSNN và đơn vị phụ thuộc (trừ trường hợp đăng ký thuế theo cơ chế một cửa liên thông qua cơ quan đăng ký kinh doanh).\n + Thành phần hồ sơ, gồm:\n * Đối với tổ chức kinh tế là đơn vị độc lập, đơn vị chủ quản (trừ tổ hợp tác):\n ++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê các nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê góp vốn của tổ chức, cá nhân mẫu số BK06-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bản sao Giấy phép thành lập và hoạt động, hoặc Quyết định thành lập, hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp, hoặc Giấy chứng nhận đăng ký kinh doanh theo quy định của pháp luật của nước có chung biên giới (đối với tổ chức của nước có chung biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu của Việt Nam).\n * Đối với đơn vị phụ thuộc của tổ chức kinh tế:\n - Tờ khai đăng ký thuế mẫu số 02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n - Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n - Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n - Bảng kê các nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n - Bản sao Giấy chứng nhận đăng ký hoạt động đơn vị phụ thuộc, hoặc Quyết định thành lập, hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp, hoặc Giấy chứng nhận đăng ký kinh doanh theo quy định của pháp luật của nước có chung biên giới (đối với tổ chức của nước có chung biên giới đất liền với Việt Nam thực hiện hoạt động mua, bán, trao đổi hàng hóa tại chợ biên giới, chợ cửa khẩu, chợ trong khu kinh tế cửa khẩu của Việt Nam).\n * Đối với tổ chức khác là đơn vị độc lập, đơn vị chủ quản, tổ hợp tác:\n ++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bảng kê các công ty con, công ty thành viên mẫu số BK01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê các đơn vị phụ thuộc mẫu số BK02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bản sao không yêu cầu chứng thực Quyết định thành lập, hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp.\n * Đối với đơn vị phụ thuộc của tổ chức khác:\n - Tờ khai đăng ký thuế mẫu số 02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n - Bảng kê địa điểm kinh doanh mẫu số BK03-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n - Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n - Bản sao không yêu cầu chứng thực Quyết định thành lập hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp.\n + Số lượng hồ sơ: 01 (bộ).\n (ii) Đăng ký thuế lần đầu đối với người nộp thuế là Người điều hành, công ty điều hành chung, doanh nghiệp liên doanh, tổ chức được Chính phủ Việt Nam giao nhiệm vụ tiếp nhận phần được chia của Việt Nam thuộc các mỏ dầu khí tại vùng chồng lấn.\n + Thành phần hồ sơ, gồm:\n ++ Tờ khai đăng ký thuế mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bảng kê nhà thầu, nhà đầu tư dầu khí mẫu số BK05-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bản sao Giấy chứng nhận đầu tư, hoặc Giấy phép đầu tư.\n + Số lượng hồ sơ: 01 (bộ).\n (iii) Đăng ký thuế lần đầu đối với người nộp thuế là nhà thầu, nhà đầu tư tham gia hợp đồng dầu khí, công ty mẹ - Tập đoàn Dầu khí Quốc gia Việt Nam đại diện nước chủ nhà nhận phần lãi được chia từ các hợp đồng dầu khí. \n + Thành phần hồ sơ, gồm: Tờ khai đăng ký thuế mẫu số 02-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n + Số lượng hồ sơ: 01 bộ.\n (iv) Đăng ký thuế lần đầu đối với người nộp thuế là nhà thầu, nhà thầu phụ nước ngoài trực tiếp kê khai, nộp thuế nhà thầu hoặc các nghĩa vụ thuế khác trừ thuế nhà thầu do bên Việt Nam khấu trừ nộp thay với cơ quan thuế.\n + Thành phần hồ sơ, gồm: \n ++ Tờ khai đăng ký thuế mẫu số 04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bảng kê các nhà thầu nước ngoài, nhà thầu phụ nước ngoài mẫu số BK04-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính (nếu có);\n ++ Bản sao Giấy xác nhận đăng ký văn phòng điều hành hoặc Văn bản tương đương do cơ quan có thẩm quyền cấp (nếu có).\n + Số lượng hồ sơ: 01 (bộ).\n (v) Đăng ký thuế lần đầu đối với người nộp thuế là cơ quan đại diện ngoại giao, cơ quan lãnh sự và cơ quan đại diện của tổ chức quốc tế tại Việt Nam thuộc đối tượng được hoàn thuế GTGT đối với đối tượng hưởng ưu đãi miễn trừ ngoại giao.\n + Thành phần hồ sơ, gồm: \n ++ Tờ khai đăng ký thuế theo mẫu số 06-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Giấy xác nhận của Cục Lễ tân Nhà nước - Bộ Ngoại giao.\n + Số lượng hồ sơ: 01 (bộ).\n (vi) Đăng ký thuế lần đầu đối với người nộp thuế là Tổ chức, cá nhân nước ngoài và tổ chức ở Việt Nam sử dụng tiền viện trợ nhân đạo, viện trợ không hoàn lại của nước ngoài mua hàng hóa, dịch vụ có thuế giá trị gia tăng ở Việt Nam để viện trợ không hoàn lại, viện trợ nhân đạo; Chủ dự án ODA thuộc diện được hoàn thuế giá trị gia tăng, Văn phòng đại diện nhà tài trợ dự án ODA, tổ chức do phía nhà tài trợ nước ngoài chỉ định quản lý chương trình, dự án ODA không hoàn lại.\n + Thành phần hồ sơ, gồm: Tờ khai đăng ký thuế theo mẫu số 01-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Giấy chứng nhận đăng ký thuế", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-ĐK-TCT", "02-ĐK-TCT", "04-ĐK-TCT", "06-ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002225"}, {"ma": "1.011042", "ten": "Đăng ký/Thay đổi thông tin sử dụng chứng từ điện tử/ủy nhiệm lập biên lai điện tử", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "+ Tổ chức thu các khoản phí, lệ phí; Tổ chức, cá nhân khấu trừ thuế thu nhập cá nhân, khấu trừ thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số, tổ chức thu các khoản thuế, phí, lệ phí.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Trường hợp (1): Đối với đăng ký/ Thay đổi thông tin sử dụng chứng từ đối với các chứng từ có đầy đủ nội dung theo quy định.\n Bước 1: Đăng ký\n + Tổ chức, cá nhân khấu trừ thuế thu nhập cá nhân, khấu trừ thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số, tổ chức thu các khoản thuế, phí, lệ phí.\n Đăng ký sử dụng chứng từ điện tử hoặc thay đổi thông tin sử dụng chứng từ điện tử qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử.\n + Trường hợp tổ chức, cá nhân trả thu nhập không thuộc đối tượng áp dụng hóa đơn điện tử; tổ chức, cá nhân trả thu nhập sử dụng hóa đơn điện tử có mã của cơ quan thuế không phải trả tiền dịch vụ theo quy định tại khoản 11 Điều 1 Nghị định 70/2025/NĐ-CP\n Được lựa chọn đăng ký sử dụng chứng từ khấu trừ thuế thu nhập cá nhân điện tử thông qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử được Cục Thuế ủy thác cung cấp dịch vụ chứng từ khấu trừ thuế thu nhập cá nhân điện tử không phải trả tiền dịch vụ theo Mẫu số 01/ĐKTĐ-CTĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025.\n Bước 2: Tổ chức thực hiện đăng ký/ Thay đổi thông tin sử dụng qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử.\n Bước 3: Cơ quan quản lý thuế tiếp nhận đăng ký/ Thay đổi thông tin sử dụng chứng từ điện tử. \n Bước 4: Gửi dữ liệu chứng từ điện tử\n ++ Tổ chức, cá nhân khấu trừ thuế sau khi lập đầy đủ các nội dung trên chứng từ khấu trừ thuế thu nhập cá nhân điện tử gửi cho người bị khấu trừ thuế và đồng thời gửi cho cơ quan thuế ngay trong ngày lập chứng từ qua tổ chức cung cấp dịch vụ hóa đơn điện tử hoặc qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế;\n Trường hợp (2): Đối với đăng ký/ Thay đổi thông tin sử dụng chứng từ đối với các chứng từ điều chỉnh một số tiêu thức bắt buộc \n Bước 1: \n Đối với tổ chức thu phí, lệ phí sử dụng biên lai điện tử trong trường hợp cần điều chỉnh một số tiêu thức nội dung trên biên lai điện tử cho phù hợp với thực tế, tổ chức thu phí, lệ phí có văn bản trao đổi với Bộ Tài chính (Cục Thuế) xem xét và có hướng dẫn trước khi thực hiện.\n Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ và giải quyết theo quy định.\n Trường hợp (3): Ủy nhiệm lập biên lai điện tử\n Bước 1: Đăng ký\n Tổ chức thu phí, lệ phí ủy nhiệm cho bên thứ ba lập biên lai. Việc ủy nhiệm giữa bên ủy nhiệm và bên nhận ủy nhiệm phải theo hình thức văn bản, đồng thời phải gửi thông báo cho cơ quan thuế quản lý trực tiếp khi đăng ký sử dụng biên lai điện tử theo Mẫu số 01/ĐKTĐ-CTĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025.\n Bước 2: Tổ chức thực hiện đăng ký ủy nhiệm/ nhận ủy nhiệm biên lai điện tử qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc tổ chức cung cấp dịch vụ hóa đơn điện tử\n Bước 3: Cơ quan quản lý thuế tiếp nhận đăng ký ủy nhiệm/nhận ủy nhiệm biên lai điện tử", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Trường hợp (1) và (3) Mẫu số 01/ĐKTĐ-CTĐT Tờ khai đăng ký/thay đổi thông tin sử dụng chứng từ điện tử ban hành kèm theo phụ lục IA Nghị định 70/2025/NĐ-CP. \n + Trường hợp (2): Có văn bản gửi Cục Thuế (không có mẫu) \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Đối với trường hợp (1) và (3): Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi thông báo theo Mẫu số 01/TB-TNĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 về việc tiếp nhận đăng ký sử dụng chứng từ điện tử qua tổ chức cung cấp dịch vụ hóa đơn điện tử đối với trường hợp đăng ký sử dụng chứng từ điện tử thông qua tổ chức cung cấp dịch vụ hóa đơn điện tử; qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế và trả kết quả xử lý theo Mẫu số 01/TB-ĐKĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP. \n + Trường hợp (2) Cục Thuế chấp thuận hồ sơ.", "dieu_kien": "+ Đảm bảo cơ sở hạ tầng CNTT để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử. \n + Đối với ủy nhiệm lập biên lai điện tử: Việc ủy nhiệm giữa bên ủy nhiệm và bên nhận ủy nhiệm phải theo hình thức văn bản.", "can_cu_phap_ly": "+ Căn cứ tại khoản 18, khoản 19, khoản 21 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ. \n + Căn cứ tại Điều 32 Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định về hóa đơn, chứng từ \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011042"}, {"ma": "2.002237", "ten": "Khai thuế thu nhập cá nhân tháng/quý đối với cá nhân có thu nhập từ tiền lương, tiền công (bao gồm cả cá nhân nhận thưởng bằng cổ phiếu từ đơn vị sử dụng lao động) thuộc diện khai thuế thu nhập cá nhân trực tiếp với cơ quan thuế", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Cá nhân có thu nhập từ tiền lương, tiền công (bao gồm cả cá nhân nhận thưởng bằng cổ phiếu từ đơn vị sử dụng lao động)", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. \n ++ Trường hợp 1: Cá nhân có thu nhập từ tiền lương, tiền công thuộc diện khai thuế thu nhập cá nhân trực tiếp với cơ quan thuế: \n +++ Cá nhân có thu nhập từ tiền lương, tiền công do các tổ chức Quốc tế, Đại sứ quán, Lãnh sự quán tại Việt Nam trả nhưng chưa khấu trừ thuế;\n +++ Cá nhân cư trú có thu nhập từ tiền lương, tiền công trả từ nước ngoài;\n +++ Cá nhân không cư trú có thu nhập từ tiền lương, tiền công phát sinh tại Việt Nam nhưng được trả từ nước ngoài;\n +++ Cá nhân chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ thuế nếu cá nhân khai thuế theo tháng hoặc ngày cuối cùng của tháng đầu tiên của quý tiếp theo quý phát sinh nghĩa vụ thuế nếu cá nhân khai thuế theo quý.\n ++ Trường hợp 2: Cá nhân nhận thưởng bằng cổ phiếu từ đơn vị sử dụng lao động khai thuế thu nhập cá nhân trực tiếp với cơ quan thuế:\n +++ Cá nhân khi nhận thưởng bằng cổ phiếu từ đơn vị sử dụng lao động chưa phải nộp thuế đối với thu nhập từ tiền lương, tiền công;\n +++ Khi cá nhân chuyển nhượng cổ phiếu cùng loại thì khai thuế đối với thu nhập từ chuyển nhượng cổ phiếu và thu nhập từ tiền lương, tiền công do được thưởng bằngcổ phiếu; \n +++ Cá nhân chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế quản lý chậm nhất là ngày thứ 10 kể từ ngày chuyển nhượng cổ phiếu cùng loại. \n + Bước 2. Cơ quan thuế thực hiện tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyếthồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận,kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân cư trú và cá nhân không cư trú có thu nhập từ tiền lương, tiền công khai thuế trực tiếp với cơ quan thuế) mẫu số 02/KK-TNCN theo Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02/KK-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002237"}, {"ma": "1.008554", "ten": "Khai quyết toán thuế tài nguyên/ Khai quyết toán phụ thu/ Khai quyết toán thuế TNDN/ Khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên của Liên doanh Vietsovpetro tại Lô 09.1", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Liên doanh Vietsovpetro hoặc đơn vị được Vietsovpetro uỷ quyền.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế.\n Thời hạn nộp hồ sơ: Chậm nhất là ngày cuối cùng của tháng thứ 3 kể từ ngày kết thúc năm dương lịch hoặc năm tài chính; Chậm nhất là ngày thứ 45 (bốn mươi lăm) kể từ ngày kết thúc Hiệp định 2010 và Nghị định thư sửa đổi, bổ sung (trong trường hợp ngày kết thúc Hiệp định 2010 và Nghị định thư sửa đổi, bổ sung khác với ngày kết thúc năm dương lịch). \n Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n + Bước 2: \n ++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế\n +++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Trường hợp (1) khai quyết toán thuế tài nguyên, hồ sơ gồm: \n +++ Tờ khai quyết toán thuế tài nguyên đối với dầu khí Mẫu số 02/TAIN-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP) và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC). \n +++ Phụ lục bảng kê sản lượng và doanh thu xuất bán dầu khí Mẫu số 02-1/TAIN-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n ++ Trường hợp (2) khai quyết toán phụ thu, hồ sơ gồm: \n +++ Tờ khai quyết toán phụ thu Mẫu số 02/PTHU-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n +++ Phụ lục bảng kê số phụ thu tạm tính đã nộp Mẫu số 02-1/PTHU-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n ++ Trường hợp (3) khai quyết toán thuế thu nhập doanh nghiệp, hồ sơ gồm: \n +++Tờ khai quyết toán thuế thu nhập doanh nghiệp Mẫu số 02/TNDN-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n ++ Trường hợp (4) khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên, hồ sơ gồm: \n +++Tờ khai điều chỉnh thuế đặc biệt đối với khí thiên nhiên Mẫu số 01/ĐCĐB-VSP ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP và Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Hiệp định giữa Chính phủ Cộng hoà Xã hội Chủ nghĩa Việt Nam và Chính phủ Liên bang Nga ký ngày 27/12/2010 về việc tiếp tục hợp tác trong lĩnh vực thăm dò địa chất và khai thác dầu khí tại thềm lục địa Cộng hoà Xã hội Chủ nghĩa Việt Nam trong khuôn khổ Liên doanh Việt-Nga “Vietsovpetro” và các Nghị định thư sửa đổi, bổ sung. \n + Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, \n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n +Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 176/2014/TT-BTC ngày 17/11/2014 của Bộ Tài chính hướng dẫn về việc thực hiện nghĩa vụ thuế đối với hoạt động tìm kiếm thăm dò, phát triển mỏ và khai thác dầu khí của Liên doanh Việt-Nga “Vietsovpetro” từ Lô 09-1 theo Hiệp định 2010 và các Nghị định thư sửa đổi, bổ sung; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \r\n Thông báo\n -->\r\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\r\n Đóng \r\n Tiếp tục \r\n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\r\n từ website này\n Hỗ trợ:\r\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\r\n -->\r\n -->\r\n -->\r\n -->\r\n -->\r\n -->\r\n -->\r\n Đã kết nối EMC -->\r\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008554"}, {"ma": "1.008564", "ten": "Hoàn thuế khi chuyển đổi sở hữu, chuyển đổi doanh nghiệp, sáp nhập, hợp nhất, chia, tách, giải thể, phá sản, chấm dứt hoạt động đối với trường hợp không thuộc diện cơ quan thuế kiểm tra tại trụ sở của người nộp thuế", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) thuộc trường hợp và đối tượng được hoàn thuế khi chuyển đổi sở hữu, chuyển đổi doanh nghiệp, sáp nhập, hợp nhất, chia, tách, giải thể, phá sản, chấm dứt hoạt động không thuộc diện cơ quan thuế kiểm tra tại trụ sở của người nộp thuế chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n * Đối với trường hợp hoàn thuế GTGT chưa được khấu trừ hết: \n Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n * Đối với trường hợp hoàn nộp thừa: \n + Văn bản đề nghị xử lý số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa mẫu số 01/DNXLNT; \n + Văn bản ủy quyền trong trường hợp người nộp thuế không trực tiếp thực hiện thủ tục hoàn thuế, trừ trường hợp đại lý thuế nộp hồ sơ hoàn thuế theo hợp đồng đã ký giữa đại lý thuế và người nộp thuế; \n + Các tài liệu kèm theo (nếu có); \n Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Đối với trường hợp hoàn GTGT chưa được khấu trừ hết: \n ++ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT \n ++ Quyết định hoàn thuế mẫu số 01/QĐHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n ++ Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n + Đối với trường hợp hoàn nộp thừa: \n ++ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT \n ++ Quyết định hoàn thuế mẫu số 01/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả theo mẫu số 01/PL-HTNT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n ++ Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả theo mẫu số 01/PL-HTNT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp NNT lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/DNXLNT", "01/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008564"}, {"ma": "2.002233", "ten": "Khai quyết toán thuế/ Hoàn thuế đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công quyết toán thuế trực tiếp với cơ quan thuế", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Cá nhân có thu nhập từ tiền lương, tiền công", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở/Chi cục Thuế Doanh nghiệp lớn/Chi cục Thuế Thương mại điện tử.", "trinh_tu": "+Bước 1. \n++ Trường hợp (1): Khai quyết toán thuế đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công quyết toán trực tiếp với cơ quan thuế: Cá nhân thuộc diện quyết toán theo quy định chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế. Thời hạn nộp hồ sơ khai quyết toán chậm nhất là ngày cuối cùng của tháng thứ 4 kể từ ngày kết thúc năm dương lịch. \n++ Trường hợp (2): Hoàn thuế đối với cá nhân cư trú có thu nhập từ tiền lương, tiền công quyết toán trực tiếp với cơ quan thuế: Cá nhân có thu nhập từ tiền lương, tiền công trực tiếp quyết toán thuế với cơ quan thuế nếu có số thuế nộp thừa thì cá nhân không phải nộp hồ sơ hoàn thuế mà chỉ cần ghi số thuế đề nghị hoàn vào chỉ tiêu [46] - “Số thuế hoàn trả cho người nộp thuế” hoặc chỉ tiêu [47] - “Số thuế bù trừ cho khoản phải nộp ngân sách nhà nước” tại tờ khai quyết toán thuế theo mẫu số 02/QTT-TNCN khi quyết toán thuế.\n* Nơi gửi hồ sơ quyết toán thuế\n++ Cá nhân có thu nhập từ tiền lương, tiền công tại một nơi và thuộc diện tự khai thuế trong năm với cơ quan thuế thì hồ sơ quyết toán thuế gửi đến cơ quan thuế nơi cá nhân trực tiếp khai thuế trong năm. \n++ Cá nhân cư trú có thu nhập tiền lương, tiền công thuộc diện tổ chức chi trả khấu trừ tại nguồn từ hai nơi trở lên thì hồ sơ khai quyết toán thuế gửi đến cơ quan thuế quản lý trực tiếp tổ chức trả thu nhập lớn nhất trong năm. Trường hợp có nhiều nguồn thu nhập lớn nhất trong năm mà các nguồn thu nhập đó bằng nhau thì hồ sơ quyết toán gửi đến một trong những cơ quan thuế quản lý trực tiếp tổ chức chi trả các nguồn thu nhập lớn nhất trên. \nTrường hợp cá nhân nộp hồ sơ khai quyết toán thuế thu nhập cá nhân không đúng quy định nêu trên thì cơ quan thuế nơi đã tiếp nhận hồ sơ của cá nhân đó căn cứ thông tin trên hệ thống cơ sở dữ liệu ngành thuế hỗ trợ chuyển hồ sơ đến cơ quan thuế quản lý trực tiếp tổ chức trả thu nhập để thực hiện quyết toán thuế thu nhập cá nhân theo quy định pháp luật.\n+ Bước 2. Cơ quan thuế tiếp nhận: \n++ Trường hợp hồ sơ đến cơ quan thuế: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ (và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n++ Trường hợp (1):\n+++ Tờ khai quyết toán thuế thu nhập cá nhân (áp dụng đối với cá nhân có thu nhập từ tiền lương, tiền công) mẫu số 02/QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (gọi là Nghị định số 373/2025/NĐ-CP) và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (gọi là Thông tư số 80/2021/TT-BTC).\n+++ Phụ lục bảng kê giảm trừ gia cảnh cho người phụ thuộc mẫu số 02-1/BK-QTT-TNCN theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 373/2025/NĐ-CP và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC.\n+++ Bản sao (bản chụp từ bản chính) các chứng từ chứng minh số thuế đã khấu trừ, đã tạm nộp trong năm, số thuế đã nộp ở nước ngoài (nếu có). Trường hợp tổ chức trả thu nhập thực hiện chuyển dữ liệu chứng từ khấu trừ thuế thu nhập cá nhân điện tử đến cơ quan thuế, người nộp thuế không cần nộp bản sao các chứng từ chứng minh số thuế đã khấu trừ. Trường hợp tổ chức trả thu nhập không cấp chứng từ khấu trừ thuế cho cá nhân do tổ chức trả thu nhập đã chấm dứt hoạt động thì cơ quan thuế căn cứ cơ sở dữ liệu của ngành thuế để xem xét xử lý hồ sơ quyết toán thuế cho cá nhân mà không bắt buộc phải có chứng từ khấu trừ thuế.\n+++ Bản sao Giấy chứng nhận khấu trừ thuế (ghi rõ đã nộp thuế theo tờ khai thuế thu nhập nào) do cơ quan trả thu nhập cấp hoặc Bản sao chứng từ ngân hàng đối với số thuế đã nộp ở nước ngoài có xác nhận của người nộp thuế trong trường hợp theo quy định của luật pháp nước ngoài, cơ quan thuế nước ngoài không cấp giấy xác nhận số thuế đã nộp.\n+++ Bản sao các hoá đơn chứng từ chứng minh khoản đóng góp vào quỹ từ thiện, quỹ nhân đạo, quỹ khuyến học (nếu có). \n+++ Tài liệu chứng minh về số tiền đã trả của đơn vị, tổ chức trả thu nhập ở nước ngoài trong trường hợp cá nhân nhận thu nhập từ các tổ chức quốc tế, Đại sứ quán, Lãnh sự quán và nhận thu nhập từ nước ngoài.\n+++ Hồ sơ đăng ký người phụ thuộc thực hiện theo thủ tục đăng ký thuế lần đầu tại văn bản quy định về đăng ký thuế (nếu tính giảm trừ cho người phụ thuộc tại thời điểm quyết toán thuế đối với người phụ thuộc chưa thực hiện đăng ký người phụ thuộc):\n++++ Tờ khai đăng ký thuế mẫu số 20-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n++++ Phụ lục bảng kê khai về người phải trực tiếp nuôi dưỡng mẫu số 07/XN-NPT-TNCN tại văn bản quy phạm pháp luật quy định về đăng ký thuế;\n++++ Hồ sơ chứng minh người phụ thuộc theo quy định của Luật Thuế thu nhập cá nhân\n++ Trường hợp (2): Không phải nộp hồ sơ hoàn thuế mà chỉ cần ghi số thuế đề nghị hoàn vào chỉ tiêu [46] - “Số thuế hoàn trả cho người nộp thuế” hoặc chỉ tiêu [47] - “Số thuế bù trừ cho khoản phải nộp ngân sách nhà nước” tại tờ khai quyết toán thuế theo mẫu số 02/QTT-TNCN khi quyết toán thuế.\n+ Số lượng hồ sơ: 01 (bộ.)", "ket_qua": "+ Trường hợp (1): Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.\n+ Trường hợp (2): Quyết định hoàn thuế theo mẫu số 01/QĐHT hoặc Quyết định hoàn kiêm bù trừ khoản thu ngân sách nhà nước mẫu số 02/QĐHT hoặc Thông báo về việc không được hoàn thuế theo mẫu số 01/TB-HT do Bộ Tài chính ban hành gửi người nộp thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính);\n+ Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ);\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính);\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp;\n+ Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["02-1/BK-QTT-TNCN", "02/QTT-TNCN", "07/XN-NPT-TNCN", "20-ĐK-TCT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=2.002233"}, {"ma": "1.010951", "ten": "Khai các khoản thu về hoa hồng dầu, khí, tiền đọc và sử dụng tài liệu dầu, khí", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tập đoàn Dầu khí Việt Nam/Đơn vị được ủy quyền/Đại lý thuế.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế. Trường hợp ngày cuối cùng của thời hạn khai, nộp thuế trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó.\n Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2: Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của người nộp thuế theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n Tờ khai các khoản thu về hoa hồng dầu khí, tiền đọc và sử dụng tài liệu dầu khí theo Mẫu số 01/TNS-DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 36/2021/NĐ-CP ngày 29/03/2021 của Chính phủ ban hành quy chế quản lý tài chính của Công ty mẹ - Tập đoàn Dầu khí Việt Nam; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành Luật Địa chất và khoáng sản; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010951"}, {"ma": "1.007277", "ten": "Khai lệ phí trước bạ nhà, đất/ Miễn lệ phí trước bạ nhà, đất", "cap_thuc_hien": "Cấp Bộ, Cấp Huyện", "doi_tuong": "Công dân Việt Nam, Doanh nghiệp, Tổ chức (không bao gồm doanh nghiệp, HTX), Hợp tác xã", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1: \n Tổ chức, cá nhân khi đăng ký quyền sử dụng đất, quyền sở hữu nhà và tài sản khác gắn liền với đất (bao gồm trường hợp thuộc diện miễn lệ phí trước bạ) nộp hồ sơ khai lệ phí trước bạ tại cơ quan tiếp nhận hồ sơ theo cơ chế một cửa liên thông nơi có bất động sản.\n + Bước 2:\n Cơ quan thuế tiếp nhận: Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Đối với hồ sơ miễn lệ phí trước bạ thuộc trường hợp chứng minh mối quan hệ trong gia đình theo quy định. Cơ quan thuế có trách nhiệm khai thác thông tin trong Cơ sở dữ liệu quốc gia về dân cư theo quy định tại Điều 84 Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi, bổ sung tại Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính) để giải quyết thủ tục miễn thuế trước bạ cho người nộp thuế. Trường hợp không thể khai thác thông tin về cư trú của công dân trong Cơ sở dữ liệu quốc gia về dân cư thì người nộp thuế cung cấp các giấy tờ liên quan đến việc xác định đối tượng được miễn thuế theo từng trường hợp.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: \n + Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14, gồm: \n ++ Tờ khai lệ phí trước bạ theo mẫu 01/LPTB tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC) \n ++ Giấy tờ chứng minh nhà, đất có nguồn gốc hợp pháp theo quy định của pháp luật; \n ++ Bản sao Giấy tờ hợp pháp theo quy định của pháp luật về việc chuyển giao tài sản ký kết giữa bên giao tài sản và bên nhận tài sản. \n ++ Bản sao Giấy tờ chứng minh tài sản (hoặc chủ tài sản) thuộc diện miễn lệ phí trước bạ (nếu có); \n Giấy tờ chứng minh tài sản (hoặc chủ tài sản) thuộc diện miễn lệ phí trước bạ trong một số trường hợp quy định tại Thông tư số 80/2021/TT-BTC. \n ++ Bản sao các Giấy tờ chứng minh thuộc đối tượng được ghi nợ trước bạ đối với đất và nhà gắn liền với đất của hộ gia đình, cá nhân thuộc đối tượng được ghi nợ tiền sử dụng đất theo quy định (nếu có). \n Số lượng hồ sơ: 01 bộ", "ket_qua": "Thông báo nộp lệ phí trước bạ.", "dieu_kien": "Không có", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/LPTB"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007277"}, {"ma": "1.008312", "ten": "Khai thuế tài nguyên, khai quyết toán thuế tài nguyên đối với cơ sở khai thác tài nguyên", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Cá nhân, tổ chức.", "co_quan": "Thuế tỉnh/thuế cơ sở", "trinh_tu": "+ Bước 1: \n ++ Tổ chức, cá nhân khai thác tài nguyên thiên nhiên lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp (trường hợp Tổ chức, cá nhân khai thác tài nguyên thiên nhiên có trụ sở chính tại tỉnh, thành phố này nhưng có hoạt động khai thác tài nguyên tại tỉnh, thành phố khác thì nộp hồ sơ khai thuế tại Thuế tỉnh, thành phố hoặc Thuế cơ sở do Trưởng Thuế tỉnh, thành phố nơi phát sinh hoạt động khai thác tài nguyên quy định). \n ++ Tổ chức, cá nhân có nhà máy sản xuất thuỷ điện thực hiện khai thuế tài nguyên và nộp hồ sơ khai thuế tài nguyên theo mẫu số 01/TAIN, cho cơ quan thuế quản lý khoản thu ngân sách nhà nước nơi có hoạt động khai thác tài nguyên nước. Trường hợp tổ chức, cá nhân có hoạt động sản xuất thủy điện mà hồ thủy điện của nhà máy thủy điện nằm trên nhiều tỉnh thì nộp hồ sơ khai thuế tài nguyên và phụ lục bảng phân bổ số thuế tài nguyên phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động sản xuất thủy điện của nhà máy thủy điện tại cơ quan thuế nơi có văn phòng điều hành nhà máy thủy điện và nộp số tiền thuế phân bổ cho tỉnh nơi có hồ thủy điện theo quy định\n ++ Thời hạn nộp hồ sơ : Chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ thuế.\n ++ Tổ chức được giao bán loại tài nguyên thiên nhiên bị bắt giữ, tịch thu; khai thác tài nguyên không thường xuyên đã được cơ quan nhà nước có thẩm quyền cấp phép hoặc không thuộc trường hợp cấp phép theo quy định của pháp luật thì thực hiện nộp hồ sơ kê khai thuế chậm nhất là ngày thứ 10 (mười) kể từ ngày phát sinh nghĩa vụ thuế cho Thuế tỉnh, thành phố hoặc Thuế cơ sở do Trưởng Thuế tỉnh, thành phố nơi bán hoặc khai thác tài nguyên quy định. \n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n+ Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n ++ Tờ khai thuế tài nguyên mẫu số 01/TAIN tại Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế.\n + Phụ lục bảng phân bổ số thuế tài nguyên phải nộp cho các địa phương nơi được hưởng nguồn thu đối với hoạt động sản xuất thủy điện mẫu số 01-1/TAIN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (áp dụng đối với cơ sở sản xuất thủy điện có hồ thủy điện nằm trên nhiều tỉnh).\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "0", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019.\n + Luật Thuế tài nguyên số 45/2009/QH12 ngày 25 tháng 11 năm 2009; Luật Dầu khí số 12/2022/QH15 ngày 14 tháng 11 năm 2022, Luật sửa đổi, bổ sung một số điều của các Luật về thuế số 71/2014/QH13 ngày 26 tháng 11 năm 2014;\n + Luật Khoáng sản số 60/2010/QH12 ngày 17 tháng 11 năm 2010, Luật Địa chất và Khoáng sản số 54/2024/QH15 ngày 29 tháng 11 năm 2024;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính, Nghị định số 193/2025/NĐ-CP ngày 02/7/2025 của Chính phủ quy định chi tiết một số điều và biện pháp thi hành luật địa chất và khoáng sản;\n + Nghị định số 50/2010/NĐ-CP ngày 14 tháng 5 năm 2010 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Luật Thuế tài nguyên, Nghị định số 12/2015/NĐ-CP của Chính phủ ngày 12 tháng 02 năm 2015 quy định chi tiết thi hành luật sửa đổi, bổ sung một số điều của các Luật về thuế và sửa đổi, bổ sung một số điều của các Nghị định về thuế;\n + Điều 4 Nghị định số 12/2015/NĐ-CP ngày 12/2/2015 của Chính phủ quy định chi tiết thi hành Luật sửa đổi, bổ sung một số điều của các Luật về thuế và sửa đổi, bổ sung một số điều của Nghị định về thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 43/2023/TT-BTC ngày 27/6/2023 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư có quy định liên quan đến việc nộp, xuất trình và khai thông tin về đăng ký sổ hộ khẩu, sổ tạm trú hoặc giấy tờ có yêu cầu xác nhận của địa phương nơi cư trú khi thực hiện các chính sách hoặc thủ tục hành chính thuộc lĩnh vực quản lý nhà nước của Bộ Tài chính;\n + Thông tư số 152/2015/TT-BTC ngày 02/10/2015 của Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 41/2024/TT-BTC ngày 20 tháng 5 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 44/2017/TT-BTC ngày 12 tháng 05 năm 2017 của Bộ trưởng Bộ Tài chính quy định khung giá tính thuế tài nguyên đối với nhóm, loại tài nguyên có tính chất lý, hóa giống nhau và Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 của Bộ trưởng Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 174/2016/TT-BTC ngày 28 tháng 10 năm 2016 của Bộ Tài chính sửa đổi, bổ sung điểm a khoản 4 điều 6 Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 của Bộ Tài chính hướng dẫn về thuế tài nguyên, Thông tư số 12/2016/TT-BTC ngày 20 tháng 01 năm 2016 của Bộ Tài chính sửa đổi, bổ sung khoản 1 điều 7 Thông tư số 152/2015/TT-BTC ngày 02 tháng 10 năm 2015 hướng dẫn về thuế tài nguyên;\n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 40/2025/TT-BTC ngày 13/6/ 2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TAIN", "01/TAIN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008312"}, {"ma": "1.010341", "ten": "Xử lý hóa đơn điện tử đã lập sai theo Mẫu số 04/SS-HĐĐT", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Xã", "doi_tuong": "Doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh đăng ký sử dụng hóa đơn điện tử.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Bước 1: Trường hợp hóa đơn điện tử đã lập đã gửi cơ quan thuế bị sai (bao gồm hóa đơn điện tử đã được cấp mã của CQT; hóa đơn điện tử không có mã của CQT đã gửi dữ liệu đến CQT) thì xử lý như sau:\n + Trường hợp có sai về tên, địa chỉ của người mua nhưng không sai mã số thuế, các nội dung khác không sai thì người bán thông báo cho người mua về việc hóa đơn đã lập sai và không phải lập lại hóa đơn. Người bán thực hiện thông báo với cơ quan thuế về hóa đơn điện tử đã lập sai theo Mẫu số 04/SS-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ. \n Bước 2: \n + Trường hợp có sai sót về tên, địa chỉ của người mua nhưng không sai mã số thuế, các nội dung khác không sai: Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế tự động tiếp nhận thông báo về việc tiếp nhận Mẫu 04/SS-HĐĐT theo Mẫu số 01/TB-SSĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP, qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế hoặc qua tổ chức cung cấp dịch vụ hóa đơn điện tử.\n Bước 3: Cơ quan Thuế tiếp nhận dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Mẫu số 04/SS-HĐĐT thông báo hóa đơn điện tử đã lập sai Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ; \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi phản hồi tự động về việc xác nhận người nộp thuế đã gửi thành công và thông báo về thời điểm tiếp nhận chính thức hồ sơ, tài liệu của người nộp thuế khi nhận Mẫu 04/SS-HĐĐT. \n + Cơ quan thuế trả thông báo về việc tiếp nhận/kết quả xử lý về việc hóa đơn điện tử đã lập sai theo Mẫu 01/TB-SSĐT Phụ lục IB ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ.", "dieu_kien": "Đảm bảo cơ sở hạ tầng CNTT để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử", "can_cu_phap_ly": "+ Khoản 13 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20 tháng 3 năm 2025 sửa đổi, bổ sung Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định về hóa đơn, chứng từ. \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010341"}, {"ma": "1.010331", "ten": "Đề nghị áp dụng APA", "cap_thuc_hien": "Cấp Bộ", "doi_tuong": "Tổ chức sản xuất, kinh doanh hàng hóa, dịch vụ là người nộp thuế thu nhập doanh nghiệp theo phương pháp kê khai, thực hiện giao dịch với các bên có quan hệ liên kết và có đề nghị với cơ quan thuế về việc áp dụng APA. Các bên có quan hệ liên kết được quy định tại Điều 5 Nghị định số 132/2020/NĐ-CP.", "co_quan": "Cục Thuế", "trinh_tu": "+ Bước 1. Người nộp thuế có yêu cầu áp dụng APA nộp đơn đề nghị áp dụng APA (tích vào ô Đề nghị áp dụng APA chính thức [đơn phương/song phương/đa phương]) theo mẫu số 01/APA-ĐN ban hành kèm theo Nghị định số 373/NĐ-CP ngày ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi một số điều của Nghị định 126/2020/NĐ-CP kèm theo hồ sơ đề nghị áp dụng APA thể hiện các thông tin, tài liệu theo quy định tại mục Ghi chú tại Đơn đề nghị áp dụng APA mẫu 01/APA-ĐN.\n ++ Trường hợp người nộp thuế đề nghị áp dụng APA song phương hoặc APA đa phương thì người nộp thuế điền thông tin đề nghị tiến hành Thủ tục thỏa thuận song phương tại mẫu số 01/APA-ĐN.\n ++ Người nộp thuế đang áp dụng APA đã ký nếu thuộc trường hợp có thể được xem xét gia hạn APA nếu có đề nghị gia hạn APA thì nộp mẫu số 01/APA-ĐN (tích ô Đề nghị gia hạn APA [đơn phương/song phương/đa phương] ) ban hành kèm theo Nghị định số 373/NĐ-CP ngày ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi một số điều của Nghị định 126/2020/NĐ-CP kèm hồ sơ đề nghị gia hạn APA trước khi APA đã ký hết hạn ít nhất 06 tháng\n ++ Người nộp thuế đang áp dụng APA đã ký nếu thuộc các trường hợp sửa đổi APA và mong muốn sửa đổi APA đó thì nộp mẫu số 01/APA-ĐN (tích ô Đề nghị sửa đổi APA [đơn phương/song phương/đa phương]) ban hành kèm theo Nghị định số 373/NĐ-CP ngày ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi một số điều của Nghị định 126/2020/NĐ-CP đề nghị với Cục Thuế.\n ++ Người nộp thuế đang áp dụng APA đã ký nếu thuộc các trường hợp có thể huỷ bỏ APA và mong muốn hủy bỏ APA đó thì nộp mẫu số 01/APA-ĐN (tích ô Đề nghị hủy bỏ APA [đơn phương/song phương/đa phương])ban hành kèm theo Nghị định số 373/NĐ-CP ngày ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi một số điều của Nghị định 126/2020/NĐ-CP nêu rõ lý do và gửi đến Cục Thuế.\n + Bước 2. Cục Thuế tiếp nhận hồ sơ theo quy định tại Luật Quản lý thuế, Nghị định 126/2020/NĐ-CP, Nghị định số 122/2025/NĐ-CP, Nghị định số 373/NĐ-CP và Thông tư 45/2021/TT-BTC.\n + Bước 3. Cục Thuế thực hiện\n ++ Họp trao đổi với người nộp thuế, khảo sát tại trụ sở người nộp thuế;\n ++ Tiến hành rà soát và phân tích hồ sơ, trao đổi, đàm phán với người nộp thuế (trong trường hợp APA đơn phương) hoặc với cơ quan thuế đối tác và người nộp thuế (trong trường hợp APA song phương hoặc APA đa phương) về nội dung APA. \n ++ Đối với trường hợp đề nghị áp dụng APA đơn phương, trên cơ sở kết quả rà soát, phân tích, trao đổi, đàm phán với người nộp thuế, về nội dung APA, Cục Thuế xây dựng dự thảo APA và trình lãnh đạo Bộ Tài chính phê duyệt, tiến hành ký kết APA. \n ++ Đối với trường hợp đề nghị áp dụng APA song phương hoặc đa phương, Cục Thuế sẽ tiến hành trao đổi, đàm phán nội dung về APA với người nộp thuế và cơ quan thuế nước ngoài, đồng thời xây dựng phương án đàm phán. Cục Thuế trình Bộ trưởng Bộ Tài chính phê duyệt phương án đàm phán. Sau khi có sự phê duyệt, Cục Thuế thực hiện trao đổi, đàm phán với người nộp thuế và cơ quan thuế nước ngoài về nội dung APA theo đúng phương án đã được phê duyệt. Trên cơ sở kết quả đàm phán, Cục Thuế xây dựng dự thảo APA và trình Bộ trưởng Bộ Tài chính ký APA.\n ++ Trường hợp trong quá trình giải quyết đề nghị APA của người nộp thuế phát sinh việc người nộp thuế (hoặc cơ quan thuế nước ngoài đối với trường hợp giải quyết đề nghị áp dụng APA song phương, đa phương) có văn bản gửi Cục Thuế đề nghị dừng đàm phán. Cục Thuế thông báo cho người nộp thuế (đối với APA đơn phương) hoặc cho người nộp thuế và thông báo hoặc xác nhận với cơ quan thuế nước ngoài (đối với APA song phương hoặc đa phương) về việc dừng đàm phán APA.", "cach_thuc": "+ Trực tiếp: Hồ sơ gửi đến cơ quan Cục Thuế; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Tờ khai theo mẫu số 01/APA-ĐN ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++ Hồ sơ nộp kèm thể hiện các thông tin chi tiết được nêu tại mục Ghi chú tại mẫu số 01/APA-ĐN hoặc nội dung, tài liệu kèm theo để xin đề nghị thực hiện thủ tục thỏa thuận song phương, gia hạn/sửa đổi/hủy bỏ hồ sơ APA. \n ++ Hồ sơ thể hiện bằng tiếng Việt; trường hợp hồ sơ đề nghị áp dụng APA song phương hoặc đa phương thì có thêm bản tiếng Anh. \n Trường hợp trong quá trình giải quyết đề nghị APA của người nộp thuế phát sinh việc người nộp thuế đề nghị dừng đàm phán: Thành phần hồ sơ là văn bản gửi Cục Thuế về việc đề nghị dừng đàm phán. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Không có", "dieu_kien": "+ Đối với đề nghị Gia hạn APA có thể được xem xét gia hạn trong trường hợp thỏa mãn đầy đủ các điều kiện sau: Phạm vi giao dịch liên kết và các bên liên kết không có thay đổi mang tính trọng yếu; các giả định quan trọng không có thay đổi mang tính trọng yếu; khoảng giá trị giao dịch độc lập chuẩn hoặc tỷ suất lợi nhuận làm cơ sở phân tích so sánh có sự ổn định trong thời gian được gia hạn. \n + Đối với đề nghị Sửa đổi APA có thể được xem xét sửa đổi trong các trường hợp sau: Các giả định quan trọng có ảnh hưởng trọng yếu có thay đổi do nguyên nhân khách quan; thay đổi của pháp luật có tác động tới APA; nhà chức trách có thẩm quyền của cơ quan thuế đối tác đề nghị sửa đổi và được Bộ Tài chính chấp thuận; và các trường hợp khác. \n + Đối với đề nghị Hủy bỏ APA: APA có thể bị hủy bỏ trong các trường hợp sau: Người nộp thuế hay bất kỳ bên liên kết nào liên quan tới giao dịch liên kết không tuân thủ theo các điều khoản và điều kiện của APA; người nộp thuế có sai sót hoặc có lỗi trọng yếu trong hồ sơ đề nghị áp dụng APA, báo cáo APA thường niên, báo cáo đột xuất; người nộp thuế không cung cấp đầy đủ thông tin, tài liệu của báo cáo APA thường niên hoặc thông tin, tài liệu và báo cáo đột xuất theo yêu cầu của cơ quan thuế; người nộp thuế và cơ quan thuế không thống nhất được kết luận việc sửa đổi APA; cơ quan thuế đối tác đề nghị hủy bỏ APA và được Bộ Tài chính chấp thuận; người nộp thuế nộp hồ sơ xin hủy bỏ APA với lý do hợp lý.L2", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Nghị định số 122/2025/NĐ-CP ngày 11 tháng 6 năm 2025 của Chính phủ. \n + Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư 45/2021/TT-BTC ngày 18 tháng 6 năm 2021 hướng dẫn việc áp dụng cơ chế Thỏa thuận trước về phương pháp xác định giá tính thuế (APA) trong quản lý thuế đối với giao dịch liên kết\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/APA-ĐN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010331"}, {"ma": "1.010343", "ten": "Chuyển dữ liệu hóa đơn điện tử tới cơ quan thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "+ Doanh nghiệp, tổ chức kinh tế, tổ chức khác, hộ kinh doanh, cá nhân kinh doanh đăng ký sử dụng hóa đơn điện tử.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "Bước 1:\n + Về phương thức lập hóa đơn điện tử và thời điểm chuyển dữ liệu hóa đơn điện tử:\n Trường hợp (1): Người bán hàng chuyển dữ liệu hóa đơn điện tử hàng hóa, cung cấp dịch vụ phát sinh trong tháng hoặc quý theo Bảng tổng hợp dữ liệu hóa đơn điện tử \n ++Trường hợp gửi theo Mẫu số 01/TH-HĐĐT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ quy định về hóa đơn, chứng từ đối với các trường hợp sau:\n +++ Cung cấp dịch vụ thuộc lĩnh vực: Bưu chính viễn thông, bảo hiểm, tài chính ngân hàng, vận tải hàng không, chứng khoán;\n +++ Bán hàng hóa là điện, nước nếu có thông tin về mã khách hàng hoặc mã số thuế của khách hàng.\n +++ Bán hàng hóa, cung cấp dịch vụ của nhà cung cấp ở nước ngoài không có cơ sở thường trú tại Việt Nam hoạt động thương mại điện tử, kinh doanh dựa trên nền tảng số và các dịch vụ khác tại Việt Nam.\n ++ Trường hợp gửi theo Mẫu 01/TH-DT Phụ lục IA ban hành kèm theo Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ: hoạt động kinh doanh casino và trò chơi điện tử có thưởng, thời điểm lập hóa đơn điện tử chậm nhất là 01 ngày kể từ thời điểm kết thúc ngày xác định doanh thu, đồng thời doanh nghiệp kinh doanh casino và trò chơi điện tử có thưởng chuyển dữ liệu ghi nhận số tiền thu được (do đổi đồng tiền quy ước cho người chơi tại quầy, tại bàn chơi và số tiền thu tại máy trò chơi điện tử có thưởng) trừ đi số tiền đổi trả cho người chơi (do người chơi trúng thưởng hoặc người chơi không sử dụng hết) theo Mẫu 01/TH-DT Phụ lục IA ban hành kèm theo Nghị định này đến cơ quan thuế cùng thời điểm chuyển dữ liệu hóa đơn điện tử. Ngày xác định doanh thu là khoảng thời gian từ 0 giờ 00 phút đến 23 giờ 59 phút cùng ngày.”\n Trường hợp (2): Phương thức chuyển đầy đủ nội dung hóa đơn áp dụng đối với trường hợp bán hàng hóa, cung cấp dịch vụ không thuộc quy định chuyển dữ liệu hóa đơn điện tử theo bảng tổng hợp: Người bán sau khi lập đầy đủ các nội dung trên hóa đơn gửi hóa đơn cho người mua và đồng thời gửi hóa đơn cho cơ quan thuế chậm nhất là ngày làm việc tiếp theo kể từ thời điểm lập hóa đơn.\n + Về hình thức gửi dữ liệu tới cơ quan thuế như sau: \n ++ Đối với hình thức gửi trực tiếp:\n +++ Doanh nghiệp, tổ chức kinh tế sử dụng hóa đơn bình quân từ 1.000.000 hóa đơn một tháng trở lên (tính theo số lượng hóa đơn bình quân năm trước liền kề), có hệ thống công nghệ thông tin đáp ứng yêu cầu về định dạng chuẩn dữ liệu, có nhu cầu chuyển dữ liệu hóa đơn điện tử theo hình thức gửi trực tiếp đến cơ quan thuế gửi văn bản kèm theo tài liệu chứng minh điều kiện đáp ứng đến Cục Thuế.\n +++ Doanh nghiệp, tổ chức kinh tế có tổ chức mô hình Công ty mẹ - con, có xây dựng hệ thống quản lý dữ liệu hóa đơn tập trung tại Công ty mẹ và có nhu cầu Công ty mẹ chuyển toàn bộ dữ liệu hóa đơn điện tử bao gồm cả dữ liệu của các công ty con đến cơ quan thuế qua Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế thì gửi kèm theo danh sách công ty con đến Cục Thuế để thực hiện kết nối kỹ thuật.\n ++ Đối với hình thức gửi thông qua tổ chức cung cấp dịch vụ hóa đơn điện tử:\n +++ Các doanh nghiệp, tổ chức kinh tế không thuộc trường hợp gửi trực tiếp thực hiện ký hợp đồng với tổ chức cung cấp dịch vụ hóa đơn điện tử để tổ chức cung cấp dịch vụ hóa đơn điện tử làm dịch vụ chuyển dữ liệu hóa đơn điện tử đến cơ quan thuế;\n Bước 2: Cơ quan Thuế tiếp nhận và giải quyết hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "++ Mẫu số 01/TH-HĐĐT đối với bảng tổng hợp dữ liệu hóa đơn điện tử. \n ++ Mẫu 01/TH-DT đối với bảng tổng hợp doanh thu (đối với hoạt động kinh doanh casino, trò chơi điện tử có thưởng). \n ++ Hồ sơ đăng ký gửi dữ liệu HĐĐT trực tiếp: Văn bản kèm theo tài liệu chứng minh điều kiện đáp ứng yêu cầu về hóa đơn bình quân từ 1.000.000 hóa đơn một tháng trở lên (tính theo số lượng hóa đơn bình quân năm trước liền kề), có hệ thống công nghệ thông tin đáp ứng yêu cầu về định dạng chuẩn dữ liệu, có nhu cầu chuyển dữ liệu hóa đơn điện tử theo hình thức gửi trực tiếp đến cơ quan thuế (không có mẫu) \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Hệ thống thông tin giải quyết thủ tục hành chính của ngành thuế gửi phản hồi tự động về việc xác nhận người nộp thuế đã gửi thành công và thông báo về thời điểm tiếp nhận chính thức hồ sơ, tài liệu của người nộp thuế khi nhận được dữ liệu hóa đơn điện tử của NNT. \n + Đối với hình thức gửi trực tiếp đến cơ quan thuế: Mẫu 01/TB-ĐKĐT Thông báo về việc chấp nhận/không chấp nhận đăng ký/thay đổi thông tin sử dụng hóa đơn điện tử/chứng từ điện tử và thực hiện kết nối kỹ thuật và kiểm tra truyền nhận dữ liệu.", "dieu_kien": "++ Đối với dữ liệu hóa đơn điện tử: Đảm bảo cơ sở hạ tầng CNTT để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử. \n ++ Đối với hình thức gửi trực tiếp: số lượng hóa đơn bình quân từ 1.000.000 hóa đơn một tháng trở lên (tính theo số lượng hóa đơn bình quân năm trước liền kề), có hệ thống công nghệ thông tin đáp ứng yêu cầu về định dạng chuẩn dữ liệu, có nhu cầu chuyển dữ liệu hóa đơn điện tử theo hình thức gửi trực tiếp đến cơ quan thuế.", "can_cu_phap_ly": "+ Khoản 14 Điều 1 Nghị định số 70/2025/NĐ-CP ngày 20/3/2025 của Chính phủ quy định về hóa đơn, chứng từ sửa đổi, bổ sung Điều 22 Nghị định số 123/2020/NĐ-CP ngày 19/10/2020 của Chính phủ về hóa đơn, chứng từ. \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010343"}, {"ma": "1.011022", "ten": "Khai thuế đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế theo phương pháp kê khai", "cap_thuc_hien": "Cấp xã", "doi_tuong": "Hộ kinh doanh, cá nhân kinh doanh nộp thuế theo phương pháp kê khai.", "co_quan": "Thuế cơ sở.", "trinh_tu": "+ Bước 1. Hộ kinh doanh, cá nhân kinh doanh nộp thuế theo phương pháp kê khai khai thuế giá trị gia tăng, thuế thu nhập cá nhân, thuế tiêu thụ đặc biệt, thuế/phí bảo vệ môi trường, thuế tài nguyên chuẩn bị hồ sơ và gửi đến cơ quan thuế nơi có hoạt động sản xuất, kinh doanh chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế đối với hộ, cá nhân khai thuế theo tháng hoặc ngày cuối cùng của tháng đầu quý tiếp theo quý phát sinh nghĩa vụ thuế đối với hộ, cá nhân khai thuế theo quý.\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Tờ khai thuế đối với hộ kinh doanh, cá nhân kinh doanh mẫu số 01/CNKD theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục Bảng kê hoạt động kinh doanh trong kỳ của hộ kinh doanh, cá nhân kinh doanh (Kèm theo Tờ khai 01/CNKD áp dụng đối với hộ kinh doanh, cá nhân kinh doanh nộp thuế theo phương pháp kê khai) mẫu số 01-2/BK-HĐKD theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. Trường hợp hộ kinh doanh, cá nhân kinh doanh có căn cứ xác định được doanh thu theo xác nhận của cơ quan chức năng thì không phải nộp Phụ lục Bảng kê mẫu số 01-2/BK-HĐKD. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 100/2021/TT-BTC ngày 15 tháng 11 năm 2021 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-2/BK-HĐKD", "01/CNKD"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011022"}, {"ma": "1.014030", "ten": "Thủ tục kê khai và nộp thuế đã khấu trừ đối với các tổ chức quản lý nền tảng thương mại điện tử của hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Các tổ chức quản lý Tổ chức quản lý nền tảng thương mại điện tử theo quy định tại Nghị định số 117/2025/NĐ-CP.", "co_quan": "Chi cục Thuế Thương mại điện tử; Thuế tỉnh, thành phố; Thuế cơ sở", "trinh_tu": "Đăng ký thuế:\n +) Các tổ chức quản lý nền tảng thương mại điện tử ở trong nước được hệ thống của cơ quan thuế cấp mã số thuế riêng (mã số thuế 10 chữ số) để kê khai và nộp thay số thuế đã khấu trừ và không phải nộp hồ sơ đăng ký thuế. \n +) Các tổ chức quản lý nền tảng thương mại điện tử ở nước ngoài được cấp mã số thuế 10 chữ số để thực hiện nghĩa vụ thuế phát sinh tại Việt Nam (nếu có) như quy định đối với nhà cung cấp ở nước ngoài tại Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ trưởng Bộ Tài chính và được sử dụng mã số thuế này để kê khai và nộp số thuế đã khấu trừ của hộ, cá nhân cư trú kinh doanh trên nền tảng thương mại điện tử ở nước ngoài.\n Khấu trừ thuế, Khai thuế:\n Các tổ chức quản lý nền tảng thương mại điện tử thực hiện khấu trừ, nộp hồ sơ khai thuế tại cơ quan thuế trực tiếp quản lý tổ chức khấu trừ đó bằng phương thức điện tử trên Cổng thông tin điện tử của ngành Thuế (thuedientu.gdt.gov.vn)\n Thời điểm thực hiện khấu trừ: tổ chức quản lý nền tảng thương mại điện tử thực hiện khấu trừ số thuế giá trị gia tăng, số thuế thu nhập cá nhân phải nộp đối với mỗi giao dịch cung cấp hàng hóa, dịch vụ phát sinh doanh thu trên nền tảng thương mại điện tử thuộc phạm vi quản lý ngay khi xác nhận đơn hàng thành công và chấp nhận thanh toán đối với giao dịch bán hàng hóa, dịch vụ trên nền tảng thương mại điện tử cho hộ, cá nhân kinh doanh. \n Tổ chức chức quản lý nền tảng thương mại điện tử khấu trừ thực hiện nộp hồ sơ khai thuế theo tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế.\n Nộp thuế:\n Các tổ chức quản lý nền tảng thương mại điện tử thực hiện nộp thuế thay theo quy định tại Luật quản lý thuế.\n +) Đối với tổ chức quản lý nền tảng thương mại điện tử ở trong nước: Nộp qua Cổng thông tin tiếp nhận và xử lý thủ tục hành chính của Cục Thuế/ Nộp qua Cổng dịch vụ Công quốc gia/ Nộp qua dịch vụ thanh toán của NHTM, chi nhánh ngân hàng nước ngoài. Ngay sau khi nộp thành công số tiền thuế đã khấu trừ của hộ, cá nhân kinh doanh vào NSNN, tổ chức khấu trừ lập Bảng kê chi tiết số tiền nộp thuế của tổ chức quản lý nền tảng thương mại điện tử theo mẫu số 01/BKNT-TMĐT trên ứng dụng hỗ trợ kê khai (HTKK) và gửi cho cơ quan thuế. \n +) Đối với tổ chức quản lý nền tảng thương mại điện tử ở nước ngoài: Hệ thống của Cơ quan thuế Việt Nam gửi email, thực hiện chuyển tiền chính xác theo đúng nội dung đã được thông báo trong email đến số tài khoản của Sở giao dịch Kho bạc Nhà nước.\n Thời hạn nộp thuế chậm nhất là ngày cuối cùng của thời hạn nộp hồ sơ khai thuế.", "cach_thuc": "Bằng phương thức điện tử qua Hệ thống thông tin giải quyết TTHC của cơ quan thuế /Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Hồ sơ khai thuế: Tờ khai khấu trừ thuế đối với hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử theo mẫu số 01/CNKD-TMĐT; Bảng kê chi tiết số tiền nộp thuế của tổ chức quản lý nền tảng thương mại điện tử theo mẫu số 01/BKNT-TMĐT\n ++ Nộp thuế: Bảng kê chi tiết số tiền nộp thuế của tổ chức quản lý nền tảng thương mại điện tử theo mẫu số 01/BKNT-TMĐT\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Cổng thông tin điện tử của Cục Thuế gửi phản hồi tự động về việc tiếp nhận và xử lý hồ sơ khai thuế theo quy định. \n + Cổng thông tin điện tử xử lý chứng từ nộp tiền và trả Thông báo liên quan tại Hệ thống Thuế điện tử Etax/Cổng dịch vụ công quốc gia/Cổng thanh toán điện tử của Ngân hàng.", "dieu_kien": "++ Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Điều 4, Điều 5, Điều 6 Nghị định số 117/2025/NĐ-CP ngày 09/6/2025 của Chính phủ quy định về quản lý thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số của hộ, cá nhân.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/BKNT-TMĐT", "01/CNKD-TMĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014030"}, {"ma": "1.008494", "ten": "Đăng ký thuế để cấp mã số thuế nộp thay đối với người nộp thuế là doanh nghiệp, tổ chức, cá nhân khấu trừ nộp thay cho nhà thầu, nhà thầu phụ nước ngoài; tổ chức hợp tác kinh doanh với cá nhân, tổ chức được giao quản lý hợp đồng hợp tác kinh doanh với tổ chức nhưng không thành lập pháp nhân riêng (nếu có nhu cầu cấp mã số thuế riêng cho hợp đồng hợp tác kinh doanh); Ngân hàng thương mại, tổ chức cung ứng dịch vụ trung gian thanh toán hoặc tổ chức, cá nhân được nhà cung cấp ở nước ngoài ủy quyền có trách nhiệm khấu trừ và nộp thuế thay cho nhà cung cấp ở nước ngoài; Tổ chức, cá nhân được cơ quan thuế ủy nhiệm thu", "cap_thuc_hien": "Thuế tỉnh, thành phố/ Thuế cơ sở", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Chi cục Thuế.", "trinh_tu": "+ Bước 1: Trong thời hạn 10 ngày làm việc kể từ ngày: Phát sinh trách nhiệm khấu trừ thuế và nộp thuế thay theo hợp đồng, văn bản hợp tác kinh doanh; Uỷ nhiệm thu theo quy định của Luật quản lý thuế, người nộp thuế (NNT) chuẩn bị hồ sơ đăng ký thuế đầy đủ theo đúng quy định sau đó gửi đến cơ quan thuế quản lý trực tiếp hoặc tại cơ quan thuế ký hợp đồng ủy nhiệm thu để làm thủ tục đăng ký thuế.\n ++ Đối với trường hợp hồ sơ đăng ký thuế điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng cục Thuế/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai tờ khai và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn;\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Đối với hồ sơ bằng giấy:\n +++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: Công chức thuế kiểm tra hồ sơ đăng ký thuế. Trường hợp hồ sơ đầy đủ theo quy định, công chức thuế tiếp nhận và đóng dấu tiếp nhận vào hồ sơ đăng ký thuế, ghi rõ ngày nhận hồ sơ, số lượng tài liệu theo bảng kê danh mục hồ sơ; lập phiếu tiếp nhận và hẹn trả kết quả, thời hạn xử lý hồ sơ đã tiếp nhận. Trường hợp hồ sơ không đầy đủ theo quy định, công chức thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ.\n +++ Trường hợp hồ sơ gửi bằng đường bưu chính: Công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ vào hồ sơ và ghi số văn thư của cơ quan thuế. Trường hợp hồ sơ không đầy đủ cần phải giải trình, bổ sung thông tin, tài liệu, cơ quan thuế thông báo cho người nộp thuế theo mẫu số 01/TB-BSTT-NNT tại Phụ lục II ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ trong thời hạn 02 (hai) ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++ Đối với hồ sơ điện tử:\n Cơ quan thuế thực hiện tiếp nhận hồ sơ qua Cổng thông tin điện tử của Tổng cục Thuế, thực hiện kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đăng ký thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của người nộp thuế theo quy định của pháp luật về đăng ký thuế và trả kết quả giải quyết qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ.\n ++++ Trường hợp hồ sơ đầy đủ, đúng thủ tục theo quy định: Cơ quan thuế gửi kết quả giải quyết hồ sơ đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ theo thời hạn quy định tại Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n ++++ Trường hợp hồ sơ chưa đầy đủ, chưa đúng thủ tục theo quy định: Cơ quan thuế gửi thông báo về việc không chấp nhận hồ sơ, gửi đến Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ trong thời hạn 02 (hai) ngày làm việc kể từ ngày ghi trên Thông báo tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n * Đối với tổ chức, cá nhân khấu trừ nộp thay cho nhà thầu nước ngoài, nhà thầu phụ nước ngoài, gồm:\n ++ Tờ khai đăng ký thuế theo mẫu số 04.1-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bảng kê các hợp đồng nhà thầu nước ngoài, nhà thầu phụ nước ngoài nộp thuế thông qua Bên Việt Nam mẫu số 04.1-ĐK-TCT-BK ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n * Đối với Tổ chức hợp tác kinh doanh với cá nhân, tổ chức được giao quản lý hợp đồng hợp tác kinh doanh với tổ chức nhưng không thành lập pháp nhân riêng, gồm:\n ++ Tờ khai đăng ký thuế theo mẫu số 04.1-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính;\n ++ Bản sao hợp đồng hoặc văn bản hợp tác kinh doanh.\n * Đối với Ngân hàng thương mại, tổ chức cung ứng dịch vụ trung gian thanh toán hoặc tổ chức, cá nhân được nhà cung cấp ở nước ngoài ủy quyền có trách nhiệm khấu trừ và nộp thuế thay cho nhà cung cấp ở nước ngoài, gồm: Tờ khai đăng ký thuế theo mẫu số 04.1-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n * Đối với tổ chức, cá nhân được cơ quan thuế ủy nhiệm thu, gồm: Tờ khai đăng ký thuế mẫu số 04.4-ĐK-TCT ban hành kèm theo Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính.\n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Thông báo mã số thuế nộp thay.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn Giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n + Thông tư số 86/2024/TT-BTC ngày 23/12/2024 của Bộ Tài chính quy định về đăng ký thuế.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008494"}, {"ma": "1.008565", "ten": "Bù trừ, hoàn nộp thừa các loại thuế và các khoản thu khác", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị hồ sơ đề nghị hoàn thuế theo quy định và gửi đến cơ quan thuế.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: cơ quan thuế kiểm tra tính đầy đủ của hồ sơ theo quy định. Trường hợp hồ sơ chưa đầy đủ, cơ quan thuế đề nghị người nộp thuế hoàn thiện hồ sơ theo quy định. Trường hợp hồ sơ đầy đủ, cơ quan thuế gửi Thông báo về việc tiếp nhận hồ sơ cho người nộp thuế mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: cơ quan thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận hoặc thông báo lý do không tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của người nộp thuế.\n Kiểm tra, giải quyết hồ sơ: \n +++ Hồ sơ được chấp nhận/không chấp nhận: Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế.\n +++ Hồ sơ không đúng thủ tục: Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC.\n + Bước 3. Cơ quan thuế xử lý hồ sơ đề nghị hoàn thuế\n Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ đề nghị hoàn thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế, cơ quan thuế gửi người nộp thuế Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC.\n Trường hợp chưa đủ thông tin để xác định hồ sơ hoàn thuế của người nộp thuế thuộc đối tượng và trường hợp được hoàn thuế, cơ quan thuế lập Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế gửi người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày cơ quan thuế tiếp nhận hồ sơ đề nghị hoàn thuế của người nộp thuế.\n Trong thời hạn 10 ngày làm việc kể từ ngày cơ quan thuế ban hành Thông báo, người nộp thuế có trách nhiệm gửi văn bản giải trình hoặc bổ sung thông tin, tài liệu theo Thông báo của cơ quan thuế.\n Hết thời hạn theo Thông báo của cơ quan thuế nhưng người nộp thuế không giải trình, bổ sung hồ sơ hoàn thuế; hoặc có văn bản giải trình, bổ sung nhưng không chứng minh được số thuế đã khai là đúng thì cơ quan thuế chuyển hồ sơ hoàn thuế sang diện kiểm tra trước hoàn thuế và gửi Thông báo về việc chuyển hồ sơ sang diện kiểm tra trước hoàn thuế theo mẫu số 05/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC cho người nộp thuế trong thời hạn 06 ngày làm việc kể từ ngày chấp nhận hồ sơ hoàn thuế.\n + Bước 4. Cơ quan thuế trả kết quả giải quyết hồ sơ đề nghị hoàn thuế\n Cơ quan thuế ban hành:\n ++ Quyết định hoàn thuế theo mẫu số 01/QĐHT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả theo mẫu số 01/PL-HTNT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp người nộp thuế không còn tiền thuế nợ.\n ++ Hoặc Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước theo mẫu số 02/QĐHT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả mẫu số 01/PL-HTNT, Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ 01/PL-BT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp người nộp thuế còn tiền thuế nợ hoặc người nộp thuế đề nghị bù trừ số thuế được hoàn trả với khoản nợ, khoản thu phát sinh của người nộp thuế khác\n + Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC trong trường hợp hồ sơ không thuộc diện được hoàn thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "Thành phần hồ sơ theo Điều 42 và Danh mục mẫu biểu tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC gồm: \n + Văn bản đề nghị xử lý số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa mẫu số 01/DNXLNT; \n + Văn bản ủy quyền trong trường hợp người nộp thuế không trực tiếp thực hiện thủ tục hoàn thuế, trừ trường hợp đại lý thuế nộp hồ sơ hoàn thuế theo hợp đồng đã ký giữa đại lý thuế và người nộp thuế; \n + Các tài liệu kèm theo (nếu có);", "ket_qua": "+ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT. \n ++ Trường hợp người nộp thuế không còn tiền thuế nợ: \n +++ Quyết định hoàn thuế mẫu số 01/QĐHT. \n +++ Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả 01/PL-HTNT. \n ++ Trường hợp người nộp thuế còn tiền thuế nợ hoặc người nộp thuế đề nghị bù trừ số thuế được hoàn trả với khoản nợ, khoản thu phát sinh của người nộp thuế khác: \n +++ Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT. \n +++ Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa được hoàn trả 01/PL-HTNT. \n +++ Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vựng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/DNXLNT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008565"}, {"ma": "1.008547", "ten": "Khai thuế tài nguyên tạm tính đối với hoạt động khai thác, xuất bán dầu thô, khí thiên nhiên (trừ Lô 09.1) (chỉ áp dụng cho kỳ tính thuế nhỏ hơn 14/02/2026)", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Người điều hành, Doanh nghiệp liên doanh, Công ty điều hành chung.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế: \n ++ Đối với dầu thô, condensate: chậm nhất là ngày thứ 35 kể từ ngày xuất bán dầu thô, condensate. Ngày xuất bán là ngày hoàn thành việc xuất dầu thô, condensate tại điểm giao nhận. Trường hợp ngày thứ 35 trùng với ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó. \n ++ Đối với khí thiên nhiên: chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế. Trường hợp ngày thứ 20 là ngày nghỉ theo quy định thì thời hạn nộp hồ sơ khai thuế được tính là ngày làm việc tiếp theo của ngày nghỉ đó. \n + Bước 2. Cơ quan thuế tiếp nhận: \n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ. \n Trường hợp tiếp nhận hồ sơ qua Cổng thông tin điện tử của Cục Thuế, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế: \n ++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế \n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Nộp trực tiếp tại trụ sở cơ quan thuế. \n + Hoặc gửi qua hệ thống bưu chính. \n + Hoặc gửi hồ sơ điện tử đến cơ quan thuế qua giao dịch điện tử (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thuế tài nguyên tạm tính đối với dầu khí Mẫu số 01/TAIN - DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n ++ Phụ lục chi tiết nghĩa vụ thuế của các nhà thầu dầu khí Mẫu số 01/PL- DK ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Dầu khí ngày 06/07/1993, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 19/2000/QH10 ngày 09/06/2000, Luật sửa đổi, bổ sung một số điều của Luật Dầu khí số 10/2008/QH12 ngày 03/06/2008 và các văn bản hướng dẫn thi hành; Luật Dầu khí số 12/2022/QH15 ngày 14/11/2022 và các văn bản hướng dẫn thi hành; \n + Các Luật thuế và các văn bản hướng dẫn hiện hành; \n + Luật quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 33/2013/NĐ-CP ngày 22/4/2013 của Chính phủ Ban hành hợp đồng mẫu của Hợp đồng Chia sản phẩm dầu khí; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Thông tư số 36/2016/TT-BTC ngày 26/02/2016 của Bộ Tài chính hướng dẫn thực hiện quy định về thuế đối với tổ chức, cá nhân tiến hành hoạt động tìm kiếm thăm dò và khai thác dầu khí theo quy định của Luật dầu khí; \n + Thông tư số 19/2021/TT-BTC ngày 19/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008547"}, {"ma": "1.008331", "ten": "Khai thuế đối với tái bảo hiểm nước ngoài/hãng hàng không nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức", "co_quan": "Thuế tỉnh, thành phố/ Thuế cơ sở/ Chi cục thuế Doanh nghiệp lớn", "trinh_tu": "+ Bước 1: \n ++ Trường hợp khai thuế đối với hãng hàng không nước ngoài: Văn phòng bán vé, đại lý tại Việt Nam của hãng Hàng không nước ngoài có trách nhiệm khai thuế TNDN và nộp thuế cho hãng Hàng không nước ngoài. Hồ sơ khai thuế được nộp cho cơ quan thuế quản lý trực tiếp Văn phòng bán vé, đại lý tại Việt Nam của hãng Hàng không nước ngoài. Khai thuế TNDN cho hãng Hàng không nước ngoài là loại khai theo quý.\n ++ Trường hợp khai thuế đối với tái bảo hiểm nước ngoài: Hàng quý, Bên Việt Nam lập hồ sơ khai thuế thay cho các tổ chức nhận tái bảo hiểm nước ngoài và gửi đến cơ quan Thuế.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n (i1) Đối với khai thuế đối với hãng hàng không nước ngoài gồm: \n ++ Tờ khai thuế cho các hãng Hàng không nước ngoài theo mẫu số 01/HKNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n ++ Bản sao hợp đồng nhà thầu, hợp đồng nhà thầu phụ có xác nhận của người nộp thuế (đối với lần khai thuế đầu tiên của hợp đồng nhà thầu); \n ++ Bản sao giấy phép kinh doanh hoặc giấy phép hành nghề có xác nhận của người nộp thuế. \n (i2) Đối với khai thuế đối với tái bảo hiểm nước ngoài gồm: \n ++ Tờ khai thuế thu nhập doanh nghiệp đối với tổ chức nhận tái bảo hiểm nước ngoài theo mẫu số 01/TBH ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++ Phụ lục hợp đồng tái bảo hiểm, chứng từ tái bảo hiểm theo tổ chức nhận tái bảo hiểm nước ngoài theo mẫu số 01-1/TBH ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++ Bản sao giấy phép kinh doanh hoặc giấy phép hành nghề có xác nhận của người nộp thuế. \n (Thành phần hồ sơ ban hành kèm theo Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục I Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14) \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC của 09/07/2025 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; Luật số sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 373/2025/NĐ-CP ngày 31 tháng 12 năm 2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TBH", "01/HKNN", "01/TBH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008331"}, {"ma": "1.010949", "ten": "Thay đổi kỳ tính thuế giá trị gia tăng từ tháng sang quý", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) đang thực hiện khai thuế giá trị gia tăng (GTGT), thuế thu nhập cá nhân (TNCN) theo tháng nếu đủ điều kiện khai thuế theo quý quy định tại khoản 1 Điều 9 Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và lựa chọn chuyển sang khai thuế theo quý thì người nộp thuế lập hồ sơ đề nghị và gửi đến cơ quan thuế quản lý trực tiếp chậm nhất là 31 tháng 01 của năm bắt đầu khai thuế theo quý. \n ++ Trường hợp NNT nộp hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính để lập hồ sơ điện tử, ký điện tử và gửi đến cơ quan thuế.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp/qua bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh/Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n +++ Kiểm tra, chấp nhận hồ sơ: Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp/qua bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ: Văn bản đề nghị thay đổi kỳ tính thuế từ tháng sang quý mẫu số 01/ĐK-TĐKTT ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ trưởng Bộ Tài chính) hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐK-TĐKTT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010949"}, {"ma": "1.008323", "ten": "Khai thuế bảo vệ môi trường", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tổ chức, cá nhân có hoạt động sản xuất kinh doanh hàng hóa chịu thuế bảo vệ môi trường.", "co_quan": "Thuế tỉnh, thành phố/Chi cục Thuế doanh nghiệp lớn.", "trinh_tu": "+ Bước 1: Người nộp thuế chuẩn bị số liệu, lập tờ khai và gửi đến cơ quan thuế chậm nhất vào ngày 20 của tháng sau tháng phát sinh, cụ thể như sau:\n ++ Người nộp thuế nộp hồ sơ khai thuế bảo vệ môi trường tại nơi sản xuất hàng hóa chịu thuế bảo vệ môi trường, nơi sản xuất, kinh doanh than, trừ thuế bảo vệ môi trường của hoạt động kinh doanh xăng dầu (quy định tại điểm a khoản 4 Điều 11 Nghị định số 126/2020/NĐ-CP), thuế bảo vệ môi trường của than khai thác và tiêu thụ nội địa (quy định tại điểm b khoản 4 Điều 11 Nghị định số 126/2020/NĐ-CP).\n ++ Đối với hoạt động kinh doanh xăng dầu:\n +++ Thương nhân đầu mối trực tiếp nhập khẩu, sản xuất, pha chế xăng dầu nộp hồ sơ khai thuế đến cơ quan thuế quản lý trực tiếp đối với lượng xăng dầu do các thương nhân đầu mối trực tiếp xuất, bán bao gồm xuất để tiêu dùng nội bộ, xuất để trao đổi sản phẩm hàng hóa khác, xuất trả hàng nhập khẩu ủy thác, bán cho tổ chức, cá nhân khác không phải là các đơn vị phụ thuộc, công ty con theo quy định tại Luật Doanh nghiệp của thương nhân đầu mối; trừ lượng xăng dầu xuất bán và nhập khẩu ủy thác cho thương nhân đầu mối khác.\n +++ Các công ty con theo quy định tại Luật Doanh nghiệp của thương nhân đầu mối hoặc các đơn vị phụ thuộc của các công ty con, các đơn vị phụ thuộc của thương nhân đầu mối nộp hồ sơ khai thuế đến cơ quan thuế quản lý trực tiếp đối với lượng xăng dầu xuất, bán cho tổ chức, cá nhân khác không phải là công ty con theo quy định tại Luật Doanh nghiệp của thương nhân đầu mối và đơn vị phụ thuộc của công ty con.\n +++ Thương nhân đầu mối hoặc công ty con theo quy định tại Luật Doanh nghiệp của thương nhân đầu mối có đơn vị phụ thuộc kinh doanh tại địa phương khác tỉnh, thành phố trực thuộc trung ương với nơi thương nhân đầu mối, công ty con của thương nhân đầu mối đóng trụ sở mà đơn vị phụ thuộc không hạch toán kế toán để khai riêng được thuế bảo vệ môi trường thì thương nhân đầu mối, công ty con của thương nhân đầu mối thực hiện khai thuế bảo vệ môi trường đến cơ quan thuế quản lý trực tiếp; tính thuế, phân bổ nghĩa vụ thuế phải nộp cho từng địa phương nơi có đơn vị phụ thuộc đóng trụ sở theo quy định của Bộ trưởng Bộ Tài chính.\n ++ Đối với than khai thác và tiêu thụ nội địa:\n Doanh nghiệp có hoạt động khai thác và tiêu thụ than nội địa thông qua hình thức quản lý và giao cho các công ty con hoặc đơn vị phụ thuộc khai thác, chế biến và tiêu thụ thì đơn vị thực hiện nhiệm vụ tiêu thụ than thực hiện khai thuế cho toàn bộ số thuế bảo vệ môi trường phát sinh đối với than khai thác thuộc diện chịu thuế và nộp hồ sơ khai thuế đến cơ quan thuế quản lý trực tiếp kèm theo Bảng xác định số thuế phải nộp cho từng địa phương nơi có công ty khai thác than đóng trụ sở theo quy định của Bộ trưởng Bộ Tài chính.\n + Bước 2: Cơ quan thuế tiếp nhận:\n ++ Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n ++Trường hợp tiếp nhận hồ sơ khai thuế điện tử, cơ quan thuế thực hiện tiếp nhận, kiểm tra, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế\n ++ Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành, gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;. \n + Trực tuyến: qua Cổng dịch vụ công quốc gia đối với các thủ tục hành chính đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết thủ tục hành chính của Cục Thuế, Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN theo quy định.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm; \n ++ Tờ khai thuế BVMT mẫu số 01/TBVMT theo Phụ lục 1 - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n ++ Phụ lục bảng xác định số thuế bảo vệ môi trường phải nộp cho các địa phương nơi được hưởng nguồn thu đối với than mẫu số 01-1/TBVMT theo Phụ lục 1 Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (trường hợp người nộp thuế thực hiện phân bổ thuế BVMT phải nộp của mặt hàng xăng dầu cho từng địa phương nơi có đơn vị phụ thuộc đóng trụ sở theo quy định); \n ++ Phụ lục bảng phân bổ số thuế bảo vệ môi trường phải nộp cho các địa phương nơi được hưởng nguồn thu đối với xăng dầu mẫu số 01-2/TBVMT theo Phụ lục 1 Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (trường hợp người nộp thuế xác định số thuế phải nộp cho từng địa phương nơi có công ty khai thác than đóng trụ sở theo quy định). \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật thuế Bảo vệ môi trường số 57/2010/QH11 ngày 15/11/2010; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 67/2011/NĐ-CP ngày 08/08/2011 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Luật thuế Bảo vệ môi trường (sửa đổi, bổ sung tại Nghị định số 69/2012/NĐ-CP ngày 14/09/2012 của Chính phủ); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; \n + Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; Thông tư số 46/2024/TT-BTC ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TBVMT", "01-2/TBVMT", "01/TBVMT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008323"}, {"ma": "1.014033", "ten": "Thủ tục hoàn thuế của hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử", "co_quan": "Thuế tỉnh, thành phố; Thuế cơ sở.", "trinh_tu": "Trường hợp hộ, cá nhân đã được tổ chức quản lý nền tảng thương mại điện tử thực hiện khấu trừ và nộp thuế thay số thuế giá trị gia tăng và thu nhập cá nhân đối với các giao dịch phát sinh trong năm nhưng có mức doanh thu năm của toàn bộ hoạt động kinh doanh thuộc đối tượng không chịu thuế giá trị gia tăng, thuế thu nhập cá nhân thì thực hiện thủ tục hoàn thuế theo quy định của pháp luật quản lý thuế đối với số thuế nộp thừa sau khi tổ chức quản lý nền tảng thương mại điện tử đã hoàn thành nghĩa vụ kê khai, nộp thuế thay số thuế đã khấu trừ của hộ, cá nhân có hoạt động kinh doanh trên các nền tảng thương mại điện tử của năm tính thuế.\nTrường hợp hộ, cá nhân đã nộp thuế giá trị gia tăng, thuế thu nhập cá nhân đối với các giao dịch phát sinh trong năm theo quy định tại Điều 8, Điều 9 Nghị định này nhưng có mức doanh thu năm của toàn bộ hoạt động kinh doanh thuộc đối tượng không chịu thuế giá trị gia tăng, thuế thu nhập cá nhân thì thực hiện thủ tục hoàn thuế theo quy định của pháp luật quản lý thuế đối với số thuế nộp thừa.", "cach_thuc": "Bằng phương thức điện tử qua Hệ thống thông tin giải quyết TTHC của cơ quan thuế /Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: ++ Văn bản đề nghị hoàn thuế của hộ, cá nhân có hoạt động kinh doanh trên nền tảng thương mại điện tử theo mẫu số 03/CNKD-TMĐT + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "+ Cổng thông tin điện tử của Cục Thuế gửi phản hồi tự động về việc tiếp nhận và xử lý hồ sơ hoàn thuế theo quy định.", "dieu_kien": "++ Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Điều 10 Nghị định số 117/2025/NĐ-CP ngày 09/6/2025 của Chính phủ quy định về quản lý thuế đối với hoạt động kinh doanh trên nền tảng thương mại điện tử, nền tảng số của hộ, cá nhân.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["03/CNKD-TMĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014033"}, {"ma": "1.008559", "ten": "Hoàn thuế GTGT đối với trường hợp được hưởng ưu đãi miễn trừ ngoại giao", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) được hưởng ưu đãi miễn trừ ngoại giao thuộc trường hợp và đối tượng được hoàn thuế GTGT chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Giấy đề nghị hoàn trả khoản thu ngân sách nhà nước theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n ++ Bảng kê thuế GTGT của hàng hoá, dịch vụ mua vào dùng cho cơ quan đại diện ngoại giao theo mẫu số 01-3a/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC có xác nhận của Cục Lễ tân nhà nước trực thuộc Bộ Ngoại giao về việc chi phí đầu vào thuộc diện áp dụng miễn trừ ngoại giao để được hoàn thuế. \n ++ Bảng kê viên chức ngoại giao thuộc đối tượng được hoàn thuế GTGT theo mẫu số 01-3b/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế mẫu số 01/QĐHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp NNT lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Thuế GTGT số 48/2024/QH15; \n + Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-3a/HT", "01-3b/HT", "01/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008559"}, {"ma": "1.011017", "ten": "Hoàn thuế tiêu thụ đặc biệt đối với xăng sinh học", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố.", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) thuộc trường hợp và đối tượng được hoàn thuế tiêu thụ đặc biệt đối với xăng sinh học chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Giấy đề nghị hoàn trả khoản thu ngân sách nhà nước theo mẫu số 01a/ĐNHT ban hành kèm theo Nghị định số 14/2019/NĐ-CP ngày 01/02/2019 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 108/2015/NĐ-CP ngày 28 tháng 10 năm 2015 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Luật thuế tiêu thụ đặc biệt và Luật sửa đổi, bổ sung một số điều của Luật thuế tiêu thụ đặc biệt (sau đây gọi là Nghị định số 14/2019/NĐ-CP). \n ++ Đối với NNT nộp hồ sơ lần đầu thì NNT phải nộp thêm: bản sao văn bản của cơ quan nhà nước có thẩm quyền về việc NNT được sản xuất xăng sinh học. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế mẫu số 01/QĐHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; \n + Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp NNT lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 14/2019/NĐ-CP ngày 01/02/2019 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 108/2015/NĐ-CP ngày 28 tháng 10 năm 2015 của Chính phủ quy định chi tiết và hướng dẫn thi hành một số điều của Luật thuế tiêu thụ đặc biệt và Luật sửa đổi, bổ sung một số điều của Luật thuế tiêu thụ đặc biệt. \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01a/ĐNHT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011017"}, {"ma": "1.011018", "ten": "Thủ tục Hoàn thuế giá trị gia tăng đối với ngân hàng thương mại là đại lý hoàn thuế giá trị gia tăng cho khách xuất cảnh", "cap_thuc_hien": "Cấp Tỉnh, thành phố", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Ngân hàng thương mại là đại lý hoàn thuế giá trị gia tăng (GTGT) cho khách xuất cảnh (sau đây gọi tắt là NNT) chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền))/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ: theo Danh mục mẫu biểu tại phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC, gồm: \n ++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT; \n ++ Bảng kê chứng từ hoàn thuế GTGT cho người nước ngoài xuất cảnh mẫu số 01-4/HT. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Thông báo về việc hồ sơ chưa đủ điều kiện hoàn thuế/không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC. \n + Quyết định về việc thanh toán cho ngân hàng thương mại số tiền đã ứng trước để hoàn trả thuế giá trị gia tăng cho người nước ngoài xuất cảnh và phí dịch vụ hoàn thuế ngân hàng thương mại được hưởng theo mẫu Phụ lục 7 ban hành kèm theo Thông tư số 92/2019/TT-BTC ngày 31/12/2019 của Bộ Tài chính.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vựng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 13/2008/QH12 ngày 03/6/2008 của Quốc hội; Luật Thuế giá trị gia tăng số 48/2024/QH15 ngày 26/11/2024 và các văn bản hướng dẫn thi hành; \n + Luật Quản lý thuế ngày 13/6/2019 của Quốc hội đã được sửa đổi, bổ sung tại Luật số 56/2024/QH15 ngày 29/11/2024 của Quốc hội sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 92/2019/TT-BTC ngày 31/12/2019 của Bộ Tài chính sửa đổi, bổ sung một số điều tại Thông tư số 72/2014/TT-BTC ngày 30 tháng 5 năm 2014 quy định về hoàn thuế giá trị gia tăng đối với hàng hoá của người nước ngoài, người Việt Nam định cư ở nước ngoài mang theo khi xuất cảnh. \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-4/HT", "01/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011018"}, {"ma": "1.011007", "ten": "Khai thuế thu nhập cá nhân đối với cá nhân nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu khi chuyển nhượng và tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân", "cap_thuc_hien": "Cấp Tỉnh, Thành phố, Cấp Xã", "doi_tuong": "Tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân có thu nhập; cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "- Bước 1:\n + Đối với khai thuế thu nhập cá nhân đối với tổ chức khai thay cho cá nhân có thu nhập từ đầu tư vốn do nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu: Tổ chức khai thuế thay, nộp thuế thay chuẩn bị hồ sơ khai thuế thu nhập cá nhân (TNCN) từ đầu tư vốn thay cho cá nhân khi cá nhân phát sinh chuyển nhượng chứng khoán cùng loại, chuyển nhượng vốn, rút vốn và lựa chọn kỳ khai thuế theo quy định. Nộp hồ sơ khai thuế tại cơ quan thuế quản lý trực tiếp tổ chức khai thay. Thời hạn nộp hồ sơ khai thuế theo từng lần phát sinh chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế; Thời hạn nộp hồ sơ khai thuế theo tháng chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế; Thời hạn nộp hồ sơ khai thuế theo quý chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế. \n + Đối với khai thuế thu nhập cá nhân đối với cá nhân nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu: Chậm nhất là ngày thứ 10 (mười) kể từ ngày chuyển nhượng vốn, rút vốn, chuyển nhượng chứng khoán cùng loại, cá nhân chuẩn bị hồ sơ khai thuế thu nhập cá nhân đối với thu nhập từ đầu tư vốn, gửi đến cơ quan thuế quản lý trực tiếp tổ chức phát hành chứng khoán hoặc tổ chức có vốn góp.\n - Bước 2: Cơ quan thuế thực hiện tiếp nhận:\n + Đối với khai thuế thu nhập cá nhân đối với tổ chức khai thay cho cá nhân có thu nhập từ đầu tư vốn do nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu\n Cơ quan quản lý thuế tiếp nhận hồ sơ khai thuế, thông báo về việc tiếp nhận hồ sơ khai thuế; trường hợp hồ sơ không hợp pháp, không đầy đủ, không đúng mẫu quy định thì thông báo cho người nộp thuế trong thời hạn 03 ngày làm việc kể từ ngày tiếp nhận hồ sơ.\n + Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n + Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n ++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Cục Thuế gửi thông báo tiếp nhận việc người nộp thuế (NNT) đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n ++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Cục Thuế/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.\n + Đối với khai thuế thu nhập cá nhân đối với cá nhân nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu:\n Cơ quan thuế thực hiện tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ(và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "- Tờ khai thuế thu nhập cá nhân (áp dụng đối với cá nhân nhận cổ tức bằng chứng khoán, lợi tức ghi tăng vốn, chứng khoán thưởng cho cổ đông hiện hữu khi chuyển nhượng và tổ chức, cá nhân khai thuế thay, nộp thuế thay cho cá nhân) mẫu số 04/ĐTV-TNCN tại Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC. \n - Phụ lục bảng kê chi tiết (áp dụng đối với tổ chức khai thuế thay, nộp thuế thay cho nhiều cá nhân) mẫu số 04-1/ĐTV-TNCN tại Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ và Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ Tài chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/06/2019; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế, Thông tư số 40/2025/TT-BTC ngày 13/ 6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp, Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["04-1/ĐTV-TNCN", "04/ĐTV-TNCN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011007"}, {"ma": "1.008339", "ten": "Khai thuế đối với hãng vận tải nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức.", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở", "trinh_tu": "+ Bước 1. Tổ chức làm đại lý tàu biển hoặc đại lý giao nhận vận chuyển hàng hóa cho các hãng vận tải nước ngoài (sau đây gọi chung là đại lý của hãng vận tải) có trách nhiệm khấu trừ và nộp thuế thay cho các hãng vận tải nước ngoài.\n Hồ sơ khai thuế đối với hãng vận tải nước ngoài được nộp cho cơ quan thuế quản lý trực tiếp bên đại lý của hãng vận tải.\n Khai thuế đối với hãng vận tải nước ngoài là tạm nộp theo quý và quyết toán theo năm.\n + Bước 2. Cơ quan thuế tiếp nhận:\n Cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định đối sơ hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính. Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai quyết toán thuế TNDN đối với hãng vận tải nước ngoài theo Mẫu số 01/VTNN ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế; \n ++ Bảng kê thu nhập vận tải quốc tế dành cho trường hợp doanh nghiệp khai thác tàu theo mẫu số 01-1/VTNN, Bảng kê thu nhập vận tải quốc tế dành cho trường hợp hoán đổi/chia chỗ theo mẫu số 01-2/VTNN, Bảng kê doanh thu lưu công-ten-nơ theo mẫu số 01-3/VTNN do Bộ Tài chính ban hành. \n (Thành phần hồ sơ ban hành kèm theo Phụ lục 1 Danh mục hồ sơ khai thuế Nghị định số 126/2020/NĐ-CP quy định chi tiết một số điều của Luật quản lý thuế số 38/2019/QH14) \n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Hồ sơ gửi đến Cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC của 09/07/2025 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019; Luật số sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024 \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/VTNN", "01-2/VTNN", "01-3/VTNN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008339"}, {"ma": "1.008562", "ten": "Hoàn thuế TNCN đối với tổ chức, cá nhân trả thu nhập từ tiền lương, tiền công thực hiện quyết toán cho các cá nhân có ủy quyền quyết toán thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân trả thu nhập từ tiền lương, tiền công thực hiện quyết toán thuế, hoàn thuế thay cho các cá nhân ủy quyền.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân trả thu nhập từ tiền lương, tiền công thực hiện quyết toán cho các cá nhân có ủy quyền sau khi bù trừ số thuế nộp thừa, nộp thiếu của các cá nhân mà có số thuế nộp thừa, nếu đề nghị cơ quan thuế hoàn trả thì tổ chức, cá nhân trả thu nhập chuẩn bị hồ sơ hoàn thuế.\n + Bước 2.\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ(và trả kết quả nếu có kết quả) thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Văn bản đề nghị xử lý số tiền thuế, tiền chậm nộp, tiền phạt nộp thừa mẫu số 01/DNXLNT theo Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021/TT-BTC của Bộ trưởng Bộ Tài chính; \n ++ Văn bản ủy quyền theo quy định của pháp luật trong trường hợp người nộp thuế không trực tiếp thực hiện thủ tục hoàn thuế, trừ trường hợp đại lý thuế nộp hồ sơ hoàn thuế theo hợp đồng đã ký giữa đại lý thuế và người nộp thuế; \n ++ Bảng kê chứng từ nộp thuế mẫu số 02-1/HT theo Phụ lục II - Mẫu biểu hồ sơ khai thuế ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài Chính. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Quyết định hoàn thuế theo mẫu 01/QĐHT hoặc Quyết định hoàn thuế kiêm bù trừ thu NSNN theo mẫu số 02/QĐHT hoặc Thông báo về việc không được hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Thông tư số 80/2021/TT-BTC", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tửtại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Nghị định số 126/2020/NĐ - CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế số 38/2019/QH14; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/DNXLNT", "02-1/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008562"}, {"ma": "1.014406", "ten": "Đăng ký/thay đổi thông tin đăng ký thuế đối với đơn vị hợp thành chịu trách nhiệm kê khai theo quy định về thuế tối thiểu toàn cầu", "cap_thuc_hien": "Cục thuế", "doi_tuong": "+ Đơn vị hợp thành được chỉ định chịu trách nhiệm kê khai của tập đoàn đa quốc gia; + Liên doanh không phải thành viên của tập đoàn liên doanh áp dụng quy định QDMTT;\n + Công ty được chỉ định chịu trách nhiệm kê khai của tập đoàn liên doanh áp dụng quy định QDMTT;\n + Đơn vị hợp thành được chỉ định chịu trách nhiệm kê khai của tập đoàn con có công ty mẹ tối cao là chủ sở hữu thiểu số áp dụng quy định QDMTT;\n + Đơn vị hợp thành có công ty mẹ tối cao là chủ sở hữu thiểu số không phải là thành viên của tập đoàn", "co_quan": "Chi cục Thuế Doanh nghiệp lớn.", "trinh_tu": "+ Đăng ký thuế lần đầu: Đối tượng đăng ký thuế theo quy định tại khoản 1 Điều 15 Nghị định số 236/2025/NĐ-CP nộp hồ sơ đăng ký thuế theo đúng quy định chậm nhất sau 90 ngày kể từ ngày kết thúc năm tài chính báo cáo. Đối tượng đăng ký thuế được cấp mã số thuế 10 chữ số để trực tiếp kê khai và nộp thuế thu nhập doanh nghiệp bổ sung theo Quy định về thuế tối thiểu toàn cầu.\n + Thay đổi thông tin đăng ký thuế: \n ++ Trường hợp Tập đoàn đa quốc gia thay đổi thông tin về tập đoàn trên Tờ khai đăng ký/thay đổi thông tin đăng ký thuế thì đơn vị hợp thành chịu trách nhiệm kê khai có trách nhiệm nộp hồ sơ thay đổi thông tin đăng ký thuế tới cơ quan thuế trong thời hạn 10 ngày làm việc kể từ ngày phát sinh thông tin thay đổi.\n ++ Trường hợp tập đoàn đa quốc gia thay đổi đơn vị hợp thành chịu trách nhiệm kê khai tại Việt Nam thì đơn vị hợp thành chịu trách nhiệm kê khai mới có trách nhiệm nộp hồ sơ thay đổi thông tin đăng ký thuế tới cơ quan thuế trong thời hạn 10 ngày làm việc kể từ ngày phát sinh thông tin thay đổi.", "cach_thuc": "Nộp hồ sơ điện tử qua cổng giao dịch điện tử.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: Tờ khai đăng ký/thay đổi thông tin đăng ký thuế theo Mẫu số 01-ĐKTĐ-ĐVHT ban hành kèm theo Nghị định số 236/2025/NĐ-CP.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Thông báo mã số thuế theo Mẫu số 01-MST-ĐVHT ban hành kèm theo Nghị định số 236/2025/NĐ-CP.", "dieu_kien": "Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Nghị quyết 107/2023/QH15 ngày 29/11/2023 của Quốc hội về áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 236/2025/NĐ-CP ngày 29/8/2025 của Chính phủ quy định chi tiết một số điều của Nghị quyết số 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội về việc áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014406"}, {"ma": "1.011520", "ten": "Khai, nộp vào ngân sách nhà nước tiền thu từ chuyển đổi sở hữu doanh nghiệp, đơn vị sự nghiệp công lập, nguồn thu từ chuyển nhượng vốn nhà nước và chênh lệch vốn chủ sở hữu lớn hơn vốn điều lệ tại doanh nghiệp", "cap_thuc_hien": null, "doi_tuong": "Doanh nghiệp, đơn vị sự nghiệp công lập và các đối tượng có trách nhiệm khai, nộp các khoản thu vào ngân sách nhà nước.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Doanh nghiệp, đơn vị sự nghiệp công lập và các đối tượng có trách nhiệm khai, nộp xác định số tiền thu từ chuyển đổi sở hữu doanh nghiệp, đơn vị sự nghiệp công lập, nguồn thu từ chuyển nhượng vốn nhà nước và chênh lệch vốn chủ sở hữu lớn hơn vốn điều lệ tại doanh nghiệp. \n + Trong thời hạn theo quy định tại Điều 7 Thông tư số 57/2022/TT-BTC, doanh nghiệp, đơn vị sự nghiệp công lập và các đối tượng có trách nhiệm khai, nộp các khoản thu vào ngân sách nhà nước thực hiện khai và nộp theo quy định tại Điều 6 Thông tư số 57/2022/TT-BTC, cụ thể:\n ++ Thu từ cổ phần hóa doanh nghiệp, đơn vị sự nghiệp công lập:\n +++ Tiền thu từ bán đấu giá công khai ra công chúng: Trong thời hạn năm (05) ngày làm việc kể từ ngày hết hạn nộp tiền của nhà đầu tư tham gia cuộc đấu giá, Tổ chức thực hiện bán đấu giá có trách nhiệm khai, nộp số tiền thu từ bán cổ phần.\n +++Tiền thu từ bán đấu giá giữa các nhà đầu tư chiến lược: Trong thời hạn năm (05) ngày làm việc kể từ ngày hết hạn nộp tiền của nhà đầu tư tham gia cuộc đấu giá, doanh nghiệp, đơn vị sự nghiệp công lập có trách nhiệm khai, nộp số tiền thu từ bán cổ phần.\n +++ Tiền thu từ bảo lãnh phát hành: Trong thời hạn mười (10) ngày kể từ ngày hoàn tất việc mua bán cổ phần theo hợp đồng bảo lãnh, tổ chức bảo lãnh phát hành có trách nhiệm khai, nộp số tiền thu từ bán cổ phần.\n +++ Tiền thu từ bán thỏa thuận cho các nhà đầu tư, bán cổ phần ưu đãi cho tổ chức công đoàn, người lao động và người quản lý doanh nghiệp: Trong thời hạn năm (05) ngày làm việc kể từ ngày hết hạn nộp tiền, doanh nghiệp, đơn vị sự nghiệp công lập khai, nộp tiền thu từ bán cổ phần.\n +++ Tiền thu từ bán cổ phần của doanh nghiệp cổ phần hóa theo phương thức dựng sổ: Trong thời hạn năm (05) ngày làm việc kể từ ngày hết hạn thanh toán tiền mua cổ phần của nhà đầu tư, tổ chức quản lý sổ lệnh có trách nhiệm khai, nộp số tiền thu từ bán cổ phần. \n +++ Tiền thu từ cổ phần hóa tại thời điểm chính thức chuyển thành công ty cổ phần: \n Trong thời hạn chín mươi (90) ngày kể từ ngày được cấp Giấy chứng nhận đăng ký doanh nghiệp lần đầu, công ty cổ phần được chuyển đổi từ doanh nghiệp, đơn vị sự nghiệp công lập cổ phần hóa có trách nhiệm tự xác định số tiền thu từ cổ phần hóa phải nộp ngân sách nhà nước và thực hiện khai, nộp.\n Trong thời hạn năm (05) ngày làm việc kể từ ngày có quyết định của cơ quan đại diện chủ sở hữu phê duyệt quyết toán tiền thu từ cổ phần hóa tại thời điểm chính thức chuyển thành công ty cổ phần, công ty cổ phần được chuyển đổi từ doanh nghiệp, đơn vị sự nghiệp công lập cổ phần hóa có trách nhiệm khai, nộp khoản chênh lệch tăng thêm so với số đã nộp (nếu có).\n +++ Các khoản thu khác:\n Trong thời hạn ba mươi (30) ngày kể từ ngày hết thời hạn bảo hành theo hợp đồng doanh nghiệp cổ phần hóa có trách nhiệm khai, nộp toàn bộ số dư dự phòng bảo hành sản phẩm, hàng hóa, công trình xây dựng (đối với các hợp đồng đã ký, thời gian bảo hành còn hiệu lực sau ngày được cấp Giấy chứng nhận đăng ký doanh nghiệp lần đầu) không chi hết.\n Trong thời hạn mười (10) ngày làm việc kể từ ngày nhận được tiền thu từ thu hồi, xử lý nợ và tài sản, DATC có trách nhiệm khai, nộp các khoản phải nộp. Trường hợp số tiền phải nộp dưới 100 triệu đồng theo từng lần phát sinh, DATC tập hợp và nộp theo tháng trong 05 ngày làm việc kể từ ngày kết thúc tháng liền kề trước đó.\n Trong thời hạn mười (10) ngày làm việc kể từ ngày thu hồi được nợ, các ngân hàng thương mại và doanh nghiệp hoạt động trong lĩnh vực viễn thông có trách nhiệm khai, nộp vào ngân sách nhà nước số phải nộp từ khoản công nợ không tính vào giá trị doanh nghiệp cổ phần hóa thu hồi được.\n ++ Thu từ chuyển nhượng vốn nhà nước đầu tư tại công ty cổ phần, công ty trách nhiệm hữu hạn hai thành viên trở lên, thu từ chuyển nhượng quyền mua cổ phần phát hành thêm đối với phần vốn nhà nước và quyền góp vốn nhà nước tại doanh nghiệp:\n +++ Thu từ chuyển nhượng vốn nhà nước đầu tư tại công ty cổ phần, công ty trách nhiệm hữu hạn hai thành viên trở lên:\n Trong thời hạn mười lăm (15) ngày kể từ ngày công bố kết quả cuộc đấu giá công khai/chào bán cạnh tranh hoặc ký hợp đồng chuyển nhượng vốn (đối với phương thức thỏa thuận), cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) chịu trách nhiệm khai, nộp tiền thu từ chuyển nhượng vốn nhà nước.\n Trong thời hạn mười (10) ngày làm việc kể từ ngày thực hiện giao dịch chuyển nhượng vốn tại các doanh nghiệp đã đăng ký giao dịch, niêm yết trên Sở giao dịch chứng khoán, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) chịu trách nhiệm khai, nộp tiền thu từ chuyển nhượng vốn nhà nước.\n Trong thời hạn mười (10) ngày làm việc kể từ ngày nhận được tiền của Tổ chức quản lý sổ lệnh, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) chịu trách nhiệm khai, nộp tiền thu từ chuyển nhượng vốn.\n Trường hợp sau khi phê duyệt quyết toán tiền thu từ chuyển nhượng vốn phát sinh tăng thêm số phải nộp ngân sách nhà nước thì trong thời hạn mười (10) ngày làm việc kể từ ngày có quyết định phê duyệt quyết toán tiền thu từ chuyển nhượng vốn, cơ quan đại diện chủ sở hữu có trách nhiệm khai, nộp khoản chênh lệch tăng thêm so với số đã nộp.\n +++ Thu chuyển nhượng quyền mua cổ phần phát hành thêm đối với phần vốn nhà nước và quyền góp vốn nhà nước tại doanh nghiệp:\n Trong mười (10) ngày làm việc kể từ ngày hết hạn nộp tiền của nhà đầu tư, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) chịu trách nhiệm khai, nộp tiền thu từ chuyển nhượng quyền mua cổ phần phát hành thêm đối với phần vốn nhà nước và quyền góp vốn nhà nước tại doanh nghiệp.\n Trong thời hạn mười (10) ngày làm việc kể từ ngày có quyết định phê duyệt quyết toán đối với tiền thu từ chuyển nhượng quyền mua cổ phần phát hành thêm đối với phần vốn nhà nước và quyền góp vốn nhà nước tại doanh nghiệp, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) có trách nhiệm khai, nộp khoản chênh lệch tăng thêm so với số đã nộp (nếu có).\n ++ Thu từ chuyển nhượng vốn nhà nước đầu tư tại các doanh nghiệp được Thủ tướng Chính phủ giao SCIC thực hiện chuyển nhượng vốn để nộp vào ngân sách nhà nước:\n Trong thời hạn mười (10) ngày làm việc kể từ ngày hết hạn nộp tiền của nhà đầu tư, SCIC có trách nhiệm khai, nộp ngân sách nhà nước số tiền thu từ chuyển nhượng vốn nhà nước do SCIC thực hiện.\n ++ Thu từ chênh lệch vốn chủ sở hữu lớn hơn vốn điều lệ tại doanh nghiệp cấp 1 đang hoạt động:\n Trong thời hạn mười (10) ngày kể từ ngày cơ quan đại diện chủ sở hữu ban hành quyết định về việc nộp phần chênh lệch giữa vốn chủ sở hữu với vốn điều lệ của doanh nghiệp vào ngân sách nhà nước, doanh nghiệp có trách nhiệm khai, nộp.\n ++ Thu từ các hình thức sắp xếp, chuyển đổi sở hữu khác:\n +++ Bán doanh nghiệp: Trong thời hạn mười (10) ngày làm việc kể từ ngày cơ quan đại diện chủ sở hữu phê duyệt quyết toán tiền thu từ bán toàn bộ doanh nghiệp, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) có trách nhiệm khai, nộp toàn bộ tiền thu từ bán doanh nghiệp sau khi trừ các chi phí.\n +++ Chuyển doanh nghiệp do Nhà nước nắm giữ 100% vốn điều lệ thành công ty trách nhiệm hữu hạn hai thành viên trở lên: Trong thời hạn mười (10) ngày làm việc kể từ ngày cơ quan có thẩm quyền phê duyệt quyết toán số tiền thu từ chuyển đổi doanh nghiệp tại thời điểm điểm công ty trách nhiệm hữu hạn hai thành viên trở lên được cấp Giấy chứng nhận đăng ký doanh nghiệp lần đầu, cơ quan đại diện chủ sở hữu (hoặc đơn vị được ủy quyền) có trách nhiệm khai, nộp số tiền thu từ chuyển đổi doanh nghiệp sau khi trừ các chi phí.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n Tờ khai số thu theo mẫu tờ khai quy định tại Điều 7 Thông tư số 57/2022/TT-BTC. \n + Số lượng hồ sơ: 01 bộ.", "ket_qua": "Không.", "dieu_kien": "Không.", "can_cu_phap_ly": "+ Nghị định số 148/2021/NĐ-CP ngày 31/12/2021 của Chính phủ; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 57/2022/TT-BTC ngày 16/9/2022 của Bộ Tài chính.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011520"}, {"ma": "1.008513", "ten": "Gia hạn nộp hồ sơ khai thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế không có khả năng nộp hồ sơ khai thuế đúng hạn do thiên tai, thảm họa, dịch bệnh, hỏa hoạn, tai nạn bất ngờ phải gửi đến cơ quan thuế văn bản đề nghị gia hạn nộp hồ sơ khai thuế trước khi hết thời hạn nộp hồ sơ khai thuế, trong đó nêu rõ lý do đề nghị gia hạn có xác nhận của Ủy ban nhân dân cấp xã hoặc Công an xã, phường, thị trấn nơi phát sinh trường hợp được gia hạn theo quy định tại Điều 46 Luật Quản lý thuế năm 2019.\n ++ Trường hợp NNT nộp hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính để lập hồ sơ điện tử, ký điện tử và gửi đến cơ quan thuế.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp/qua bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh/Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n +++ Kiểm tra, chấp nhận hồ sơ: Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp/qua bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: Văn bản đề nghị gia hạn nộp hồ sơ khai thuế theo quy định tại khoản 3 Điều 46 Luật Quản lý thuế năm 2019. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Văn bản trả lời của cơ quan thuế gửi cho người nộp thuế về việc chấp nhận hay không chấp nhận việc gia hạn nộp hồ sơ khai thuế.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ trưởng Bộ Tài chính) hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008513"}, {"ma": "1.008558", "ten": "Hoàn thuế GTGT đối với các chương trình, dự án sử dụng nguồn vốn viện trợ không hoàn lại", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức.", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Người nộp thuế (NNT) thuộc trường hợp và đối tượng được Hoàn thuế GTGT đối với hàng hóa, dịch vụ mua trong nước bằng nguồn tiền viện trợ không hoàn lại không thuộc hỗ trợ phát triển chính chuẩn bị hồ sơ đề nghị hoàn và gửi đến cơ quan thuế.\n Trường hợp NNT gửi hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng thông tin điện tử mà NNT lựa chọn (Cổng thông tin điện tử của Tổng Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Tổng Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ hoàn thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế: \n +++ Tiếp nhận hồ sơ: công chức thuế tiếp nhận hồ sơ và gửi Thông báo về việc tiếp nhận hồ sơ theo mẫu số 01/TB-HT ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC) cho NNT và ghi sổ nhận hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính: \n +++ Tiếp nhận hồ sơ: công chức thuế đóng dấu tiếp nhận, ghi ngày nhận hồ sơ và ghi sổ hồ sơ trên hệ thống ứng dụng quản lý thuế.\n +++ Kiểm tra, giải quyết hồ sơ:\n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đề nghị hoàn thuế theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ không đúng thủ tục: Cơ quan thuế gửi Thông báo về việc hồ sơ không đúng thủ tục theo mẫu số 03/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC trong thời hạn 03 (ba) ngày làm việc kể từ ngày tiếp nhận hồ sơ đề nghị hoàn thuế.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ hoàn thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Tổng Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ đề nghị hoàn thuế theo mẫu số 01/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC cho NNT qua Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ đề nghị hoàn thuế của NNT.\n +++ Kiểm tra, giải quyết hồ sơ: \n ++++ Hồ sơ được chấp nhận/không chấp nhận: Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ theo mẫu số 02/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) trong thời hạn 03 (ba) ngày làm việc kể từ ngày thông báo tiếp nhận hồ sơ hoàn thuế điện tử.\n ++++ Hồ sơ được chấp nhận giải quyết: Cơ quan thuế giải quyết hồ sơ đề nghị hoàn thuế của NNT và trả kết quả theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n+Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "1. Hoàn thuế GTGT đối với hàng hóa, dịch vụ mua trong nước bằng nguồn tiền viện trợ không hoàn lại không thuộc hỗ trợ phát triển chính thức\n + Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n + Bản sao Lệnh ghi thu, ghi chi ngân sách nhà nước đối với hàng hóa, dịch vụ mua trong nước đối với dự án, phi dự án chi thường xuyên hoặc giấy đề nghị thanh toán vốn (trường hợp tiếp nhận vốn viện trợ bằng tiền thuộc nguồn thu ngân sách nhà nước bố trí từ nguồn kế hoạch đầu tư công) theo quy định tại điểm b khoản 2 Điều 24 Nghị định số 313/2025/NĐ-CP ngày 8/12/2025 của Chính phủ;\n + Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: Bản sao Quyết định phê duyệt dự án, phi dự án hoặc Quyết định đầu tư kèm theo văn kiện dự án, phi dự án theo quy định tại điểm a khoản 2 Điều 24 Nghị định số 313/2025/NĐ-CP ngày 8/12/2025 của Chính phủ;\n 2. Hoàn thuế GTGT đối với chương trình, dự án sử dụng vốn hỗ trợ phát triển chính thức (ODA) không hoàn lại \n + Trường hợp vốn ODA không hoàn lại do chủ chương trình, dự án trực tiếp quản lý, thực hiện:\n ++ Trường hợp chủ chương trình, dự án trực tiếp quản lý, thực hiện chương trình, dự án và đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC ;\n +++ Giấy đề nghị xác nhận chi phí hợp lệ vốn sự nghiệp và giấy đề nghị thanh toán vốn đầu tư của chủ dự án theo quy định của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước theo quy định. \n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: \n +++ Bản sao Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n +++ Bản sao văn bản xác nhận của cơ quan chủ quản chương trình, dự án ODA cho chủ chương trình, dự án về hình thức cung cấp chương trình, dự án ODA là ODA không hoàn lại thuộc đối tượng được hoàn thuế giá trị gia tăng và việc không được ngân sách nhà nước cấp vốn đối ứng để trả thuế giá trị gia tăng.\n ++ Trường hợp đơn vị, tổ chức được chủ chương trình, dự án giao một phần hoặc toàn bộ chương trình, dự án để quản lý, thực hiện chương trình, dự án đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n +++ Giấy đề nghị xác nhận chi phí hợp lệ vốn sự nghiệp và giấy đề nghị thanh toán vốn đầu tư của chủ dự án theo quy định của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước theo quy định tại điểm d khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ.\n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: \n +++ Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n +++ Bản sao văn bản xác nhận của cơ quan chủ quản chương trình, dự án ODA cho chủ chương trình, dự án về hình thức cung cấp chương trình, dự án ODA là ODA không hoàn lại thuộc đối tượng được hoàn thuế giá trị gia tăng và việc không được ngân sách nhà nước cấp vốn đối ứng để trả thuế giá trị gia tăng.\n +++ Bản sao văn bản về việc giao quản lý, thực hiện chương trình, dự án ODA của chủ chương trình, dự án cho đơn vị, tổ chức đề nghị hoàn thuế (trường hợp việc giao quản lý, thực hiện của chủ chương trình, dự án chưa được nêu tại một trong các tài liệu sau: Bản sao Điều ước quốc tế hoặc thỏa thuận vốn ODA không hoàn lại hoặc văn bản trao đổi về việc cam kết và tiếp nhận vốn ODA không hoàn lại; bản sao Quyết định phê duyệt Văn kiện dự án, phi dự án hoặc Quyết định đầu tư chương trình và Văn kiện dự án hoặc Báo cáo nghiên cứu khả thi được phê duyệt; bản sao văn bản xác nhận của cơ quan chủ quản chương trình, dự án ODA cho chủ chương trình, dự án về hình thức cung cấp chương trình, dự án ODA là ODA không hoàn lại thuộc đối tượng được hoàn thuế giá trị gia tăng và việc không được ngân sách nhà nước cấp vốn đối ứng để trả thuế giá trị gia tăng).\n ++ Trường hợp nhà thầu chính thực hiện chương trình, dự án lập hồ sơ đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n +++ Giấy đề nghị xác nhận chi phí hợp lệ vốn sự nghiệp và giấy đề nghị thanh toán vốn đầu tư của chủ dự án theo quy định của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước theo quy định. \n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: \n +++ Bản sao Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n +++ Bản sao văn bản xác nhận của cơ quan chủ quản chương trình, dự án ODA cho chủ chương trình, dự án về hình thức cung cấp chương trình, dự án ODA là ODA không hoàn lại thuộc đối tượng được hoàn thuế giá trị gia tăng và việc không được ngân sách nhà nước cấp vốn đối ứng để trả thuế giá trị gia tăng.\n +++ Bản sao hợp đồng ký kết giữa chủ dự án với nhà thầu chính thể hiện giá thanh toán theo kết quả thầu không bao gồm thuế giá trị gia tăng. \n + Trường hợp vốn ODA không hoàn lại do nhà tài trợ trực tiếp quản lý, thực hiện:\n ++ Trường hợp nhà tài trợ trực tiếp quản lý, thực hiện chương trình, dự án và đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: Bản sao Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n ++ Trường hợp Văn phòng đại diện của nhà tài trợ hoặc tổ chức do nhà tài trợ chỉ định quản lý, thực hiện chương trình, dự án (trừ trường hợp tổ chức là nhà thầu chính) đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm:\n +++ Bản sao Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n +++ Bản sao văn bản về việc giao quản lý, thực hiện chương trình, dự án ODA của nhà tài trợ cho Văn phòng đại diện của nhà tài trợ hoặc tổ chức do nhà tài trợ chỉ định (trường hợp việc giao quản lý, thực hiện chương trình, dự án chưa được nêu tại một trong các tài liệu sau: Bản sao Điều ước quốc tế hoặc thỏa thuận vốn ODA không hoàn lại hoặc văn bản trao đổi về việc cam kết và tiếp nhận vốn ODA không hoàn lại; bản sao Quyết định phê duyệt Văn kiện dự án, phi dự án hoặc Quyết định đầu tư chương trình và Văn kiện dự án hoặc Báo cáo nghiên cứu khả thi được phê duyệt). \n +++ Bản sao văn bản của cơ quan có thẩm quyền về việc thành lập Văn phòng đại diện của nhà tài trợ, tổ chức do nhà tài trợ chỉ định.\n ++ Trường hợp nhà thầu chính thực hiện chương trình, dự án lập hồ sơ đề nghị hoàn thuế:\n +++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n +++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm:\n +++ Bản sao Điều ước quốc tế cụ thể hoặc thỏa thuận cụ thể về vốn ODA không hoàn lại hoặc văn bản trao đổi về dự án ODA không hoàn lại (thư cam kết, ý định thư, biên bản thảo luận, biên bản ghi nhớ,...) của nhà tài trợ nước ngoài: 01 bản chụp theo quy định tại điểm a khoản 2 Điều 90 Nghị định số 242/2025/NĐ-CP ngày 10/9/2025 của Chính phủ;\n +++ Bản sao hợp đồng hợp đồng ký kết giữa nhà tài trợ với nhà thầu chính hoặc bản tóm tắt hợp đồng có xác nhận của nhà tài trợ về hợp đồng ký kết giữa nhà tài trợ với nhà thầu chính bao gồm các thông tin: số hợp đồng, ngày ký kết hợp đồng, thời hạn hợp đồng, phạm vi công việc, giá trị hợp đồng, phương thức thanh toán, giá thanh toán theo kết quả thầu không bao gồm thuế giá trị gia tăng.\n 3. Hoàn thuế giá trị gia tăng đối với hàng hóa, dịch vụ mua trong nước bằng nguồn tiền viện trợ quốc tế khẩn cấp để cứu trợ và khắc phục hậu quả thiên tai tại Việt Nam\n ++ Giấy đề nghị hoàn trả khoản thu NSNN theo mẫu số 01/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC;\n ++ Bảng kê hoá đơn, chứng từ hàng hoá, dịch vụ mua vào mẫu số 01-1/HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.\n ++ Đối với hồ sơ đề nghị hoàn thuế lần đầu hoặc khi các tài liệu sau có thay đổi, bổ sung thì NNT phải nộp thêm: Bản sao Quyết định tiếp nhận viện trợ khẩn cấp để cứu trợ (trường hợp viện trợ quốc tế khẩn cấp để cứu trợ) hoặc Quyết định chủ trương tiếp nhận viện trợ quốc tế khẩn cấp để khắc phục hậu quả thiên tai và văn kiện viện trợ quốc tế khẩn cấp để khắc phục hậu quả thiên tai (trường hợp viện trợ quốc tế khẩn cấp để khắc phục hậu quả thiên tai) theo quy định tại khoản 6, 7, 8 Điều 3 Nghị định số 50/2020/NĐ-CP ngày 20/4/2020 của Chính phủ.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Thông báo về việc không được hoàn thuế theo mẫu số 04/TB-HT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; + Quyết định hoàn thuế mẫu số 01/QĐHT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC; + Quyết định hoàn thuế kiêm bù trừ thu ngân sách nhà nước mẫu số 02/QĐHT và Phụ lục số tiền thuế, tiền chậm nộp, tiền phạt phải nộp được bù trừ theo mẫu số 01/PL-BT ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp NNT lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội;\n+ Nghị định số 313/2025/NĐ-CP ngày 8/12/2025 của Chính phủ quản lý và sử dụng viện trợ không hoàn lại không thuộc hỗ trợ phát triển chính thức của cơ quan, tổ chức, cá nhân nước ngoài dành cho Việt Nam;\n+ Nghị định 242/2025/NĐ-CP ngày 10/9/2 quản lý và sử dụng vốn hỗ trợ phát triển chính thức (ODA) và vốn vay ưu đãi nước ngoài\n+ Nghị định số 50/2020/NĐ-CP ngày 20/4/2020 của Chính phủ quy định về tiếp nhận, quản lý và sử dụng viện trợ quốc tế khẩn cấp để cứu trợ và khắc phục hậu quả thiên tai;\n+ Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/HT", "01/HT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008558"}, {"ma": "1.010761", "ten": "Đề nghị kết nối để phối hợp thu nộp ngân sách nhà nước (NSNN)/Thay đổi, bổ sung thông tin kết nối/Ngừng kết nối", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "+ Các tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế đáp ứng các tiêu chuẩn kỹ thuật theo công khai của Cục Thuế;\n + Các ngân hàng và tổ chức cung ứng dịch vụ trung gian thanh toán tại khoản 4 Điều 2 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính đáp ứng các tiêu chuẩn kỹ thuật theo công khai của Cục Thuế.", "co_quan": "Cục Thuế.", "trinh_tu": "+ Bước 1.\n a) Các ngân hàng và tổ chức cung ứng dịch vụ trung gian thanh toán tại khoản 4 Điều 2 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính lập văn bản đề nghị kết nối (kèm theo các hồ sơ, tài liệu chứng minh hệ thống đáp ứng tiêu chuẩn kết nối)/Thay đổi, bổ sung thông tin kết nối/Ngừng kết nối và gửi đến Cục Thuế.\n b) Các tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế đáp ứng các tiêu chuẩn kỹ thuật theo công khai của Cục Thuế lập văn bản đề nghị kết nối (kèm theo các hồ sơ, tài liệu chứng minh) và gửi đến Cục Thuế. Thời hạn nộp hồ sơ:\n ++ Chậm nhất là 10 ngày làm việc kể từ ngày phát sinh thay đổi, bổ sung thông tin liên quan đến thỏa thuận đã ký với Cục Thuế (đối với trường hợp thay đổi, bổ sung thông tin liên quan đến thỏa thuận đã ký với ngân hàng và tổ chức cung ứng dịch vụ trung gian thanh toán);\n ++ Trước thời hạn đề nghị ngừng/tạm ngừng cung cấp dịch vụ 30 ngày, tổ chức tham gia kết nối (ngân hàng hoặc tổ chức cung ứng dịch vụ trung gian thanh toán) phải trao đổi và thống nhất với Cục Thuế bằng văn bản (đối với trường hợp tạm ngừng/ngừng cung cấp dịch vụ).\n + Bước 2. Cục Thuế thực hiện tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế, công chức thuế tiếp nhận và đóng dấu tiếp nhận hồ sơ, ghi thời gian nhận hồ sơ, ghi nhận số lượng tài liệu trong hồ sơ và ghi vào sổ văn thư của cơ quan thuế;\n ++ Trường hợp hồ sơ được gửi qua đường bưu chính, công chức thuế đóng dấu ghi ngày nhận hồ sơ và ghi vào sổ văn thư của cơ quan thuế;\n ++ Trường hợp hồ sơ gửi qua Cổng thông tin điện tử của Cục Thuế thì Cổng thông tin điện tử của Cục Thuế tiếp nhận hồ sơ.", "cach_thuc": "+ Trực tiếp: tại Trung tâm Phục vụ hành chính công cấp tỉnh, xã. + Bưu chính: Qua dịch vụ bưu chính. + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n (i) Đối với ngân hàng hoặc tổ chức cung ứng dịch vụ trung gian thanh toán:\n a) Trường hợp (1) Đề nghị kết nối để phối hợp thu nộp NSNN của ngân hàng hoặc tổ chức cung ứng dịch vụ trung gian thanh toán với cơ quan thuế:\n ++ Văn bản đề nghị kết nối với Cổng thông tin điện tử của Cục Thuế theo mẫu số 01/KNNT-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính;\n ++ Hồ sơ, tài liệu chứng minh (nếu có) về việc đáp ứng các tiêu chuẩn kỹ thuật theo công khai của Cục Thuế.\n b) Trường hợp (2) Thay đổi, bổ sung thông tin kết nối đã ký thỏa thuận với ngân hàng hoặc tổ chức cung ứng dịch vụ trung gian thanh toán:\n ++ Văn bản đề nghị thay đổi, bổ sung thông tin liên quan đến thông tin kết nối đã cung cấp theo mẫu số 01/KNNT-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính;\n ++ Các tài liệu kèm theo.\n c) Trường hợp (3) Tạm ngừng/ngừng kết nối với Cổng thông tin điện tử của Cục Thuế: Văn bản tạm ngừng cung cấp dịch vụ hoặc Văn bản ngừng cung cấp dịch vụ.\n (ii) Đối với tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế:\n a) Trường hợp (1) Đề nghị kết nối để phối hợp thu nộp NSNN của tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế:\n ++ Văn bản đề nghị kết nối với Cổng thông tin điện tử của Cục Thuế mẫu số 01/KNNT-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính;\n ++ Hồ sơ, tài liệu chứng minh (nếu có) về việc đáp ứng các tiêu chuẩn kỹ thuật theo yêu cầu của Cục Thuế.\n b) Trường hợp (2) Tạm ngừng/chấm dứt kết nối với Cổng thông tin điện tử của Cục Thuế:\n ++ Trường hợp tạm ngừng: là văn bản tạm dừng hợp đồng ủy nhiệm thu theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành;\n ++ Trường hợp chấm dứt kết nối: không quy định (thực hiện khi đã hết hạn hợp đồng ủy nhiệm thu và không gia hạn hợp đồng đó hoặc ký mới hợp đồng).\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "(i) Đối với ngân hàng hoặc tổ chức cung ứng dịch vụ trung gian thanh toán: \n a) Trường hợp (1): \n + Thông báo về việc hồ sơ đề nghị kết nối với Cổng thông tin điện tử của Cục Thuế đảm bảo/không đảm bảo kết nối với Cổng thông tin điện tử của Cục Thuế; hoặc yêu cầu bổ sung thông tin theo mẫu 01/TBKN-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính; \n + Văn bản thỏa thuận kết nối giữa ngân hàng hoặc tổ chức cung cấp dịch vụ trung gian thanh toán và Cục Thuế. \n b) Trường hợp (2): Văn bản thỏa thuận bổ sung thống nhất giữa ngân hàng hoặc tổ chức cung cấp dịch vụ trung gian thanh toán và Cục Thuế. \n c) Trường hợp (3): Văn bản chấm dứt thỏa thuận kết nối với ngân hàng hoặc tổ chức cung cấp dịch vụ trung gian thanh toán. \n (ii) Đối với tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế: \n a) Trường hợp (1): \n + Thông báo về việc hồ sơ đề nghị kết nối với Cổng thông tin điện tử của Cục Thuế đảm bảo/không đảm bảo kết nối với Cổng thông tin điện tử của Cục Thuế; hoặc yêu cầu bổ sung thông tin theo mẫu 01/TBKN-TĐT ban hành kèm theo Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính; \n + Văn bản thỏa thuận về việc truyền nhận, sử dụng dữ liệu giữa tổ chức ủy nhiệm thu và Cục Thuế. \n b) Trường hợp (2): Không quy định.", "dieu_kien": "Các tổ chức có hợp đồng ủy nhiệm thu với cơ quan quản lý thuế; Các ngân hàng và tổ chức cung ứng dịch vụ trung gian thanh toán tại khoản 4 Điều 2 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế (theo quy định tại khoản 1 Điều 4; khoản 1 và khoản 2 Điều 7; điểm c khoản 1 Điều 10 Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính).", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019; Luật sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dữ trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n + Luật Giao dịch điện tử ngày 22/6/2023;\n + Luật Công nghệ thông tin ngày 29/06/2006;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 sửa đổi bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 165/2018/NĐ-CP ngày 24/12/2018 của Chính phủ quy định về giao dịch điện tử trong hoạt động tài chính;\n + Nghị định số 130/2018/NĐ-CP ngày 27/9/2018 của Chính phủ quy định chi tiết thi hành Luật giao dịch điện tử về chữ ký số và dịch vụ chứng thực chữ ký số;\n + Nghị định số 45/2020/NĐ-CP ngày 08/4/2020 của Chính phủ về thực hiện thủ tục hành chính trên môi trường điện tử;\n + Nghị định số 11/2020/NĐ-CP ngày 20/01/2020 của Chính phủ về thủ tục hành chính thuộc lĩnh vực Kho bạc Nhà nước;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn về giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/KNNT-TĐT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010761"}, {"ma": "1.014407", "ten": "Khai thuế thu nhập doanh nghiệp bổ sung theo quy định về thuế thu nhập doanh nghiệp bổ sung tối thiểu nội địa đạt chuẩn (QDMTT)", "cap_thuc_hien": "Cục thuế", "doi_tuong": "Đơn vị hợp thành hoặc tập hợp các đơn vị hợp thành của tập đoàn đa quốc gia có hoạt động sản xuất, kinh doanh tại Việt Nam trong năm tài chính phải áp dụng quy định về thuế thu nhập doanh nghiệp bổ sung tối thiểu nội địa đạt chuẩn.", "co_quan": "Chi cục Thuế Doanh nghiệp lớn.", "trinh_tu": "Đơn vị hợp thành chịu trách nhiệm kê khai thực hiện nộp hồ sơ khai thuế theo quy định về thu nhập doanh nghiệp bổ sung tối thiểu nội địa đạt chuẩn (QDMTT) chậm nhất là 12 tháng sau ngày kết thúc năm tài chính. \n Thời hạn nộp Tờ khai thông tin theo quy định về thuế tối thiểu toàn cầu của tập đoàn đa quốc gia và Thông báo đơn vị hợp thành đã nộp Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu tại nước có Hiệp định giữa nhà chức trách có thẩm quyền về trao đổi thông tin theo quy định thuế tối thiểu toàn cầu có hiệu lực với Việt Nam chậm nhất là 18 tháng sau ngày kết thúc năm tài chính đối với năm đầu tiên mà bất kỳ đơn vị hợp thành nào của Tập đoàn đa quốc gia thuộc đối tượng áp dụng của Nghị quyết số 107/2023/QH15; 15 tháng sau ngày kết thúc năm tài chính đối với các năm tiếp theo.", "cach_thuc": "Nộp hồ sơ điện tử qua cổng giao dịch điện tử.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu (Mẫu số 01/TKTT-QDMTT) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Tờ khai thuế thu nhập doanh nghiệp bổ sung (Mẫu số 01/TNDN-QDMTT) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Bản thuyết minh giải trình chênh lệch do khác biệt giữa các chuẩn mực kế toán tài chính (Mẫu số 01/TM) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Thông báo đơn vị hợp thành đã nộp Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu tại nước có Hiệp định giữa nhà chức trách có thẩm quyền về trao đổi thông tin theo quy định thuế tối thiểu toàn cầu có hiệu lực với Việt Nam (Mẫu số 03/TB-ĐVHT) ban hành kèm theo Nghị định số 236/2025/NĐ-CP (nếu có);\n ++ Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu của tập đoàn đa quốc gia đối với phần thông tin chung của tập đoàn đa quốc gia, thông tin về cấu trúc Tập đoàn và thông tin liên quan đến việc tính toán thuế suất thực tế, thuế bổ sung của các đơn vị hợp thành tại Việt Nam, trừ trường hợp tập đoàn đa quốc gia không phải nộp Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu ở bất kỳ quốc gia nào (bản chính hoặc bản sao);\n ++ Báo cáo số liệu tài chính từng đơn vị hợp thành sử dụng cho mục đích lập Báo cáo tài chính hợp nhất của công ty mẹ tối cao (bản chính hoặc bản sao).\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Nghị quyết 107/2023/QH15 ngày 29/11/2023 của Quốc hội về áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 236/2025/NĐ-CP ngày 29/8/2025 của Chính phủ quy định chi tiết một số điều của Nghị quyết số 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội về việc áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014407"}, {"ma": "1.008590", "ten": "Gia hạn nộp thuế", "cap_thuc_hien": "Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở/Chi cục Thuế Doanh nghiệp lớn/Chi cục Thuế Thương mại điện tử.", "trinh_tu": "+ Bước 1: Người nộp thuế (NNT) thuộc trường hợp được gia hạn nộp thuế chuẩn bị hồ sơ đề nghị gia hạn nộp thuế đầy đủ theo đúng quy định và gửi tới cơ quan thuế quản lý trực tiếp hoặc cơ quan thuế quản lý khoản thu.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm phục vụ hành chính công (TTPVHCC) cấp tỉnh, xã hoặc qua dịch vụ bưu chính: công chức thuế tiếp nhận, giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã;\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n ++ Trường hợp gia hạn nộp thuế theo quy định tại Điều 62 Luật Quản lý thuế số 38/2019/QH14:\n +++Văn bản đề nghị gia hạn nộp thuế của người nộp thuế theo mẫu số 01/GHAN ban hành kèm theo Phụ lục III Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ.\n +++ Tùy từng trường hợp, hồ sơ đề nghị gia hạn nộp thuế phải có thêm các tài liệu sau:\n (*) Trường hợp do thiên tai, thảm họa, dịch bệnh, hoả hoạn, tai nạn bất ngờ quy định tại điểm a khoản 27 Điều 3 Luật Quản lý thuế (đã sửa đổi, bổ sung), phải có:\n - Tài liệu chứng thực về thời gian, địa điểm xảy ra thiên tai, thảm họa, dịch bệnh, hỏa hoạn, tai nạn bất ngờ (bản chính hoặc bản sao có xác nhận của người nộp thuế);\n - Văn bản xác định giá trị vật chất bị thiệt hại do người nộp thuế hoặc người đại diện hợp pháp của người nộp thuế lập và chịu trách nhiệm về tính chính xác của số liệu;\n - Văn bản (bản chính hoặc bản sao có xác nhận của người nộp thuế) quy định trách nhiệm của tổ chức, cá nhân phải bồi thường thiệt hại (nếu có);\n - Các chứng từ (bản chính hoặc bản sao có xác nhận của người nộp thuế) liên quan đến việc bồi thường thiệt hại (nếu có).\n (*) Trường hợp bất khả kháng khác theo quy định tại Khoản 1 Điều 3 Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ (đã sửa đổi, bổ sung), phải có:\n - Văn bản xác định giá trị vật chất bị thiệt hại do người nộp thuế hoặc người đại diện hợp pháp của người nộp thuế lập và chịu trách nhiệm về tính chính xác của số liệu;\n - Tài liệu chứng thực về thời gian, địa điểm xảy ra bất khả kháng của cơ quan có thẩm quyền; tài liệu chứng minh người nộp thuế phải ngừng, nghỉ sản xuất, kinh doanh đối với trường hợp do chiến tranh, bạo loạn, đình công mà người nộp thuế phải ngừng, nghỉ sản xuất, kinh doanh (bản chính hoặc bản sao có xác nhận của người nộp thuế);\n - Tài liệu chứng minh việc gặp rủi ro không thuộc nguyên nhân, trách nhiệm chủ quan của người nộp thuế và người nộp thuế không có khả năng nguồn tài chính nộp ngân sách nhà nước đối với trường hợp bị thiệt hại do gặp rủi ro không thuộc nguyên nhân, trách nhiệm chủ quan của người nộp thuế (bản chính hoặc bản sao có xác nhận của người nộp thuế);\n - Các chứng từ (bản chính hoặc bản sao có xác nhận của người nộp thuế) liên quan đến việc bồi thường thiệt hại của cơ quan bảo hiểm (nếu có).\n (*) Trường hợp di dời cơ sở sản xuất, kinh doanh theo quy định tại điểm b khoản 1 Điều 62 Luật Quản lý thuế (đã sửa đổi, bổ sung), phải có:\n - Quyết định của cơ quan nhà nước có thẩm quyền về việc di dời cơ sở sản xuất, kinh doanh đối với người nộp thuế (bản chính hoặc bản sao có xác nhận của người nộp thuế);\n - Đề án hoặc phương án di dời, trong đó thể hiện rõ kế hoạch và tiến độ thực hiện di dời của người nộp thuế (bản chính hoặc bản sao có xác nhận của người nộp thuế).\n ++ Trường hợp gia hạn nộp tiền cấp quyền khai thác khoáng sản khi có vướng mắc về giải phóng mặt bằng thuê đất theo quy định tại Điều 20 Nghị định số 126/20202/NĐ-CP ngày 19/10/2020 của Chính phủ:\n +++Văn bản đề nghị gia hạn nộp thuế của người nộp thuế theo mẫu số 01/GHAN ban hành kèm theo Phụ lục III Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ.\n +++ Văn bản có xác nhận của cơ quan nhà nước có thẩm quyền (Ủy ban nhân dân cấp xã hoặc Ban bồi thường giải phóng mặt bằng cấp huyện hoặc cơ quan khác có chức năng tương tự) về việc người nộp thuế có vướng mắc về giải phóng mặt bằng thuê đất, trong đó ghi rõ diện tích đất có vướng mắc về giải phóng mặt bằng thuê đất.\n +++ Các tài liệu liên quan khác (nếu có). \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "mẫu số 03/GHAN, mẫu số 02/GHAN", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã sửa đổi, bổ sung).", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội;\n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ Sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/GHAN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008590"}, {"ma": "1.008588", "ten": "Nộp dần tiền thuế nợ", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1: Người nộp thuế (NNT) thuộc trường hợp được nộp dần tiền thuế nợ chuẩn bị hồ sơ đề nghị nộp dần tiền thuế nợ đầy đủ theo đúng quy định và gửi tới cơ quan thuế quản lý trực tiếp.\n ++ Đối với trường hợp hồ sơ nộp dần tiền thuế nợ điện tử: NNT truy cập vào Hệ thống thông tin giải quyết TTHC mà NNT lựa chọn (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN)/ Cổng thông tin điện tử của Cục Thuế (trường hợp TTHC đã toàn trình như chưa tích hợp lên cổng dịch vụ công quốc gia) để lập văn bản đề nghị nộp dần tiền thuế nợ và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm phục vụ hành chính công (TTPVHCC) cấp tỉnh, xã hoặc qua dịch vụ bưu chính: công chức thuế tiếp nhận, giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++ Văn bản đề nghị nộp dần tiền thuế nợ của người nộp thuế theo mẫu số 01/NDAN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. \n ++ Thư bảo lãnh theo đúng quy định của pháp luật về bảo lãnh và bắt buộc phải có nội dung cam kết về việc bên bảo lãnh sẽ thực hiện nộp thay cho người nộp thuế trong trường hợp người nộp thuế không thực hiện đúng thời hạn nộp dần tiền thuế nợ; \n ++ Quyết định cưỡng chế thi hành quyết định hành chính thuế (nếu có). \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Thông báo không chấp thuận việc nộp dần tiền thuế nợ (mẫu số 03/NDAN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính). \n + Hoặc Quyết định về việc nộp dần tiền thuế nợ (mẫu số 04/NDAN ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính).", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/NDAN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008588"}, {"ma": "1.010237", "ten": "Đăng ký dự thi cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế/đăng ký cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế đối với trường hợp được miễn môn thi", "cap_thuc_hien": "Cục Thuế", "doi_tuong": "Cá nhân.", "co_quan": "Cục Thuế", "trinh_tu": "+ Bước 1: Người đăng ký dự thi, người đăng ký cấp chứng chỉ hành nghề (CCHN) dịch vụ làm thủ tục về thuế thực hiện:\n (i) Đối với dự thi cấp CCHN dịch vụ làm thủ tục về thuế: Người có đủ điều kiện, có nhu cầu dự thi cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế chuẩn bị hồ sơ đăng ký dự thi và gửi đến Cục Thuế (Hội đồng thi cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế) trong thời hạn theo Thông báo của Hội đồng thi cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế;\n (ii) Đối với đăng ký cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế trường hợp được miễn môn thi: Người được miễn môn thi, khi đủ điều kiện được cấp chứng chỉ hành nghề, có nhu cầu đăng ký cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế thì chuẩn bị hồ sơ, gửi đến Cục Thuế.\n + Bước 2: Cục Thuế thực hiện tiếp nhận hồ sơ, giải quyết và trả kết quả theo quy định.", "cach_thuc": "+ Nộp hồ sơ qua Cổng DVC Quốc gia đối với dự thi cấp CCHN dịch vụ làm thủ tục về thuế. \n + Nộp hồ sơ qua Cổng DVC Quốc gia, Tại TTPVHCC hoặc gửi qua dịch vụ bưu chính công ích đến Cục Thuế đối với đăng ký cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế được miễn môn thi.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm:\n (i) Đối với dự thi cấp CCHN dịch vụ làm thủ tục về thuế:\n a) Trường hợp đăng ký thi lần đầu, hồ sơ gồm:\n ++ Đơn đăng ký dự thi cấp CCHN dịch vụ làm thủ tục về thuế theo Mẫu 1.1 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế;\n ++ Bằng tốt nghiệp đại học, sau đại học theo quy định tại khoản 2 Điều 4 Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính; nếu bằng tốt nghiệp không thuộc ngành, chuyên ngành kinh tế, thuế, tài chính, kế toán, kiểm toán, luật, người dự thi phải nộp kèm bảng điểm ghi rõ số đơn vị học trình hoặc tín chỉ hoặc tiết học của tất cả các môn học (bản scan);\n ++ Giấy xác nhận thời gian công tác theo Mẫu 1.2 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hoặc sổ bảo hiểm xã hội chứng minh thời gian công tác theo quy định tại khoản 3 Điều 4 Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính (bản scan);\n ++ Chứng minh nhân dân hoặc thẻ căn cước công dân (đối với người Việt Nam) trong trường hợp cơ sở dữ liệu quốc gia về dân cư chưa đưa vào vận hành hoặc hộ chiếu (đối với người nước ngoài) còn hiệu lực đến thời điểm đăng ký dự thi (bản scan);\n ++ Một ảnh màu 3x4 cm nền trắng chụp trong thời gian 06 tháng tính đến thời điểm nộp hồ sơ dự thi (file ảnh).\n b) Trường hợp đăng ký thi tiếp môn chưa thi hoặc thi lại môn thi chưa đạt yêu cầu, hồ sơ gồm:\n ++ Đơn đăng ký dự thi theo Mẫu 1.1 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính;\n ++ Một ảnh màu 3x4 cm nền trắng chụp trong thời gian 06 tháng tính đến thời điểm nộp hồ sơ dự thi (file ảnh);\n ++ Chứng minh nhân dân hoặc thẻ căn cước công dân (đối với người Việt Nam) trong trường hợp cơ sở dữ liệu quốc gia về dân cư chưa đưa vào vận hành hoặc hộ chiếu (đối với người nước ngoài) còn hiệu lực đến thời điểm đăng ký dự thi (chỉ cần nộp trong trường hợp có thay đổi so với lần thi trước).\n (ii) Đối với đăng ký cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế trường hợp được miễn môn thi, hồ sơ gồm:\n ++ Đơn đề nghị cấp chứng chỉ hành nghề dịch vụ làm thủ tục về thuế theo Mẫu 1.3 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế;\n ++ Chứng minh nhân dân hoặc căn cước công dân (đối với người Việt Nam) trong trường hợp cơ sở dữ liệu quốc gia về dân cư chưa đưa vào vận hành hoặc hộ chiếu (đối với người nước ngoài) còn hiệu lực đến thời điểm nộp hồ sơ (bản sao có chứng thực);\n ++ Một ảnh màu 3x4(cm) nền trắng chụp trong thời gian 06 tháng tính đến thời điểm nộp hồ sơ đề nghị cấp chứng chỉ;\n ++ Giấy tờ chứng minh đủ điều kiện được miễn môn thi, nộp một trong các giấy tờ sau:\n +++ Giấy xác nhận thời gian công tác theo Mẫu 1.2 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính đối với người được miễn môn thi pháp luật về thuế hoặc được miễn cả 02 môn thi do có thời gian làm việc trong ngành Thuế;\n +++ Bằng tốt nghiệp đại học hoặc sau đại học và sổ bảo hiểm xã hội (bản sao có chứng thực) đối với người được miễn môn thi kế toán do đáp ứng điều kiện: Người đã tốt nghiệp đại học, sau đại học thuộc ngành, chuyên ngành kế toán, kiểm toán và có thời gian làm kế toán, kiểm toán 60 tháng liên tục trở lên tính đến thời điểm đăng ký xét miễn môn thi. Thời gian làm kế toán, kiểm toán được tính sau khi tốt nghiệp đại học, sau đại học thuộc ngành, chuyên ngành kế toán, kiểm toán đến thời điểm đăng ký xét miễn môn thi;\n +++ Giấy chứng nhận điểm thi (bản sao có chứng thực) đối với người được miễn môn thi kế toán do đáp ứng điều kiện: Người đã đạt yêu cầu môn thi kế toán tài chính, kế toán quản trị nâng cao và còn trong thời gian bảo lưu tại kỳ thi cấp chứng chỉ kế toán viên, kiểm toán viên do Bộ Tài chính tổ chức;\n +++ Chứng chỉ kiểm toán viên hoặc chứng chỉ kế toán viên (bản sao có chứng thực) đối với người được miễn cả 02 môn thi (pháp luật về thuế và môn thi kế toán) do đáp ứng điều kiện: Người có chứng chỉ kiểm toán viên hoặc chứng chỉ kế toán viên do cơ quan nhà nước có thẩm quyền cấp theo quy định.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "+ Kết quả thực hiện thủ tục hành chính đối với trường hợp (i): Danh sách người dự thi và các thông tin khác có liên quan được đăng tải trên cổng thông tin điện tử của Tổng cục Thuế; Kết quả thi, kết quả phúc khảo được công bố trên cổng thông tin điện tử của Tổng cục Thuế; + Kết quả thực hiện thủ tục hành chính đối với trường hợp (ii): là Chứng chỉ hành nghề dịch vụ làm thủ tục về thuế.", "dieu_kien": "Không", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019;\n + Nghị định số 118/2025/NĐ-CP ngày 09/06/025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia\n + Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010237"}, {"ma": "1.014408", "ten": "Khai thuế thu nhập doanh nghiệp bổ sung theo quy định về tổng hợp thu nhập chịu thuế tối thiểu (IIR)", "cap_thuc_hien": "Cục thuế", "doi_tuong": "Công ty mẹ tối cao, công ty mẹ bị sở hữu một phần, công ty mẹ trung gian tại Việt Nam là đơn vị hợp thành của tập đoàn đa quốc gia, nắm giữ trực tiếp hoặc gián tiếp quyền sở hữu đơn vị hợp thành chịu thuế suất thấp tại nước ngoài theo quy định về thuế tối thiểu toàn cầu tại bất kỳ thời điểm nào trong năm tài chính phải áp dụng quy định tổng hợp thu nhập chịu thuế tối thiểu.", "co_quan": "Chi cục Thuế Doanh nghiệp lớn.", "trinh_tu": "Đơn vị hợp thành chịu trách nhiệm kê khai thực hiện nộp hồ sơ khai thuế theo quy định về tổng hợp thu nhập chịu thuế tối thiểu (IIR) chậm nhất là 18 tháng sau ngày kết thúc năm tài chính đối với năm đầu tiên tập đoàn đa quốc gia thuộc đối tượng áp dụng; thời hạn chậm nhất là 15 tháng sau ngày kết thúc năm tài chính đối với các năm tiếp theo.", "cach_thuc": "Nộp hồ sơ điện tử qua cổng giao dịch điện tử.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n ++ Tờ khai thông tin theo Quy định về thuế tối thiểu toàn cầu (Mẫu số 01/TKTT-IIR) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Tờ khai thuế thu nhập doanh nghiệp bổ sung (Mẫu số 01/TNDN-IIR) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Bản thuyết minh giải trình chênh lệch do khác biệt giữa các chuẩn mực kế toán tài chính (Mẫu số 01/TM) ban hành kèm theo Nghị định số 236/2025/NĐ-CP;\n ++ Báo cáo tài chính hợp nhất của công ty mẹ tối cao (bản chính hoặc bản sao);\n ++ Báo cáo số liệu tài chính của từng đơn vị hợp thành sử dụng cho mục đích lập báo cáo tài chính hợp nhất của công ty mẹ tối cao (bản chính hoặc bản sao).\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Đảm bảo cơ sở hạ tầng công nghệ thông tin để gửi dữ liệu tới cơ quan thuế bằng phương thức điện tử.", "can_cu_phap_ly": "+ Nghị quyết 107/2023/QH15 ngày 29/11/2023 của Quốc hội về áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 236/2025/NĐ-CP ngày 29/8/2025 của Chính phủ quy định chi tiết một số điều của Nghị quyết số 107/2023/QH15 ngày 29 tháng 11 năm 2023 của Quốc hội về việc áp dụng thuế thu nhập doanh nghiệp bổ sung theo quy định chống xói mòn cơ sở thuế toàn cầu.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận một cửa và Cổng dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.014408"}, {"ma": "1.008581", "ten": "Miễn thuế, giảm thuế theo Hiệp định thuế đối với Nhà thầu nước ngoài nộp thuế theo phương pháp trực tiếp - đối với tái bảo hiểm nước ngoài", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Doanh nghiệp, Doanh nghiệp có vốn đầu tư nước ngoài, Tổ chức (không bao gồm doanh nghiệp, HTX), Tổ chức nước ngoài", "co_quan": "Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1. Các tổ chức nhận tái bảo hiểm nước ngoài thuộc diện được miễn thuế, giảm thuế do áp dụng Hiệp định tránh đánh thuế hai lần giữa Việt Nam và nước, vùng lãnh thổ khác chuẩn bị hồ sơ đề nghị miễn, giảm thuế theo Hiệp định thuế gửi đến Thuế tỉnh, thành phố. Các tổ chức nhận tái bảo hiểm nước ngoài trực tiếp nộp hồ sơ đề nghị áp dụng Hiệp định thuế cho từng năm cho tất cả các hợp đồng tái bảo hiểm mà các tổ chức đã ký kết hoặc dự kiến ký kết trong năm đó. Các tổ chức nhận tái bảo hiểm nước ngoài có thể uỷ quyền cho các đại lý thuế, văn phòng đại diện của công ty tại Việt Nam hoặc công ty tái bảo hiểm Việt Nam nộp hồ sơ. Khi đó, các tổ chức nhận tái bảo hiểm nước ngoài nộp cho Cơ quan thuế 02 (hai) hồ sơ đề nghị gồm: hồ sơ đề nghị dự kiến và hồ sơ đề nghị chính thức. Các tổ chức nhận tái bảo hiểm nước ngoài có văn phòng đại diện tại Việt Nam nộp hồ sơ tại Thuế tỉnh, thành phố nơi đóng văn phòng đại diện. Đối với các tổ chức nhận tái bảo hiểm nước ngoài không có văn phòng đại diện tại Việt Nam: \n ++ Trường hợp các tổ chức nhận tái bảo hiểm nước ngoài trực tiếp nộp hồ sơ thì nộp tại Thuế tỉnh, thành phố nơi Công ty tái bảo hiểm Việt Nam đầu tiên dự kiến ký kết hợp đồng;\n ++ Trường hợp các tổ chức nhận tái bảo hiểm nước ngoài uỷ quyền cho đại diện hợp pháp tại Việt Nam (Đại lý thuế, Công ty kiểm toán hoặc Công ty tái bảo hiểm Việt Nam đầu tiên dự kiến ký kết hợp đồng...) nộp hồ sơ: Nộp tại Thuế tỉnh, thành phố nơi đại điện hợp pháp đăng ký nộp thuế. Thời điểm nộp hồ sơ: (i) Đối với hồ sơ đề nghị dự kiến: 05 (năm) ngày trước khi ký kết Hợp đồng; hoặc 05 (năm) ngày sau khi thực hiện Hợp đồng; hoặc 05 (năm) ngày trước khi thanh toán. (ii) Đối với hồ sơ đề nghị chính thức: Trong vòng quý I của năm sau, tổ chức nhận tái bảo hiểm nước ngoài có trách nhiệm nộp cho cơ quan thuế hồ sơ đề nghị chính thức cùng với tài liệu liên quan.\n + Bước 2. Cơ quan thuế tiếp nhận: \n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận và giải quyết hồ sơ và trả kết quả theo quy định. \n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế. \n ++ Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã. \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n Đối với Hồ sơ đề nghị chính thức bao gồm \n ++Văn bản đề nghị chính thức theo mẫu số 02/TBH-TB ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC) \n ++ Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp đã được hợp pháp hoá lãnh sự trong năm tính thuế đó; \n ++ Bản sao các Hợp đồng tái bảo hiểm đã thực hiện trong năm có xác nhận của người nộp thuế (bao gồm cả những hợp đồng đã có trong kế hoạch và những hợp đồng ngoài kế hoạch đã gửi cơ quan thuế) nhưng chưa nộp cho cơ quan thuế; \n ++ Danh mục hợp đồng theo từng loại theo mẫu số 02-1/TBH-TB ban hành kèm theo Thông tư. Tại thời điểm nộp hồ sơ đề nghị chính thức, người nộp thuế sẽ phân loại hợp đồng và gửi danh mục hợp đồng theo từng loại (với các chỉ tiêu nhất định); mỗi loại hợp đồng chỉ gửi một bản sao có xác nhận của người nộp thuế để làm mẫu. Người nộp thuế phải chịu trách nhiệm về việc thống kê này; \n ++ Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế. \n Đối với Hồ sơ đề nghị dự kiến bao gồm: \n ++ Văn bản đề nghị dự kiến theo mẫu số 01/TBH-TB ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC). \n ++ Bản gốc (hoặc bản sao đã được chứng thực) Giấy chứng nhận cư trú do cơ quan thuế của nước cư trú cấp đã được hợp pháp hoá lãnh sự (cho năm ngay trước năm nộp hồ sơ đề nghị dự kiến); \n ++ Bảng kê các Hợp đồng tái bảo hiểm đã hoặc dự kiến ký kết theo mẫu số 01-1/TBH-TB ban hành kèm theo Thông tư; \n ++ Giấy uỷ quyền trong trường hợp người nộp thuế uỷ quyền cho đại diện hợp pháp thực hiện thủ tục áp dụng Hiệp định thuế. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Thông báo về việc người nộp thuế thuộc hoặc không thuộc diện được miễn thuế theo Hiệp định thuế hoặc Điều ước quốc tế khác (Mẫu số 03-1/MGTH)", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019; \n + Luật số 56/2024/QH15 của Quốc hội: Luật sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế. \n + Thông tư số 80/2021/TT-BTC ngày 29/09/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế. \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính Hóng dãn về giao dịch điện tử trong lĩnh vực thuế; \n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi một số điều của Thông tư 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế. \n + Thông tư số 40/2025/TT-BTC Sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp. \n + Nghị định số 91/2022/NĐ-CP sửa đổi bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế \n + Thông tư số 94/2025/TT-BTC ngày 14/10/2025 sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/TBH-TB", "01/TBH-TB", "02-1/TBH-TB", "02/TBH-TB"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008581"}, {"ma": "1.008327", "ten": "Khai bổ sung hồ sơ khai thuế", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức, cá nhân.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế phát hiện hồ sơ khai thuế đã nộp cho cơ quan thuế có sai, sót thuộc trường hợp quy định tại Điều 47 Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15) thì thực hiện khai bổ sung hồ sơ khai thuế và gửi đến cơ quan thuế quản lý trực tiếp. \n ++ Trường hợp NNT nộp hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính để lập hồ sơ điện tử, ký điện tử và gửi đến cơ quan thuế.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp/qua bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh/Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n +++ Kiểm tra, chấp nhận hồ sơ: Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp/qua bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm: \n (i) Trường hợp khai bổ sung làm thay đổi nghĩa vụ thuế: \n ++ Tờ khai bổ sung mẫu số 01/KHBS ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo quy định tại điểm b khoản 7 Điều 1 Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính); \n ++ Bản giải trình khai bổ sung mẫu số 01-1/KHBS ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính; \n ++ Hồ sơ khai thuế của kỳ tính thuế có sai sót đã được bổ sung theo mẫu ban hành tại từng thời kỳ văn bản có hiệu lực. \n (ii) Trường hợp khai bổ sung không làm thay đổi nghĩa vụ thuế: \n ++ Bản giải trình khai bổ sung mẫu số 01-1/KHBS ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính; \n ++ Hồ sơ khai thuế của kỳ tính thuế có sai sót đã được bổ sung theo mẫu ban hành tại từng thời kỳ văn bản có hiệu lực. \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ trưởng Bộ Tài chính) hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế năm 2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-1/KHBS", "01/KHBS"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008327"}, {"ma": "1.011021", "ten": "Khai thuế đối với tổ chức khai thuế thay, nộp thuế thay cho cá nhân có bất động sản cho thuê", "cap_thuc_hien": "Cấp tỉnh, thành phố/Cấp xã", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Tổ chức, cá nhân khai thuế thay cho cá nhân có tài sản cho thuê chuẩn bị hồ sơ khai thuế và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 (hai mươi) của tháng tiếp theo tháng phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo tháng, hoặc chậm nhất là ngày cuối cùng của tháng đầu tiên của quý tiếp theo quý phát sinh nghĩa vụ khai thuế thay nếu tổ chức khai thuế theo quý, hoặc chậm nhất là ngày cuối cùng của tháng đầu tiên của năm dương lịch hoặc năm tài chính nếu tổ chức, cá nhân khai thuế theo năm, hoặc chậm nhất là ngày thứ 10 kể từ ngày bắt đầu thời hạn cho thuê của kỳ thanh toán nếu tổ chức, cá nhân khai thuế theo từng lần phát sinh kỳ thanh toán .\n + Bước 2. Cơ quan thuế tiếp nhận hồ sơ của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm Phục vụ hành chính công cấp tỉnh/cấp xã hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận, giải quyết hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/ Hệ thống thông tin giải quyết TTHC.", "thanh_phan_ho_so": "+ Thành phần hồ sơ gồm: \n ++Tờ khai thuế đối với hoạt động cho thuê tài sản (áp dụng đối với cá nhân có hoạt động cho thuê tài sản trực tiếp khai thuế với cơ quan thuế và tổ chức khai thay cho cá nhân) mẫu số 01/TTS theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Phụ lục bảng kê chi tiết cá nhân cho thuê tài sản (áp dụng đối với tổ chức khai thay cho cá nhân cho thuê tài sản) mẫu số 01-2/BK-TTS theo Phụ lục I - Danh mục hồ sơ khai thuế ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và Phụ lục II - Danh mục mẫu biểu ban hành kèm theo Thông tư số 40/2021/TT-BTC ngày 01/6/2021 của Bộ trưởng Bộ Tài chính. \n ++ Bản sao hợp đồng thuê tài sản, phụ lục hợp đồng (nếu là lần khai thuế đầu tiên của Hợp đồng hoặc Phụ lục hợp đồng). Cơ quan thuế có quyền yêu cầu xuất trình bản chính để đối chiếu, xác nhận tính chính xác của bản sao so với bản chính. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế; Nghị định số 125/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của Bộ Tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia. \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; Thông tư số 40/2025/TT-BTC ngày 13/6/2025 sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; Thông tư số 94/2025/TT-BTC ngày 14/10/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 100/2021/TT-BTC ngày 15 tháng 11 năm 2021 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ trưởng Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh; \n + Thông tư số 19/2021/TT-BTC ngày 18/03/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế, Thông tư số 46/2024/TT-BTC, ngày 09 tháng 7 năm 2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-2/BK-TTS", "01/TTS"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.011021"}, {"ma": "1.008591", "ten": "Thủ tục xác nhận thực hiện nghĩa vụ thuế", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "Tổ chức, cá nhân", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/Thuế cơ sở.", "trinh_tu": "+ Bước 1. Người nộp thuế gửi văn bản đề nghị xác nhận việc thực hiện nghĩa vụ thuế với ngân sách nhà nước đến cơ quan thuế.\n + Bước 2. Cơ quan thuế tiếp nhận văn bản đề nghị xác nhận của người nộp thuế:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc hồ sơ được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp tại Trung tâm Phục vụ hành chính công cấp tỉnh hoặc qua Trung tâm Phục vụ hành chính công cấp xã: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp đến cơ quan thuế thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo tiếp nhận hoặc thông báo lý do không tiếp nhận hồ sơ cho người nộp thuế chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành: Cơ quan thuế gửi Thông báo chấp nhận/không chấp nhận văn bản đề nghị xác nhận việc thực hiện nghĩa vụ thuế với NSNN điện tử cho người nộp thuế qua Hệ thống thông tin giải quyết thủ tục hành chính trong thời hạn 05 (năm) ngày làm việc kể từ ngày gửi Thông báo tiếp nhận văn bản đề nghị xác nhận việc thực hiện nghĩa vụ thuế với NSNN điện tử.\n + Bước 3. Cơ quan thuế xử lý văn bản đề nghị xác nhận của người nộp thuế\n Trường hợp thông tin đề nghị của người nộp thuế và thông tin trên hệ thống ứng dụng quản lý thuế chưa đầy đủ hoặc có chênh lệch, cơ quan thuế gửi Thông báo yêu cầu bổ sung thông tin theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế cho người nộp thuế để giải trình, bổ sung thông tin.\n + Bước 4. Cơ quan thuế trả kết quả xử lý văn bản đề nghị xác nhận của người nộp thuế\n Cơ quan thuế ban hành Thông báo xác nhận/không xác nhận việc thực hiện nghĩa vụ thuế với ngân sách nhà nước theo mẫu số 01/TB-XNNV ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "+ Thành phần hồ sơ: Văn bản đề nghị xác nhận việc thực hiện nghĩa vụ thuế với ngân sách nhà nước theo mẫu số 01/ĐNXN ban hành kèm theo Thông tư số 80/2021/TT-BTC. \n + Số lượng hồ sơ: 01 bộ", "ket_qua": "Thông báo xác nhận/không xác nhận việc thực hiện nghĩa vụ thuế với ngân sách nhà nước theo mẫu số 01/TB-XNNV ban hành kèm theo Thông tư số 80/2021/TT-BTC.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/6/2019; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia; \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/ĐNXN"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008591"}, {"ma": "1.010700", "ten": "Đăng ký tổ chức lớp cập nhật kiến thức/ Thông báo kế hoạch, báo cáo kết quả tổ chức lớp cập nhật kiến thức", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Tổ chức.", "co_quan": "Cục Thuế.", "trinh_tu": "+ Bước 1: Cơ sở đào tạo, tổ chức xã hội nghề nghiệp về đại lý thuế, đơn vị tổ chức cập nhật kiến thức thực hiện:\n ++ Trường hợp (1) đăng ký tổ chức lớp cập nhật kiến thức: Cơ sở đào tạo, tổ chức xã hội nghề nghiệp về đại lý thuế nếu đáp ứng điều kiện theo quy định tại khoản 3, Điều 21 Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế và có nhu cầu thì lập hồ sơ đăng ký tổ chức cập nhật kiến thức gửi đến Cục Thuế;\n ++ Trường hợp (2) thông báo kế hoạch, báo cáo kết quả tổ chức lớp cập nhật kiến thức: Đơn vị tổ chức cập nhật kiến thức gửi thông báo kế hoạch các lớp cập nhật kiến thức trong quý I hàng năm; gửi báo cáo kết quả tổ chức cập nhật trong thời hạn 05 ngày làm việc kể từ ngày kết thúc lớp học đến Cục Thuế.\n + Bước 2: Cục Thuế thực hiện tiếp nhận hồ sơ theo quy định. Đối với trường hợp (1), Cục Thuế giải quyết và trả kết quả.", "cach_thuc": "Cơ sở đào tạo, tổ chức xã hội nghề nghiệp về đại lý thuế nộp trực tuyến: qua Cổng DVC Quốc gia, trực tiếp: Tại TTPVHCC hoặc gửi qua dịch vụ bưu chính công ích đến Cục Thuế đối với trường hợp (1). Đơn vị tổ chức cập nhật kiến thức nộp qua Cổng DVC Quốc gia đối với trường hợp (2).", "thanh_phan_ho_so": "+ Thành phần hồ sơ, gồm:\n ++ Trường hợp (1):\n +++ Bản đăng ký tổ chức cập nhật kiến thức hành nghề dịch vụ làm thủ tục về thuế theo Mẫu số 01/CNKT tại Phụ lục ban hành kèm theo Quy chế tổ chức cập nhật kiến thức hành nghề dịch vụ làm thủ tục về thuế theo Quyết định số 811/QĐ-TCT ngày 11/6/2021 của Tổng cục Thuế về việc ban hành Quy chế tổ chức cập nhật kiến thức hành nghề dịch vụ làm thủ tục về thuế;\n +++ Bản sao có chứng thực quyết định thành lập cơ sở đào tạo, tổ chức xã hội nghề nghiệp do cơ quan nhà nước có thẩm quyền cấp;\n +++ Tài liệu chứng minh đáp ứng điều kiện giảng viên.\n ++ Trường hợp (2): Báo cáo kết quả tổ chức lớp cập nhật kiến thức Mẫu 2.5 tại Phụ lục ban hành kèm theo Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế.\n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Kết quả thực hiện thủ tục hành chính đối với trường hợp (1) là Giấy xác nhận đủ điều kiện tổ chức cập nhật kiến thức. Hồ sơ không phải trả kết quả đối với trường hợp (2).", "dieu_kien": "Trường hợp cơ sở đào tạo và các tổ chức xã hội nghề nghiệp về đại lý thuế gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân theo các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế ngày 13/06/2019;\n + Nghị định số 118/2025/NĐ-CP ngày 09/06/025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia\n + Thông tư số 10/2021/TT-BTC ngày 26/01/2021 của Bộ Tài chính hướng dẫn quản lý hành nghề dịch vụ làm thủ tục về thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.010700"}, {"ma": "1.007014", "ten": "Khai thuế GTGT đối với phương pháp khấu trừ đối với hoạt động sản xuất kinh doanh", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố/ Thuế cơ sở", "trinh_tu": "+ Bước 1. Người nộp thuế áp dụng phương pháp tính thuế GTGT theo phương pháp khấu trừ theo quy định của pháp luật về thuế GTGT lập hồ sơ khai thuế và gửi đến cơ quan thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo tháng); chậm nhất là ngày cuối cùng của tháng đầu của quý tiếp theo quý phát sinh nghĩa vụ thuế (đối với trường hợp khai và nộp thuế GTGT theo quý); chậm nhất là ngày thứ 10 kể từ ngày phát sinh nghĩa vụ thuế (chỉ áp dụng đối với trường hợp khai và nộp thuế GTGT theo Tờ khai mẫu số 05/GTGT theo lần phát sinh).\n Trường hợp người nộp thuế gửi hồ sơ qua giao dịch điện tử: Người nộp thuế (NNT) truy cập vào Cổng thông tin điện tử mà người nộp thuế lựa chọn (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm: Cổng dịch vụ công quốc gia, Cổng dịch vụ công cấp Bộ, cấp tỉnh theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Thuế tỉnh/TP (sau đây gọi là Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền)/Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN) để khai hồ sơ khai thuế và các phụ lục đính kèm theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà người nộp thuế lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại cơ quan thuế hoặc được gửi qua đường bưu chính: cơ quan thuế thực hiện tiếp nhận hồ sơ theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận, giải quyết hồ sơ thông qua hệ thống xử lý dữ liệu điện tử của cơ quan thuế:\n +++ Tiếp nhận hồ sơ: Cổng thông tin điện tử của Thuế tỉnh/TP gửi thông báo tiếp nhận việc NNT đã nộp hồ sơ hoặc thông báo lý do không tiếp nhận hồ sơ cho NNT qua Cổng thông tin điện tử mà người nộp thuế lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 15 phút kể từ khi nhận được hồ sơ khai thuế điện tử của người nộp thuế.\n +++ Kiểm tra, giải quyết hồ sơ: Cơ quan thuế thực hiện kiểm tra, giải quyết hồ sơ khai thuế của NNT theo quy định của Luật Quản lý thuế và các văn bản hướng dẫn thi hành:\n Cơ quan thuế gửi thông báo chấp nhận/không chấp nhận hồ sơ đến Cổng thông tin điện tử mà NNT lựa chọn lập và gửi hồ sơ (Cổng thông tin điện tử của Thuế tỉnh/TP/Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền hoặc tổ chức cung cấp dịch vụ T-VAN) chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận nộp hồ sơ khai thuế điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n+Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n+ Trực tuyến: Qua Cổng dịch vụ công quốc gia.", "thanh_phan_ho_so": "Thành phần hồ sơ gồm: Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 126/2020/NĐ-CP), Phụ lục II ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Thông tư số 80/2021/TT-BTC), Thông tư số 35/2011/TT-BTC ngày 15/3/2011 hướng dẫn một số nội dung về thuế giá trị gia tăng đối với dịch vụ viễn thông. Hồ sơ khai thuế GTGT cụ thể như sau:\n + Đối với người nộp thuế có hoạt động sản xuất điện:\n ++ Tờ khai thuế GTGT mẫu số 01/GTGT;\n ++ Trường hợp người nộp thuế là cơ sở sản xuất thủy điện có nhà máy thủy điện nằm chung trên địa bàn các tỉnh thì nộp thêm Phụ lục bảng phân bổ số thuế GTGT phải nộp đối với hoạt động sản xuất thủy điện mẫu số 01-2/GTGT.\n + Đối với người nộp thuế có hoạt động kinh doanh xổ số điện toán: \n ++ Tờ khai thuế GTGT mẫu số 01/GTGT;\n ++ Phụ lục bảng phân bổ số thuế GTGT phải nộp đối với hoạt động kinh doanh xổ số điện toán mẫu số 01-3/GTGT (nếu có).\n + Đối với người nộp thuế là doanh nghiệp viễn thông có các chi nhánh hạch toán phụ thuộc tại tỉnh khác với nơi doanh nghiệp đóng trụ sở chính: \n ++ Tờ khai thuế GTGT mẫu số 01/GTGT;\n ++ Trường hợp người nộp thuế có dịch vụ viễn thông cước trả sau thì nộp thêm Phụ lục bảng phân bổ thuế GTGT phải nộp (trừ sản xuất thủy điện, kinh doanh xổ số điện toán) mẫu số 01-6/GTGT.\n ++ Trường hợp cơ sở kinh doanh dịch vụ viễn thông mua hàng hóa, dịch vụ để đầu tư cho toàn hệ thống hạ tầng viễn thông của cơ sở kinh doanh thì nộp thêm Bảng phân bổ thuế GTGT đầu vào cho các đơn vị hạch toán phụ thuộc và cho trụ sở chính Mẫu số 01 ban hành kèm theo Thông tư số 35/2011/TT-BTC ngày 15/3/2011 của Bộ Tài chính.\n + Đối với người nộp thuế có đơn vị phụ thuộc, địa điểm kinh doanh là cơ sở sản xuất khác tỉnh với nơi người nộp thuế đóng trụ sở chính:\n ++ Tờ khai thuế GTGT mẫu số 01/GTGT;\n ++ Phụ lục bảng phân bổ thuế GTGT phải nộp (trừ sản xuất thủy điện, kinh doanh xổ số điện toán) mẫu số 01-6/GTGT.\n + Đối với người nộp thuế chỉ có hoạt động sản xuất kinh doanh thông thường không thuộc các trường hợp nêu trên:\n ++ Tờ khai thuế GTGT mẫu số 01/GTGT.\n + Đối với người nộp thuế thuộc đối tượng nộp thuế GTGT theo phương pháp khấu trừ có hoạt động chuyển nhượng bất động sản tại địa bàn khác tỉnh, thành phố trực thuộc trung ương với nơi người nộp thuế đóng trụ sở chính (trừ hoạt động chuyển nhượng bất động sản của dự án đầu tư cơ sở hạ tầng, nhà để chuyển nhượng theo quy định tại điểm b khoản 1 Điều 11 Nghị định số 126/2020/NĐ-CP):\n ++ Hồ sơ khai thuế gồm: Tờ khai thuế GTGT mẫu số 05/GTGT;\n ++ Người nộp thuế phải tổng hợp doanh thu chưa có thuế giá trị gia tăng đối với hoạt động chuyển nhượng bất động sản vào hồ sơ khai thuế tại trụ sở chính để xác định số thuế phải nộp cho toàn bộ hoạt động sản xuất kinh doanh tại trụ sở chính. Số thuế giá trị gia tăng đã nộp tại tỉnh nơi có bất động sản chuyển nhượng được bù trừ với số thuế giá trị gia tăng phải nộp tại trụ sở chính.\n + Đối với người nộp thuế thuộc đối tượng nộp thuế GTGT theo phương pháp khấu trừ là nhà thầu xây dựng (nhà thầu chính, nhà thầu phụ), ký hợp đồng (phụ lục hợp đồng) trực tiếp với chủ đầu tư để thi công công trình xây dựng (hoạt động xây dựng theo quy định của pháp luật về hệ thống ngành kinh tế quốc dân và quy định của pháp luật chuyên ngành) tại địa bàn khác tỉnh, thành phố trực thuộc trung ương với nơi người nộp thuế đóng trụ sở chính (bao gồm cả công trình, hạng mục công trình xây dựng liên quan tới nhiều tỉnh):\n ++ Hồ sơ khai thuế gồm: Tờ khai thuế GTGT mẫu số 05/GTGT;\n ++ Người nộp thuế phải tổng hợp doanh thu chưa có thuế giá trị gia tăng đối với hoạt động xây dựng vào hồ sơ khai thuế tại trụ sở chính để xác định số thuế phải nộp cho toàn bộ hoạt động sản xuất kinh doanh tại trụ sở chính. Số thuế giá trị gia tăng đã nộp tại tỉnh nơi có công trình xây dựng được bù trừ với số thuế giá trị gia tăng phải nộp tại trụ sở chính. \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử đồng thời đăng ký và đảm bảo đầy đủ các điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế theo quy định tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 hướng dẫn giao dịch điện tử trong lĩnh vực thuế của Bộ Tài chính.", "can_cu_phap_ly": "+ Luật Thuế giá trị gia tăng số 48/2024/QH15;\n+ Luật Quản lý thuế ngày 13/6/2019;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế.\n+ Thông tư số 35/2011/TT-BTC ngày 15/3/2011 hướng dẫn một số nội dung về thuế giá trị gia tăng đối với dịch vụ viễn thông.\n+ Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-2/GTGT", "01-3/GTGT", "01-6/GTGT", "01/GTGT", "05/GTGT"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007014"}, {"ma": "1.008596", "ten": "Xóa nợ tiền thuế, tiền phạt phát sinh trước ngày 01/7/2007 đối với doanh nghiệp nhà nước hoàn thành cổ phần hóa/ doanh nghiệp nhà nước thực hiện chuyển đổi sở hữu theo hình thức giao, bán", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh", "doi_tuong": "Doanh nghiệp nhà nước hoàn thành cổ phần hóa/ Doanh nghiệp nhà nước thực hiện chuyển đổi sở hữu theo hình thức giao, bán.", "co_quan": "Cục Thuế/Thuế tỉnh, thành phố", "trinh_tu": "+ Bước 1: Người nộp thuế (NNT) thuộc trường hợp xóa nợ tiền thuế, tiền phạt phát sinh trước ngày 01/7/2007 đối với doanh nghiệp nhà nước hoàn thành cổ phần hóa/ doanh nghiệp nhà nước thực hiện chuyển đổi sở hữu theo hình thức giao, bán chuẩn bị hồ sơ đề nghị xóa nợ theo đúng quy định và gửi tới cơ quan thuế quản lý trực tiếp.\n ++ Đối với trường hợp hồ sơ xóa nợ nộp điện tử: NNT truy cập vào Hệ thống thông tin giải quyết TTHC mà NNT lựa chọn (Cổng thông tin điện tử của cơ quan nhà nước có thẩm quyền bao gồm Cổng dịch vụ công quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính và đã được kết nối với Cổng thông tin điện tử của Cục Thuế/ Cổng thông tin của tổ chức cung cấp dịch vụ T-VAN)/ Cổng thông tin điện tử của Cục Thuế (trường hợp TTHC đã toàn trình như chưa tích hợp lên cổng dịch vụ công quốc gia) để lập văn bản đề nghị xóa nợ và gửi kèm các hồ sơ theo quy định dưới dạng điện tử (nếu có), ký điện tử và gửi đến cơ quan thuế qua Cổng thông tin điện tử mà NNT lựa chọn.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp trực tiếp tại Trung tâm phục vụ hành chính công (TTPVHCC) cấp tỉnh, xã hoặc qua dịch vụ bưu chính: công chức thuế tiếp nhận, giải quyết hồ sơ và trả kết quả theo quy định.\n ++ Trường hợp hồ sơ được nộp thông qua giao dịch điện tử, việc tiếp nhận, kiểm tra, chấp nhận hồ sơ thuế do cơ quan thuế thực hiện thông qua hệ thống xử lý dữ liệu điện tử.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã \n +Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: Qua Cổng dịch vụ công quốc gia/Hệ thống thông tin giải quyết TTHC", "thanh_phan_ho_so": "'+ Thành phần hồ sơ gồm:\n ++ Văn bản đề nghị xóa nợ của doanh nghiệp gửi về cơ quan quản lý thuế trực tiếp, trong đó nêu số tiền thuế, tiền phạt đề nghị xóa nợ; căn cứ xóa nợ; lý do số tiền thuế, tiền phạt đề nghị xóa nợ chưa được giảm vốn nhà nước có tại doanh nghiệp mẫu số 05 và 05a ban hành kèm theo Thông tư số 179/2013/TT-BTC.\n Trường hợp số tiền thuế, tiền phạt đề nghị xóa nợ chỉ phát sinh từ hoạt động sản xuất kinh doanh nội địa hoặc số tiền thuế, tiền phạt đề nghị xóa nợ bao gồm cả tiền thuế, tiền phạt phát sinh từ hoạt động sản xuất kinh doanh nội địa và tiền thuế, tiền phạt của hàng hoá xuất khẩu, nhập khẩu thì doanh nghiệp gửi văn bản đề nghị xóa nợ về cơ quan thuế quản lý trực tiếp.\n ++ Tùy từng trường hợp, hồ sơ đề nghị xóa nợ phải có thêm các tài liệu sau:\n (*) Trường hợp xóa nợ tiền thuế, tiền phạt phát sinh trước ngày 01/7/2007 đối với doanh nghiệp nhà nước hoàn thành cổ phần hóa\n ++ Văn bản xác nhận của cơ quan nhà nước có thẩm quyền quyết định về giá trị doanh nghiệp đối với số tiền thuế, tiền phạt đề nghị xóa nợ chưa được giảm vốn nhà nước có tại doanh nghiệp.\n ++ Quyết định của cơ quan nhà nước có thẩm quyền về thực hiện cổ phần hóa doanh nghiệp nhà nước (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Giấy chứng nhận đăng ký kinh doanh thành lập công ty cổ phần (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Biên bản xác định giá trị doanh nghiệp, kèm theo báo cáo chi tiết nợ phải trả (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Quyết định công bố giá trị doanh nghiệp và quyết định giá trị doanh nghiệp khi chuyển thành công ty cổ phần của cơ quan có thẩm quyền (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n Trường hợp chưa có các quyết định này thì trong văn bản xác nhận của cơ quan nhà nước có thẩm quyền nêu tại Khoản 3 Điều này phải ghi rõ việc chưa có quyết định và nêu rõ lý do.\n ++ Quyết toán thuế và báo cáo tài chính khi xác định giá trị doanh nghiệp và khi chính thức chuyển sang công ty cổ phần (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n (*) Trường hợp xóa nợ tiền thuế, tiền phạt phát sinh trước ngày 01/7/2007 đối với doanh nghiệp nhà nước thực hiện chuyển đổi sở hữu theo hình thức giao, bán\n ++ Văn bản xác nhận của cơ quan nhà nước có thẩm quyền quyết định về giá trị doanh nghiệp về việc số tiền thuế, tiền phạt đề nghị xóa nợ không được tính vào giá trị doanh nghiệp để giao, bán.\n ++ Quyết định của cơ quan có thẩm quyền về thực hiện giao, bán doanh nghiệp nhà nước (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Giấy chứng nhận đăng ký kinh doanh thành lập doanh nghiệp (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Quyết toán thuế và báo cáo tài chính khi xác định giá trị doanh nghiệp để giao, bán (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Biên bản xác định giá trị doanh nghiệp (kèm theo báo cáo chi tiết nợ phải trả) (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Hợp đồng mua bán hoặc hợp đồng giao doanh nghiệp (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Xác nhận số tiền thuế, tiền phạt đề nghị xóa nợ đến nay còn nợ của cơ quan Hải quan (đối với trường hợp số tiền thuế, tiền phạt đề nghị xóa nợ vừa có tiền thuế, tiền phạt nội địa vừa có tiền thuế, tiền phạt của hàng hóa xuất khẩu, nhập khẩu).\n ++ Các thông báo về thực hiện nộp tiền thuế nợ, tiền chậm nộp và tiền phạt chậm nộp tại thời điểm đề nghị xóa nợ tiền thuế, tiền phạt (bản sao có chữ ký, đóng dấu của doanh nghiệp).\n ++ Biên bản kiểm tra thuế (kết luận thanh tra) hoặc quyết định về việc ấn định thuế (đối với trường hợp ấn định thu) (bản sao có chữ ký, đóng dấu của doanh nghiệp). \n + Số lượng hồ sơ: 01 (bộ)", "ket_qua": "=+ Thông báo không thuộc đối tượng được xoá nợ thuế \n + Hoặc Quyết định xoá nợ thuế", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng các quy định của pháp luật về giao dịch điện tử.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội;\n + Luật Quản lý thuế số 78/2006/QH11 ngày 29/11/2006.\n + Nghị định số 83/2013/NĐ-CP ngày 22/7/2013 của Chính phủ quy định chi tiết thi hành một số điều của Luật Quản lý thuế và Luật sửa đổi, bổ sung một số điều của Luật Quản lý thuế.\n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại bộ phận một cửa và cổng dịch vụ công quốc gia;\n + Thông tư số 179/2013/TT-BTC ngày 02/12/2013 của Bộ Tài chính hướng dẫn thực hiện xóa nợ tiền thuế, tiền phạt (dưới đây gọi chung là xóa nợ) không có khả năng thu hồi phát sinh trước ngày 01 tháng 7 năm 2007.\n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế;\n + Thông tư số 46/2024/TT-BTC ngày 9/7/2024 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008596"}, {"ma": "1.008584", "ten": "Miễn giảm trong các trường hợp bất khả kháng, thiên tai, hỏa hoạn, tai nạn bất ngờ (tiền thuê đất, thuê mặt nước; thuế sử dụng đất nông nghiệp; thuế sử dụng đất phi nông nghiệp)", "cap_thuc_hien": "Cấp Bộ, Cấp Tỉnh, Cấp Huyện", "doi_tuong": "(i) Miễn tiền thuê đất, thuê mặt nước trong thời gian tạm ngừng hoạt động trong các trường hợp bất khả kháng: Tổ chức kinh tế; tổ chức, cá nhân nước ngoài, người Việt Nam định cư ở nước ngoài.\n(ii) Miễn, giảm thuế sử dụng đất nông nghiệp gặp khó khăn do gặp thiên tai, hoả hoạn, tai nạn bất ngờ, (iii) Miễn, giảm thuế sử dụng đất phi nông nghiệp gặp khó khăn do sự kiện bất khả kháng: Tổ chức, hộ gia đình, cá nhân", "co_quan": "Thuế tỉnh, thành phố/ Thuế Cơ sở", "trinh_tu": "+ Bước 1: Người nộp thuế tạm ngừng hoạt động trong các trường hợp bất khả kháng hoặc gặp thiên tai, hỏa hoạn thực hiện nộp hồ sơ đề nghị miễn, giảm tiền thuê đất; Người nộp thuế gặp khó khăn do thiên tai, hoả hoạn nộp hồ sơ miễn, giảm thuế sử dụng đất nông nghiệp; Người nộp thuế gặp khó khăn do sự kiện bất khả kháng thuộc đối tượng quy định tại Khoản 9 Điều 9 và khoản 4 Điều 10 Luật thuế sử dụng đất phi nông nghiệp thực hiện nộp hồ sơ đề nghị miễn, giảm thuế sử dụng đất phi nông nghiệp tại TTPVHCC cấp tỉnh, xã (trực tiếp) hoặc nộp qua Cổng DVC Quốc gia (trực tuyến).\n + Bước 2. Cơ quan thuế tiếp nhận: Cơ quan thuế quản lý trực tiếp tiếp nhận hồ sơ, giải quyết, trả kết quả (nếu có) theo quy định; Trường hợp hồ sơ không đầy đủ theo quy định, cơ quan thuế không tiếp nhận và hướng dẫn người nộp thuế hoàn thiện hồ sơ theo quy định.", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã.\n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật;\n + Trực tuyến: qua Cổng DVC Quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "- Thành phần hồ sơ:\n(i) Miễn tiền thuê đất, thuê mặt nước trong thời gian tạm ngừng hoạt động trong các trường hợp bất khả kháng\n+ Thành phần hồ sơ gồm: \n++ Hồ sơ miễn tiền thuê đất, thuê mặt nước trong thời gian tạm ngừng hoạt động trong các trường hợp bất khả kháng, bao gồm:\n+++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n+++ Văn bản xác nhận của cơ quan đăng ký đầu tư về thời gian tạm ngừng hoạt động của dự án hoặc văn bản xác nhận của cơ quan quản lý nhà nước có thẩm quyền;\n+++ Bản sao Quyết định cho thuê đất, thuê mặt nước của cơ quan nhà nước có thẩm quyền\n++ Hồ sơ giảm tiền thuê đất đối với đất sử dụng vào mục đích sản xuất nông nghiệp, lâm nghiệp, nuôi trồng thuỷ sản, làm muối bị thiệt hại sản lượng do thiên tai, hỏa hoạn, bao gồm:\n+++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC);\n+++ Biên bản xác định sản lượng của cơ quan có thẩm quyền và có xác nhận của chính quyền địa phương cấp xã nơi xảy ra thiên tai, hỏa hoạn theo mẫu số 02/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC);\n+++ Bản sao Quyết định cho thuê đất của cơ quan nhà nước có thẩm quyền.\n(ii) Miễn, giảm thuế sử dụng đất nông nghiệp gặp khó khăn do gặp thiên tai, hoả hoạn, tai nạn bất ngờ \n+ Thành phần hồ sơ gồm: \n++ Văn bản đề nghị theo mẫu số 01/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC); \n++ Biên bản xác định mức độ, giá trị thiệt hại về tài sản của cơ quan có thẩm quyền và có xác nhận của chính quyền địa phương cấp xã nơi xảy ra thiên tai, hỏa hoạn theo mẫu số 02/MGTH tại Phụ lục I ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 (đã được sửa đổi tại Thông tư số 94/2025/TT-BTC); \n++ Báo cáo tài chính (nếu là doanh nghiệp) kèm theo giải trình phân tích xác định số bị thiệt hại, số lỗ do bị thiệt hại;\n++ Văn bản hoặc biên bản xác nhận tai nạn có xác nhận của cơ quan công an hoặc xác nhận mức độ thương tật của cơ quan y tế (nếu là tai nạn bất ngờ);\n++ Giấy tờ xác định việc bồi thường của cơ quan bảo hiểm hoặc thỏa thuận bồi thường của người gây tai nạn (nếu có), nếu là tai nạn bất ngờ;\n++ Các chứng từ chi liên quan trực tiếp đến việc khắc phục tai nạn (nếu là tai nại bất ngờ).\n(iii) Miễn, giảm thuế sử dụng đất phi nông nghiệp gặp khó khăn do sự kiện bất khả kháng \n+ Thành phần hồ sơ gồm: \n++ Văn bản đề nghị theo mẫu số 01/MGTH ban hành kèm theo Phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi tại Thông tư số 40/2025/TT-BTC và Thông tư số 94/2025/TT-BTC).\n++ Bản sao các giấy tờ liên quan đến thửa đất chịu thuế như: Giấy chứng nhận quyền sử dụng đất, Quyết định giao đất, Quyết định hoặc Hợp đồng cho thuê đất, Quyết định cho phép chuyển mục đích sử dụng đất;\n++ Xác nhận của Uỷ ban nhân dân cấp xã nơi có đất bị thiệt hại.\n- Số lượng hồ sơ: 01 bộ", "ket_qua": "+ Quyết định miễn thuế, giảm thuế theo mẫu số 03/MGTH ban hành kèm theo Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. + Thông báo không được miễn thuế, giảm thuế theo mẫu số 04/MGTH ban hành kèm theo phụ lục I Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính. Trong quá trình giải quyết hồ sơ miễn thuế, giảm thuế còn thiếu thông tin cần giải trình, bổ sung tài liệu thì cơ quan thuế gửi Thông báo giải trình, bổ sung thông tin, tài liệu theo mẫu số 01/TB-BSTT-NNT ban hành kèm theo Nghị định số 126/2020/NĐ-CP cho người nộp thuế để yêu cầu giải trình, bổ sung thông tin, tài liệu.", "dieu_kien": "Không có", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 của Quốc hội; \n+ Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của luật chứng khoán, luật kế toán, luật kiểm toán độc lập, luật ngân sách nhà nước, luật quản lý, sử dụng, tài sản công, luật quản lý thuế, luật thuế thu nhập cá nhân, luật dự trữ quốc, luật xử lý vi phạm hành chính ngày 29/11/2024;\n+ Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 91/2022/NĐ-CP ngày 30 tháng 10 năm 2022 của Chính phủ sửa đổi, bổ sung một số điều của nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế;\n+ Nghị định số 122/2025/NĐ-CP ngày 11/6/2025 của Chính phủ quy định về phân quyền, phân cấp trong lĩnh vực quản lý thuế, Nghị định số 125/2025/NĐ-CP ngày 11/ 6/ 2025 của Chính phủ quy định về phân định thẩm quyền của chính quyền địa phương 02 cấp trong lĩnh vực quản lý nhà nước của bộ tài chính; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia;\n+ Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật quản lý thuế;\n+ Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của các thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp.\n+ Thông tư số 94/2025/TT-BTC ngày 14 tháng 10 năm 2025 của Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 80/2021/TT-BTC ngày 29 tháng 9 năm 2021 của Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19 tháng 10 năm 2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế và sửa đổi, bổ sung một số mẫu biểu của Thông tư số 40/2021/TT-BTC ngày 01 tháng 6 năm 2021 của Bộ Tài chính hướng dẫn thuế giá trị gia tăng, thuế thu nhập cá nhân và quản lý thuế đối với hộ kinh doanh, cá nhân kinh doanh.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01/MGTH", "02/MGTH"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.008584"}, {"ma": "1.007040", "ten": "Khai thuế tiêu thụ đặc biệt đối với sản xuất, kinh doanh hàng hóa, dịch vụ chịu thuế TTĐB", "cap_thuc_hien": "Cấp Tỉnh, Thành phố,Cấp Xã", "doi_tuong": "Tổ chức", "co_quan": "Thuế tỉnh, thành phố/Thuế cơ sở/Chi cục Thuế Doanh nghiệp lớn.", "trinh_tu": "+ Bước 1. Người nộp thuế chuẩn bị số liệu, lập hồ sơ và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất là ngày thứ 20 của tháng tiếp theo tháng phát sinh nghĩa vụ thuế.\n Trường hợp người nộp thuế có hoạt động kinh doanh xuất khẩu chưa nộp thuế tiêu thụ đặc biệt ở khâu sản xuất sau đó không xuất khẩu mà bán trong nước và trường hợp cơ sở kinh doanh mua xe ô tô, tàu bay, du thuyền sản xuất trong nước thuộc đối tượng không chịu thuế tiêu thụ đặc biệt nhưng sau đó chuyển mục đích sử dụng sang đối tượng chịu thuế tiêu thụ đặc biệt thì thực hiện khai thuế tiêu thụ đặc biệt theo từng lần phát sinh và gửi đến cơ quan thuế quản lý trực tiếp người nộp thuế chậm nhất 10 ngày kể từ ngày phát sinh.\n ++ Trường hợp NNT nộp hồ sơ qua giao dịch điện tử: NNT truy cập vào Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính để lập hồ sơ điện tử, ký điện tử và gửi đến cơ quan thuế.\n ++ Trường hợp NNT nộp hồ sơ trực tiếp/qua bưu chính: NNT lập hồ sơ giấy, ký và gửi đến cơ quan thuế qua Trung tâm Phục vụ hành chính công cấp tỉnh/Trung tâm Phục vụ hành chính công cấp xã hoặc qua đường bưu chính.\n + Bước 2. Cơ quan thuế tiếp nhận:\n ++ Trường hợp hồ sơ được nộp qua giao dịch điện tử thì việc tiếp nhận và kiểm tra, chấp nhận hồ sơ thực hiện như sau:\n +++ Tiếp nhận hồ sơ: Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính gửi thông báo cho NNT về việc tiếp nhận hồ sơ của NNT hoặc thông báo lý do không tiếp nhận hồ sơ của NNT chậm nhất 15 phút kể từ khi nhận được hồ sơ điện tử của NNT.\n +++ Kiểm tra, chấp nhận hồ sơ: Cơ quan thuế kiểm tra hồ sơ và gửi thông báo cho NNT về việc chấp nhận hoặc không chấp nhận hồ sơ của NNT qua Cổng Dịch vụ công Quốc gia/Hệ thống thông tin giải quyết thủ tục hành chính chậm nhất 01 ngày làm việc kể từ ngày ghi trên thông báo tiếp nhận hồ sơ điện tử của NNT.\n ++ Trường hợp hồ sơ được nộp trực tiếp/qua bưu chính: cơ quan thuế thực hiện tiếp nhận, đóng dấu tiếp nhận hồ sơ của NNT (nếu hồ sơ đã đầy đủ, đúng quy định) hoặc hướng dẫn NNT hoàn thiện hồ sơ (nếu hồ sơ không đầy đủ, không đúng quy định).", "cach_thuc": "+ Trực tiếp: Tại TTPVHCC cấp tỉnh, xã; \n + Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật; \n + Trực tuyến: qua Cổng DVC Quốc gia hoặc Ứng dụng định danh quốc gia đối với các TTHC đã toàn trình và được tích hợp, kết nối với Cổng dịch vụ công của Bộ Tài chính theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính/ các Hệ thống thông tin điện tử, hệ thống thông tin giải quyết TTHC của Cục Thuế.", "thanh_phan_ho_so": "+ Thành phần hồ sơ: \n ++ Tờ khai thuế TTĐB mẫu số 01/TTĐB ban hành kèm theo Danh mục hồ sơ khai thuế tại Phụ lục I ban hành kèm theo Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19 /10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (sau đây gọi là Nghị định số 373/2025/NĐ-CP); \n ++ Bảng xác định thuế tiêu thụ đặc biệt được khấu trừ (nếu có) mẫu số 01-2/TTĐB ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính; \n ++ Bảng phân bổ thuế tiêu thụ đặc biệt theo địa bàn tỉnh, thành phố từ hoạt động kinh doanh sổ xố (nếu có) mẫu số 01-3/TTĐB ban hành kèm theo Phụ lục II Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo quy định tại điểm b khoản 7 Điều 1 Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính). \n + Số lượng hồ sơ: 01 (bộ).", "ket_qua": "Hồ sơ gửi đến cơ quan thuế không có kết quả giải quyết.", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/7/2024 của Bộ trưởng Bộ Tài chính) hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "+ Luật Quản lý thuế số 38/2019/QH14 ngày 13/6/2019 (đã được sửa đổi, bổ sung theo quy định tại khoản 6 Điều 6 Luật số 56/2024/QH15 sửa đổi, bổ sung một số điều của Luật Chứng khoán, Luật Kế toán, Luật Kiểm toán độc lập, Luật Ngân sách nhà nước, Luật Quản lý, sử dụng tài sản công, Luật Quản lý thuế, Luật Thuế thu nhập cá nhân, Luật Dự trữ quốc gia, Luật Xử lý vi phạm hành chính); \n + Nghị định số 373/2025/NĐ-CP ngày 31/12/2025 của Chính phủ sửa đổi, bổ sung một số điều của Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế (đã được sửa đổi, bổ sung theo Nghị định số 91/2022/NĐ-CP ngày 30/10/2022 của Chính phủ); \n + Thông tư số 80/2021/TT-BTC ngày 29/9/2021 của Bộ trưởng Bộ Tài chính hướng dẫn thi hành một số điều của Luật Quản lý thuế và Nghị định số 126/2020/NĐ-CP ngày 19/10/2020 của Chính phủ quy định chi tiết một số điều của Luật Quản lý thuế; \n + Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế (đã được sửa đổi, bổ sung theo Thông tư số 46/2024/TT-BTC ngày 09/07/2024 của Bộ trưởng Bộ Tài chính); \n + Thông tư số 40/2025/TT-BTC ngày 13/6/2025 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của các Thông tư thuộc lĩnh vực quản lý thuế để phân định thẩm quyền của chính quyền địa phương theo mô hình tổ chức chính quyền địa phương 02 cấp; \n + Nghị định số 118/2025/NĐ-CP ngày 09/6/2025 của Chính phủ về thực hiện thủ tục hành chính theo cơ chế một cửa, một cửa liên thông tại Bộ phận Một cửa và Cổng Dịch vụ công quốc gia.\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": ["01-2/TTĐB", "01-3/TTĐB", "01/TTĐB"], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.007040"}, {"ma": "1.009824", "ten": "Thông báo địa điểm kinh doanh của hộ kinh doanh, cá nhân kinh doanh", "cap_thuc_hien": null, "doi_tuong": "Công dân Việt Nam, Doanh nghiệp", "co_quan": "Không có thông tin", "trinh_tu": "Bước 1: Hộ kinh doanh, cá nhân kinh doanh thành lập thêm địa điểm kinh doanh ngoài trụ sở chính, hoặc thay đổi thông tin, hoặc tạm ngừng kinh doanh, hoặc chấm dứt hoạt động đối với địa điểm kinh doanh thì thực hiện gửi Thông báo về việc thành lập địa điểm kinh doanh, thay đổi thông tin, tạm ngừng kinh doanh, chấm dứt hoạt động địa điểm kinh doanh đến cơ quan thuế quản lý trực tiếp trụ sở của hộ kinh doanh, cá nhân kinh doanh theo mẫu số 01/TB-ĐĐKD ban hành kèm theo Thông tư số 18/2026/TT-BTC trong thời hạn 10 ngày làm việc kể từ ngày địa điểm kinh doanh đi vào hoạt động, hoặc thay đổi thông tin, hoặc tạm ngừng, hoặc chấm dứt hoạt động.\n Bước 2: Cơ quan thuế quản lý trực tiếp trụ sở của hộ kinh doanh, cá nhân kinh doanh tiếp nhận và gửi thông báo về việc cập nhật thông tin của địa điểm kinh doanh cho người nộp thuế biết theo mẫu số 02/TB-ĐĐKD ban hành kèm theo Thông tư số 18/2026/TT-BTC.", "cach_thuc": "Hình thức nộp\n Thời gian\n Phí, lệ phí\n Mô tả\n Trực tiếp\n Hệ thống giải quyết thủ tục hành chính ngành Thuế thực hiện phản hồi tự động thông qua phương thức điện tử.\n Không có thông tin\n Tại Trung tâm phục vụ hành chính công cấp tỉnh, xã\n Trực tuyến\n Hệ thống giải quyết thủ tục hành chính ngành Thuế thực hiện phản hồi tự động thông qua phương thức điện tử.\n Không có thông tin\n Qua Cổng dịch vụ công Quốc gia hoặc Ứng dụng định danh quốc gia theo quy định về thực hiện cơ chế một cửa, một cửa liên thông trong giải quyết thủ tục hành chính\n Dịch vụ bưu chính\n Hệ thống giải quyết thủ tục hành chính ngành Thuế thực hiện phản hồi tự động thông qua phương thức điện tử\n Không có thông tin\n Thông qua dịch vụ bưu chính công ích theo quy định của Thủ tướng Chính phủ, qua thuê dịch vụ của doanh nghiệp, cá nhân hoặc qua ủy quyền theo quy định của pháp luật", "thanh_phan_ho_so": "Thông báo thành lập địa điểm kinh doanh, thay đổi thông tin, tạm ngừng kinh doanh, chấm dứt hoạt động địa điểm kinh doanh (Mẫu số 01/TB-ĐĐKD Thông tư số 18/2026/TT-BTC)", "ket_qua": "Thông báo về việc thành lập/thay đổi thông tin/tạm ngừng/chấm dứt hoạt động đối với địa điểm kinh doanh (Mẫu số 01/TB-ĐĐKD)", "dieu_kien": "Trường hợp người nộp thuế lựa chọn và gửi hồ sơ đến cơ quan thuế thông qua giao dịch điện tử thì phải tuân thủ đúng, đầy đủ các quy định và điều kiện thực hiện giao dịch điện tử trong lĩnh vực thuế tại Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ trưởng Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế và Thông tư số 46/2024/TT-BTC ngày 09/07/2024 sửa đổi, bổ sung một số điều của Thông tư số 19/2021/TT-BTC ngày 18/3/2021 của Bộ Tài chính hướng dẫn giao dịch điện tử trong lĩnh vực thuế.", "can_cu_phap_ly": "Số ký hiệu \n Trích yếu \n Ngày ban hành \n Cơ quan ban hành \n 38/2019/QH14\n Luật 38/2019/QH14\n 13-06-2019\n 19/2021/TT-BTC\n Thông tư 19/2021/TT-BTC\n 18-03-2021\n 86/2024/TT-BTC\n 86/2024/TT-BTC\n 23-12-2024\n Bộ Tài chính\n Quay lại \n Thông báo\n -->\n Đề nghị NNT thực hiện kê khai mẫu 01/TB-ĐĐKD\n Đóng \n Tiếp tục \n CỤC THUẾ - HỆ THỐNG THÔNG TIN GIẢI QUYẾT THỦ TỤC HÀNH CHÍNH\n Cơ quan chủ quản:\n Bộ Tài chính\n Địa chỉ:\n Số 1A - Nguyễn Công Trứ - Phường Hai Bà Trưng - Thành phố Hà Nội\n Ghi rõ nguồn \"https://www.dichvucong.gdt.gov.vn\" khi phát hành thông tin\n từ website này\n Hỗ trợ:\n (024) 39712555\n Điện thoại:\n Tổng đài hỗ trợ 024.730.55999 nhánh 1\n Thư điện tử:\n nhomhttdt@gdt.gov.vn\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n -->\n Đã kết nối EMC -->\n -->", "mau_to_khai": [], "nguon": "https://dichvucong.gdt.gov.vn/tthc/homelogin/chi-tiet-tthc?maTTHC=1.009824"}]$du_lieu$::jsonb)
